class AgentLatencyKernelTest {
public:
    static double getQueueLatencyMs(int64_t currentTimeUs,
                                    double runningElapsedScale = 1.0)
    {
        AgentLatencyKernel kernel;
        kernel._timeCompression = runningElapsedScale;
        kernel._queueLatencyUs.store(300 * 1000, std::memory_order_relaxed);
        kernel._runningBatches.emplace(
            1, AgentLatencyKernel::RunningBatch{1000 * 1000, 100 * 1000});
        return kernel.getQueueLatencyMs(currentTimeUs);
    }

    static double getConcurrentQueueLatencyMs(int64_t currentTimeUs)
    {
        AgentLatencyKernel kernel;
        kernel._queueLatencyUs.store(300 * 1000, std::memory_order_relaxed);
        kernel._runningBatches.emplace(
            1, AgentLatencyKernel::RunningBatch{1000 * 1000, 100 * 1000});
        kernel._runningBatches.emplace(
            2, AgentLatencyKernel::RunningBatch{1050 * 1000, 80 * 1000});
        return kernel.getQueueLatencyMs(currentTimeUs);
    }

    static std::vector<int64_t> updateExecutionState()
    {
        AgentLatencyKernel kernel;
        AgentLatencyInput latest;
        latest.batchWaitingRequests = 4;
        latest.queuedBatchRequests = 5;
        latest.runningRequests = 6;
        latest.eventTimeUs = 300;
        kernel.updateExecutionState(latest);

        AgentLatencyInput stale;
        stale.batchWaitingRequests = 1;
        stale.queuedBatchRequests = 2;
        stale.runningRequests = 3;
        stale.eventTimeUs = 400;
        kernel.updateExecutionState(stale);
        return {
            kernel._latestBatchWaitingRequests,
            kernel._latestQueuedBatchRequests,
            kernel._latestRunningRequests,
        };
    }

    static std::vector<int64_t> startRunningBatch(int64_t eventTimeUs)
    {
        AgentLatencyKernel kernel;
        kernel._batchLatencyUs.emplace(7, 123000);
        AgentLatencyInput input;
        input.batchId = 7;
        input.eventTimeUs = eventTimeUs;
        kernel.startRunningBatch(input);
        const auto &running = kernel._runningBatches.at(7);
        return {
            static_cast<int64_t>(kernel._runningBatches.size()),
            running.startTimeUs,
            running.predictedLatencyUs,
        };
    }

    static std::pair<double, double> runningElapsedTimeMs(int64_t currentTimeUs)
    {
        AgentLatencyKernel kernel;
        kernel._timeCompression = 2.0;
        kernel._latestRunningRequests = 3;
        AgentLatencyKernel::QueueFeatures first;
        first.requestCount = 2;
        kernel._batchQueueFeatures.emplace(1, first);
        kernel._runningBatches.emplace(1, AgentLatencyKernel::RunningBatch{1'000'000, 0});
        AgentLatencyKernel::QueueFeatures second;
        second.requestCount = 1;
        kernel._batchQueueFeatures.emplace(2, second);
        kernel._runningBatches.emplace(2, AgentLatencyKernel::RunningBatch{1'500'000, 0});
        const auto elapsed = kernel.getRunningElapsedTimeMs(currentTimeUs);
        const auto snapshot = kernel.makeUnifiedWorkloadSnapshot(currentTimeUs);
        return {elapsed, snapshot.runningElapsedTimeMs};
    }

    static std::vector<int64_t> scheduleBatchIdLifecycle()
    {
        AgentLatencyKernel kernel;
        NaviSchedLocalBatchInfo localBatch;
        localBatch.scheduleBatchId = 101;
        localBatch.localBatchId = 7;
        localBatch.requestCount = 1;
        kernel._batchLocalInfos.emplace(7, localBatch);
        return {
            kernel.getLocalBatchInfo(7, false).scheduleBatchId,
            kernel.getLocalBatchInfo(7, true).scheduleBatchId,
            kernel.getLocalBatchInfo(7, false).scheduleBatchId,
        };
    }

    static bool shouldLogQueueDebugSample(int64_t scheduleBatchId)
    {
        return AgentLatencyKernel::shouldLogQueueDebugSample(scheduleBatchId);
    }

    static bool shouldFitQueueLatency(bool unifiedLatencyPrediction,
                                      AgentLatencyInputType inputType,
                                      bool hasQueueFeatures,
                                      bool latencySampleValid = true)
    {
        return AgentLatencyKernel::shouldFitQueueLatency(
            unifiedLatencyPrediction, inputType, hasQueueFeatures, latencySampleValid);
    }

    static bool shouldRecordLatencySample(bool unifiedLatencyPrediction,
                                          AgentLatencyInputType inputType,
                                          bool unifiedLatencySample,
                                          bool latencySampleValid = true)
    {
        return AgentLatencyKernel::shouldRecordLatencySample(
            unifiedLatencyPrediction, inputType, unifiedLatencySample,
            latencySampleValid);
    }

    static bool shouldRecordLatencyValidation(AgentLatencyInputType inputType,
                                              bool latencySampleValid,
                                              bool latencyValidationValid)
    {
        return AgentLatencyKernel::shouldRecordLatencyValidation(
            inputType, latencySampleValid, latencyValidationValid);
    }

    static bool derivesUnifiedWorkloadFromBatches(AgentReportR *reportR)
    {
        AgentLatencyKernel kernel;
        kernel._agentReportR__ = reportR;
        return kernel.derivesUnifiedWorkloadFromBatches();
    }

    static std::vector<double> unifiedBatchLifecycle(const NaviSchedBatchPtr &firstBatch,
                                                     const NaviSchedBatchPtr &secondBatch)
    {
        AgentLatencyKernel kernel;
        kernel._timeCompression = 2.0;
        AgentLatencyInput firstReady;
        firstReady.type = AgentLatencyInputType::BATCH_READY;
        firstReady.batch = firstBatch;
        firstReady.batchId = firstBatch->batchId;
        firstReady.eventTimeUs = 1'000'000;
        AgentLatencyKernel::UnifiedBatchState firstState;
        NaviSchedLocalBatchInfo firstAdmittedBatch;
        const bool firstAdded =
            kernel.addUnifiedBatch(firstReady, firstState, firstAdmittedBatch);

        AgentLatencyInput secondReady;
        secondReady.type = AgentLatencyInputType::BATCH_READY;
        secondReady.batch = secondBatch;
        secondReady.batchId = secondBatch->batchId;
        secondReady.eventTimeUs = 2'000'000;
        AgentLatencyKernel::UnifiedBatchState secondState;
        NaviSchedLocalBatchInfo secondAdmittedBatch;
        const bool secondAdded =
            kernel.addUnifiedBatch(secondReady, secondState, secondAdmittedBatch);
        const auto batchCountAfterAdd = kernel._unifiedWorkloadFeatures.getBatchCount();
        const auto requestCountAfterAdd = kernel._unifiedWorkloadFeatures.getBatchSize();
        const auto remainingPrefillAfterAdd = kernel._unifiedRemainingPrefillRequestCount;

        const auto savedFeatures = kernel._unifiedWorkloadFeatures;
        kernel._unifiedRemainingPrefillRequestCount = 0;
        AgentLatencyInput failedFinish;
        failedFinish.type = AgentLatencyInputType::BATCH_FINISHED;
        failedFinish.eventTimeUs = 1'050'000;
        const bool invalidRetireRejected =
            !kernel.retireUnifiedBatch(failedFinish, firstState);
        const bool failedRetireWasAtomic =
            savedFeatures.getBatchCount() ==
                kernel._unifiedWorkloadFeatures.getBatchCount() &&
            savedFeatures.getBatchSize() ==
                kernel._unifiedWorkloadFeatures.getBatchSize() &&
            !failedFinish.unifiedLatencySample;
        kernel._unifiedRemainingPrefillRequestCount = remainingPrefillAfterAdd;

        AgentLatencyInput firstFinish;
        firstFinish.type = AgentLatencyInputType::BATCH_FINISHED;
        firstFinish.eventTimeUs = 1'050'000;
        const bool firstRetired = kernel.retireUnifiedBatch(firstFinish, firstState);
        const auto batchCountAfterFinish =
            kernel._unifiedWorkloadFeatures.getBatchCount();
        const auto requestCountAfterFinish =
            kernel._unifiedWorkloadFeatures.getBatchSize();
        const auto remainingPrefillAfterFinish =
            kernel._unifiedRemainingPrefillRequestCount;

        AgentLatencyInput secondAbort;
        secondAbort.type = AgentLatencyInputType::BATCH_ABORTED;
        secondAbort.eventTimeUs = 1'060'000;
        const bool secondRetired = kernel.retireUnifiedBatch(secondAbort, secondState);
        return {
            static_cast<double>(firstAdded),
            static_cast<double>(secondAdded),
            static_cast<double>(firstAdmittedBatch.scheduleBatchId),
            static_cast<double>(secondAdmittedBatch.scheduleBatchId),
            static_cast<double>(batchCountAfterAdd),
            static_cast<double>(requestCountAfterAdd),
            static_cast<double>(remainingPrefillAfterAdd),
            static_cast<double>(secondState.precedingFeatures.getBatchCount()),
            static_cast<double>(secondState.precedingFeatures.getBatchSize()),
            static_cast<double>(invalidRetireRejected),
            static_cast<double>(failedRetireWasAtomic),
            static_cast<double>(firstRetired),
            firstFinish.modelLatencyMs,
            static_cast<double>(firstFinish.unifiedLatencySample),
            static_cast<double>(batchCountAfterFinish),
            static_cast<double>(requestCountAfterFinish),
            static_cast<double>(remainingPrefillAfterFinish),
            static_cast<double>(secondRetired),
            static_cast<double>(kernel._unifiedWorkloadFeatures.getBatchCount()),
            static_cast<double>(kernel._unifiedWorkloadFeatures.getBatchSize()),
            static_cast<double>(kernel._unifiedRemainingPrefillRequestCount),
        };
    }

    static std::vector<double> unifiedBatchReplacementLifecycle(
        const NaviSchedBatchPtr &originalBatch, const NaviSchedBatchPtr &remainingBatch,
        const NaviSchedBatchPtr &lateRemainingBatch)
    {
        AgentLatencyKernel kernel;
        AgentLatencyInput ready;
        ready.type = AgentLatencyInputType::BATCH_READY;
        ready.batch = originalBatch;
        ready.batchId = originalBatch->batchId;
        ready.eventTimeUs = 1'000'000;
        AgentLatencyKernel::UnifiedBatchState state;
        NaviSchedLocalBatchInfo admittedBatch;
        const bool added = kernel.addUnifiedBatch(ready, state, admittedBatch);

        AgentLatencyInput partialAbort;
        partialAbort.type = AgentLatencyInputType::BATCH_REQUESTS_ABORTED;
        partialAbort.batch = remainingBatch;
        partialAbort.batchId = remainingBatch->batchId;
        partialAbort.eventTimeUs = 1'050'000;
        const bool replaced = kernel.replaceUnifiedBatch(partialAbort, state);

        const auto savedFeatures = kernel._unifiedWorkloadFeatures;
        const auto savedState = state;
        kernel._unifiedRemainingPrefillRequestCount = 0;
        AgentLatencyInput invalidReplacement;
        invalidReplacement.type = AgentLatencyInputType::BATCH_REQUESTS_ABORTED;
        invalidReplacement.batch = lateRemainingBatch;
        invalidReplacement.batchId = lateRemainingBatch->batchId;
        invalidReplacement.eventTimeUs = 1'060'000;
        const bool invalidReplacementRejected =
            !kernel.replaceUnifiedBatch(invalidReplacement, state);
        const auto sameFeatures = [](const NaviSchedLatencyFeatures &lhs,
                                     const NaviSchedLatencyFeatures &rhs) {
            return lhs.getBatchCount() == rhs.getBatchCount() &&
                   lhs.getBatchSize() == rhs.getBatchSize() &&
                   lhs.getCacheHitTokenCount() == rhs.getCacheHitTokenCount() &&
                   lhs.getCacheMissTokenCount() == rhs.getCacheMissTokenCount() &&
                   lhs.getCacheMissTokenSquareSum() == rhs.getCacheMissTokenSquareSum() &&
                   lhs.getCacheHitMissTokenProductSum() ==
                       rhs.getCacheHitMissTokenProductSum();
        };
        const bool failedReplacementWasAtomic =
            sameFeatures(savedFeatures, kernel._unifiedWorkloadFeatures) &&
            sameFeatures(savedState.features, state.features) &&
            sameFeatures(savedState.precedingFeatures, state.precedingFeatures) &&
            savedState.remainingPrefillRequestCount ==
                state.remainingPrefillRequestCount &&
            savedState.readyTimeUs == state.readyTimeUs &&
            savedState.localBatch.scheduleBatchId == state.localBatch.scheduleBatchId &&
            savedState.localBatch.localBatchId == state.localBatch.localBatchId &&
            savedState.localBatch.requestCount == state.localBatch.requestCount &&
            savedState.localBatch.requestIds == state.localBatch.requestIds;

        return {
            static_cast<double>(added),
            static_cast<double>(replaced),
            static_cast<double>(kernel._unifiedWorkloadFeatures.getBatchCount()),
            static_cast<double>(kernel._unifiedWorkloadFeatures.getBatchSize()),
            static_cast<double>(kernel._unifiedWorkloadFeatures.getCacheHitTokenCount()),
            static_cast<double>(kernel._unifiedWorkloadFeatures.getCacheMissTokenCount()),
            kernel._unifiedWorkloadFeatures.getCacheMissTokenSquareSum(),
            kernel._unifiedWorkloadFeatures.getCacheHitMissTokenProductSum(),
            static_cast<double>(savedState.remainingPrefillRequestCount),
            static_cast<double>(state.features.getBatchCount()),
            static_cast<double>(state.features.getBatchSize()),
            static_cast<double>(state.features.getCacheHitTokenCount()),
            static_cast<double>(state.features.getCacheMissTokenCount()),
            state.features.getCacheMissTokenSquareSum(),
            state.features.getCacheHitMissTokenProductSum(),
            static_cast<double>(state.precedingFeatures.getBatchCount()),
            static_cast<double>(state.precedingFeatures.getBatchSize()),
            static_cast<double>(state.readyTimeUs),
            static_cast<double>(state.localBatch.scheduleBatchId),
            static_cast<double>(state.localBatch.localBatchId),
            static_cast<double>(state.localBatch.requestCount),
            static_cast<double>(state.localBatch.requestIds.size()),
            state.localBatch.requestIds.empty()
                ? 0.0
                : static_cast<double>(state.localBatch.requestIds.front()),
            static_cast<double>(invalidReplacementRejected),
            static_cast<double>(failedReplacementWasAtomic),
        };
    }

    static std::vector<double> fitConstantQueueBias(size_t stepCount)
    {
        AgentLatencyKernel kernel;
        const auto initialPrediction = kernel.getQueueFeatures(0).predictedLatencyMs;
        for (size_t step = 0; step < stepCount; ++step) {
            const auto features = kernel.getQueueFeatures(0);
            kernel.fitQueueLatency(features, 8.0);
        }
        return {
            initialPrediction,
            kernel.getQueueFeatures(0).predictedLatencyMs,
            kernel._queueWeights[0],
            static_cast<double>(kernel._queueFitStep - 1),
        };
    }

    static std::vector<double> getReportedQueueLoadWithLearnedBias()
    {
        AgentLatencyKernel kernel;
        for (size_t step = 0; step < 100; ++step) {
            const auto features = kernel.getQueueFeatures(0);
            kernel.fitQueueLatency(features, 8.0);
        }
        const auto idle = kernel.getQueueLoadPrediction(0);
        kernel._batchLatencyUs.emplace(1, 0);
        const auto active = kernel.getQueueLoadPrediction(0);
        return {
            kernel._queueWeights[0],     idle.totalLatencyMs,
            idle.decayHeadRemainingMs,   active.totalLatencyMs,
            active.decayHeadRemainingMs,
        };
    }

    static std::vector<double> immutableQueuedPrediction()
    {
        AgentLatencyKernel kernel;
        kernel._queueLatencyUs.store(125000, std::memory_order_relaxed);
        kernel._batchLatencyUs.emplace(1, 125000);
        const auto before = kernel.getQueueFeatures(1000);
        for (size_t step = 0; step < 100; ++step) {
            const auto trainingFeatures = kernel.getQueueFeatures(1000);
            kernel.fitQueueLatency(trainingFeatures, 8.0);
        }
        const auto after = kernel.getQueueFeatures(1000);
        return {
            before.rawLatencyMs,
            before.precedingBatchCount,
            after.rawLatencyMs,
            after.precedingBatchCount,
            before.predictedLatencyMs,
            static_cast<double>(before.fitStep),
            before.weights[0],
            kernel.predictQueueLatencyMs(after),
            static_cast<double>(after.fitStep),
            after.weights[0],
        };
    }

    static std::vector<double> delayedQueueResidual()
    {
        AgentLatencyKernel kernel;
        const auto delayed = kernel.getQueueFeatures(1000);
        for (size_t step = 0; step < 100; ++step) {
            const auto trainingFeatures = kernel.getQueueFeatures(1000);
            kernel.fitQueueLatency(trainingFeatures, 8.0);
        }
        kernel._queueAdamMoment1.fill(0.0);
        kernel._queueAdamMoment2.fill(0.0);
        const auto weightBefore = kernel._queueWeights[0];
        kernel.fitQueueLatency(delayed, delayed.predictedLatencyMs);
        return {delayed.predictedLatencyMs, weightBefore, kernel._queueWeights[0]};
    }
};

