AgentUpdateToMasterDataPtr makeWorkloadUpdate(uint64_t revision, int64_t eventTimeUs = 0)
{
    auto update = std::make_shared<AgentUpdateToMasterData>();
    update->event = NaviSchedAgentEvent::WORKLOAD_UPDATED;
    update->eventTimeUs = eventTimeUs > 0 ? eventTimeUs : revision;
    update->workload = std::make_shared<NaviSchedWorkloadSnapshot>();
    auto &workload = *update->workload;
    workload.revision = revision;
    workload.eventTimeUs = update->eventTimeUs;
    workload.requestCount = revision;
    workload.remainingPrefillRequestCount = revision;
    workload.runningRequestCount = revision + 1;
    workload.waitingRequestCount = revision + 2;
    workload.remainingPrefillContextTokenCount = revision * 3;
    workload.remainingPrefillTokenCount = revision * 4;
    workload.remainingPrefillTokenSquareSum = revision * 5;
    workload.contextRemainingPrefillTokenProductSum = revision * 6;
    workload.remainingTotalContextTokenCount = revision * 7;
    workload.remainingTotalTokenCount = revision * 8;
    workload.remainingTotalTokenSquareSum = revision * 9;
    workload.contextRemainingTotalTokenProductSum = revision * 10;
    workload.totalPromptTokenCount = revision * 11;
    workload.inFlightScheduledTokenCount = revision * 12;
    return update;
}

void enableCapacitySplitWorkload(NaviSchedWorkloadSnapshot &workload)
{
    workload.prefillCapacitySplit = true;
    workload.maxRunningRequestCount =
        std::max(workload.requestCount, workload.remainingPrefillRequestCount);
    workload.runningCapacitySlotCount = workload.maxRunningRequestCount;
    workload.runningCapacityPrefillRequestCount = workload.remainingPrefillRequestCount;
    workload.runningCapacityPrefillContextTokenCount =
        workload.remainingPrefillContextTokenCount;
    workload.runningCapacityPrefillTokenCount = workload.remainingPrefillTokenCount;
    workload.runningCapacityPrefillTokenSquareSum =
        workload.remainingPrefillTokenSquareSum;
    workload.runningCapacityContextRemainingPrefillTokenProductSum =
        workload.contextRemainingPrefillTokenProductSum;
}

