    ASSERT_TRUE(resource.activateSubscriber(
        "mi_collector", "mi_agent", "10.0.0.1", 1,
        AgentSchedulerConfigR::hashJson(miJson), miJson,
        R"({"hardware":"AMD_Instinct_MI308X"})"));
    ASSERT_TRUE(resource.activateSubscriber(
        "rtx_collector", "rtx_agent", "10.0.0.2", 1,
        AgentSchedulerConfigR::hashJson(rtxJson), rtxJson,
        R"({"hardware":"NVIDIA RTX PRO 5000 72GB Blackwell"})"));

    SchedulerConfigR::Request request;
    request.update = true;
    request.hardware = "AMD_Instinct_MI308X";
    request.configJson =
        R"({"latency_online_learning_rate_scale":128,"residual_learning_rate":0})";
    request.responsePipe = std::make_shared<CaptureAsyncPipe>();
    SchedulerConfigResponseDataPtr response;
    bool waitingForAgents = false;
    ASSERT_TRUE(resource.processRequest(request, response, waitingForAgents));
    ASSERT_TRUE(waitingForAgents);
    EXPECT_EQ(1, miNotification->overrideCount);
    EXPECT_EQ(0, rtxNotification->overrideCount);

    SchedulerConfigR::PendingAgentUpdate update;
    ASSERT_TRUE(resource.getPendingAgentUpdate("mi_collector", update));
    EXPECT_FALSE(resource.getPendingAgentUpdate("rtx_collector", update));
    AgentSchedulerConfig expected;
