TEST_F(NaviSchedResourceTest,
       testSchedulerConfigNewAgentInheritsGlobalAndHardwarePatches)
{
    SchedulerConfigR resource;
    auto applyWithoutAgents = [&resource](const std::string &hardware,
                                          const std::string &configJson) {
        SchedulerConfigR::Request request;
        request.update = true;
        request.hardware = hardware;
        request.configJson = configJson;
        request.responsePipe = std::make_shared<CaptureAsyncPipe>();
        SchedulerConfigResponseDataPtr response;
        bool waitingForAgents = false;
        EXPECT_TRUE(resource.processRequest(request, response, waitingForAgents));
        EXPECT_FALSE(waitingForAgents);
        EXPECT_TRUE(response && response->accepted) << (response ? response->error : "");
    };
    applyWithoutAgents("", R"({"latency_current_sample_weight":3})");
    applyWithoutAgents("AMD_Instinct_MI308X",
                       R"({"latency_current_sample_weight":4,"residual_learning_rate":1})");

    auto notification = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource.subscribe("collector", notification));
    AgentSchedulerConfig startupConfig;
    startupConfig.batchTimeoutMs = 23;
    startupConfig.latencyCurrentSampleWeight = 2.0;
    startupConfig.residualLearningRate = 0.4;
    const auto startupJson = AgentSchedulerConfigR::toJson(startupConfig);
    ASSERT_TRUE(resource.activateSubscriber(
        "collector", "agent", "10.0.0.3", 1,
        AgentSchedulerConfigR::hashJson(startupJson), startupJson,
        R"({"hardware":"AMD_Instinct_MI308X"})"));

    SchedulerConfigR::PendingAgentUpdate update;
    ASSERT_TRUE(resource.getPendingAgentUpdate("collector", update));
    AgentSchedulerConfig expected;
    std::string error;
    ASSERT_TRUE(AgentSchedulerConfigR::parse(update.configJson, expected, error))
        << error;
    EXPECT_EQ(23, expected.batchTimeoutMs);
    EXPECT_DOUBLE_EQ(4.0, expected.latencyCurrentSampleWeight);
    EXPECT_DOUBLE_EQ(1.0, expected.residualLearningRate);

    ASSERT_TRUE(resource.subscribe("collector_matching", std::make_shared<CaptureAsyncPipe>()));
    const auto matchingJson = AgentSchedulerConfigR::toJson(expected);
    ASSERT_TRUE(resource.activateSubscriber(
        "collector_matching", "matching_agent", "10.0.0.4", 1,
        AgentSchedulerConfigR::hashJson(matchingJson), matchingJson,
        R"({"hardware":"AMD_Instinct_MI308X"})"));
    EXPECT_FALSE(resource.getPendingAgentUpdate("collector_matching", update));

    ASSERT_TRUE(resource.subscribe("collector_other", std::make_shared<CaptureAsyncPipe>()));
    ASSERT_TRUE(resource.activateSubscriber(
        "collector_other", "other_agent", "10.0.0.5", 1,
        AgentSchedulerConfigR::hashJson(startupJson), startupJson,
        R"({"hardware":"RTX_PRO_5000"})"));
    ASSERT_TRUE(resource.getPendingAgentUpdate("collector_other", update));
    ASSERT_TRUE(AgentSchedulerConfigR::parse(update.configJson, expected, error)) << error;
    EXPECT_EQ(23, expected.batchTimeoutMs);
    EXPECT_DOUBLE_EQ(3.0, expected.latencyCurrentSampleWeight);
    EXPECT_DOUBLE_EQ(0.4, expected.residualLearningRate);
}

