TEST_F(NaviSchedResourceTest, testSchedulerConfigWaitsForEveryAgentAck)
{
    SchedulerConfigR resource;
    auto syncPipe = std::make_shared<CaptureAsyncPipe>();
    auto firstNotification = std::make_shared<CaptureAsyncPipe>();
    auto secondNotification = std::make_shared<CaptureAsyncPipe>();
    auto responsePipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource.setSyncPipe(syncPipe));
    ASSERT_TRUE(resource.subscribe("collector_a", firstNotification));
    ASSERT_TRUE(resource.subscribe("collector_b", secondNotification));

    AgentSchedulerConfig firstConfig;
    firstConfig.batchTimeoutMs = 11;
    const auto firstJson = AgentSchedulerConfigR::toJson(firstConfig);
    const auto firstHash = AgentSchedulerConfigR::hashJson(firstJson);
    AgentSchedulerConfig secondConfig;
    secondConfig.batchTimeoutMs = 17;
    const auto secondJson = AgentSchedulerConfigR::toJson(secondConfig);
    const auto secondHash = AgentSchedulerConfigR::hashJson(secondJson);
    ASSERT_TRUE(resource.activateSubscriber("collector_a", "agent_a", "10.0.0.1", 1,
                                            firstHash, firstJson));
    ASSERT_TRUE(resource.activateSubscriber("collector_b", "agent_b", "10.0.0.2", 1,
                                            secondHash, secondJson));

    SchedulerConfigR::Request request;
    request.update = true;
    request.configJson = R"({"residual_learning_rate":0.02})";
    request.responsePipe = responsePipe;
    ASSERT_TRUE(resource.submit(request));
    ASSERT_EQ(1, syncPipe->overrideCount);
    SchedulerConfigR::Request queued;
    ASSERT_TRUE(resource.takeRequest(queued));
    SchedulerConfigResponseDataPtr response;
    bool waitingForAgents = false;
    ASSERT_TRUE(resource.processRequest(queued, response, waitingForAgents));
    ASSERT_TRUE(waitingForAgents);
    ASSERT_FALSE(response);
    ASSERT_EQ(1, firstNotification->overrideCount);
    ASSERT_EQ(1, secondNotification->overrideCount);

    SchedulerConfigR::PendingAgentUpdate firstUpdate;
    SchedulerConfigR::PendingAgentUpdate secondUpdate;
    ASSERT_TRUE(resource.getPendingAgentUpdate("collector_a", firstUpdate));
    ASSERT_TRUE(resource.getPendingAgentUpdate("collector_b", secondUpdate));
    AgentSchedulerConfig expectedFirst;
    AgentSchedulerConfig expectedSecond;
    std::string error;
    ASSERT_TRUE(
        AgentSchedulerConfigR::parse(firstUpdate.configJson, expectedFirst, error))
        << error;
    ASSERT_TRUE(
        AgentSchedulerConfigR::parse(secondUpdate.configJson, expectedSecond, error))
        << error;
    EXPECT_EQ(11, expectedFirst.batchTimeoutMs);
    EXPECT_EQ(17, expectedSecond.batchTimeoutMs);
    EXPECT_DOUBLE_EQ(0.02, expectedFirst.residualLearningRate);
    EXPECT_DOUBLE_EQ(0.02, expectedSecond.residualLearningRate);

    resource.reportAgentConfig("collector_a", firstUpdate.requestGeneration,
                               firstUpdate.requestGeneration, firstUpdate.configHash,
                               firstUpdate.configJson, "");
    navi::AsyncPipePtr completedResponsePipe;
    EXPECT_FALSE(resource.finishAgentSync(false, response, completedResponsePipe));
    resource.reportAgentConfig("collector_b", secondUpdate.requestGeneration,
                               secondUpdate.requestGeneration, secondUpdate.configHash,
                               secondUpdate.configJson, "");
    ASSERT_TRUE(resource.finishAgentSync(false, response, completedResponsePipe));
    ASSERT_TRUE(response);
    EXPECT_TRUE(response->accepted) << response->error;
    EXPECT_EQ(2, response->targetAgentCount);
    EXPECT_EQ(2, response->updatedAgentCount);
    EXPECT_EQ(0, response->failedAgentCount);
    ASSERT_EQ(2, response->agentResults.size());
    EXPECT_TRUE(response->agentResults[0].updated);
    EXPECT_TRUE(response->agentResults[1].updated);
    EXPECT_EQ(responsePipe, completedResponsePipe);
    EXPECT_FALSE(resource.hasActiveAgentSync());
    EXPECT_EQ(0, resource._activeUpdateToken);
}

TEST_F(NaviSchedResourceTest, testSchedulerConfigReportsAgentFailureAndDisconnect)
{
    SchedulerConfigR resource;
    auto notificationPipe = std::make_shared<CaptureAsyncPipe>();
    auto responsePipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource.subscribe("collector", notificationPipe));
    AgentSchedulerConfig config;
    const auto configJson = AgentSchedulerConfigR::toJson(config);
    const auto configHash = AgentSchedulerConfigR::hashJson(configJson);
    ASSERT_TRUE(resource.activateSubscriber("collector", "agent", "10.0.0.9", 3,
                                            configHash, configJson));

    SchedulerConfigR::Request request;
    request.update = true;
    request.configJson = R"({"queue_learning_rate":0.03})";
    request.responsePipe = responsePipe;
    SchedulerConfigResponseDataPtr response;
    bool waitingForAgents = false;
    ASSERT_TRUE(resource.processRequest(request, response, waitingForAgents));
    ASSERT_TRUE(waitingForAgents);
    SchedulerConfigR::PendingAgentUpdate pending;
    ASSERT_TRUE(resource.getPendingAgentUpdate("collector", pending));
    resource.reportAgentConfig("collector", pending.requestGeneration, 3, configHash,
                               configJson, "apply failed");
    navi::AsyncPipePtr completedResponsePipe;
    ASSERT_TRUE(resource.finishAgentSync(false, response, completedResponsePipe));
    ASSERT_TRUE(response);
    EXPECT_FALSE(response->accepted);
    EXPECT_EQ(1, response->targetAgentCount);
    EXPECT_EQ(0, response->updatedAgentCount);
    EXPECT_EQ(1, response->failedAgentCount);
    ASSERT_EQ(1, response->agentResults.size());
    EXPECT_FALSE(response->agentResults[0].updated);
    EXPECT_EQ("10.0.0.9", response->agentResults[0].ip);
    EXPECT_EQ("apply failed", response->agentResults[0].error);
    EXPECT_EQ(configHash, response->agentResults[0].effectiveHash);
    EXPECT_EQ(configJson, response->agentResults[0].effectiveConfigJson);
    EXPECT_NE(std::string::npos, response->error.find("10.0.0.9"));
    EXPECT_NE(std::string::npos, response->error.find("apply failed"));
    EXPECT_NE(std::string::npos, response->error.find(configHash));

    request.configJson = R"({"queue_learning_rate":0.04})";
    ASSERT_TRUE(resource.processRequest(request, response, waitingForAgents));
    ASSERT_TRUE(waitingForAgents);
    ASSERT_TRUE(resource.getPendingAgentUpdate("collector", pending));
    resource.unsubscribe("collector", notificationPipe);
    ASSERT_TRUE(resource.finishAgentSync(false, response, completedResponsePipe));
    ASSERT_FALSE(response->accepted);
    EXPECT_EQ(1, response->targetAgentCount);
    EXPECT_EQ(0, response->updatedAgentCount);
    EXPECT_EQ(1, response->failedAgentCount);
    EXPECT_NE(std::string::npos, response->error.find("disconnected"));
}

