        resource.getAgentSyncRemainingTimeoutMs(autil::TimeUtility::monotonicTimeUs());
    EXPECT_GT(remainingMs, 9000);
    EXPECT_LE(remainingMs, 10000);
    navi::AsyncPipePtr completedResponsePipe;
