TEST_F(NaviSchedResourceTest, testMasterScheduleRejectsAfterTerminatedPipe)
{
    MasterScheduleR resource;
    const auto oldGeneration = resource.beginRequestPipeGeneration();
    ASSERT_GT(oldGeneration, 0);
    ASSERT_TRUE(
        resource.setRequestPipe(oldGeneration, std::make_shared<RejectedAsyncPipe>()));
    auto request = std::make_shared<ClientRequestToMasterData>();
    request->requestId = 1;
    auto responsePipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_FALSE(resource.submit(request, responsePipe));
    ASSERT_EQ(1, responsePipe->datas.size());
    auto rejected = std::dynamic_pointer_cast<MasterResponseToClientData>(
        responsePipe->datas.front());
    ASSERT_TRUE(rejected);
    EXPECT_EQ(1, rejected->requestId);
    EXPECT_EQ("master_restarting", rejected->reason);
    EXPECT_TRUE(responsePipe->eof);
    EXPECT_EQ(0, resource.getPendingRequestCount());

    auto replacement = std::make_shared<CaptureAsyncPipe>();
    const auto replacementGeneration = resource.beginRequestPipeGeneration();
    ASSERT_GT(replacementGeneration, oldGeneration);
    ASSERT_TRUE(resource.setRequestPipe(replacementGeneration, replacement));
    ASSERT_TRUE(resource.submit(request, std::make_shared<CaptureAsyncPipe>()));
    ASSERT_EQ(1, replacement->datas.size());
    EXPECT_EQ(0, resource.getPendingRequestCount());
}

TEST_F(NaviSchedResourceTest, testMasterScheduleSlowPathClearsTerminatedPipe)
{
    MasterScheduleR resource;
    auto rejectedPipe = std::make_shared<RejectedAsyncPipe>();
    auto request = std::make_shared<ClientRequestToMasterData>();
    request->requestId = 1;
    const auto rejectedGeneration = resource.beginRequestPipeGeneration();
    ASSERT_GT(rejectedGeneration, 0);

    std::promise<void> setterStarted;
    std::future<bool> setterResult;
    std::future<bool> submitResult;
    {
        autil::ScopedReadLock holdReadLock(resource._lock);
        setterResult = std::async(std::launch::async, [&]() {
            setterStarted.set_value();
            return resource.setRequestPipe(rejectedGeneration, rejectedPipe);
        });
        setterStarted.get_future().wait();
        std::this_thread::sleep_for(std::chrono::milliseconds(10));

        submitResult = std::async(std::launch::async, [&]() {
            return bool(resource.submit(request, std::make_shared<CaptureAsyncPipe>()));
        });
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(1);
        while (resource._nextCanonicalRequestId.load(std::memory_order_relaxed) == 1 &&
               std::chrono::steady_clock::now() < deadline) {
            std::this_thread::yield();
        }
        ASSERT_EQ(2, resource._nextCanonicalRequestId.load(std::memory_order_relaxed));
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    ASSERT_TRUE(setterResult.get());
    ASSERT_FALSE(submitResult.get());
    EXPECT_EQ(0, resource.getPendingRequestCount());
    auto replacementPipe = std::make_shared<CaptureAsyncPipe>();
    const auto replacementGeneration = resource.beginRequestPipeGeneration();
    ASSERT_GT(replacementGeneration, rejectedGeneration);
    EXPECT_TRUE(resource.setRequestPipe(replacementGeneration, replacementPipe));
    EXPECT_TRUE(replacementPipe->datas.empty());
}

