TEST_F(NaviSchedResourceTest, testWaitMasterScheduleRequestPipeStopsForRetiredGeneration)
{
    MasterScheduleR resource;
    const auto oldGeneration = resource.beginRequestPipeGeneration();
    ASSERT_GT(oldGeneration, 0);

    auto oldWaiter = std::async(std::launch::async, [&]() {
        return resource.waitRequestPipe(oldGeneration, 1000);
    });
    const auto replacementGeneration = resource.beginRequestPipeGeneration();
    ASSERT_GT(replacementGeneration, oldGeneration);
    EXPECT_FALSE(oldWaiter.get());
    EXPECT_FALSE(resource.waitRequestPipe(oldGeneration, 0));
    EXPECT_FALSE(resource.waitRequestPipe(replacementGeneration, 1));

    auto stoppedWaiter = std::async(std::launch::async, [&]() {
        return resource.waitRequestPipe(replacementGeneration, 1000);
    });
    resource.stop();
    EXPECT_FALSE(stoppedWaiter.get());
}

TEST_F(NaviSchedResourceTest, testLateScheduleGraphCleanupDoesNotClearReplacementPipe)
{
    MasterScheduleR resource;
    auto oldPipe = std::make_shared<CaptureAsyncPipe>();
    const auto oldGeneration = resource.beginRequestPipeGeneration();
    ASSERT_TRUE(resource.setRequestPipe(oldGeneration, oldPipe));
    resource.clearRequestPipe(oldGeneration);

    auto replacementPipe = std::make_shared<CaptureAsyncPipe>();
    const auto replacementGeneration = resource.beginRequestPipeGeneration();
    ASSERT_TRUE(resource.setRequestPipe(replacementGeneration, replacementPipe));

    // A late old-graph closure must not clear a pipe installed by its successor.
    resource.clearRequestPipe(oldGeneration);
    auto request = std::make_shared<ClientRequestToMasterData>();
    request->requestId = 3;
    ASSERT_TRUE(resource.submit(request, std::make_shared<CaptureAsyncPipe>()));
    EXPECT_EQ(1, replacementPipe->datas.size());
    EXPECT_EQ(0, resource.getPendingRequestCount());
}

TEST_F(NaviSchedResourceTest, testMasterScheduleRequestLifecycle)
{
    auto request = std::make_shared<ClientRequestToMasterData>();
    request->requestId = 1;
    auto responsePipe = std::make_shared<CaptureAsyncPipe>();
    auto requestData = std::make_shared<MasterScheduleRequestData>(request, responsePipe);
    auto sharedRequestData = requestData;
    auto response = std::make_shared<MasterResponseToClientData>();
    response->requestId = request->requestId;

    ASSERT_TRUE(requestData->finish(response));
    ASSERT_FALSE(sharedRequestData->finish(response));
    ASSERT_EQ(1, responsePipe->datas.size());
    ASSERT_EQ(response, responsePipe->datas.front());
    ASSERT_TRUE(responsePipe->eof);
    ASSERT_EQ(1, responsePipe->eofCount);
    requestData.reset();
    sharedRequestData.reset();
    ASSERT_EQ(1, responsePipe->eofCount);

    auto cancelledPipe = std::make_shared<CaptureAsyncPipe>();
    {
        auto cancelled =
            std::make_shared<MasterScheduleRequestData>(request, cancelledPipe);
    }
    ASSERT_TRUE(cancelledPipe->eof);
    ASSERT_EQ(1, cancelledPipe->eofCount);
}

TEST_F(NaviSchedResourceTest,
       testMasterResponseReadsPublishedGlobalZeroPointForSelectedAgent)
{
    NaviSchedScheduleContext context;
    LatencyModelGlobalData global;
    global.masterEpoch = 100;
    global.version = 7;
    global.formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    global.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    global.parameterCount = NonLinearPrefillModelR::CAPACITY_SPLIT_PARAMETER_COUNT;
    global.globalZeroPoint = 9.5;
    context._latencyModelGlobals.emplace("127.0.0.1:19000", global);

    NaviSchedDecision decision;
    decision.requestId = 11;
    decision.target.agentAddress = "127.0.0.1:19000";
    auto response = context.makeResponse(decision);
    ASSERT_TRUE(response);
    ASSERT_TRUE(response->latencyModelGlobal.valid());
    EXPECT_EQ(global.version, response->latencyModelGlobal.version);
    EXPECT_DOUBLE_EQ(global.globalZeroPoint,
                     response->latencyModelGlobal.globalZeroPoint);

    decision.target.agentAddress = "127.0.0.1:19001";
    response = context.makeResponse(decision);
    ASSERT_TRUE(response);
    EXPECT_FALSE(response->latencyModelGlobal.valid());
}

TEST_F(NaviSchedResourceTest, testMasterScheduleRequestId)
{
    const auto firstSeed = MasterScheduleR::makeRequestIdSeed("10.0.0.1", 1000);
    const auto sameSeed = MasterScheduleR::makeRequestIdSeed("10.0.0.1", 1000);
    const auto anotherMasterSeed = MasterScheduleR::makeRequestIdSeed("10.0.0.2", 1000);
    const auto anotherStartupSeed = MasterScheduleR::makeRequestIdSeed("10.0.0.1", 1001);
    EXPECT_NE(0, firstSeed);
    EXPECT_EQ(firstSeed, sameSeed);
    EXPECT_NE(firstSeed, anotherMasterSeed);
    EXPECT_NE(firstSeed, anotherStartupSeed);

    MasterScheduleR resource;
    auto requestPipe = std::make_shared<CaptureAsyncPipe>();
    const auto generation = resource.beginRequestPipeGeneration();
    ASSERT_TRUE(resource.setRequestPipe(generation, requestPipe));
    for (size_t index = 0; index < 3; ++index) {
        auto request = std::make_shared<ClientRequestToMasterData>();
        request->requestId = 100 + index;
        ASSERT_TRUE(resource.submit(request, std::make_shared<CaptureAsyncPipe>()));
        EXPECT_EQ(100 + index, request->requestId);
    }
    ASSERT_EQ(3, requestPipe->datas.size());
    for (size_t index = 0; index < requestPipe->datas.size(); ++index) {
        auto request = std::dynamic_pointer_cast<MasterScheduleRequestData>(
            requestPipe->datas[index]);
        ASSERT_TRUE(request);
        ASSERT_TRUE(request->request);
        EXPECT_EQ(index + 1, request->request->requestId);
        EXPECT_NE(100 + index, request->request->requestId);
    }

    MasterScheduleR wrappingResource;
    wrappingResource._nextCanonicalRequestId.store(std::numeric_limits<uint64_t>::max(),
                                                   std::memory_order_relaxed);
    auto wrappingPipe = std::make_shared<CaptureAsyncPipe>();
    const auto wrappingGeneration = wrappingResource.beginRequestPipeGeneration();
    ASSERT_TRUE(wrappingResource.setRequestPipe(wrappingGeneration, wrappingPipe));
    auto wrappingRequest = std::make_shared<ClientRequestToMasterData>();
    wrappingRequest->requestId = 999;
    ASSERT_TRUE(
        wrappingResource.submit(wrappingRequest, std::make_shared<CaptureAsyncPipe>()));
    ASSERT_TRUE(
        wrappingResource.submit(wrappingRequest, std::make_shared<CaptureAsyncPipe>()));
    ASSERT_EQ(2, wrappingPipe->datas.size());
    auto maximum =
        std::dynamic_pointer_cast<MasterScheduleRequestData>(wrappingPipe->datas[0]);
    auto afterWrap =
        std::dynamic_pointer_cast<MasterScheduleRequestData>(wrappingPipe->datas[1]);
    ASSERT_TRUE(maximum && maximum->request);
    ASSERT_TRUE(afterWrap && afterWrap->request);
    EXPECT_EQ(std::numeric_limits<uint64_t>::max(), maximum->request->requestId);
    EXPECT_EQ(1, afterWrap->request->requestId);
}

