TEST_F(NaviSchedResourceTest, testAgentOnlineModelUpdateRecomputesOnlyWaitingInflight)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init());
    auto resource = context.get();
    ASSERT_TRUE(resource);
    auto tracker = std::make_shared<ConcurrentRequestLatencyTracker>();
    auto prediction = std::make_shared<NaviSchedLatencyPrediction>();
    ASSERT_TRUE(prediction->features.appendBatchCount(1));
    prediction->features.appendRequest(0, 1024);
    prediction->fixedLatencyMs = 7.0;
    prediction->recomputable = true;
    RequestLatencyTracker::Snapshot inflight;
    ASSERT_TRUE(tracker->add(101, 100.0, prediction, inflight));
    ASSERT_TRUE(tracker->add(102, 200.0, prediction, inflight));
    ASSERT_TRUE(tracker->markRunning({102}, inflight));
    ASSERT_TRUE(resource->setInflightTracker(tracker));

    auto pipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("collector", pipe));
    auto snapshot = std::make_shared<NaviSchedLatencyModelSnapshot>();
    snapshot->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    snapshot->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    snapshot->revision = 9;
    snapshot->parameters.assign(NonLinearPrefillModelR::PARAMETER_COUNT, 1.0);
    snapshot->onlineFitUpdate = true;
    const auto expectedWaitingLatency =
        NonLinearPrefillModelR::predict(prediction->features, snapshot->parameters) +
        prediction->fixedLatencyMs;

    ASSERT_EQ(1, resource->reportLatencyModelUpdated(snapshot));
    const auto recomputed = tracker->snapshot();
    EXPECT_EQ(4, recomputed.revision);
    EXPECT_EQ(2, recomputed.requestCount);
    EXPECT_DOUBLE_EQ(expectedWaitingLatency + 200.0, recomputed.totalPredictedLatencyMs);
    EXPECT_EQ(1, recomputed.recomputeCount);
    EXPECT_EQ(1, recomputed.recomputedRequestCount);

    auto update = dynamic_cast<AgentUpdateToMasterData *>(pipe->datas.back().get());
    ASSERT_TRUE(update);
    ASSERT_TRUE(update->valid());
    ASSERT_TRUE(update->latency);
    ASSERT_TRUE(update->requestEvent);
    EXPECT_EQ(snapshot->revision, update->latency->modelRevision);
    EXPECT_EQ(recomputed.revision, update->requestEvent->inflightStatsRevision);
    EXPECT_EQ(recomputed.requestCount, update->requestEvent->inflightRequests);
    EXPECT_DOUBLE_EQ(recomputed.totalPredictedLatencyMs,
                     update->requestEvent->inflightPredictedLatencySumMs);

    auto sessionProgress = std::make_shared<NaviSchedLatencyModelSnapshot>(*snapshot);
    sessionProgress->onlineFitUpdate = false;
    sessionProgress->sessionSampleCount = 32;
    ASSERT_EQ(1, resource->reportLatencyModelUpdated(sessionProgress));
    const auto afterProgress = tracker->snapshot();
    EXPECT_EQ(recomputed.revision, afterProgress.revision);
    EXPECT_EQ(recomputed.requestCount, afterProgress.requestCount);
    EXPECT_DOUBLE_EQ(recomputed.totalPredictedLatencyMs,
                     afterProgress.totalPredictedLatencyMs);
    EXPECT_EQ(recomputed.recomputeCount, afterProgress.recomputeCount);
    EXPECT_EQ(recomputed.recomputedRequestCount, afterProgress.recomputedRequestCount);

    update = dynamic_cast<AgentUpdateToMasterData *>(pipe->datas.back().get());
    ASSERT_TRUE(update);
    ASSERT_TRUE(update->valid());
    ASSERT_TRUE(update->latency);
    ASSERT_TRUE(update->requestEvent);
    EXPECT_EQ(snapshot->revision, update->latency->modelRevision);
    EXPECT_EQ(snapshot->parameters, update->latency->parameters);
    EXPECT_EQ(32, update->latency->sessionSampleCount);
    EXPECT_EQ(afterProgress.revision, update->requestEvent->inflightStatsRevision);
    EXPECT_EQ(afterProgress.requestCount, update->requestEvent->inflightRequests);
    EXPECT_DOUBLE_EQ(afterProgress.totalPredictedLatencyMs,
                     update->requestEvent->inflightPredictedLatencySumMs);
}

TEST_F(NaviSchedResourceTest, testDisablingResidualRecomputesWaitingInflight)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init());
    auto resource = context.get();
    ASSERT_TRUE(resource);
    auto configResource = resource->_agentSchedulerConfigR;
    ASSERT_TRUE(configResource);
    AgentSchedulerConfigR::Snapshot configSnapshot;
    std::string error;
    const auto applyConfig = [&](uint64_t generation, double residualRate) {
        auto config = configResource->get().config;
        config.residualLearningRate = residualRate;
        const auto json = AgentSchedulerConfigR::toJson(config);
        return configResource->apply(generation, AgentSchedulerConfigR::hashJson(json),
                                     json, configSnapshot, error);
    };
    ASSERT_EQ(AgentSchedulerConfigR::ApplyResult::APPLIED, applyConfig(2, 0.03)) << error;

    auto snapshot = std::make_shared<NaviSchedLatencyModelSnapshot>();
    snapshot->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    snapshot->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    snapshot->revision = 9;
    snapshot->parameters.assign(NonLinearPrefillModelR::PARAMETER_COUNT, 1.0);
    std::fill(snapshot->residualParameters.begin() + 1,
              snapshot->residualParameters.end() - 1, 30.0);
    snapshot->residualLastUpdateTimeUs = autil::TimeUtility::currentTime();
    ASSERT_TRUE(snapshot->valid());

    auto prediction = std::make_shared<NaviSchedLatencyPrediction>();
    ASSERT_TRUE(prediction->features.appendBatchCount(1));
    prediction->features.appendRequest(0, 1024);
    prediction->fixedLatencyMs = 7.0;
    prediction->recomputable = true;
    const auto base = NonLinearPrefillModelR::predict(
        prediction->features, snapshot->parameters);
    const auto withResidual = LatencyResidualModel::evaluate(
        base, snapshot->residualParameters, snapshot->residualLastUpdateTimeUs,
        snapshot->residualLastUpdateTimeUs, configSnapshot.config.residualRuntimeConfig());
    ASSERT_GT(withResidual.correctionMs, 0.0);
    auto tracker = std::make_shared<ConcurrentRequestLatencyTracker>();
    RequestLatencyTracker::Snapshot inflight;
    ASSERT_TRUE(tracker->add(101, withResidual.predictionMs + 7.0, prediction, inflight));
    ASSERT_TRUE(tracker->add(102, 200.0, prediction, inflight));
    ASSERT_TRUE(tracker->markRunning({102}, inflight));
    ASSERT_TRUE(resource->setInflightTracker(tracker));
    auto pipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("collector", pipe));
    ASSERT_EQ(1, resource->reportLatencyModelUpdated(snapshot));

    ASSERT_EQ(AgentSchedulerConfigR::ApplyResult::APPLIED, applyConfig(3, 0.0)) << error;
    auto disabled = std::make_shared<NaviSchedLatencyModelSnapshot>(*snapshot);
    disabled->onlineFitUpdate = false;
    ASSERT_EQ(1, resource->reportLatencyModelUpdated(disabled, true));
    const auto updated = tracker->snapshot();
    EXPECT_DOUBLE_EQ(base + 7.0 + 200.0, updated.totalPredictedLatencyMs);
    EXPECT_EQ(1, updated.recomputeCount);
    EXPECT_EQ(1, updated.recomputedRequestCount);
    auto event = dynamic_cast<AgentUpdateToMasterData *>(pipe->datas.back().get());
    ASSERT_TRUE(event);
    ASSERT_TRUE(event->requestEvent);
    EXPECT_EQ(updated.revision, event->requestEvent->inflightStatsRevision);
    EXPECT_DOUBLE_EQ(updated.totalPredictedLatencyMs,
                     event->requestEvent->inflightPredictedLatencySumMs);

    TestMasterStateR master;
    auto masterNode = master.registerAgent("agent_0", "agent_biz",
                                           "127.0.0.1:19000", 0);
    ASSERT_TRUE(masterNode);
    auto modelUpdate = std::dynamic_pointer_cast<AgentUpdateToMasterData>(
        pipe->datas.back());
    ASSERT_TRUE(master.reportAgent("agent_0", modelUpdate));
    EXPECT_DOUBLE_EQ(updated.totalPredictedLatencyMs,
                     masterNode->getInfo().inflightPredictedLatencySumMs);
    ASSERT_EQ(1, resource->reportSchedulerConfigUpdated(
        3, configSnapshot.generation, configSnapshot.configHash,
        configSnapshot.configJson, ""));
    auto configUpdate = std::dynamic_pointer_cast<AgentUpdateToMasterData>(
        pipe->datas.back());
    ASSERT_TRUE(master.reportAgent("agent_0", configUpdate));
    EXPECT_DOUBLE_EQ(0.0, masterNode->getResidualRuntimeConfig().learningRate);
    EXPECT_DOUBLE_EQ(updated.totalPredictedLatencyMs,
                     masterNode->getInfo().inflightPredictedLatencySumMs);
}
