TEST_F(NaviSchedResourceTest, testConcurrentCollectorsGetConsistentLatencyModelMetadata)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init(19000, "10.0.0.1", 0, false, true, false, false,
                             "stable-model-fingerprint"));
    auto resource = context.get();
    constexpr size_t UPDATE_COUNT = 200;
    constexpr size_t COLLECTOR_COUNT = 100;
    constexpr size_t COLLECTOR_THREAD_COUNT = 4;
    auto initialSnapshot = std::make_shared<NaviSchedLatencyModelSnapshot>();
    initialSnapshot->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    initialSnapshot->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    initialSnapshot->revision = 1;
    initialSnapshot->parameters =
        std::vector<double>(NonLinearPrefillModelR::PARAMETER_COUNT, 1.0);
    initialSnapshot->overloadPredictionTrusted = false;
    initialSnapshot->warmStarted = false;
    resource->setLatencyModelSnapshot(initialSnapshot);

    std::atomic<bool> start{false};
    std::thread updater([&]() {
        while (!start.load(std::memory_order_acquire)) {
            std::this_thread::yield();
        }
        for (size_t revision = 2; revision <= UPDATE_COUNT; ++revision) {
            auto snapshot = std::make_shared<NaviSchedLatencyModelSnapshot>();
            snapshot->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
            snapshot->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
            snapshot->revision = revision;
            snapshot->parameters = std::vector<double>(
                NonLinearPrefillModelR::PARAMETER_COUNT, static_cast<double>(revision));
            snapshot->overloadPredictionTrusted = revision % 2 == 0;
            snapshot->warmStarted = revision % 3 == 0;
            resource->setLatencyModelSnapshot(snapshot);
            std::this_thread::yield();
        }
    });

    std::vector<std::shared_ptr<CaptureAsyncPipe>> pipes(COLLECTOR_COUNT);
    std::vector<uint8_t> subscribeResults(COLLECTOR_COUNT, 0);
    std::vector<std::thread> collectors;
    for (size_t threadIndex = 0; threadIndex < COLLECTOR_THREAD_COUNT; ++threadIndex) {
        collectors.emplace_back([&, threadIndex]() {
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }
            for (size_t i = threadIndex; i < COLLECTOR_COUNT;
                 i += COLLECTOR_THREAD_COUNT) {
                auto pipe = std::make_shared<CaptureAsyncPipe>();
                subscribeResults[i] =
                    resource->subscribe("collector_" + std::to_string(i), pipe);
                pipes[i] = std::move(pipe);
            }
        });
    }
    start.store(true, std::memory_order_release);
    for (auto &collector : collectors) {
        collector.join();
    }
    updater.join();

    for (size_t i = 0; i < COLLECTOR_COUNT; ++i) {
        ASSERT_TRUE(subscribeResults[i]);
        const auto &pipe = pipes[i];
        ASSERT_TRUE(pipe);
        ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT, pipe->datas.size());
        auto handshake =
            dynamic_cast<AgentUpdateToMasterData *>(pipe->datas.front().get());
        ASSERT_TRUE(handshake);
        ASSERT_TRUE(handshake->latency);
        const auto revision = handshake->latency->modelRevision;
        ASSERT_GE(revision, 1);
        ASSERT_LE(revision, UPDATE_COUNT);
        EXPECT_EQ(static_cast<double>(revision), handshake->latency->parameters.front());
        EXPECT_EQ(revision % 2 == 0, handshake->latencyModelTrusted);
        EXPECT_EQ(revision % 3 == 0, handshake->latencyModelWarmStarted);
        EXPECT_EQ("stable-model-fingerprint", handshake->latencyModelFingerprint);
    }
}

TEST_F(NaviSchedResourceTest, testAgentPublishesMonotonicWorkloadAndRestoresHandshake)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init(18000, "127.0.0.1", 0, false, false, true));
    auto resource = context.get();
    auto firstPipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("first_collector", firstPipe));
    auto firstHandshake =
        dynamic_cast<AgentUpdateToMasterData *>(firstPipe->datas.front().get());
    ASSERT_TRUE(firstHandshake);
    ASSERT_FALSE(firstHandshake->control->pdSeparated);
    ASSERT_FALSE(firstHandshake->workload);
    const auto *baseHandshake = resource->_handshake.get();

    NaviSchedWorkloadSnapshot workload;
    workload.revision = 99;
    workload.eventTimeUs = 123456;
    workload.requestCount = 2;
    workload.remainingPrefillRequestCount = 1;
    workload.remainingPrefillContextTokenCount = 16;
    workload.remainingPrefillTokenCount = 32;
    workload.remainingPrefillTokenSquareSum = 1024.0;
    workload.contextRemainingPrefillTokenProductSum = 512.0;
    workload.remainingTotalContextTokenCount = 16;
    workload.remainingTotalTokenCount = 64;
    workload.remainingTotalTokenSquareSum = 4096.0;
    workload.contextRemainingTotalTokenProductSum = 1024.0;
    workload.totalPromptTokenCount = 48;
    workload.inFlightScheduledTokenCount = 8;
    ASSERT_EQ(1, resource->reportWorkloadUpdated(workload));
    ASSERT_EQ(baseHandshake, resource->_handshake.get());
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT + 1, firstPipe->datas.size());
    ASSERT_EQ(1, resource->reportWorkloadUpdated(workload));
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT + 1, firstPipe->datas.size());

    auto stored = resource->getWorkloadSnapshot();
    ASSERT_TRUE(stored);
    ASSERT_EQ(1, stored->revision);
    workload.admittedBatch = makeLocalBatchInfo(17, 71, 2);
    ASSERT_EQ(2, resource->reportWorkloadUpdated(workload));
    stored = resource->getWorkloadSnapshot();
    ASSERT_TRUE(stored);
    ASSERT_EQ(2, stored->revision);
    ASSERT_TRUE(stored->admittedBatch.empty());
    auto admittedUpdate =
        dynamic_cast<AgentUpdateToMasterData *>(firstPipe->datas.back().get());
    ASSERT_TRUE(admittedUpdate);
    ASSERT_TRUE(admittedUpdate->workload);
    ASSERT_EQ(2, admittedUpdate->workload->revision);
    ASSERT_EQ(17, admittedUpdate->workload->admittedBatch.scheduleBatchId);
    ASSERT_EQ(71, admittedUpdate->workload->admittedBatch.localBatchId);
    auto secondPipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("second_collector", secondPipe));
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT, secondPipe->datas.size());
    auto secondHandshake =
        dynamic_cast<AgentUpdateToMasterData *>(secondPipe->datas.front().get());
    ASSERT_TRUE(secondHandshake);
    ASSERT_TRUE(secondHandshake->workload);
    ASSERT_EQ(2, secondHandshake->workload->revision);
    ASSERT_EQ(2, secondHandshake->workload->requestCount);
    ASSERT_EQ(2, resource->getStats().publishedWorkloadUpdateCount);
    const auto publishStats = resource->takeWorkloadPublishWindowStats();
    ASSERT_EQ(2, publishStats.sampleCount);
    ASSERT_GE(publishStats.totalTimeUs, 0);
    ASSERT_GE(publishStats.maxTimeUs, 0);
    ASSERT_EQ(0, resource->takeWorkloadPublishWindowStats().sampleCount);
}

TEST_F(NaviSchedResourceTest, testBlockedWorkloadDeliveryDoesNotBlockSnapshotUpdate)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init(18000, "127.0.0.1", 0, false, false, true));
    auto resource = context.get();
    auto pipe = std::make_shared<BlockingWorkloadAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("collector", pipe));

    NaviSchedWorkloadSnapshot first;
    first.eventTimeUs = 100;
    first.batchCount = 1;
    first.requestCount = 1;
    first.remainingPrefillRequestCount = 1;
    first.remainingPrefillTokenCount = 32;
    first.remainingPrefillTokenSquareSum = 1024.0;
    first.remainingTotalTokenCount = 32;
    first.remainingTotalTokenSquareSum = 1024.0;
    first.totalPromptTokenCount = 32;
    uint64_t firstRevision = 0;
    std::thread firstReporter(
        [&]() { firstRevision = resource->reportWorkloadUpdated(first); });
    const bool blocked = pipe->waitUntilBlocked();
    if (!blocked) {
        pipe->release();
        firstReporter.join();
    }
    ASSERT_TRUE(blocked);

    auto second = first;
    second.eventTimeUs = 200;
    second.requestCount = 2;
    second.batchCount = 2;
    second.remainingPrefillRequestCount = 2;
    second.remainingPrefillTokenCount = 64;
    second.remainingPrefillTokenSquareSum = 2048.0;
    second.remainingTotalTokenCount = 64;
    second.remainingTotalTokenSquareSum = 2048.0;
    second.totalPromptTokenCount = 64;
    uint64_t secondRevision = 0;
    std::thread secondReporter(
        [&]() { secondRevision = resource->reportWorkloadUpdated(second); });

    NaviSchedWorkloadSnapshotConstPtr current;
    for (size_t retry = 0; retry < 100; ++retry) {
        current = resource->getWorkloadSnapshot();
        if (current && current->revision == 2) {
            break;
        }
        usleep(1000);
    }
    pipe->release();
    firstReporter.join();
    secondReporter.join();
    ASSERT_TRUE(current);
    EXPECT_EQ(2, current->revision);
    EXPECT_EQ(2, current->batchCount);
    EXPECT_EQ(1, firstRevision);
    EXPECT_EQ(2, secondRevision);
}

TEST_F(NaviSchedResourceTest, testAgentSendsCacheSnapshotAfterHandshake)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init(0, "", 100));
    auto resource = context.get();

    auto beforePolicyPipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("before_policy", beforePolicyPipe));
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT, beforePolicyPipe->datas.size());
    auto beforePolicySnapshot =
        dynamic_cast<AgentUpdateToMasterData *>(beforePolicyPipe->datas[1].get());
    ASSERT_TRUE(beforePolicySnapshot);
    ASSERT_TRUE(beforePolicySnapshot->cache);
    EXPECT_EQ(-1, beforePolicySnapshot->cache->blockSize);
    EXPECT_EQ(-1, beforePolicySnapshot->cache->linearStep);
    EXPECT_EQ(-1, beforePolicySnapshot->cache->hybridTailRequired);
    ASSERT_TRUE(resource->unsubscribe("before_policy", beforePolicyPipe));

    NaviSchedBatchRequest beforePolicy;
    beforePolicy.requestId = 1;
    beforePolicy.totalTokenCount = 256;
    EXPECT_FALSE(resource->makeRequestAudit(beforePolicy).valid);

    NaviSchedCacheUpdate incompletePolicy;
    incompletePolicy.hybridTailRequired = 0;
    EXPECT_EQ(0, resource->reportCacheUpdated(incompletePolicy));
    EXPECT_FALSE(resource->makeRequestAudit(beforePolicy).valid);

    NaviSchedCacheUpdate firstUpdate;
    firstUpdate.totalBlocks = 100;
    firstUpdate.blockSize = 256;
    firstUpdate.linearStep = 1;
    firstUpdate.hybridTailRequired = 0;
    firstUpdate.addedBlockHashes = makeBlockHashes({11, 22});
    firstUpdate.eventTimeUs = 100;
    ASSERT_EQ(0, resource->reportCacheUpdated(firstUpdate));

    NaviSchedCacheUpdate secondUpdate;
    secondUpdate.removedBlockHashes = makeBlockHashes({11});
    secondUpdate.eventTimeUs = 110;
    ASSERT_EQ(0, resource->reportCacheUpdated(secondUpdate));

    auto pipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("collector", pipe));
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT, pipe->datas.size());
    auto handshake = dynamic_cast<AgentUpdateToMasterData *>(pipe->datas[0].get());
    auto cache = dynamic_cast<AgentUpdateToMasterData *>(pipe->datas[1].get());
    ASSERT_TRUE(handshake);
    ASSERT_TRUE(cache);
    ASSERT_TRUE(handshake->control);
    ASSERT_TRUE(cache->cache);
    ASSERT_EQ(NaviSchedAgentEvent::AGENT_HANDSHAKE, handshake->event);
    ASSERT_EQ(100, cache->cache->totalBlocks);
    ASSERT_EQ(256, cache->cache->blockSize);
    ASSERT_EQ(1, cache->cache->linearStep);
    ASSERT_EQ(1, cache->cache->addedBlockHashes->size());
    ASSERT_EQ(0, BlockHashUtil::size(cache->cache->removedBlockHashes));

    NaviSchedBatchRequest hitRequest;
    hitRequest.requestId = 1;
    hitRequest.totalTokenCount = 700;
    hitRequest.blockHashes = makeBlockHashes({22, 33, 22});
    auto hitStats = resource->makeRequestStats(hitRequest);
    ASSERT_EQ(256, hitStats.cacheHitTokenCount);
    const auto requestAudit = resource->makeRequestAudit(hitRequest);
    EXPECT_EQ(256, requestAudit.stats.cacheHitTokenCount);
    EXPECT_EQ(2, requestAudit.cacheState.revision);
    EXPECT_EQ(1, requestAudit.cacheState.cachedBlockCount);
    EXPECT_GT(requestAudit.eventTimeUs, 0);
    EXPECT_FALSE(requestAudit.hybridTailRequired);
    hitRequest.blockSize = 16;
    const auto mismatchAudit = resource->makeRequestAudit(hitRequest);
    EXPECT_FALSE(mismatchAudit.valid);
    ASSERT_EQ(0, mismatchAudit.stats.cacheHitTokenCount);
}

