TEST_F(NaviSchedResourceTest,
       testCompletedPendingCacheRetiresWithoutMatchingCacheEvents)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init());
    auto resource = context.get();
    NaviSchedCacheUpdate policy;
    policy.blockSize = 1;
    policy.linearStep = 1;
    policy.hybridTailRequired = 0;
    ASSERT_EQ(0, resource->reportCacheUpdated(policy));

    auto pipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("collector", pipe));
    NaviSchedPendingCacheReservation completed;
    completed.batchId = 7;
    completed.scheduleBatchId = 70;
    completed.fullReadyBlockHashes = {11, 22};
    ASSERT_TRUE(resource->reportPendingCacheReady(completed));
    auto active = completed;
    active.batchId = 8;
    active.fullReadyBlockHashes = {11, 33};
    ASSERT_TRUE(resource->reportPendingCacheReady(active));

    ASSERT_TRUE(resource->reportPendingCacheCompleted(7));
    EXPECT_EQ(1, resource->getPendingCacheState().batchCount);
    EXPECT_EQ(2, resource->getPendingCacheState().uniqueBlockCount);
    EXPECT_EQ(0, resource->getCacheState().cachedBlockCount);
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT + 3, pipe->datas.size());
    auto removal = dynamic_cast<AgentUpdateToMasterData *>(pipe->datas.back().get());
    ASSERT_TRUE(removal);
    ASSERT_TRUE(removal->pendingCache);
    EXPECT_EQ(std::vector<int64_t>({7}), removal->pendingCache->removedBatchIds);
    EXPECT_EQ(1, removal->pendingCache->batchCount);

    NaviSchedCacheUpdate lateCache;
    lateCache.addedBlockHashes = makeBlockHashes({11, 22});
    ASSERT_EQ(1, resource->reportCacheUpdated(lateCache));
    EXPECT_EQ(2, resource->getCacheState().cachedBlockCount);
    EXPECT_EQ(1, resource->getPendingCacheState().batchCount);
    EXPECT_FALSE(resource->reportPendingCacheCompleted(7));
    ASSERT_TRUE(resource->reportPendingCacheCompleted(8));
    EXPECT_EQ(0, resource->getPendingCacheState().batchCount);
    EXPECT_EQ(0, resource->getPendingCacheState().uniqueBlockCount);
    EXPECT_EQ(2, resource->getCacheState().cachedBlockCount);
}

