TEST_F(NaviSchedResourceTest,
       testReorderedPartialAbortsCannotRestorePendingBlocks)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init());
    auto resource = context.get();
    NaviSchedPendingCacheReservation older;
    older.batchId = 7;
    older.scheduleBatchId = 70;
    older.fullReadyBlockHashes = {11, 22, 33};
    older.tailReadyBlockHashes = {22, 33};
    ASSERT_TRUE(resource->reportPendingCacheReady(older));
    older.fullReadyBlockHashes = {22, 33};
    auto newer = older;
    newer.fullReadyBlockHashes = {33};
    newer.tailReadyBlockHashes = {33};
    ASSERT_TRUE(resource->replacePendingCache(7, &newer));
    const auto before = resource->getPendingCacheState();
    ASSERT_EQ(2, before.revision);
    ASSERT_TRUE(resource->replacePendingCache(7, &older));
    const auto after = resource->getPendingCacheState();
    EXPECT_EQ(before.revision, after.revision);
    EXPECT_EQ(1, after.batchCount);
    EXPECT_EQ(1, after.uniqueBlockCount);
    EXPECT_EQ(1, after.uniqueTailReadyBlockCount);
    EXPECT_EQ(before.checksum, after.checksum);
    NaviSchedPendingCacheReservation actual;
    ASSERT_TRUE(resource->_agentPendingCacheR->getReservation(7, actual));
    EXPECT_EQ(NaviSchedBlockHashes({33}), actual.fullReadyBlockHashes);
    EXPECT_EQ(NaviSchedBlockHashes({33}), actual.tailReadyBlockHashes);
    ASSERT_TRUE(resource->reportPendingCacheCompleted(7));
    EXPECT_EQ(0, resource->getPendingCacheState().batchCount);
}

