    auto recoveredPipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("recovered", recoveredPipe));
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT, recoveredPipe->datas.size());
