TEST_F(NaviSchedResourceTest, testAgentBatchWaitsForAllAcceptedCallbacks)
{
    AgentBatchR resource(20, 1000);
    std::mutex mutex;
    std::condition_variable condition;
    bool firstAccepted = false;
    bool releaseFirst = false;
    bool firstResult = false;
    std::atomic<int32_t> acceptedCount{0};
    std::atomic<int32_t> readyCount{0};
    auto callback = [&]() {
        std::unique_lock<std::mutex> lock(mutex);
        firstAccepted = true;
        condition.notify_all();
        condition.wait(lock, [&]() { return releaseFirst; });
        acceptedCount.fetch_add(1, std::memory_order_relaxed);
    };
    std::thread firstThread([&]() {
        firstResult = resource.addRequest(
            makeRequestStats(1), 1, 2,
            [&](const NaviSchedBatchPtr &) {
                EXPECT_EQ(2, acceptedCount.load(std::memory_order_relaxed));
                readyCount.fetch_add(1, std::memory_order_relaxed);
            },
            callback);
    });
    {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [&]() { return firstAccepted; });
    }
    ASSERT_TRUE(resource.addRequest(
        makeRequestStats(2), 1, 2,
        [&](const NaviSchedBatchPtr &) {
            EXPECT_EQ(2, acceptedCount.load(std::memory_order_relaxed));
            readyCount.fetch_add(1, std::memory_order_relaxed);
        },
        [&]() { acceptedCount.fetch_add(1, std::memory_order_relaxed); }));
    EXPECT_EQ(0, readyCount.load(std::memory_order_relaxed));
    {
        std::lock_guard<std::mutex> lock(mutex);
        releaseFirst = true;
    }
    condition.notify_all();
    firstThread.join();
    EXPECT_TRUE(firstResult);
    EXPECT_EQ(2, acceptedCount.load(std::memory_order_relaxed));
    EXPECT_EQ(1, readyCount.load(std::memory_order_relaxed));
}

TEST_F(NaviSchedResourceTest, testAgentBatchStopWaitsForAcceptedCallback)
{
    AgentBatchR resource(20, 1000);
    std::mutex mutex;
    std::condition_variable condition;
    bool acceptedStarted = false;
    bool releaseAccepted = false;
    std::atomic<bool> stopFinished{false};
    std::atomic<int32_t> readyCount{0};
    std::thread addThread([&]() {
        EXPECT_TRUE(resource.addRequest(
            makeRequestStats(1), 0, 0,
            [&](const NaviSchedBatchPtr &) {
                readyCount.fetch_add(1, std::memory_order_relaxed);
            },
            [&]() {
                std::unique_lock<std::mutex> lock(mutex);
                acceptedStarted = true;
                condition.notify_all();
                condition.wait(lock, [&]() { return releaseAccepted; });
            }));
    });
    {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [&]() { return acceptedStarted; });
    }
    std::thread stopThread([&]() {
        resource.stop();
        stopFinished.store(true, std::memory_order_relaxed);
    });
    usleep(10 * 1000);
    EXPECT_FALSE(stopFinished.load(std::memory_order_relaxed));
    {
        std::lock_guard<std::mutex> lock(mutex);
        releaseAccepted = true;
    }
    condition.notify_all();
    addThread.join();
    stopThread.join();
    EXPECT_TRUE(stopFinished.load(std::memory_order_relaxed));
    EXPECT_EQ(0, readyCount.load(std::memory_order_relaxed));
}

