TEST_F(NaviSchedResourceTest, testAgentBatchStopWaitsForTimeoutCallback)
{
    AgentBatchR resource(1, 1000);
    std::mutex mutex;
    std::condition_variable condition;
    bool callbackStarted = false;
    bool releaseCallback = false;
    std::atomic<bool> stopFinished{false};
    ASSERT_TRUE(
        resource.addRequest(makeRequestStats(1), 1, 2, [&](const NaviSchedBatchPtr &) {
            std::unique_lock<std::mutex> lock(mutex);
            callbackStarted = true;
            condition.notify_all();
            condition.wait(lock, [&]() { return releaseCallback; });
        }));
    usleep(2 * 1000);
    std::thread expireThread([&]() { resource.expireBatches(); });
    {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [&]() { return callbackStarted; });
    }
    std::thread stopThread([&]() {
        resource.stop();
        stopFinished.store(true, std::memory_order_relaxed);
    });
    usleep(10 * 1000);
    EXPECT_FALSE(stopFinished.load(std::memory_order_relaxed));
    {
        std::lock_guard<std::mutex> lock(mutex);
        releaseCallback = true;
    }
    condition.notify_all();
    expireThread.join();
    stopThread.join();
    EXPECT_TRUE(stopFinished.load(std::memory_order_relaxed));
}

TEST_F(NaviSchedResourceTest, testAgentBatchTimeoutAndLateRequest)
{
    AgentBatchR resource(10, 1000);
    std::vector<NaviSchedBatchPtr> readyBatches;
    auto callback = [&readyBatches](const NaviSchedBatchPtr &batch) {
        readyBatches.emplace_back(batch);
    };
    ASSERT_TRUE(resource.addRequest(makeRequestStats(1), 1, 3, callback));
    ASSERT_FALSE(resource.addRequest(makeRequestStats(2), 1, 2, callback));
    usleep(20 * 1000);
    resource.expireBatches();
    ASSERT_EQ(1, readyBatches.size());
    ASSERT_EQ(1, resource.getTimeoutBatchCount());
    ASSERT_EQ(2, resource.getTimeoutMissingRequestCount());
    ASSERT_EQ(0, resource.getLateRequestCount());
    const auto &batch = readyBatches[0];
    ASSERT_EQ(std::vector<uint64_t>({1}), batch->requestIds);
    ASSERT_TRUE(batch->timedOut);

    ASSERT_TRUE(resource.addRequest(makeRequestStats(3), 1, 3, callback));
    ASSERT_EQ(2, readyBatches.size());
    ASSERT_EQ(std::vector<uint64_t>({3}), readyBatches[1]->requestIds);
    ASSERT_TRUE(readyBatches[1]->timedOut);
    ASSERT_NE(readyBatches[0]->batchId, readyBatches[1]->batchId);
    ASSERT_EQ(1, resource.getTimeoutBatchCount());
    ASSERT_EQ(2, resource.getTimeoutMissingRequestCount());
    ASSERT_EQ(1, resource.getLateRequestCount());
}

TEST_F(NaviSchedResourceTest, testAgentBatchTimeoutKeepsFirstRequestDeadline)
{
    AgentBatchR resource(150, 2000);
    std::vector<NaviSchedBatchPtr> readyBatches;
    auto callback = [&readyBatches](const NaviSchedBatchPtr &batch) {
        readyBatches.emplace_back(batch);
    };

    ASSERT_TRUE(resource.addRequest(makeRequestStats(1), 1, 3, callback));
    const auto batch = resource._callbackBatches.at(1);
    batch->firstRequestTimeUs = autil::TimeUtility::currentTime() - 100000;
    batch->deadlineTimeUs = batch->firstRequestTimeUs + 150000;
    const auto deadline = batch->deadlineTimeUs;
    ASSERT_TRUE(resource.addRequest(makeRequestStats(2), 1, 3, callback));
    EXPECT_EQ(deadline, batch->deadlineTimeUs);
    ASSERT_TRUE(readyBatches.empty());
    batch->deadlineTimeUs = autil::TimeUtility::currentTime() - 1;
    resource.expireBatches();
    ASSERT_EQ(1, readyBatches.size());
    EXPECT_EQ(std::vector<uint64_t>({1, 2}), readyBatches[0]->requestIds);
    EXPECT_TRUE(readyBatches[0]->timedOut);
}

TEST_F(NaviSchedResourceTest, testAgentBatchUsesFirstRequestTimeout)
{
    for (const int64_t timeoutMs : {37, 970}) {
        AgentBatchR resource(150, 2000);
        std::vector<NaviSchedBatchPtr> ready;
        const auto callback = [&](const NaviSchedBatchPtr &batch) { ready.push_back(batch); };
        ASSERT_TRUE(resource.addRequest(makeRequestStats(1), 99, 3, callback, {}, {}, {},
                                        timeoutMs));
        const auto batch = resource._callbackBatches.at(99);
        const auto deadline = batch->deadlineTimeUs;
        EXPECT_EQ(timeoutMs * 1000, deadline - batch->firstRequestTimeUs);
        ASSERT_TRUE(resource.addRequest(makeRequestStats(2), 99, 3, callback, {}, {}, {},
                                        timeoutMs == 37 ? 970 : 37));
        EXPECT_EQ(deadline, batch->deadlineTimeUs);
        EXPECT_TRUE(ready.empty());
        batch->deadlineTimeUs = autil::TimeUtility::currentTime() - 1;
        resource.expireBatches();
        ASSERT_EQ(1u, ready.size());
        EXPECT_EQ(std::vector<uint64_t>({1, 2}), ready[0]->requestIds);
        EXPECT_TRUE(ready[0]->timedOut);
        EXPECT_EQ(1u, resource.getTimeoutMissingRequestCount());
        ASSERT_TRUE(resource.addRequest(makeRequestStats(3), 99, 3, callback, {}, {}, {},
                                        timeoutMs));
        ASSERT_EQ(2u, ready.size());
        EXPECT_EQ(std::vector<uint64_t>({3}), ready[1]->requestIds);
        EXPECT_TRUE(ready[1]->timedOut);
        EXPECT_EQ(1u, resource.getLateRequestCount());
    }
}

TEST_F(NaviSchedResourceTest, testAgentBatchArrivalCannotJoinExpiredWindow)
{
    navi::NaviLoggerProvider loggerProvider("INFO");
    AgentBatchR resource(150, 2000);
    ASSERT_TRUE(resource.setGraphPipe(resource.beginGraphPipeGeneration(),
                                     std::make_shared<CaptureAsyncPipe>()));
    std::vector<NaviSchedBatchPtr> ready;
    const auto callback = [&](const NaviSchedBatchPtr &batch) { ready.push_back(batch); };
    ASSERT_TRUE(resource.addRequest(makeRequestStats(1), 99, 2, callback));
    resource._callbackBatches.at(99)->deadlineTimeUs =
        autil::TimeUtility::currentTime() - 1;
    ASSERT_TRUE(resource.addRequest(makeRequestStats(2), 99, 2, callback));
    ASSERT_EQ(2, ready.size());
    EXPECT_EQ(std::vector<uint64_t>({1}), ready[0]->requestIds);
    EXPECT_EQ(std::vector<uint64_t>({2}), ready[1]->requestIds);
    EXPECT_TRUE(ready[0]->timedOut);
    EXPECT_TRUE(ready[1]->timedOut);
    EXPECT_NE(ready[0]->batchId, ready[1]->batchId);
    EXPECT_EQ(1, resource.getTimeoutBatchCount());
    EXPECT_EQ(1, resource.getTimeoutMissingRequestCount());
    EXPECT_EQ(1, resource.getLateRequestCount());
    AgentBatchR::ExecutionState state;
    ASSERT_TRUE(resource.getExecutionState(state));
    EXPECT_EQ(0, state.batchWaitingRequests);
    EXPECT_EQ(2, state.queuedBatchRequests);
    const auto traces = loggerProvider.getTrace("[navi-batch-timeout]");
    ASSERT_EQ(1u, traces.size());
    EXPECT_NE(std::string::npos, traces[0].find("schedule_batch_id=99 "));
    EXPECT_NE(std::string::npos, traces[0].find("expected_batch_size=2 "));
    EXPECT_NE(std::string::npos, traces[0].find("received_request_count=1 "));
    EXPECT_NE(std::string::npos, traces[0].find("missing_request_count=1 "));
}

