TEST_F(NaviSchedResourceTest, testAgentBatchCacheKeyAuditLogsAcrossThreads)
{
    navi::NaviLoggerProvider loggerProvider("INFO");
    AgentBatchR resource(10, 1000);
    const auto graphPipeGeneration = resource.beginGraphPipeGeneration();
    ASSERT_GT(graphPipeGeneration, 0);
    ASSERT_TRUE(
        resource.setGraphPipe(graphPipeGeneration, std::make_shared<CaptureAsyncPipe>()));
    NaviSchedBatchPtr readyBatch;
    auto callback = [&readyBatch](const NaviSchedBatchPtr &batch) { readyBatch = batch; };

    auto request = makeRequestStats(101);
    AgentBatchR::CacheKeyAudit audit;
    audit.blockHashes = makeBlockHashes({11, 22});
    audit.arrivalTimeUs = 123456;
    ASSERT_TRUE(resource.addRequest(request, 77, 1, callback, {}, audit));
    ASSERT_TRUE(readyBatch);

    bool started = false;
    bool finished = false;
    std::thread executionThread([&]() {
        AgentBatchR::ExecutionState state;
        started = resource.startBatch(readyBatch->batchId, {request.requestId}, state);
        EXPECT_TRUE(resource.recordCacheStateAtStart(readyBatch->batchId, 19, 23, 29, 17,
                                                     31, 13, 37, 11));
        finished = resource.finishBatch(readyBatch->batchId, {request}, state);
    });
    executionThread.join();
    ASSERT_TRUE(started);
    ASSERT_TRUE(finished);
    const auto traces = loggerProvider.getTrace("[navi-cache-key-audit]");
    ASSERT_EQ(1, traces.size());
    EXPECT_NE(std::string::npos, traces[0].find("start_cache_revision=19"));
    EXPECT_NE(std::string::npos, traces[0].find("start_cached_blocks=23"));
    EXPECT_NE(std::string::npos, traces[0].find("start_rtp_cached_blocks=11"));
}

TEST_F(NaviSchedResourceTest, testAgentBatchTracksReadyWithoutRunningGaps)
{
    AgentBatchR resource(10, 1000);
    std::vector<NaviSchedBatchPtr> readyBatches;
    auto callback = [&readyBatches](const NaviSchedBatchPtr &batch) {
        readyBatches.emplace_back(batch);
    };

    ASSERT_TRUE(resource.addRequest(makeRequestStats(1), 0, 0, callback));
    ASSERT_EQ(1, readyBatches.size());
    usleep(2 * 1000);
    auto stats = resource.getReadyWithoutRunningStats();
    EXPECT_EQ(1, stats.gapCount);
    EXPECT_GE(stats.currentTimeUs, 1000);
    EXPECT_EQ(stats.currentTimeUs, stats.totalTimeUs);

    AgentBatchR::ExecutionState state;
    ASSERT_TRUE(resource.startBatch(readyBatches[0]->batchId, {1}, state));
    stats = resource.getReadyWithoutRunningStats();
    EXPECT_EQ(1, stats.gapCount);
    EXPECT_EQ(0, stats.currentTimeUs);
    EXPECT_GE(stats.totalTimeUs, 1000);

    ASSERT_TRUE(resource.addRequest(makeRequestStats(2), 0, 0, callback));
    ASSERT_EQ(2, readyBatches.size());
    EXPECT_EQ(1, resource.getReadyWithoutRunningStats().gapCount);
    ASSERT_TRUE(
        resource.finishBatch(readyBatches[0]->batchId, {makeRequestStats(1)}, state));
    usleep(2 * 1000);
    stats = resource.getReadyWithoutRunningStats();
    EXPECT_EQ(2, stats.gapCount);
    EXPECT_GE(stats.currentTimeUs, 1000);

    ASSERT_TRUE(resource.abortBatch(readyBatches[1]->batchId, state));
    stats = resource.getReadyWithoutRunningStats();
    EXPECT_EQ(2, stats.gapCount);
    EXPECT_EQ(0, stats.currentTimeUs);
    EXPECT_GE(stats.totalTimeUs, 2000);
    EXPECT_GE(stats.maxTimeUs, 1000);
}

