TEST_F(NaviSchedResourceTest, testAgentBatchGraphRecoveryStateIsOrderedAndComplete)
{
    AgentBatchR resource(10, 1000);
    std::vector<NaviSchedBatchPtr> readyBatches;
    const auto callback = [&readyBatches](const NaviSchedBatchPtr &batch) {
        readyBatches.emplace_back(batch);
    };
    ASSERT_TRUE(resource.addRequest(makeRequestStats(11), 1, 1, callback));
    ASSERT_TRUE(resource.addRequest(makeRequestStats(22), 2, 1, callback));
    ASSERT_EQ(2, readyBatches.size());
    ASSERT_EQ(2, resource.getLatestLocalBatchId());

    AgentBatchR::ExecutionState executionState;
    ASSERT_TRUE(resource.startBatch(readyBatches[1]->batchId, {22}, executionState));
    const auto recovery = resource.getGraphRecoveryState();

    ASSERT_EQ(2, recovery.batches.size());
    EXPECT_EQ(0, recovery.batchWaitingRequests);
    EXPECT_EQ(1, recovery.queuedBatchRequests);
    EXPECT_EQ(1, recovery.runningRequests);
    EXPECT_TRUE(std::is_sorted(recovery.batches.begin(), recovery.batches.end(),
                               [](const AgentBatchR::GraphRecoveryBatch &lhs,
                                  const AgentBatchR::GraphRecoveryBatch &rhs) {
                                   if (lhs.batch->readyTimeUs != rhs.batch->readyTimeUs) {
                                       return lhs.batch->readyTimeUs <
                                              rhs.batch->readyTimeUs;
                                   }
                                   return lhs.batch->batchId < rhs.batch->batchId;
                               }));
    size_t runningBatchCount = 0;
    for (const auto &batch : recovery.batches) {
        ASSERT_TRUE(batch.batch);
        ASSERT_EQ(1, batch.batch->requestIds.size());
        if (batch.running) {
            ++runningBatchCount;
            EXPECT_EQ(readyBatches[1]->batchId, batch.batch->batchId);
            EXPECT_GT(batch.startTimeUs, 0);
        } else {
            EXPECT_EQ(readyBatches[0]->batchId, batch.batch->batchId);
            EXPECT_EQ(0, batch.startTimeUs);
        }
    }
    EXPECT_EQ(1, runningBatchCount);
}

