TEST_F(NaviSchedResourceTest, testAgentBatchRejectsTerminatedPipe)
{
    AgentBatchR resource(10, 1000);
    const auto rejectedGeneration = resource.beginGraphPipeGeneration();
    ASSERT_GT(rejectedGeneration, 0);
    ASSERT_TRUE(
        resource.setGraphPipe(rejectedGeneration, std::make_shared<RejectedAsyncPipe>()));
    ASSERT_FALSE(
        resource.addRequest(makeRequestStats(1), 0, 0, [](const NaviSchedBatchPtr &) {}));
    AgentBatchR::ExecutionState state;
    ASSERT_TRUE(resource.getExecutionState(state));
    ASSERT_EQ(0, state.batchWaitingRequests);
    ASSERT_EQ(0, state.queuedBatchRequests);

    auto replacement = std::make_shared<CaptureAsyncPipe>();
    const auto replacementGeneration = resource.beginGraphPipeGeneration();
    ASSERT_GT(replacementGeneration, rejectedGeneration);
    ASSERT_TRUE(resource.setGraphPipe(replacementGeneration, replacement));
    ASSERT_TRUE(
        resource.addRequest(makeRequestStats(2), 0, 0, [](const NaviSchedBatchPtr &) {}));
}

TEST_F(NaviSchedResourceTest, testLateAgentBatchGraphCleanupDoesNotClearReplacementPipe)
{
    AgentBatchR resource(10, 1000);
    const auto oldGeneration = resource.beginGraphPipeGeneration();
    ASSERT_TRUE(
        resource.setGraphPipe(oldGeneration, std::make_shared<CaptureAsyncPipe>()));
    resource.clearGraphPipe(oldGeneration);

    const auto replacementGeneration = resource.beginGraphPipeGeneration();
    auto replacement = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource.setGraphPipe(replacementGeneration, replacement));
    resource.clearGraphPipe(oldGeneration);

    ASSERT_TRUE(
        resource.addRequest(makeRequestStats(2), 0, 0, [](const NaviSchedBatchPtr &) {}));
    EXPECT_EQ(1, replacement->overrideCount);
    EXPECT_EQ(replacementGeneration, resource.getGraphPipeGeneration());
}

TEST_F(NaviSchedResourceTest, testAgentReporterDestructorAbortsStartedBatch)
{
    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_reporter_destructor_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);

    NaviSchedBatchPtr firstBatch;
    NaviSchedRequestStats first;
    first.requestId = 1;
    first.totalTokenCount = 256;
    ASSERT_TRUE(agent.addBatchRequest(
        makeBatchRequest(first), 0, 0,
        [&firstBatch](const NaviSchedBatchPtr &batch) { firstBatch = batch; }));
    ASSERT_TRUE(firstBatch);
    ASSERT_TRUE(firstBatch->finishReporter->startBatch({first.requestId}));
    firstBatch->finishReporter.reset();

    NaviSchedBatchPtr secondBatch;
    NaviSchedRequestStats second;
    second.requestId = 2;
    second.totalTokenCount = 256;
    ASSERT_TRUE(agent.addBatchRequest(
        makeBatchRequest(second), 0, 0,
        [&secondBatch](const NaviSchedBatchPtr &batch) { secondBatch = batch; }));
    ASSERT_TRUE(secondBatch);
    ASSERT_TRUE(secondBatch->finishReporter->startBatch({second.requestId}));
    second.cacheHitTokenCount = second.totalTokenCount + 1;
    ASSERT_FALSE(secondBatch->finishReporter->finishBatch({second}));
    second.cacheHitTokenCount = 0;
    ASSERT_TRUE(secondBatch->finishReporter->finishBatch({second}));

    NaviSchedRequestStats failed;
    failed.requestId = 3;
    failed.totalTokenCount = 256;
    ASSERT_FALSE(agent.addBatchRequest(
        makeBatchRequest(failed), 0, 0, [](const NaviSchedBatchPtr &) {
            throw std::runtime_error("ready callback failed");
        }));

    NaviSchedBatchPtr batchAfterFailure;
    NaviSchedRequestStats afterFailure;
    afterFailure.requestId = 4;
    afterFailure.totalTokenCount = 256;
    ASSERT_TRUE(
        agent.addBatchRequest(makeBatchRequest(afterFailure), 0, 0,
                              [&batchAfterFailure](const NaviSchedBatchPtr &batch) {
                                  batchAfterFailure = batch;
                              }));
    ASSERT_TRUE(batchAfterFailure);
    ASSERT_TRUE(batchAfterFailure->finishReporter->startBatch({afterFailure.requestId}));
    ASSERT_TRUE(batchAfterFailure->finishReporter->finishBatch({afterFailure}));
    agent.stop();
}

