TEST_F(NaviSchedResourceTest,
       testAgentReporterRejectedOperationsNeverChangeInflightOwnership)
{
    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_reporter_rejected_operation_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    config.service.waitNoQuery = false;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);
    auto impl = NaviSchedAgentImpl::getImpl(agent);
    ASSERT_TRUE(impl);

    NaviSchedBatchPtr batch;
    auto firstStats = makeRequestStats(101);
    auto secondStats = makeRequestStats(102);
    firstStats.totalTokenCount = secondStats.totalTokenCount = 256;
    auto first = makeBatchRequest(firstStats);
    auto second = makeBatchRequest(secondStats);
    first.predictedQueueLatencyMs = second.predictedQueueLatencyMs = 10.0;
    first.predictedExecutionLatencyMs = second.predictedExecutionLatencyMs = 20.0;
    ASSERT_TRUE(agent.addBatchRequest(
        first, 77, 2,
        [&batch](const NaviSchedBatchPtr &readyBatch) { batch = readyBatch; }));
    ASSERT_TRUE(agent.addBatchRequest(
        second, 77, 2,
        [&batch](const NaviSchedBatchPtr &readyBatch) { batch = readyBatch; }));
    ASSERT_TRUE(batch);
    const auto owned = impl->getInflightStats();
    ASSERT_EQ(2, owned.requestCount);
    ASSERT_DOUBLE_EQ(60.0, owned.totalPredictedLatencyMs);

    EXPECT_FALSE(batch->finishReporter->startBatch({}));
    EXPECT_FALSE(batch->finishReporter->startBatch({101, 0}));
    auto unchanged = impl->getInflightStats();
    EXPECT_EQ(owned.revision, unchanged.revision);
    EXPECT_EQ(owned.requestCount, unchanged.requestCount);
    EXPECT_DOUBLE_EQ(owned.totalPredictedLatencyMs, unchanged.totalPredictedLatencyMs);

    ASSERT_TRUE(batch->finishReporter->startBatch({101, 102}));
    EXPECT_FALSE(batch->finishReporter->startBatch({101, 102}));
    EXPECT_FALSE(batch->finishReporter->abortRequests({}));
    EXPECT_FALSE(batch->finishReporter->abortRequests({999}));
    EXPECT_FALSE(batch->finishReporter->finishBatch({}));
    auto invalidStats = makeRequestStats(0);
    EXPECT_FALSE(batch->finishReporter->finishBatch({invalidStats}));
    unchanged = impl->getInflightStats();
    EXPECT_EQ(owned.revision, unchanged.revision);
    EXPECT_EQ(2, unchanged.requestCount);
    EXPECT_DOUBLE_EQ(60.0, unchanged.totalPredictedLatencyMs);
    EXPECT_EQ(owned.missingRemoveCount, unchanged.missingRemoveCount);

    ASSERT_TRUE(batch->finishReporter->abortRequests({101}));
    const auto partial = impl->getInflightStats();
    EXPECT_EQ(owned.revision + 1, partial.revision);
    EXPECT_EQ(1, partial.requestCount);
    EXPECT_DOUBLE_EQ(30.0, partial.totalPredictedLatencyMs);
    EXPECT_EQ(owned.missingRemoveCount, partial.missingRemoveCount);
    EXPECT_FALSE(batch->finishReporter->abortRequests({101}));
    unchanged = impl->getInflightStats();
    EXPECT_EQ(partial.revision, unchanged.revision);
    EXPECT_EQ(partial.missingRemoveCount, unchanged.missingRemoveCount);

    ASSERT_TRUE(batch->finishReporter->finishBatch({secondStats}));
    const auto finished = impl->getInflightStats();
    EXPECT_EQ(partial.revision + 1, finished.revision);
    EXPECT_EQ(0, finished.requestCount);
    EXPECT_DOUBLE_EQ(0.0, finished.totalPredictedLatencyMs);
    EXPECT_EQ(partial.missingRemoveCount, finished.missingRemoveCount);
    EXPECT_FALSE(batch->finishReporter->finishBatch({secondStats}));
    EXPECT_FALSE(batch->finishReporter->abortRequests({102}));
    batch->finishReporter.reset();
    const auto afterLateTerminalCalls = impl->getInflightStats();
    EXPECT_EQ(finished.revision, afterLateTerminalCalls.revision);
    EXPECT_EQ(finished.missingRemoveCount, afterLateTerminalCalls.missingRemoveCount);
    agent.stop();
}

