TEST_F(NaviSchedResourceTest,
       testConcurrentStopFinishAndAbortReleaseEveryInflightOwnerExactlyOnce)
{
    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_concurrent_stop_finish_abort_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    config.service.waitNoQuery = false;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);
    auto impl = NaviSchedAgentImpl::getImpl(agent);
    ASSERT_TRUE(impl);

    constexpr size_t REQUEST_COUNT = 32;
    std::vector<NaviSchedRequestStats> requestStats;
    std::vector<NaviSchedBatchPtr> batches;
    requestStats.reserve(REQUEST_COUNT);
    batches.reserve(REQUEST_COUNT);
    for (size_t index = 0; index < REQUEST_COUNT; ++index) {
        auto stats = makeRequestStats(1001 + index);
        stats.totalTokenCount = 256;
        auto request = makeBatchRequest(stats);
        request.predictedQueueLatencyMs = 1.0;
        request.predictedExecutionLatencyMs = 2.0;
        NaviSchedBatchPtr batch;
        ASSERT_TRUE(agent.addBatchRequest(
            request, 0, 0,
            [&batch](const NaviSchedBatchPtr &readyBatch) { batch = readyBatch; }));
        ASSERT_TRUE(batch);
        ASSERT_TRUE(batch->finishReporter->startBatch({stats.requestId}));
        requestStats.emplace_back(std::move(stats));
        batches.emplace_back(std::move(batch));
    }
    const auto owned = impl->getInflightStats();
    ASSERT_EQ(REQUEST_COUNT, static_cast<size_t>(owned.requestCount));
    ASSERT_DOUBLE_EQ(REQUEST_COUNT * 3.0, owned.totalPredictedLatencyMs);

    std::atomic<size_t> ready{0};
    std::atomic<bool> start{false};
    std::vector<std::thread> workers;
    workers.reserve(REQUEST_COUNT);
    for (size_t index = 0; index < REQUEST_COUNT; ++index) {
        workers.emplace_back([&, index]() {
            ready.fetch_add(1, std::memory_order_release);
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }
            if (index % 2 == 0) {
                batches[index]->finishReporter->finishBatch({requestStats[index]});
            } else {
                batches[index]->finishReporter->abortRequests(
                    {requestStats[index].requestId});
            }
        });
    }
    std::thread stopThread([&]() {
        ready.fetch_add(1, std::memory_order_release);
        while (!start.load(std::memory_order_acquire)) {
            std::this_thread::yield();
        }
        agent.stop();
    });
    while (ready.load(std::memory_order_acquire) != REQUEST_COUNT + 1) {
        std::this_thread::yield();
    }
    start.store(true, std::memory_order_release);
    for (auto &worker : workers) {
        worker.join();
    }
    stopThread.join();

    const auto drained = impl->getInflightStats();
    EXPECT_EQ(owned.revision + REQUEST_COUNT, drained.revision);
    EXPECT_EQ(0, drained.requestCount);
    EXPECT_DOUBLE_EQ(0.0, drained.totalPredictedLatencyMs);
    EXPECT_EQ(owned.missingRemoveCount, drained.missingRemoveCount);
    const auto reported = impl->_agentReportR->getInflightStats();
    EXPECT_EQ(drained.revision, reported.revision);
    EXPECT_EQ(0, reported.requestCount);
    EXPECT_DOUBLE_EQ(0.0, reported.totalPredictedLatencyMs);
    AgentBatchR::ExecutionState state;
    ASSERT_TRUE(impl->_agentBatchR->getExecutionState(state));
    EXPECT_EQ(0, state.batchWaitingRequests);
    EXPECT_EQ(0, state.queuedBatchRequests);
    EXPECT_EQ(0, state.runningRequests);
    EXPECT_EQ(0, impl->_agentBatchR->getPendingBatchCount());

    for (auto &batch : batches) {
        batch->finishReporter.reset();
    }
    const auto afterLateDestructors = impl->getInflightStats();
    EXPECT_EQ(drained.revision, afterLateDestructors.revision);
    EXPECT_EQ(drained.missingRemoveCount, afterLateDestructors.missingRemoveCount);
}

TEST_F(NaviSchedResourceTest, testStopWaitsForDetachedFinishInflightCleanup)
{
    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_detached_finish_stop_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    config.service.waitNoQuery = false;
    config.pdSeparated = false;
    config.unifiedLatencyPrediction = true;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);
    auto impl = NaviSchedAgentImpl::getImpl(agent);
    ASSERT_TRUE(impl);
    auto stats = makeRequestStats(1001);
    stats.totalTokenCount = 256;
    NaviSchedBatchPtr batch;
    ASSERT_TRUE(agent.addBatchRequest(
        makeBatchRequest(stats), 0, 0,
        [&batch](const NaviSchedBatchPtr &readyBatch) { batch = readyBatch; }));
    ASSERT_TRUE(batch);
    ASSERT_TRUE(batch->finishReporter->startBatch({stats.requestId}));
    const auto owned = impl->getInflightStats();
    ASSERT_EQ(1, owned.requestCount);

    // Pause finish after detaching its batch but before publishing/removing inflight.
    auto reportLock = std::make_unique<autil::ScopedLock>(impl->_agentReportR->_mutex);
    std::thread finisher([&]() { batch->finishReporter->finishBatch({stats}); });
    bool detached = false;
    for (size_t retry = 0; retry < 1000; ++retry) {
        AgentBatchR::ExecutionState state;
        impl->_agentBatchR->getExecutionState(state);
        if (state.runningRequests == 0) {
            detached = true;
            break;
        }
        usleep(1000);
    }
    EXPECT_TRUE(detached);
    std::thread stopper([&]() { agent.stop(); });
    bool stopping = false;
    for (size_t retry = 0; retry < 1000; ++retry) {
        {
            autil::ScopedLock lock(impl->_agentBatchR->_lock);
            stopping = impl->_agentBatchR->_stopped;
        }
        if (stopping) break;
        usleep(1000);
    }
    EXPECT_TRUE(stopping);
    for (size_t retry = 0; retry < 200 && impl->getInflightStats().requestCount == 1;
         ++retry) {
        usleep(1000);
    }
    EXPECT_EQ(1, impl->getInflightStats().requestCount);
    reportLock.reset();
    finisher.join();
    stopper.join();
    const auto drained = impl->getInflightStats();
    EXPECT_EQ(0, drained.requestCount);
    EXPECT_EQ(owned.revision + 1, drained.revision);
    EXPECT_EQ(owned.missingRemoveCount, drained.missingRemoveCount);
}

