TEST_F(NaviSchedResourceTest, testForwardHandlerRejectionClearsEveryOwnedState)
{
    TestMasterStateR master;
    const std::string agentId = "agent_0";
    auto node = master.registerAgent(agentId, "agent_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(node);

    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_forward_rejection_cleanup_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    config.service.waitNoQuery = false;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);
    ASSERT_TRUE(agent.setForwardBatchHandler(
        [](const std::vector<NaviSchedForwardedRequest> &, int64_t,
           const NaviSchedBatchFinishReporterPtr &) { return false; }));
    auto impl = NaviSchedAgentImpl::getImpl(agent);
    ASSERT_TRUE(impl);
    auto reportPipe = std::make_shared<MasterReportAsyncPipe>(&master, agentId);
    ASSERT_TRUE(impl->_agentReportR->subscribe("master_0", reportPipe));
    ASSERT_TRUE(reportPipe->allReportsSucceeded());

    NaviSchedForwardRequest request;
    request.request.requestId = 101;
    request.request.promptTokenCount = 256;
    request.request.blockSize = 256;
    request.request.blockHashes = makeBlockHashes({11});
    request.request.forwardPayload = "request";
    request.decision.batchId = 77;
    request.decision.expectedBatchSize = 1;
    request.decision.predictedQueueLatencyMs = 10.0;
    request.decision.predictedExecutionLatencyMs = 20.0;
    auto pipe = std::make_shared<CaptureAsyncPipe>();
    const auto initial = impl->getInflightStats();
    std::vector<MasterBatchReservation::Request> reservedRequests = {
        {request.request.requestId, request.request.promptTokenCount,
         request.request.blockSize, 0, request.request.blockHashes},
    };
    const NaviSchedCachePolicy cachePolicy{256, 1, false};
    bool pendingCacheTracked = false;
    ASSERT_TRUE(node->reserveBatch(
        request.decision.batchId, autil::TimeUtility::currentTime(),
        request.decision.predictedQueueLatencyMs +
            request.decision.predictedExecutionLatencyMs,
        std::move(reservedRequests), &cachePolicy, &pendingCacheTracked));
    ASSERT_TRUE(pendingCacheTracked);
    ASSERT_EQ(1, pendingReservationCount(node));
    ASSERT_EQ(1, pendingCacheBatchCount(node));

    ASSERT_TRUE(impl->submitForwardRequest(request, pipe));
    ASSERT_TRUE(reportPipe->waitForAbortedBatch(request.decision.batchId));
    ASSERT_TRUE(reportPipe->allReportsSucceeded());

    const auto cleaned = impl->getInflightStats();
    EXPECT_EQ(initial.revision + 2, cleaned.revision);
    EXPECT_EQ(0, cleaned.requestCount);
    EXPECT_DOUBLE_EQ(0.0, cleaned.totalPredictedLatencyMs);
    EXPECT_EQ(initial.missingRemoveCount, cleaned.missingRemoveCount);
    EXPECT_EQ(0, impl->_agentResponseR->requestCount());
    EXPECT_TRUE(pipe->eof);
    EXPECT_EQ(1, pipe->eofCount);
    AgentBatchR::ExecutionState state;
    ASSERT_TRUE(impl->_agentBatchR->getExecutionState(state));
    EXPECT_EQ(0, state.batchWaitingRequests);
    EXPECT_EQ(0, state.queuedBatchRequests);
    EXPECT_EQ(0, state.runningRequests);
    EXPECT_EQ(0, impl->_agentBatchR->getPendingBatchCount());
    const auto pending = impl->_agentReportR->getPendingCacheState();
    EXPECT_EQ(0, pending.batchCount);
    EXPECT_EQ(0, pending.uniqueBlockCount);
    EXPECT_EQ(1, impl->_agentBatchR->getAbnormalBatchFinishCount());
    EXPECT_EQ(0, pendingReservationCount(node));
    EXPECT_EQ(0, pendingCacheBatchCount(node));
    const auto runtime = node->getRuntimeState();
    EXPECT_EQ(0, runtime.load.inflightRequests);
    EXPECT_DOUBLE_EQ(0.0, runtime.load.inflightPredictedLatencySumMs);
    ASSERT_TRUE(impl->_agentReportR->unsubscribe("master_0", reportPipe));
    agent.stop();
}

