TEST_F(NaviSchedResourceTest, testPendingBatchAbortPropagatesThroughAgentGraphToMaster)
{
    TestMasterStateR master;
    const std::string agentId = "agent_0";
    auto node = master.registerAgent(agentId, "agent_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(node);

    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_abort_master_integration_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);
    auto impl = NaviSchedAgentImpl::getImpl(agent);
    ASSERT_TRUE(impl);
    auto reportPipe = std::make_shared<MasterReportAsyncPipe>(&master, agentId);
    ASSERT_TRUE(impl->_agentReportR->subscribe("master_0", reportPipe));
    ASSERT_TRUE(reportPipe->allReportsSucceeded());

    auto firstHashes = makeBlockHashes({11, 22});
    auto secondHashes = makeBlockHashes({11, 33});
    std::vector<MasterBatchReservation::Request> requests = {
        {1001, 512, 256, 0, firstHashes},
        {1002, 512, 256, 0, secondHashes},
    };
    const NaviSchedCachePolicy cachePolicy{256, 1, false};
    bool pendingCacheTracked = false;
    ASSERT_TRUE(node->reserveBatch(101, autil::TimeUtility::currentTime(), 20.0,
                                   std::move(requests), &cachePolicy,
                                   &pendingCacheTracked));
    ASSERT_TRUE(pendingCacheTracked);
    ASSERT_EQ(1, pendingReservationCount(node));
    ASSERT_EQ(1, pendingCacheBatchCount(node));
    ASSERT_EQ(2, node->getMatchedBlockCount({11, 22}));
    ASSERT_EQ(2, node->getMatchedBlockCount({11, 33}));

    NaviSchedRequestStats request;
    request.requestId = 1001;
    request.totalTokenCount = 512;
    bool batchReady = false;
    ASSERT_TRUE(agent.addBatchRequest(
        makeBatchRequest(request), 101, 2,
        [&batchReady](const NaviSchedBatchPtr &) { batchReady = true; }));
    ASSERT_FALSE(batchReady);
    ASSERT_TRUE(agent.abortPendingBatch(101));
    ASSERT_TRUE(reportPipe->waitForAbortedBatch(101));
    ASSERT_TRUE(reportPipe->allReportsSucceeded());

    EXPECT_EQ(MasterBatchReservation::RequestState::FAILED,
              reservationRequestState(node, 101, 1001));
    EXPECT_EQ(MasterBatchReservation::RequestState::WAITING,
              reservationRequestState(node, 101, 1002));
    EXPECT_EQ(1, pendingReservationCount(node));
    EXPECT_EQ(1, pendingCacheBatchCount(node));
    EXPECT_EQ(1, node->getMatchedBlockCount({11, 22}));
    EXPECT_EQ(2, node->getMatchedBlockCount({11, 33}));

    NaviSchedTarget target;
    target.bizName = "agent_biz";
    target.agentAddress = "127.0.0.1:19000";
    EXPECT_TRUE(master.reportDispatchFailed(target, 101, 1002));
    EXPECT_EQ(0, pendingReservationCount(node));
    EXPECT_EQ(0, pendingCacheBatchCount(node));
    ASSERT_TRUE(impl->_agentReportR->unsubscribe("master_0", reportPipe));
    agent.stop();
}

TEST_F(NaviSchedResourceTest,
       testPartialBatchTimeoutAcknowledgesOnlyArrivedRequestAndCleansLifecycle)
{
    TestMasterStateR master;
    const std::string agentId = "agent_0";
    auto node = master.registerAgent(agentId, "agent_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(node);

    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_partial_batch_timeout_master_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    config.service.waitNoQuery = false;
    config.service.batchTimeoutMs = 10;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);
    auto impl = NaviSchedAgentImpl::getImpl(agent);
    ASSERT_TRUE(impl);
    auto reportPipe = std::make_shared<MasterReportAsyncPipe>(&master, agentId);
    ASSERT_TRUE(impl->_agentReportR->subscribe("master_0", reportPipe));
    ASSERT_TRUE(reportPipe->allReportsSucceeded());

    reserveBatch(node, 101, autil::TimeUtility::currentTime(), 30.0, {1001, 1002});
    NaviSchedTarget target;
    target.bizName = "agent_biz";
    target.agentAddress = "127.0.0.1:19000";
    auto arrivedWaiter = std::make_shared<CountingAsyncPipe>();
    auto missingWaiter = std::make_shared<CountingAsyncPipe>();
    bool acknowledged = false;
    ASSERT_TRUE(
        master.registerDispatchWaiter(target, 101, 1001, arrivedWaiter, acknowledged));
    ASSERT_FALSE(acknowledged);
    ASSERT_TRUE(
        master.registerDispatchWaiter(target, 101, 1002, missingWaiter, acknowledged));
    ASSERT_FALSE(acknowledged);

    NaviSchedBatchPtr partialBatch;
    auto request = makeRequestStats(1001);
    request.totalTokenCount = 256;
    auto batchRequest = makeBatchRequest(request);
    batchRequest.blockHashes = makeBlockHashes({11});
    ASSERT_TRUE(agent.addBatchRequest(
        batchRequest, 101, 2,
        [&partialBatch](const NaviSchedBatchPtr &batch) { partialBatch = batch; }));
    for (size_t retry = 0;
         retry < 500 &&
         (!partialBatch || !arrivedWaiter->eof.load(std::memory_order_acquire));
         ++retry) {
        usleep(1000);
    }

    ASSERT_TRUE(partialBatch);
    EXPECT_TRUE(partialBatch->timedOut);
    EXPECT_TRUE(partialBatch->pendingCacheTracked);
    EXPECT_EQ(1, impl->_agentReportR->getPendingCacheState().batchCount);
    EXPECT_EQ((std::vector<uint64_t>{1001}), partialBatch->requestIds);
    EXPECT_TRUE(arrivedWaiter->eof.load(std::memory_order_acquire));
    EXPECT_FALSE(missingWaiter->eof.load(std::memory_order_acquire));
    EXPECT_EQ(MasterBatchReservation::RequestState::DISPATCHED,
              reservationRequestState(node, 101, 1001));
    EXPECT_EQ(MasterBatchReservation::RequestState::WAITING,
              reservationRequestState(node, 101, 1002));
    EXPECT_EQ(1, dispatchWaiterCount(node, 101));

    ASSERT_TRUE(partialBatch->finishReporter->startBatch({1001}));
    ASSERT_TRUE(partialBatch->finishReporter->finishBatch({request}));
    for (size_t retry = 0;
         retry < 500 && reservationRequestState(node, 101, 1001) !=
                            MasterBatchReservation::RequestState::COMPLETED;
         ++retry) {
        usleep(1000);
    }
    EXPECT_EQ(MasterBatchReservation::RequestState::COMPLETED,
              reservationRequestState(node, 101, 1001));
    EXPECT_EQ(0, impl->_agentReportR->getPendingCacheState().batchCount);
    EXPECT_EQ(0, node->_pendingCacheR->getStats(node->_info.agentIdHash).agentBatchCount);
    EXPECT_TRUE(master.cancelDispatchWaiter(target, 101, 1002, missingWaiter));
    EXPECT_EQ(0, pendingReservationCount(node));
    EXPECT_EQ(0, dispatchWaiterCount(node, 101));
    EXPECT_EQ(0, pendingCacheBatchCount(node));
    const auto runtime = node->getRuntimeState();
    EXPECT_EQ(0, runtime.load.inflightRequests);
    EXPECT_DOUBLE_EQ(0.0, runtime.load.inflightPredictedLatencySumMs);
    EXPECT_TRUE(reportPipe->allReportsSucceeded());

    ASSERT_TRUE(impl->_agentReportR->unsubscribe("master_0", reportPipe));
    agent.stop();
}

TEST_F(NaviSchedResourceTest,
       testPartialBatchLateArrivalFinishesWithoutMasterResidue)
{
    TestMasterStateR master;
    const std::string agentId = "agent_0";
    auto node = master.registerAgent(agentId, "agent_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(node);

    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_partial_batch_late_arrival_master_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    config.service.waitNoQuery = false;
    config.service.batchTimeoutMs = 10;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);
    auto impl = NaviSchedAgentImpl::getImpl(agent);
    ASSERT_TRUE(impl);
    auto reportPipe = std::make_shared<MasterReportAsyncPipe>(&master, agentId);
    ASSERT_TRUE(impl->_agentReportR->subscribe("master_0", reportPipe));
    ASSERT_TRUE(reportPipe->allReportsSucceeded());

    reserveBatch(node, 101, autil::TimeUtility::currentTime(), 30.0, {1001, 1002, 1003});
    NaviSchedTarget target;
    target.bizName = "agent_biz";
    target.agentAddress = "127.0.0.1:19000";
    auto arrivedWaiter = std::make_shared<CountingAsyncPipe>();
    auto missingWaiter = std::make_shared<CountingAsyncPipe>();
    bool acknowledged = false;
    ASSERT_TRUE(
        master.registerDispatchWaiter(target, 101, 1001, arrivedWaiter, acknowledged));
    ASSERT_FALSE(acknowledged);
    ASSERT_TRUE(
        master.registerDispatchWaiter(target, 101, 1002, missingWaiter, acknowledged));
    ASSERT_FALSE(acknowledged);

    NaviSchedBatchPtr partialBatch;
    auto request = makeRequestStats(1001);
    request.totalTokenCount = 256;
    auto batchRequest = makeBatchRequest(request);
    batchRequest.blockHashes = makeBlockHashes({11});
    ASSERT_TRUE(agent.addBatchRequest(
        batchRequest, 101, 3,
        [&partialBatch](const NaviSchedBatchPtr &batch) { partialBatch = batch; }));
    for (size_t retry = 0;
         retry < 500 &&
         (!partialBatch || !arrivedWaiter->eof.load(std::memory_order_acquire));
         ++retry) {
        usleep(1000);
    }

    ASSERT_TRUE(partialBatch);
    EXPECT_TRUE(partialBatch->timedOut);
    EXPECT_TRUE(partialBatch->pendingCacheTracked);
    EXPECT_EQ(1, impl->_agentReportR->getPendingCacheState().batchCount);
    EXPECT_EQ((std::vector<uint64_t>{1001}), partialBatch->requestIds);
    EXPECT_TRUE(arrivedWaiter->eof.load(std::memory_order_acquire));
    EXPECT_FALSE(missingWaiter->eof.load(std::memory_order_acquire));
    EXPECT_EQ(MasterBatchReservation::RequestState::DISPATCHED,
              reservationRequestState(node, 101, 1001));
    EXPECT_EQ(MasterBatchReservation::RequestState::WAITING,
              reservationRequestState(node, 101, 1002));
    EXPECT_EQ(1, dispatchWaiterCount(node, 101));

    ASSERT_TRUE(partialBatch->finishReporter->startBatch({1001}));
    ASSERT_TRUE(partialBatch->finishReporter->finishBatch({request}));
    for (size_t retry = 0;
         retry < 500 && reservationRequestState(node, 101, 1001) !=
                            MasterBatchReservation::RequestState::COMPLETED;
         ++retry) {
        usleep(1000);
    }
    EXPECT_EQ(MasterBatchReservation::RequestState::COMPLETED,
              reservationRequestState(node, 101, 1001));
    EXPECT_EQ(0, impl->_agentReportR->getPendingCacheState().batchCount);
    EXPECT_EQ(0, node->_pendingCacheR->getStats(node->_info.agentIdHash).agentBatchCount);
    // One missing member is cancelled; another arrives after the first local batch finished.
    ASSERT_TRUE(master.reportDispatchFailed(target, 101, 1003));
    EXPECT_EQ(1, pendingReservationCount(node));
    NaviSchedBatchPtr lateBatch;
    auto lateRequest = makeRequestStats(1002);
    lateRequest.totalTokenCount = 256;
    auto lateBatchRequest = makeBatchRequest(lateRequest);
    lateBatchRequest.blockHashes = makeBlockHashes({22});
    ASSERT_TRUE(agent.addBatchRequest(
        lateBatchRequest, 101, 3,
        [&lateBatch](const NaviSchedBatchPtr &batch) { lateBatch = batch; }));
    ASSERT_TRUE(lateBatch);
    EXPECT_NE(partialBatch->batchId, lateBatch->batchId);
    EXPECT_EQ(std::vector<uint64_t>({1002}), lateBatch->requestIds);
    EXPECT_EQ(std::vector<uint64_t>({1002}), lateBatch->makeLocalBatchInfo().requestIds);
    EXPECT_EQ(1, lateBatch->makeLocalBatchInfo().requestCount);
    ASSERT_TRUE(lateBatch->finishReporter->startBatch({1002}));
    ASSERT_TRUE(lateBatch->finishReporter->finishBatch({lateRequest}));
    for (size_t retry = 0; retry < 500 && pendingReservationCount(node) != 0; ++retry) {
        usleep(1000);
    }
    EXPECT_EQ(0, impl->_agentReportR->getPendingCacheState().batchCount);
    EXPECT_EQ(0, impl->_agentReportR->getPendingCacheState().uniqueBlockCount);
    EXPECT_EQ(0, node->_pendingCacheR->getStats(node->_info.agentIdHash).agentBatchCount);
    EXPECT_EQ(0, node->_pendingCacheR->getStats(node->_info.agentIdHash).uniqueBlockCount);
    EXPECT_EQ(0, pendingReservationCount(node));
    EXPECT_EQ(0, dispatchWaiterCount(node, 101));
    EXPECT_EQ(0, pendingCacheBatchCount(node));
    const auto runtime = node->getRuntimeState();
    EXPECT_EQ(0, runtime.load.inflightRequests);
    EXPECT_DOUBLE_EQ(0.0, runtime.load.inflightPredictedLatencySumMs);
    EXPECT_TRUE(reportPipe->allReportsSucceeded());

    ASSERT_TRUE(impl->_agentReportR->unsubscribe("master_0", reportPipe));
    agent.stop();
}

TEST_F(NaviSchedResourceTest,
       testCancelledReservationLatePartialBatchPublishesAndRetiresActualAgentLoad)
{
    for (const bool pdSeparated : {true, false}) {
        for (const bool abnormalFinish : {false, true}) {
            SCOPED_TRACE(pdSeparated);
            SCOPED_TRACE(abnormalFinish);
            TestMasterStateR master;
            const std::string agentId = "agent_0";
            auto node = master.registerAgent(
                agentId, "agent_biz", "127.0.0.1:19000", 100);
            ASSERT_TRUE(node);
            NaviSchedAgentConfig config;
            config.runtime.bizName = "agent_biz";
            config.runtime.threadNum = 2;
            config.service.name = "agent_cancelled_reservation_late_load_test";
            config.service.enableKmon = false;
            config.service.gig.grpcPort = 0;
            config.service.enableSnapshot = false;
            config.service.waitNoQuery = false;
            config.service.batchTimeoutMs = 60000;
            config.pdSeparated = pdSeparated;
            config.unifiedLatencyPrediction = true;
            NaviSchedAgent agent(config);
            ASSERT_TRUE(agent.init());
            initializeAgentCachePolicy(agent);
            auto impl = NaviSchedAgentImpl::getImpl(agent);
            ASSERT_TRUE(impl);
            auto reportPipe = std::make_shared<MasterReportAsyncPipe>(&master, agentId);
            ASSERT_TRUE(impl->_agentReportR->subscribe("master_0", reportPipe));
            ASSERT_TRUE(reportPipe->allReportsSucceeded());

            reserveBatch(node, 101, autil::TimeUtility::currentTime(), 30.0,
                         {1001, 1002});
            NaviSchedTarget target;
            target.bizName = "agent_biz";
            target.agentAddress = "127.0.0.1:19000";
            ASSERT_TRUE(master.reportDispatchFailed(target, 101, 1001));
            ASSERT_TRUE(master.reportDispatchFailed(target, 101, 1002));
            ASSERT_EQ(0u, pendingReservationCount(node));
            ASSERT_EQ(0u, pendingCacheBatchCount(node));

            auto stats = makeRequestStats(1001);
            stats.totalTokenCount = 256;
            auto request = makeBatchRequest(stats);
            request.blockHashes = makeBlockHashes({11});
            request.predictedQueueLatencyMs = 10.0;
            request.predictedExecutionLatencyMs = 20.0;
            std::promise<NaviSchedBatchPtr> ready;
            auto readyFuture = ready.get_future();
            ASSERT_TRUE(agent.addBatchRequest(
                request, 101, 2,
                [&ready](const NaviSchedBatchPtr &batch) { ready.set_value(batch); }));
            const auto aggregating = node->getRuntimeState();
            EXPECT_EQ(1, aggregating.load.inflightRequests);
            EXPECT_DOUBLE_EQ(30.0, aggregating.load.inflightPredictedLatencySumMs);
            EXPECT_EQ(1, aggregating.load.batchWaitingRequests);
            EXPECT_EQ(pdSeparated ? 0 : 1, aggregating.workload.requestCount);
            if (!pdSeparated) {
                EXPECT_EQ(256, aggregating.workload.remainingPrefillTokenCount);
                const auto native = impl->_agentReportR->getWorkloadOwnershipStats();
                EXPECT_EQ(1u, native.requestCount);
                EXPECT_EQ(1u, native.unbatchedRequestCount);
                EXPECT_EQ(0u, native.batchCount);
                EXPECT_NE(std::string::npos, impl->makeSnapshot().find(
                    "native_workload: batches=0, requests=1, unbatched_requests=1,"));
            }
            EXPECT_EQ(0u, pendingReservationCount(node));
            EXPECT_EQ(0, impl->_agentReportR->getPendingCacheState().batchCount);

            // Trigger the real expiration path without relying on a short wall-clock
            // deadline for the assertions about the aggregation phase.
            {
                autil::ScopedLock lock(impl->_agentBatchR->_lock);
                auto &pending = impl->_agentBatchR->_callbackBatches;
                ASSERT_EQ(1u, pending.size());
                pending.at(101)->deadlineTimeUs = autil::TimeUtility::currentTime() - 1;
            }
            impl->_agentBatchR->expireBatches();
            ASSERT_EQ(std::future_status::ready,
                      readyFuture.wait_for(std::chrono::seconds(2)));
            auto batch = readyFuture.get();
            ASSERT_TRUE(batch);
            EXPECT_TRUE(batch->timedOut);
            EXPECT_EQ((std::vector<uint64_t>{1001}), batch->requestIds);
            EXPECT_EQ(1u, impl->_agentBatchR->getTimeoutBatchCount());
            EXPECT_EQ(1u, impl->_agentBatchR->getTimeoutMissingRequestCount());
            for (size_t retry = 0; retry < 2000; ++retry) {
                const auto runtime = node->getRuntimeState();
                if (runtime.load.queuedBatchRequests == 1 &&
                    runtime.workload.requestCount == 1) {
                    break;
                }
                usleep(1000);
            }
            const auto queued = node->getRuntimeState();
            EXPECT_EQ(1, queued.load.inflightRequests);
            EXPECT_EQ(0, queued.load.batchWaitingRequests);
            EXPECT_EQ(1, queued.load.queuedBatchRequests);
            EXPECT_EQ(1, queued.workload.requestCount);
            EXPECT_EQ(256, queued.workload.remainingPrefillTokenCount);
            EXPECT_EQ(0u, pendingReservationCount(node));
            EXPECT_EQ(1, impl->_agentReportR->getPendingCacheState().batchCount);

            if (abnormalFinish) {
                batch->finishReporter.reset();
            } else {
                ASSERT_TRUE(batch->finishReporter->startBatch({1001}));
                ASSERT_TRUE(batch->finishReporter->finishBatch({stats}));
            }
            for (size_t retry = 0; retry < 2000; ++retry) {
                const auto runtime = node->getRuntimeState();
                if (runtime.load.inflightRequests == 0 &&
                    runtime.workload.requestCount == 0) {
                    break;
                }
                usleep(1000);
            }
            const auto finished = node->getRuntimeState();
            EXPECT_EQ(0, finished.load.inflightRequests);
            EXPECT_DOUBLE_EQ(0.0, finished.load.inflightPredictedLatencySumMs);
            EXPECT_EQ(0, finished.workload.requestCount);
            EXPECT_EQ(0, impl->_agentReportR->getPendingCacheState().batchCount);
            EXPECT_EQ(0u, pendingReservationCount(node));
            EXPECT_EQ(0u, pendingCacheBatchCount(node));
            EXPECT_TRUE(reportPipe->allReportsSucceeded());
            ASSERT_TRUE(impl->_agentReportR->unsubscribe("master_0", reportPipe));
            agent.stop();
        }
    }
}

TEST_F(NaviSchedResourceTest,
       testNonPdUnifiedBatchReadyOwnsWorkloadBeforeObserverAdmission)
{
    TestMasterStateR master;
    const std::string agentId = "agent_0";
    auto node = master.registerAgent(agentId, "agent_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(node);

    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_non_pd_unified_admission_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    config.service.waitNoQuery = false;
    config.pdSeparated = false;
    config.unifiedLatencyPrediction = true;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);
    auto impl = NaviSchedAgentImpl::getImpl(agent);
    ASSERT_TRUE(impl);
    auto reportPipe = std::make_shared<MasterReportAsyncPipe>(&master, agentId);
    ASSERT_TRUE(impl->_agentReportR->subscribe("master_0", reportPipe));
    ASSERT_TRUE(reportPipe->allReportsSucceeded());

    reserveBatch(node, 101, autil::TimeUtility::currentTime(), 20.0, {1001});
    auto waiter = std::make_shared<CountingAsyncPipe>();
    bool acknowledged = false;
    ASSERT_TRUE(node->registerDispatchWaiter(101, 1001, waiter, acknowledged));
    ASSERT_FALSE(acknowledged);

    NaviSchedBatchPtr batch;
    auto request = makeRequestStats(1001);
    request.totalTokenCount = 256;
    ASSERT_TRUE(agent.addBatchRequest(
        makeBatchRequest(request), 101, 1,
        [&batch](const NaviSchedBatchPtr &readyBatch) { batch = readyBatch; }));
    ASSERT_TRUE(batch);
    for (size_t retry = 0; retry < 500 && !waiter->eof.load(std::memory_order_acquire);
         ++retry) {
        usleep(1000);
    }
    EXPECT_TRUE(waiter->eof.load(std::memory_order_acquire));
    EXPECT_EQ(MasterBatchReservation::RequestState::DISPATCHED,
              reservationRequestState(node, 101, 1001));
    ASSERT_EQ(1, pendingReservationCount(node));
    EXPECT_EQ(0, node->_pendingBatchReservations.front()->batch.getWaitingFeatures()
                     .getBatchCount());
    EXPECT_FALSE(
        node->_pendingBatchReservations.front()->batch.isDispatchAcknowledged(1001));
    auto lateWaiter = std::make_shared<CountingAsyncPipe>();
    acknowledged = false;
    ASSERT_TRUE(node->registerDispatchWaiter(101, 1001, lateWaiter, acknowledged));
    EXPECT_TRUE(acknowledged);
    EXPECT_FALSE(lateWaiter->eof.load(std::memory_order_acquire));

    const auto acknowledgedRuntime = node->getRuntimeState();
    EXPECT_EQ(1, acknowledgedRuntime.load.inflightRequests);
    EXPECT_EQ(1, acknowledgedRuntime.workload.requestCount);
    EXPECT_EQ(256, acknowledgedRuntime.workload.remainingPrefillTokenCount);
    EXPECT_EQ(1u, impl->_agentReportR->_nativeWorkload.requestCount());

    NaviSchedWorkloadSnapshot workload;
    workload.revision = 1;
    workload.eventTimeUs = autil::TimeUtility::currentTime();
    workload.batchCount = 1;
    workload.requestCount = 1;
    workload.remainingPrefillRequestCount = 1;
    workload.runningRequestCount = 1;
    workload.remainingPrefillTokenCount = request.totalTokenCount;
    workload.remainingPrefillTokenSquareSum =
        static_cast<double>(request.totalTokenCount) * request.totalTokenCount;
    workload.remainingTotalTokenCount = request.totalTokenCount;
    workload.remainingTotalTokenSquareSum = workload.remainingPrefillTokenSquareSum;
    workload.totalPromptTokenCount = request.totalTokenCount;
    workload.prefillCapacitySplit = true;
    workload.maxRunningRequestCount = 1;
    workload.runningCapacitySlotCount = 1;
    workload.runningCapacityPrefillRequestCount = 1;
    workload.runningCapacityPrefillTokenCount = request.totalTokenCount;
    workload.runningCapacityPrefillTokenSquareSum =
        workload.remainingPrefillTokenSquareSum;
    workload.admittedBatch = batch->makeLocalBatchInfo();
    ASSERT_TRUE(workload.valid());
    ASSERT_EQ(4, impl->_agentReportR->reportWorkloadUpdated(workload));
    EXPECT_EQ(0u, impl->_agentReportR->_nativeWorkload.requestCount());
    EXPECT_EQ(MasterBatchReservation::RequestState::DISPATCHED,
              reservationRequestState(node, 101, 1001));
    EXPECT_EQ(0, node->_pendingBatchReservations.front()->batch.getWaitingFeatures()
                     .getBatchCount());
    EXPECT_EQ(0, node->_pendingBatchReservations.front()->batch.getAcknowledgedWaitingRequestCount());
    const auto admittedRuntime = node->getRuntimeState();
    EXPECT_EQ(1, admittedRuntime.load.inflightRequests);
    EXPECT_EQ(1, admittedRuntime.workload.requestCount);
    EXPECT_TRUE(reportPipe->allReportsSucceeded());

    ASSERT_TRUE(batch->finishReporter->startBatch({request.requestId}));
    ASSERT_TRUE(batch->finishReporter->finishBatch({request}));
    for (size_t retry = 0; retry < 500 && pendingReservationCount(node) != 0; ++retry) {
        usleep(1000);
    }
    EXPECT_EQ(0, pendingReservationCount(node));
    ASSERT_TRUE(impl->_agentReportR->unsubscribe("master_0", reportPipe));
    agent.stop();
}

TEST_F(NaviSchedResourceTest, testDisablingForwardHandlerAbortsPendingBatch)
{
    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_forward_disable_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    config.service.waitNoQuery = false;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);
    ASSERT_TRUE(agent.setForwardBatchHandler(
        [](const std::vector<NaviSchedForwardedRequest> &, int64_t,
           const NaviSchedBatchFinishReporterPtr &) { return true; }));
    auto impl = NaviSchedAgentImpl::getImpl(agent);
    impl->_agentReportR->finishAll();
    impl->_stoppingReported = true;

    NaviSchedForwardRequest request;
    request.request.requestId = 1;
    request.request.promptTokenCount = 256;
    request.request.blockSize = 256;
    request.request.forwardPayload = "first";
    request.decision.batchId = 72;
    request.decision.expectedBatchSize = 2;
    auto pipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(impl->submitForwardRequest(request, pipe));
    ASSERT_EQ(1, impl->getInflightRequestCount());

    ASSERT_TRUE(agent.setForwardBatchHandler({}));

    ASSERT_TRUE(pipe->eof);
    ASSERT_EQ(1, pipe->eofCount);
    ASSERT_EQ(0, impl->getInflightRequestCount());
    AgentBatchR::ExecutionState state;
    ASSERT_TRUE(impl->_agentBatchR->getExecutionState(state));
    ASSERT_EQ(0, state.batchWaitingRequests);
    ASSERT_EQ(0, state.queuedBatchRequests);
    ASSERT_EQ(1, impl->_agentBatchR->getAbnormalBatchFinishCount());
    agent.stop();
}

TEST_F(NaviSchedResourceTest, testAgentStopWaitsForReadyCallback)
{
    NaviSchedAgentConfig config;
    config.runtime.bizName = "agent_biz";
    config.runtime.threadNum = 2;
    config.service.name = "agent_stop_ready_callback_test";
    config.service.enableKmon = false;
    config.service.gig.grpcPort = 0;
    config.service.enableSnapshot = false;
    NaviSchedAgent agent(config);
    ASSERT_TRUE(agent.init());
    initializeAgentCachePolicy(agent);

    std::mutex mutex;
    std::condition_variable condition;
    bool callbackStarted = false;
    bool releaseCallback = false;
    std::atomic<bool> stopFinished{false};
    NaviSchedRequestStats request;
    request.requestId = 1;
    request.totalTokenCount = 256;
    std::thread requestThread([&]() {
        EXPECT_TRUE(agent.addBatchRequest(
            makeBatchRequest(request), 0, 0, [&](const NaviSchedBatchPtr &) {
                std::unique_lock<std::mutex> lock(mutex);
                callbackStarted = true;
                condition.notify_all();
                condition.wait(lock, [&]() { return releaseCallback; });
            }));
    });
    {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [&]() { return callbackStarted; });
    }
    std::thread stopThread([&]() {
        agent.stop();
        stopFinished.store(true, std::memory_order_relaxed);
    });
    usleep(10 * 1000);
    EXPECT_FALSE(stopFinished.load(std::memory_order_relaxed));
    {
        std::lock_guard<std::mutex> lock(mutex);
        releaseCallback = true;
    }
    condition.notify_all();
    requestThread.join();
    stopThread.join();
    EXPECT_TRUE(stopFinished.load(std::memory_order_relaxed));
}

