TEST_F(NaviSchedResourceTest, testScheduleSnapshotFollowsAgentBiz)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("prefill_0", "model_biz_a", "127.0.0.1:1000", 0);
    ASSERT_TRUE(state);
    auto makeRequest = [](const std::string &bizName) {
        auto request = std::make_shared<ClientRequestToMasterData>();
        request->requestId = 1;
        request->bizName = bizName;
        request->promptTokenCount = 256;
        request->timeoutMs = 1000;
        return request;
    };
    auto contextA =
        SchedulerTestDriver::makeContext(runtime, {makeRequest("model_biz_a")});
    ASSERT_EQ(0, contextA.nodeCount());

    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    handshake->control->serverInfo.port = 18000;
    ASSERT_TRUE(runtime.reportAgent("prefill_0", handshake));
    contextA = SchedulerTestDriver::makeContext(runtime, {makeRequest("model_biz_a")});
    ASSERT_EQ(0, contextA.nodeCount());
    ASSERT_TRUE(runtime.reportAgent("prefill_0", makeCachePolicyUpdate(256)));

    contextA = SchedulerTestDriver::makeContext(runtime, {makeRequest("model_biz_a")});
    ASSERT_EQ(0, contextA.nodeCount());
    ASSERT_TRUE(runtime.reportAgent("prefill_0", makeEmptyPendingCacheSnapshot()));
    contextA = SchedulerTestDriver::makeContext(runtime, {makeRequest("model_biz_a")});
    ASSERT_EQ(1, contextA.nodeCount());
    ASSERT_EQ("prefill_0", contextA.getNode(0).getAgentId());

    runtime.registerAgent("prefill_0", "model_biz_b", "127.0.0.1:1000", 0);
    contextA = SchedulerTestDriver::makeContext(runtime, {makeRequest("model_biz_a")});
    auto contextB =
        SchedulerTestDriver::makeContext(runtime, {makeRequest("model_biz_b")});
    ASSERT_EQ(0, contextA.nodeCount());
    ASSERT_EQ(1, contextB.nodeCount());
    ASSERT_EQ("prefill_0", contextB.getNode(0).getAgentId());

    auto stopping = makeControlUpdate(NaviSchedAgentEvent::AGENT_STOPPING);
    ASSERT_TRUE(runtime.reportAgent(state, stopping));
    contextB = SchedulerTestDriver::makeContext(runtime, {makeRequest("model_biz_b")});
    ASSERT_EQ(0, contextB.nodeCount());
    ASSERT_EQ(1, runtime.getNodes().size());

    ASSERT_TRUE(runtime.removeAgent(state));
    ASSERT_TRUE(runtime.getNodes().empty());
}

TEST_F(NaviSchedResourceTest, testOldCollectorCannotRemoveReplacementNode)
{
    TestMasterStateR runtime;
    const std::string agentId = "prefill_0";
    auto oldState = runtime.createAgent(agentId, "model_biz", "127.0.0.1:1000", 0);
    ASSERT_TRUE(oldState);
    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    handshake->control->serverInfo.port = 18000;
    ASSERT_TRUE(runtime.reportAgent(oldState, handshake));
    ASSERT_TRUE(runtime.reportAgent(oldState, makeCachePolicyUpdate(1)));
    ASSERT_TRUE(runtime.reportAgent(oldState, makeCacheSnapshot({11}, 100, 2)));
    ASSERT_TRUE(runtime.reportAgent(oldState, makeEmptyPendingCacheSnapshot()));
    NaviSchedNodeSnapshot oldSnapshot;
    ASSERT_TRUE(oldState->getScheduleSnapshot("model_biz", oldSnapshot));

    auto newState = runtime.createAgent(agentId, "model_biz", "127.0.0.1:1000", 0);
    ASSERT_TRUE(newState);
    ASSERT_NE(oldState, newState);
    ASSERT_EQ(newState, runtime.getNodeState(hashString(agentId)));
    std::vector<MasterBatchReservation::Request> staleRequests = {
        {1001, 1, 1, 0, nullptr},
    };
    EXPECT_FALSE(oldState->reserveBatch(101, autil::TimeUtility::currentTime(), 1.0,
                                        std::move(staleRequests)));
    EXPECT_FALSE(oldState->getScheduleSnapshot("model_biz", oldSnapshot));

    auto stopping = makeControlUpdate(NaviSchedAgentEvent::AGENT_STOPPING);
    ASSERT_TRUE(runtime.reportAgent(oldState, stopping));
    ASSERT_FALSE(runtime.removeAgent(oldState));
    ASSERT_EQ(newState, runtime.getNodeState(hashString(agentId)));

    ASSERT_TRUE(runtime.reportAgent(newState, handshake));
    ASSERT_TRUE(newState->getInfo().online);
    ASSERT_EQ(newState, runtime.getNodeState(hashString(agentId)));
    ASSERT_TRUE(runtime.removeAgent(newState));
    ASSERT_TRUE(runtime.getNodes().empty());
}

TEST_F(NaviSchedResourceTest, testCustomSchedulerUsesConcurrentNodeViews)
{
    TestMasterStateR runtime;
    auto addAgent = [&runtime](const std::string &agentId, int32_t serverPort,
                               const NaviSchedBlockHashes &hashes) {
        runtime.registerAgent(agentId, "model_biz", "127.0.0.1:19000", 0);
        auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
        handshake->control->serverInfo.port = serverPort;
        handshake->latency = std::make_shared<AgentLatencyToMasterData>();
        handshake->latency->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
        handshake->latency->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
        handshake->latency->modelRevision = 3;
        handshake->latency->parameters.assign(NonLinearPrefillModelR::PARAMETER_COUNT,
                                              1.0);
        handshake->latency->residualParameters[3] = 25.0;
        handshake->latency->residualLastUpdateTimeUs = autil::TimeUtility::currentTime();
        ASSERT_TRUE(runtime.reportAgent(agentId, handshake));
        auto cacheUpdate = makeCacheSnapshot(hashes);
        cacheUpdate->cache->blockSize = 256;
        cacheUpdate->cache->linearStep = 1;
        cacheUpdate->cache->hybridTailRequired = 0;
        cacheUpdate->cache->totalBlocks = 100;
        ASSERT_TRUE(runtime.reportAgent(agentId, cacheUpdate));
        ASSERT_TRUE(runtime.reportAgent(agentId, makeEmptyPendingCacheSnapshot()));
    };
    addAgent("agent_0", 18000, {11});
    addAgent("agent_1", 18001, {11, 22});
    auto batchFinished = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED);
    setInflightSnapshot(batchFinished, 2, 3);
    batchFinished->requestEvent->completedRequestCount = 1;
    batchFinished->requestEvent->latencyMs = 12.5;
    ASSERT_TRUE(runtime.reportAgent("agent_1", batchFinished));
    auto loadUpdate = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
    setInflightSnapshot(loadUpdate, 2, 3);
    loadUpdate->requestEvent->batchWaitingRequests = 4;
    loadUpdate->requestEvent->queuedBatchRequests = 5;
    loadUpdate->requestEvent->runningRequests = 2;
    loadUpdate->requestEvent->batchTimeoutCount = 9;
    loadUpdate->requestEvent->queueTotalPredictedLatencyMs = 31.5;
    ASSERT_TRUE(runtime.reportAgent("agent_1", loadUpdate));
    PrefixScheduler scheduler;
    auto request = std::make_shared<ClientRequestToMasterData>();
    request->requestId = 103;
    request->bizName = "model_biz";
    request->timeoutMs = 1000;
    request->promptTokenCount = 512;
    request->blockHashes = makeBlockHashes({11, 22});
    auto context = SchedulerTestDriver::makeContext(runtime, {request});
    std::vector<NaviSchedDecision> decisions;
    ASSERT_TRUE(ScheduleReplayRunner::runContext(context, scheduler, decisions));
    ASSERT_EQ(1, decisions.size());
    const auto &decision = decisions.front();

    ASSERT_EQ("127.0.0.1:18001", decision.target.address);
    ASSERT_EQ("prefix_selected", decision.reason);
    ASSERT_GT(ScheduleReplayRunner::getScheduleTimeUs(context), 0);
    ASSERT_EQ(1, context.requestCount());
    ASSERT_EQ(2, context.nodeCount());
    const auto &item = context.getRequest(0);
    ASSERT_EQ(request->requestId, item.request.requestId);
    ASSERT_EQ(request->promptTokenCount, item.request.promptTokenCount);
    ASSERT_EQ(request->blockHashes.get(), item.request.blockHashes.get());
    ASSERT_EQ(0, item.waitTimeMs);
    ASSERT_EQ(1000, item.remainingTimeoutMs);
    ASSERT_FALSE(item.timeoutTriggered);
    const NaviSchedScheduleNode *selectedNode = nullptr;
    for (size_t index = 0; index < context.nodeCount(); ++index) {
        const auto &node = context.getNode(index);
        if ("agent_1" == node.getAgentId()) {
            selectedNode = &node;
            break;
        }
    }
    ASSERT_NE(nullptr, selectedNode);
    ASSERT_EQ("agent_1", selectedNode->getAgentId());
    ASSERT_EQ(3, selectedNode->getInflightRequests());
    ASSERT_EQ(4, selectedNode->getBatchWaitingRequests());
    ASSERT_EQ(5, selectedNode->getQueuedBatchRequests());
    ASSERT_EQ(2, selectedNode->getRunningRequests());
    ASSERT_GE(selectedNode->getEstimatedQueueWaitMs(), 0.0);
    ASSERT_LE(selectedNode->getEstimatedQueueWaitMs(), 31.5);
    ASSERT_EQ(100, selectedNode->getTotalBlocks());
    ASSERT_TRUE(selectedNode->hasLatencyModel());
    ASSERT_EQ(NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL,
              selectedNode->getLatencyFormula());
    ASSERT_EQ(NonLinearPrefillModelR::BINARY_VERSION,
              selectedNode->getLatencyBinaryVersion());
    ASSERT_EQ(3, selectedNode->getLatencyModelRevision());
    ASSERT_EQ(std::vector<double>(NonLinearPrefillModelR::PARAMETER_COUNT, 1.0),
              selectedNode->getLatencyParameters());

    ASSERT_EQ(0, context.getCacheHitBlockCount(context.requestCount(), 0));
    ASSERT_EQ(0, context.getCacheHitBlockCount(0, context.nodeCount()));
}

