TEST_F(NaviSchedResourceTest, testUnifiedPredictionIncludesWorkloadAndEachReservationOnce)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(state);
    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    handshake->control->pdSeparated = true;
    handshake->control->unifiedLatencyPrediction = true;
    handshake->control->serverInfo.port = 18000;
    handshake->latency = std::make_shared<AgentLatencyToMasterData>();
    handshake->latency->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    handshake->latency->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    handshake->latency->modelRevision = 1;
    handshake->latency->parameters = {
        30.0, 20.0, 10.0, 40.0, 5.0, 3.0, 0.0, 100.0, 4.0, 0.75,
    };
    auto workload = makeWorkloadUpdate(1, 100)->workload;
    workload->batchCount = 1;
    workload->requestCount = 2;
    workload->remainingPrefillRequestCount = 1;
    workload->runningRequestCount = 2;
    workload->waitingRequestCount = 0;
    workload->remainingPrefillContextTokenCount = 256;
    workload->remainingPrefillTokenCount = 512;
    workload->remainingPrefillTokenSquareSum = 512.0 * 512.0;
    workload->contextRemainingPrefillTokenProductSum = 256.0 * 512.0;
    workload->remainingTotalContextTokenCount = 384;
    workload->remainingTotalTokenCount = 768;
    workload->remainingTotalTokenSquareSum = 512.0 * 512.0 + 256.0 * 256.0;
    workload->contextRemainingTotalTokenProductSum = 256.0 * 512.0 + 128.0 * 256.0;
    workload->totalPromptTokenCount = 1152;
    workload->inFlightScheduledTokenCount = 0;
    handshake->workload = workload;
    ASSERT_TRUE(runtime.reportAgent("agent_0", handshake));
    ASSERT_TRUE(runtime.reportAgent("agent_0", makeCachePolicyUpdate(256)));
    ASSERT_TRUE(runtime.reportAgent("agent_0", makeEmptyPendingCacheSnapshot()));

    auto load = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
    load->requestEvent->runningRequests = 1;
    load->requestEvent->queueTotalPredictedLatencyMs = 125.0;
    ASSERT_TRUE(runtime.reportAgent("agent_0", load));

    auto makeRequest = [](uint64_t requestId, int64_t promptTokenCount) {
        auto request = std::make_shared<ClientRequestToMasterData>();
        request->requestId = requestId;
        request->bizName = "model_biz";
        request->promptTokenCount = promptTokenCount;
        request->blockSize = 256;
        request->blockHashes = makeBlockHashes({requestId * 10 + 1, requestId * 10 + 2});
        request->timeoutMs = 1000;
        return request;
    };

    auto firstRequest = makeRequest(101, 512);
    auto firstContext = SchedulerTestDriver::makeContext(runtime, {firstRequest});
    std::vector<NaviSchedDecision> firstDecisions;
    BatchScheduler scheduler;
    ASSERT_TRUE(
        ScheduleReplayRunner::runContext(firstContext, scheduler, firstDecisions));
    ASSERT_EQ(1, firstContext.nodeCount());
    ASSERT_TRUE(firstContext.getNode(0).usesUnifiedLatencyPrediction());
    EXPECT_DOUBLE_EQ(0.0, firstContext.getNode(0).getEstimatedQueueWaitMs());
    NaviSchedLatencyFeatures firstExpected;
    ASSERT_TRUE(firstExpected.appendPrefillWorkload(*workload));
    firstExpected.appendBatchCount(1);
    firstExpected.appendRequest(0, firstRequest->promptTokenCount);
    NaviSchedLatencyFeatures firstFloor;
    firstFloor.appendBatchCount(1);
    firstFloor.appendRequest(0, firstRequest->promptTokenCount);
    EXPECT_DOUBLE_EQ(
        firstContext.getNode(0).decayUnifiedLatency(
            NonLinearPrefillModelR::predict(firstExpected,
                                            handshake->latency->parameters),
            NonLinearPrefillModelR::predict(firstFloor, handshake->latency->parameters)),
        firstContext.estimateBatchExecutionLatencyMs(0, {0}));

    runtime.reserveScheduleBatches(firstContext);
    ASSERT_EQ(1, pendingReservationCount(state));

    auto secondRequest = makeRequest(202, 512);
    auto secondContext = SchedulerTestDriver::makeContext(runtime, {secondRequest});
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(secondContext));
    ASSERT_EQ(1, secondContext.nodeCount());
    NaviSchedLatencyFeatures secondExpected;
    ASSERT_TRUE(secondExpected.appendPrefillWorkload(*workload));
    secondExpected.appendBatchCount(2);
    secondExpected.appendRequest(0, firstRequest->promptTokenCount);
    secondExpected.appendRequest(0, secondRequest->promptTokenCount);
    NaviSchedLatencyFeatures secondFloor;
    secondFloor.appendBatchCount(2);
    secondFloor.appendRequest(0, firstRequest->promptTokenCount);
    secondFloor.appendRequest(0, secondRequest->promptTokenCount);
    EXPECT_DOUBLE_EQ(
        secondContext.getNode(0).decayUnifiedLatency(
            NonLinearPrefillModelR::predict(secondExpected,
                                            handshake->latency->parameters),
            NonLinearPrefillModelR::predict(secondFloor, handshake->latency->parameters)),
        secondContext.estimateBatchExecutionLatencyMs(0, {0}));

    auto replay = runtime.makeScheduleReplay(secondContext);
    ASSERT_TRUE(replay);
    ASSERT_EQ(1, replay->nodes.size());
    EXPECT_TRUE(replay->nodes[0].unifiedLatencyPrediction);
    EXPECT_EQ(workload->batchCount, replay->nodes[0].workload.batchCount);
    EXPECT_EQ(1, replay->nodes[0].reservedWorkloadFeatures.getBatchCount());
    EXPECT_EQ(firstRequest->promptTokenCount,
              replay->nodes[0].reservedWorkloadFeatures.getCacheMissTokenCount());

    autil::DataBuffer replayBuffer;
    replay->serialize(replayBuffer);
    NaviSchedScheduleReplay wireReplay;
    wireReplay.deserialize(replayBuffer);
    const auto replayJson = NaviSchedScheduleReplayJson::toJsonString(wireReplay);
    NaviSchedScheduleReplay decodedReplay;
    ASSERT_NO_THROW(
        NaviSchedScheduleReplayJson::fromJsonString(replayJson, decodedReplay));
    NaviSchedScheduleContext replayContext;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(decodedReplay, replayContext));
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(replayContext));
    ASSERT_EQ(1, replayContext.nodeCount());
    EXPECT_DOUBLE_EQ(secondContext.estimateBatchExecutionLatencyMs(0, {0}),
                     replayContext.estimateBatchExecutionLatencyMs(0, {0}));
}

