TEST_F(NaviSchedResourceTest, testMasterReservesQueueUntilAgentReportsBatchLoad)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(state);
    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    handshake->control->serverInfo.port = 18000;
    handshake->latency = std::make_shared<AgentLatencyToMasterData>();
    handshake->latency->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    handshake->latency->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    handshake->latency->modelRevision = 1;
    handshake->latency->parameters = {
        30.0, 20.0, 10.0, 40.0, 5.0, 3.0, 0.0, 100.0, 4.0, 0.75,
    };
    ASSERT_TRUE(runtime.reportAgent("agent_0", handshake));
    ASSERT_TRUE(runtime.reportAgent("agent_0", makeCachePolicyUpdate(256)));
    ASSERT_TRUE(runtime.reportAgent("agent_0", makeEmptyPendingCacheSnapshot()));

    auto makeRequest = [](uint64_t requestId) {
        auto request = std::make_shared<ClientRequestToMasterData>();
        request->requestId = requestId;
        request->bizName = "model_biz";
        request->promptTokenCount = 1024;
        request->blockSize = 256;
        request->timeoutMs = 1000;
        return request;
    };
    auto first = makeRequest(101);
    auto second = makeRequest(102);
    auto context = SchedulerTestDriver::makeContext(runtime, {first, second});
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
    BatchLatencyProbeScheduler scheduler;
    ASSERT_TRUE(scheduler.schedule(context));
    std::vector<NaviSchedDecision> decisions;
    ASSERT_TRUE(ScheduleReplayRunner::collectDecisions(context, decisions));
    ASSERT_EQ(2, decisions.size());
    ASSERT_GT(scheduler.predictedLatencyMs, 0.0);
    const auto firstPredictedLatencyMs =
        decisions[0].predictedQueueLatencyMs + decisions[0].predictedExecutionLatencyMs;
    const auto secondPredictedLatencyMs =
        decisions[1].predictedQueueLatencyMs + decisions[1].predictedExecutionLatencyMs;
    const auto totalPredictedLatencyMs =
        firstPredictedLatencyMs + secondPredictedLatencyMs;
    runtime.reserveScheduleBatches(context);
    ASSERT_EQ(1, pendingReservationCount(state));
    auto dispatchStats = state->getDispatchStats();
    EXPECT_EQ(2, dispatchStats.requestCount);
    EXPECT_EQ(1, dispatchStats.batchCount);
    runtime.reserveScheduleBatches(context);
    dispatchStats = state->getDispatchStats();
    EXPECT_EQ(2, dispatchStats.requestCount);
    EXPECT_EQ(1, dispatchStats.batchCount);
    const auto scheduleTimeUs = reservationScheduleTimeUs(state);
    const auto expectedPredictedLatencyMs = scheduler.predictedLatencyMs;
    auto reservedContext = SchedulerTestDriver::makeContext(runtime, {makeRequest(103)});
    ASSERT_EQ(1, reservedContext.nodeCount());
    EXPECT_EQ(2, reservedContext.getNode(0).getInflightRequests());

    auto reservedLoad = scheduleLoad(state, scheduleTimeUs + 10 * 1000 * 1000);
    EXPECT_DOUBLE_EQ(expectedPredictedLatencyMs,
                     reservedLoad.queueTotalPredictedLatencyMs);

    auto received = makeRequestUpdate(NaviSchedAgentEvent::REQUEST_RECEIVED);
    received->requestEvent->requestId = first->requestId;
    setInflightSnapshot(received, 2, 1, firstPredictedLatencyMs);
    ASSERT_TRUE(runtime.reportAgent("agent_0", received));
    ASSERT_EQ(1, pendingReservationCount(state));
    EXPECT_EQ(
        MasterBatchReservation::RequestState::WAITING,
        reservationRequestState(state, decisions.front().batchId, first->requestId));
    auto afterRequestReceivedLoad =
        scheduleLoad(state, scheduleTimeUs + 20 * 1000 * 1000);
    EXPECT_DOUBLE_EQ(expectedPredictedLatencyMs,
                     afterRequestReceivedLoad.queueTotalPredictedLatencyMs);

    received = makeRequestUpdate(NaviSchedAgentEvent::REQUEST_RECEIVED);
    received->requestEvent->requestId = second->requestId;
    setInflightSnapshot(received, 3, 2, totalPredictedLatencyMs);
    ASSERT_TRUE(runtime.reportAgent("agent_0", received));
    ASSERT_EQ(1, pendingReservationCount(state));
    EXPECT_EQ(
        MasterBatchReservation::RequestState::WAITING,
        reservationRequestState(state, decisions.front().batchId, second->requestId));
    auto partiallyReceivedContext =
        SchedulerTestDriver::makeContext(runtime, {makeRequest(104)});
    ASSERT_EQ(1, partiallyReceivedContext.nodeCount());
    EXPECT_EQ(2, partiallyReceivedContext.getNode(0).getInflightRequests());

    received = makeRequestUpdate(NaviSchedAgentEvent::REQUEST_RECEIVED);
    received->requestEvent->requestId = second->requestId;
    setInflightSnapshot(received, 4, INT_MAX, totalPredictedLatencyMs);
    ASSERT_TRUE(runtime.reportAgent("agent_0", received));
    auto saturatedContext = SchedulerTestDriver::makeContext(runtime, {makeRequest(105)});
    ASSERT_EQ(1, saturatedContext.nodeCount());
    EXPECT_EQ(INT_MAX, saturatedContext.getNode(0).getInflightRequests());

    received = makeRequestUpdate(NaviSchedAgentEvent::REQUEST_RECEIVED);
    received->requestEvent->requestId = second->requestId;
    setInflightSnapshot(received, 5, 2, totalPredictedLatencyMs);
    ASSERT_TRUE(runtime.reportAgent("agent_0", received));

    auto load = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
    setInflightSnapshot(load, 5, 2, totalPredictedLatencyMs);
    load->requestEvent->runningRequests = 2;
    ASSERT_TRUE(runtime.reportAgent("agent_0", load));
    ASSERT_EQ(1, pendingReservationCount(state));
    EXPECT_GT(scheduleLoad(state, autil::TimeUtility::currentTime())
                  .queueTotalPredictedLatencyMs,
              0.0);

    load = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
    setInflightSnapshot(load, 5, 2, totalPredictedLatencyMs);
    const auto localBatch = makeLocalBatchInfo(decisions.front().batchId, 9001, 2);
    load->requestEvent->localBatch = localBatch;
    ASSERT_TRUE(runtime.reportAgent("agent_0", load));
    EXPECT_EQ(1, pendingReservationCount(state));
    EXPECT_EQ(
        MasterBatchReservation::RequestState::DISPATCHED,
        reservationRequestState(state, decisions.front().batchId, first->requestId));
    EXPECT_DOUBLE_EQ(0.0, scheduleLoad(state, autil::TimeUtility::currentTime())
                              .queueTotalPredictedLatencyMs);
    auto admittedContext = SchedulerTestDriver::makeContext(runtime, {makeRequest(104)});
    ASSERT_EQ(1, admittedContext.nodeCount());
    EXPECT_EQ(2, admittedContext.getNode(0).getInflightRequests());

    auto finished = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED);
    setInflightSnapshot(finished, 6, 0);
    finished->requestEvent->localBatch = localBatch;
    ASSERT_TRUE(runtime.reportAgent("agent_0", finished));
    EXPECT_EQ(0, pendingReservationCount(state));
}

TEST_F(NaviSchedResourceTest, testDuplicateBatchReservationRequiresIdenticalDefinition)
{
    TestMasterStateR master;
    auto node = master.createAgent("agent_0", "agent_biz", "", 0);
    ASSERT_TRUE(node);
    const auto scheduleTimeUs = autil::TimeUtility::currentTime();
    const NaviSchedCachePolicy policy{1, 1, false};
    auto makeRequests = [](uint64_t requestId, uint64_t blockHash) {
        return std::vector<MasterBatchReservation::Request>{
            {requestId, 1, 1, 0, makeBlockHashes({blockHash})},
        };
    };

    bool pendingCacheTracked = false;
    ASSERT_TRUE(node->reserveBatch(101, scheduleTimeUs, 20.0, makeRequests(1001, 11),
                                   &policy, &pendingCacheTracked));
    ASSERT_TRUE(pendingCacheTracked);
    const auto initialDispatchStats = node->getDispatchStats();
    ASSERT_EQ(1, initialDispatchStats.requestCount);
    ASSERT_EQ(1, initialDispatchStats.batchCount);
    ASSERT_EQ(1, pendingReservationCount(node));
    ASSERT_EQ(1, pendingCacheBatchCount(node));

    pendingCacheTracked = false;
    EXPECT_TRUE(node->reserveBatch(101, scheduleTimeUs, 20.0, makeRequests(1001, 11),
                                   &policy, &pendingCacheTracked));
    EXPECT_TRUE(pendingCacheTracked);
    EXPECT_EQ(initialDispatchStats.requestCount, node->getDispatchStats().requestCount);
    EXPECT_EQ(initialDispatchStats.batchCount, node->getDispatchStats().batchCount);
    EXPECT_EQ(1, pendingReservationCount(node));
    EXPECT_EQ(1, pendingCacheBatchCount(node));

    pendingCacheTracked = true;
    EXPECT_FALSE(node->reserveBatch(101, scheduleTimeUs, 20.0, makeRequests(1002, 12),
                                    &policy, &pendingCacheTracked));
    EXPECT_FALSE(pendingCacheTracked);
    EXPECT_EQ(1, pendingReservationCount(node));
    EXPECT_EQ(1, pendingCacheBatchCount(node));
}

