TEST_F(NaviSchedResourceTest, testDispatchFailureRemovesOnlyFailedRequestFromPendingCache)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(state);
    NaviSchedTarget target;
    target.bizName = "model_biz";
    target.agentAddress = "127.0.0.1:19000";

    reserveBatchWithCache(state, 101, autil::TimeUtility::currentTime(), 20.0,
                          {1001, 1002}, {11});
    EXPECT_TRUE(runtime.reportDispatchFailed(target, 101, 1001));
    EXPECT_EQ(1, pendingReservationCount(state));
    EXPECT_EQ(1, pendingCacheBatchCount(state));
    EXPECT_TRUE(runtime.reportDispatchFailed(target, 101, 1002));
    EXPECT_EQ(0, pendingReservationCount(state));
    EXPECT_EQ(0, pendingCacheBatchCount(state));
    EXPECT_FALSE(runtime.reportDispatchFailed(target, 101, 1002));

    reserveBatchWithCache(state, 102, autil::TimeUtility::currentTime(), 30.0,
                          {2001, 2002}, {22});
    const auto admitted = makeLocalBatchInfo(102, 1002, 1, {2001});
    auto load = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
    load->requestEvent->localBatch = admitted;
    ASSERT_TRUE(runtime.reportAgent("agent_0", load));
    EXPECT_TRUE(runtime.reportDispatchFailed(target, 102, 2002));
    EXPECT_EQ(1, pendingReservationCount(state));
    EXPECT_EQ(1, pendingCacheBatchCount(state));

    auto finished = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED);
    finished->requestEvent->localBatch = admitted;
    ASSERT_TRUE(runtime.reportAgent("agent_0", finished));
    EXPECT_EQ(0, pendingReservationCount(state));
    EXPECT_EQ(0, pendingCacheBatchCount(state));
}

TEST_F(NaviSchedResourceTest, testDispatchFailurePreservesSurvivorCostSnapshot)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(state);
    const NaviSchedCachePolicy policy{16, 1, false};
    ASSERT_TRUE(state->reserveBatch(101, autil::TimeUtility::currentTime(), 30.0,
        {{1001, 32, 16, 16, makeBlockHashes({11, 12})},
         {1002, 48, 16, 16, makeBlockHashes({21, 22, 23})},
         {1003, 16, 16, 0, makeBlockHashes({31})}}, &policy));
    ASSERT_TRUE(runtime.reportAgent("agent_0", makeCacheSnapshot({21, 22, 23, 31})));
    auto *reservation = state->findReservationLocked(101);
    ASSERT_TRUE(reservation);
    ASSERT_EQ(32, reservation->batch.getWaitingFeatures().getCacheHitTokenCount());
    bool released = true;
    ASSERT_TRUE(state->reportDispatchFailed(101, 1001, released));
    EXPECT_FALSE(released);
    reservation = state->findReservationLocked(101);
    ASSERT_TRUE(reservation);
    const auto &features = reservation->batch.getWaitingFeatures();
    EXPECT_EQ(1, features.getBatchCount());
    EXPECT_EQ(2, features.getBatchSize());
    EXPECT_EQ(16, features.getCacheHitTokenCount());
    EXPECT_EQ(48, features.getCacheMissTokenCount());
    EXPECT_DOUBLE_EQ(1280, features.getCacheMissTokenSquareSum());
    EXPECT_DOUBLE_EQ(512, features.getCacheHitMissTokenProductSum());
}

TEST_F(NaviSchedResourceTest, testAgentUpdateTimingSeparatesRuntimeLockAndRejects)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(state);
    auto update = makeWorkloadUpdate(7, 123);
    MasterStateR::AgentUpdateTiming timing;
    const auto before = autil::TimeUtility::monotonicTimeUs();
    ASSERT_TRUE(runtime.reportAgent(state, update, nullptr, nullptr, nullptr,
                                   "", nullptr, &timing));
    const auto after = autil::TimeUtility::monotonicTimeUs();
    EXPECT_LE(before, timing.beginMonoUs);
    EXPECT_LE(timing.beginMonoUs, timing.runtimeLockBeginMonoUs);
    EXPECT_LE(timing.runtimeLockBeginMonoUs, timing.runtimeLockAcquiredMonoUs);
    EXPECT_LE(timing.runtimeLockAcquiredMonoUs, timing.runtimeLockReleasedMonoUs);
    EXPECT_LE(timing.runtimeLockReleasedMonoUs, timing.endMonoUs);
    EXPECT_LE(timing.endMonoUs, after);
    EXPECT_EQ(7, state->_runtimeState.workload.revision);

    const auto rejectBefore = autil::TimeUtility::monotonicTimeUs();
    EXPECT_FALSE(runtime.reportAgent(state, nullptr, nullptr, nullptr, nullptr,
                                    "", nullptr, &timing));
    EXPECT_LE(rejectBefore, timing.beginMonoUs);
    EXPECT_LE(timing.beginMonoUs, timing.endMonoUs);
    EXPECT_LE(timing.endMonoUs, autil::TimeUtility::monotonicTimeUs());
    EXPECT_EQ(0, timing.runtimeLockBeginMonoUs);
    EXPECT_EQ(0, timing.runtimeLockAcquiredMonoUs);
    EXPECT_EQ(0, timing.runtimeLockReleasedMonoUs);
    EXPECT_EQ(7, state->_runtimeState.workload.revision);
}

TEST_F(NaviSchedResourceTest, testDispatchFailureDoesNotWaitForPhysicalCacheWriter)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(state);
    std::vector<uint64_t> requestIds(30);
    std::iota(requestIds.begin(), requestIds.end(), uint64_t{1001});
    reserveBatchWithCache(state, 101, autil::TimeUtility::currentTime(),
                          20.0, requestIds, {11, 22});

    std::promise<void> entered;
    auto started = entered.get_future();
    std::future<bool> cleanup;
    std::future_status status;
    {
        autil::ScopedWriteLock cacheWriter(state->_cacheLock);
        cleanup = std::async(std::launch::async, [&]() {
            entered.set_value();
            bool valid = true;
            for (auto requestId : requestIds) {
                bool released = false;
                valid &= state->reportDispatchFailed(101, requestId, released);
                valid &= released == (requestId == requestIds.back());
            }
            return valid;
        });
        started.wait();
        status = cleanup.wait_for(std::chrono::seconds(1));
    }
    // Release the writer before joining, including when the old path blocks.
    EXPECT_EQ(std::future_status::ready, status);
    EXPECT_TRUE(cleanup.get());
    EXPECT_EQ(0, state->getReservationStats().batchCount);
    EXPECT_EQ(0, pendingCacheBatchCount(state));
    EXPECT_EQ(0, pendingCacheBlockCount(state));
}

TEST_F(NaviSchedResourceTest, testBatchCompletionPreservesWaitingCacheSnapshotWithoutCacheLock)
{
    for (const bool successful : {false, true}) {
        SCOPED_TRACE(successful);
        TestMasterStateR runtime;
        auto state = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
        ASSERT_TRUE(state);
        std::vector<uint64_t> requestIds(30);
        std::iota(requestIds.begin(), requestIds.end(), uint64_t{1001});
        reserveBatchWithCache(state, 101, autil::TimeUtility::currentTime(),
                              20.0, requestIds, {11, 22});
        auto reservation = state->_pendingBatchReservations.front();
        EXPECT_EQ(0, reservation->batch.getWaitingFeatures().getCacheHitTokenCount());
        EXPECT_EQ(60, reservation->batch.getWaitingFeatures().getCacheMissTokenCount());

        std::promise<void> entered;
        auto started = entered.get_future();
        std::future<bool> completion;
        std::future_status status;
        {
            autil::ScopedWriteLock cacheWriter(state->_cacheLock);
            state->_cachedBlockHashes.insert(11);
            state->_cachedBlockHashes.insert(22);
            completion = std::async(std::launch::async, [&]() {
                entered.set_value();
                bool valid = true;
                for (size_t i = 0; i < requestIds.size(); ++i) {
                    auto finished = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED);
                    setInflightSnapshot(finished, 2 + i, 0);
                    finished->requestEvent->abnormalBatchFinished = !successful;
                    finished->requestEvent->localBatch =
                        makeLocalBatchInfo(101, 9001 + i, 1, {requestIds[i]});
                    valid &= runtime.reportAgent("agent_0", finished);
                    const auto remaining = requestIds.size() - i - 1;
                    const auto &features = reservation->batch.getWaitingFeatures();
                    valid &= reservation->batch.getWaitingRequestCount() == remaining;
                    valid &= features.getCacheHitTokenCount() == 0;
                    valid &= features.getCacheMissTokenCount() == int64_t(remaining * 2);
                }
                return valid;
            });
            started.wait();
            status = completion.wait_for(std::chrono::seconds(1));
        }
        // Join after unlocking so a failing old implementation cannot hang the test.
        EXPECT_EQ(std::future_status::ready, status);
        EXPECT_TRUE(completion.get());
        EXPECT_EQ(0u, state->getReservationStats().batchCount);
        EXPECT_EQ(0u, pendingCacheBatchCount(state));
        EXPECT_EQ(0u, pendingCacheBlockCount(state));
        EXPECT_FALSE(reservation->attached);
        EXPECT_EQ(successful ? 30u : 0u, reservation->batch.getCompletedRequestCount());
        EXPECT_EQ(successful ? 0u : 30u, reservation->batch.getFailedRequestCount());
    }
}

TEST_F(NaviSchedResourceTest, testParallelResultTimingIncludesWorkerDispatchAndBarrierWait)
{
    auto context = std::make_shared<NaviSchedScheduleContext>();
    MasterScheduleResultState state(context);
    state.workers.resize(2);
    state.deliveryWorkers.resize(2);
    state.reserveDispatchUs = 1000;
    state.reserveBarrierUs = 4000;
    state.deliveryDispatchUs = 4500;
    state.deliveryBarrierUs = 7000;
    state.workers[0].reserveBeginUs = 1100;
    state.workers[0].reserveUs = 1000;
    state.workers[1].reserveBeginUs = 2500;
    state.workers[1].reserveUs = 1400;
    state.deliveryWorkers[0].beginUs = 4600;
    state.deliveryWorkers[0].elapsedUs = 800;
    state.deliveryWorkers[1].beginUs = 5000;
    state.deliveryWorkers[1].elapsedUs = 1500;
    state.cleanupDispatchUs = autil::TimeUtility::monotonicTimeUs() - 4000;
    state.workers[0].cleanupBeginUs = state.cleanupDispatchUs + 200;
    state.workers[0].cleanupUs = 500;
    state.workers[1].cleanupBeginUs = state.cleanupDispatchUs + 700;
    state.workers[1].cleanupUs = 1500;
    state.merge();
    EXPECT_EQ(3000, context->_resultReserveStageUs);
    EXPECT_EQ(1400, context->_resultReserveUs);
    EXPECT_EQ(1500, context->_resultReserveDispatchDelayUs);
    EXPECT_EQ(2500, context->_resultDeliveryStageUs);
    EXPECT_EQ(1500, context->_resultDeliveryUs);
    EXPECT_EQ(500, context->_resultDeliveryDispatchDelayUs);
    EXPECT_EQ(state.cleanupBarrierUs - state.cleanupDispatchUs,
              context->_resultCleanupStageUs);
    EXPECT_GE(context->_resultCleanupStageUs, 4000);
    EXPECT_EQ(1500, context->_resultFailureCleanupUs);
    EXPECT_EQ(700, context->_resultCleanupDispatchDelayUs);
    EXPECT_GE(context->_resultMergeUs, 0);
}

TEST_F(NaviSchedResourceTest, testParallelResultBarrierRunsBeforeInlineClientDescendantsDrain)
{
    class WorkItem final : public navi::NaviThreadPoolItemBase {
    public:
        WorkItem(std::function<void()> action, bool inlineCompute)
            : action(std::move(action)) { setInlineCompute(inlineCompute); }
        void process() override { action(); }
        void destroy() override { delete this; }
        std::function<void()> action;
    };

    for (size_t depth : {size_t(8), size_t(32)}) {
        SCOPED_TRACE(depth);
        auto pool = std::make_shared<navi::NaviThreadPool>();
        navi::ConcurrencyConfig config;
        config.threadNum = config.minThreadNum = config.maxThreadNum = 1;
        ASSERT_TRUE(pool->start(config, nullptr, "result_barrier_fairness"));
        constexpr size_t REQUESTS = 64;
        size_t executed = 0;
        size_t observed = 0;
        int64_t beginUs = 0;
        int64_t barrierWaitUs = 0;
        std::promise<void> barrierDone;
        std::promise<void> clientsDone;
        auto barrierFuture = barrierDone.get_future();
        auto clientsFuture = clientsDone.get_future();
        std::function<void(size_t)> clientStep;
        clientStep = [&](size_t remaining) {
            const auto workBeginUs = autil::TimeUtility::monotonicTimeUs();
            while (autil::TimeUtility::monotonicTimeUs() - workBeginUs < 100) {}
            ++executed;
            if (remaining > 1) {
                pool->push(1, 1, new WorkItem([&, remaining]() {
                    clientStep(remaining - 1);
                }, true), false);
            }
            if (executed == REQUESTS * depth) clientsDone.set_value();
        };
        MasterScheduleResultBarrierKernel barrier;
        // Like response delivery, enqueue inline client work before the result barrier.
        pool->push(1, 1, new WorkItem([&]() {
            beginUs = autil::TimeUtility::monotonicTimeUs();
            for (size_t index = 0; index < REQUESTS; ++index) {
                pool->push(1, 1, new WorkItem([&]() { clientStep(depth); }, true), false);
            }
            pool->push(1, 1, new WorkItem([&]() {
                observed = executed;
                barrierWaitUs = autil::TimeUtility::monotonicTimeUs() - beginUs;
                barrierDone.set_value();
            }, !barrier.isExpensive()), false);
        }, false), false);
        const auto barrierStatus = barrierFuture.wait_for(std::chrono::seconds(5));
        const auto clientsStatus = clientsFuture.wait_for(std::chrono::seconds(5));
        pool->stop();
        ASSERT_EQ(std::future_status::ready, barrierStatus);
        ASSERT_EQ(std::future_status::ready, clientsStatus);
        std::cout << "RESULT_BARRIER_BENCHMARK depth=" << depth
                  << " requests=" << REQUESTS << " observed=" << observed
                  << " total=" << executed << " barrier_wait_us=" << barrierWaitUs << std::endl;
        EXPECT_EQ(REQUESTS, observed);
        EXPECT_EQ(REQUESTS * depth, executed);
    }
}

TEST_F(NaviSchedResourceTest, testParallelResultMatchesSerialReservationsAndFailures)
{
    for (size_t nodeCount : {1, 8}) {
        SCOPED_TRACE(nodeCount);
        for (size_t workerCount : {1, 2, 4, 8, 10}) {
            SCOPED_TRACE(workerCount);
            TestMasterStateR serialRuntime, parallelRuntime;
            std::vector<std::shared_ptr<CaptureAsyncPipe>> serialPipes, parallelPipes;
            auto serial = makeParallelResultContext(serialRuntime, 512, nodeCount, serialPipes);
            auto parallel = makeParallelResultContext(parallelRuntime, 512, nodeCount, parallelPipes);
            serialRuntime.reserveScheduleBatches(*serial);
            EXPECT_FALSE(serial->finish());
            std::vector<MasterDispatchHandle> failures;
            for (auto index : serial->_responseDeliveryFailedIndexes) {
                failures.push_back(serial->_dispatchHandles[index]);
            }
            MasterDispatchHandle::fail(failures);

            MasterScheduleResultState state(parallel);
            state.partition(workerCount);
            ASSERT_EQ(std::min(workerCount, nodeCount), state.workers.size());
            std::vector<size_t> nodeOwners(nodeCount), requestOwners(512);
            std::vector<std::thread> threads;
            for (size_t worker = 0; worker < state.workers.size(); ++worker) {
                for (auto node : state.workers[worker].nodes) ++nodeOwners[node];
                for (auto request : state.workers[worker].requests) ++requestOwners[request];
                threads.emplace_back([&, worker]() { state.reserveWorker(worker, parallelRuntime); });
            }
            for (auto &thread : threads) thread.join();
            state.prepareDelivery(workerCount);
            EXPECT_EQ(workerCount, state.deliveryWorkers.size());
            threads.clear();
            for (size_t worker = 0; worker < state.deliveryWorkers.size(); ++worker) {
                threads.emplace_back([&, worker]() { state.deliverWorker(worker); });
            }
            for (auto &thread : threads) thread.join();
            state.collectDeliveryFailures();
            threads.clear();
            for (size_t worker = 0; worker < state.workers.size(); ++worker) {
                threads.emplace_back([&, worker]() { state.cleanupWorker(worker); });
            }
            for (auto &thread : threads) thread.join();
            state.merge();
            EXPECT_EQ(std::vector<size_t>(nodeCount, 1), nodeOwners);
            EXPECT_EQ(std::vector<size_t>(512, 1), requestOwners);
            std::set<size_t> actual(parallel->_responseDeliveryFailedIndexes.begin(),
                                    parallel->_responseDeliveryFailedIndexes.end());
            std::set<size_t> expected(serial->_responseDeliveryFailedIndexes.begin(),
                                      serial->_responseDeliveryFailedIndexes.end());
            EXPECT_EQ(expected, actual);
            EXPECT_EQ(74, actual.size());
            for (size_t index = 0; index < 512; ++index) {
                EXPECT_EQ(1, parallelPipes[index]->eofCount);
                EXPECT_EQ(serialPipes[index]->datas.size(), parallelPipes[index]->datas.size());
                if (index % 7 != 0) {
                    auto response = std::dynamic_pointer_cast<MasterResponseToClientData>(
                        parallelPipes[index]->datas.at(0));
                    ASSERT_TRUE(response);
                    EXPECT_EQ(1001 + index, response->requestId);
                    EXPECT_EQ(parallel->_decisions[index].target.agentAddress, response->target.agentAddress);
                    EXPECT_EQ(512 / nodeCount, response->expectedBatchSize);
                    EXPECT_TRUE(response->dispatchHandle.valid());
                }
            }
            for (size_t node = 0; node < nodeCount; ++node) {
                const auto id = hashString("agent_" + std::to_string(node));
                auto a = std::const_pointer_cast<MasterStateR::NodeState>(serialRuntime.getNodeState(id));
                auto b = std::const_pointer_cast<MasterStateR::NodeState>(parallelRuntime.getNodeState(id));
                EXPECT_EQ(a->getReservationStats().waitingRequestCount,
                          b->getReservationStats().waitingRequestCount);
                EXPECT_EQ(pendingCacheBlockCount(a), pendingCacheBlockCount(b));
                EXPECT_EQ(1, pendingReservationCount(b));
            }
            MasterDispatchHandle::fail(serial->_dispatchHandles);
            MasterDispatchHandle::fail(parallel->_dispatchHandles);
            for (size_t node = 0; node < nodeCount; ++node) {
                auto b = std::const_pointer_cast<MasterStateR::NodeState>(
                    parallelRuntime.getNodeState(hashString("agent_" + std::to_string(node))));
                EXPECT_EQ(0, pendingReservationCount(b));
                EXPECT_EQ(0, pendingCacheBlockCount(b));
            }
            EXPECT_FALSE(parallel->_replay);
        }
    }
}

TEST_F(NaviSchedResourceTest, testParallelResultRetainsRoundUntilAllWorkersJoin)
{
    TestMasterStateR runtime;
    std::vector<std::shared_ptr<CaptureAsyncPipe>> pipes;
    auto context = makeParallelResultContext(runtime, 128, 4, pipes);
    std::atomic<size_t> completions{0};
    context->_scheduleRoundCompletion = std::shared_ptr<void>(
        new int(1), [&](void *p) { delete static_cast<int *>(p); ++completions; });
    auto state = std::make_shared<MasterScheduleResultState>(context);
    EXPECT_FALSE(context->_scheduleRoundCompletion);
    state->partition(10);
    ASSERT_EQ(4, state->workers.size());
    for (size_t worker = 0; worker < state->workers.size(); ++worker) {
        state->reserveWorker(worker, runtime);
        EXPECT_EQ(0, completions.load());
    }
    state->prepareDelivery(10);
    for (size_t worker = 0; worker < state->deliveryWorkers.size(); ++worker) {
        state->deliverWorker(worker);
        EXPECT_EQ(0, completions.load());
    }
    state->collectDeliveryFailures();
    for (size_t worker = 0; worker < state->workers.size(); ++worker) {
        state->cleanupWorker(worker);
        EXPECT_EQ(0, completions.load());
    }
    state->merge();
    EXPECT_EQ(0, completions.load());
    state->completion.reset();
    EXPECT_EQ(1, completions.load());
    state.reset();
    EXPECT_EQ(1, completions.load());
}

TEST_F(NaviSchedResourceTest, testParallelResultKeepsRejectedAndDeferredRequestsIsolated)
{
    TestMasterStateR runtime;
    std::vector<std::shared_ptr<CaptureAsyncPipe>> pipes;
    auto context = makeParallelResultContext(runtime, 64, 1, pipes);
    auto deferredPipe = std::make_shared<CaptureAsyncPipe>();
    auto deferredRequest = std::make_shared<ClientRequestToMasterData>();
    deferredRequest->requestId = 9001;
    NaviSchedDecision deferredDecision;
    deferredDecision.requestId = 9001;
    deferredDecision.reason = "expired_before_scheduling";
    context->_deferredResponses.push_back({std::make_shared<MasterScheduleRequestData>(
        deferredRequest, deferredPipe), deferredDecision});
    for (size_t index = 0; index < 64; ++index) {
        context->_selectedNodeIndexes[index] = NaviSchedScheduleContext::INVALID_NODE_INDEX;
        context->_decisions[index] = NaviSchedDecision();
        context->_decisions[index].requestId = index + 1001;
        context->_decisions[index].reason = "not_scheduled";
    }
    MasterScheduleResultState state(context);
    state.partition(10);
    ASSERT_EQ(1, state.workers.size());
    EXPECT_TRUE(state.workers[0].nodes.empty());
    EXPECT_EQ(64, state.workers[0].requests.size());
    state.reserveWorker(0, runtime);
    state.prepareDelivery(10);
    ASSERT_EQ(2, state.deliveryWorkers.size());
    for (size_t worker = 0; worker < state.deliveryWorkers.size(); ++worker) {
        state.deliverWorker(worker);
    }
    state.collectDeliveryFailures();
    state.cleanupWorker(0);
    state.merge();
    EXPECT_EQ(10, context->_responseDeliveryFailedIndexes.size());
    ASSERT_EQ(1, deferredPipe->datas.size());
    EXPECT_EQ(1, deferredPipe->eofCount);
    const auto deferredResponse = std::dynamic_pointer_cast<MasterResponseToClientData>(
        deferredPipe->datas.front());
    ASSERT_TRUE(deferredResponse);
    EXPECT_EQ(9001, deferredResponse->requestId);
    EXPECT_EQ("expired_before_scheduling", deferredResponse->reason);
    for (const auto &handle : context->_dispatchHandles) EXPECT_FALSE(handle.valid());
    auto node = std::const_pointer_cast<MasterStateR::NodeState>(
        runtime.getNodeState(hashString("agent_0")));
    EXPECT_EQ(0, pendingReservationCount(node));
    EXPECT_EQ(0, pendingCacheBlockCount(node));
}

