    EXPECT_FALSE(acknowledged);
    EXPECT_EQ(1, dispatchWaiterCount(state, 101));

    auto admitted = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
    admitted->requestEvent->localBatch = makeLocalBatchInfo(101, 1001, 1);
