TEST_F(NaviSchedResourceTest,
       testAbandonedDispatchOnlyReleasesWaitingRequestsWithoutOwner)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(state);
    NaviSchedTarget target;
    target.bizName = "model_biz";
    target.agentAddress = "127.0.0.1:19000";

    reserveBatchWithCache(state, 101, autil::TimeUtility::currentTime(), 20.0,
                          {1001, 1002}, {11});
    EXPECT_TRUE(runtime.reportDispatchAbandoned(target, 101, 1001));
    EXPECT_EQ(MasterBatchReservation::RequestState::FAILED,
              reservationRequestState(state, 101, 1001));
    EXPECT_EQ(1, pendingReservationCount(state));
    EXPECT_EQ(1, pendingCacheBatchCount(state));

    auto ownedPipe = std::make_shared<CaptureAsyncPipe>();
    bool acknowledged = false;
    ASSERT_TRUE(
        runtime.registerDispatchWaiter(target, 101, 1002, ownedPipe, acknowledged));
    ASSERT_FALSE(acknowledged);
    EXPECT_FALSE(runtime.reportDispatchAbandoned(target, 101, 1002));
    EXPECT_EQ(MasterBatchReservation::RequestState::WAITING,
              reservationRequestState(state, 101, 1002));

    auto admitted = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
    admitted->requestEvent->localBatch = makeLocalBatchInfo(101, 10001, 1, {1002});
    ASSERT_TRUE(runtime.reportAgent("agent_0", admitted));
    EXPECT_TRUE(ownedPipe->eof);
    EXPECT_FALSE(runtime.reportDispatchAbandoned(target, 101, 1002));
    EXPECT_EQ(MasterBatchReservation::RequestState::DISPATCHED,
              reservationRequestState(state, 101, 1002));

    auto finished = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED);
    finished->requestEvent->localBatch = admitted->requestEvent->localBatch;
    ASSERT_TRUE(runtime.reportAgent("agent_0", finished));
    EXPECT_EQ(0, pendingReservationCount(state));
    EXPECT_EQ(0, pendingCacheBatchCount(state));

    reserveBatchWithCache(state, 102, autil::TimeUtility::currentTime(), 20.0, {2001},
                          {22});
    auto expiredPipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(
        runtime.registerDispatchWaiter(target, 102, 2001, expiredPipe, acknowledged));
    ASSERT_FALSE(acknowledged);
    expiredPipe.reset();
    EXPECT_TRUE(runtime.reportDispatchAbandoned(target, 102, 2001));
    EXPECT_EQ(0, pendingReservationCount(state));
    EXPECT_EQ(0, pendingCacheBatchCount(state));
}

