TEST_F(NaviSchedResourceTest, testDispatchAckAndCancellationAreRaceSafe)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(state);
    NaviSchedTarget target;
    target.bizName = "model_biz";
    target.agentAddress = "127.0.0.1:19000";

    for (uint64_t requestId = 1001; requestId < 1065; ++requestId) {
        const auto batchId = static_cast<int64_t>(requestId);
        reserveBatch(state, batchId, autil::TimeUtility::currentTime(), 20.0,
                     {requestId});
        auto pipe = std::make_shared<CaptureAsyncPipe>();
        bool acknowledged = false;
        ASSERT_TRUE(runtime.registerDispatchWaiter(target, batchId, requestId, pipe,
                                                   acknowledged));
        ASSERT_FALSE(acknowledged);

        std::atomic<size_t> ready{0};
        std::atomic<bool> start{false};
        bool dispatchFailed = false;
        std::thread ackThread([&]() {
            ready.fetch_add(1, std::memory_order_release);
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }
            auto admitted =
                makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
            admitted->requestEvent->localBatch =
                makeLocalBatchInfo(batchId, batchId + 10000, 1);
            EXPECT_TRUE(runtime.reportAgent("agent_0", admitted));
        });
        std::thread cancelThread([&]() {
            ready.fetch_add(1, std::memory_order_release);
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }
            dispatchFailed =
                runtime.cancelDispatchWaiter(target, batchId, requestId, pipe);
        });
        while (ready.load(std::memory_order_acquire) != 2) {
            std::this_thread::yield();
        }
        start.store(true, std::memory_order_release);
        ackThread.join();
        cancelThread.join();

        const auto received = reservationReceivedRequest(state, batchId, requestId);
        EXPECT_NE(dispatchFailed, received);
        EXPECT_EQ(dispatchFailed ? 0 : 1,
                  static_cast<int>(pendingReservationCount(state)));
        if (received) {
            auto finished = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED);
            finished->requestEvent->localBatch =
                makeLocalBatchInfo(batchId, batchId + 10000, 1);
            ASSERT_TRUE(runtime.reportAgent("agent_0", finished));
        }
        EXPECT_EQ(0, pendingReservationCount(state));
    }
}

