TEST_F(NaviSchedResourceTest,
       testStoppingClearsCountsAndHandshakeAuthoritativelyReplacesThem)
{
    TestMasterStateR runtime;

    auto stopped = runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    ASSERT_TRUE(stopped);
    NaviSchedTarget stoppedTarget;
    stoppedTarget.bizName = "model_biz";
    stoppedTarget.agentAddress = "127.0.0.1:19000";
    auto stoppedLoad =
        makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED, 100);
    setInflightSnapshot(stoppedLoad, 7, 2, 30.0);
    ASSERT_TRUE(runtime.reportAgent("agent_0", stoppedLoad));
    reserveBatchWithCache(stopped, 101, autil::TimeUtility::currentTime(), 30.0,
                          {1001, 1002}, {11, 22});
    auto stoppedWaiter = std::make_shared<CaptureAsyncPipe>();
    bool acknowledged = false;
    ASSERT_TRUE(runtime.registerDispatchWaiter(stoppedTarget, 101, 1001, stoppedWaiter,
                                               acknowledged));
    ASSERT_FALSE(acknowledged);

    auto stopping = makeControlUpdate(NaviSchedAgentEvent::AGENT_STOPPING);
    ASSERT_TRUE(runtime.reportAgent("agent_0", stopping));
    EXPECT_EQ(1, stoppedWaiter->eofCount);
    EXPECT_EQ(0, pendingReservationCount(stopped));
    EXPECT_EQ(0, pendingCacheBatchCount(stopped));
    auto stoppedInfo = stopped->getInfo();
    EXPECT_FALSE(stoppedInfo.online);
    EXPECT_EQ(0, stoppedInfo.inflightStatsRevision);
    EXPECT_EQ(0, stoppedInfo.inflightRequests);
    EXPECT_DOUBLE_EQ(0.0, stoppedInfo.inflightPredictedLatencySumMs);

    auto reconnected =
        runtime.registerAgent("agent_1", "model_biz", "127.0.0.1:19001", 100);
    ASSERT_TRUE(reconnected);
    NaviSchedTarget reconnectTarget;
    reconnectTarget.bizName = "model_biz";
    reconnectTarget.agentAddress = "127.0.0.1:19001";
    auto oldLoad = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED, 200);
    setInflightSnapshot(oldLoad, 9, 4, 80.0);
    ASSERT_TRUE(runtime.reportAgent("agent_1", oldLoad));
    reserveBatchWithCache(reconnected, 102, autil::TimeUtility::currentTime(), 25.0,
                          {2001}, {33});
    auto reconnectWaiter = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(runtime.registerDispatchWaiter(reconnectTarget, 102, 2001,
                                               reconnectWaiter, acknowledged));
    ASSERT_FALSE(acknowledged);

    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    handshake->control->pdSeparated = true;
    setInflightSnapshot(handshake, 1, 3, 45.0);
    ASSERT_TRUE(runtime.reportAgent("agent_1", handshake));
    EXPECT_EQ(1, reconnectWaiter->eofCount);
    EXPECT_EQ(0, pendingReservationCount(reconnected));
    EXPECT_EQ(0, pendingCacheBatchCount(reconnected));
    const auto reconnectInfo = reconnected->getInfo();
    EXPECT_TRUE(reconnectInfo.online);
    EXPECT_EQ(1, reconnectInfo.inflightStatsRevision);
    EXPECT_EQ(3, reconnectInfo.inflightRequests);
    EXPECT_DOUBLE_EQ(45.0, reconnectInfo.inflightPredictedLatencySumMs);
}

