    reserveBatch(state, 101, autil::TimeUtility::currentTime(), 20.0, {1001, 1002});
    const auto localBatch = makeLocalBatchInfo(101, 1001, 1, {1001});
    auto ack = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
    ack->requestEvent->localBatch = localBatch;
