TEST_F(NaviSchedResourceTest, testQueueOverloadRecoveryKeepsUnknownBusyCandidatesOfEitherTrust)
{
    for (bool trusted : {false, true}) {
        for (size_t busyField = 0; busyField < 6; ++busyField) {
            SCOPED_TRACE(::testing::Message() << "trusted=" << trusted
                                            << " busyField=" << busyField);
            auto replay = makeCostSchedulerReplay(4, 3);
            NaviSchedScheduleContext context;
            ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
            ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
            for (auto &node : context._scheduleNodes) {
                node._latencyModel = makeTrustedLatencyModel();
                node._unifiedLatencyPrediction = false;
                node._queueReportReceiveTimeUs = context._scheduleTimeUs;
                node._inflightRequests = 0;
                node._runningRequests = 0;
                node._batchWaitingRequests = 0;
                node._queuedBatchRequests = 0;
                node._queueTotalPredictedLatencyMs = 0.0;
                node._queueDecayHeadRemainingMs = 0.0;
            }
            auto &saturated = context._scheduleNodes[0];
            saturated._inflightRequests = 128;
            saturated._queueTotalPredictedLatencyMs = 1200.0;
            saturated._queueDecayHeadRemainingMs = 1200.0;
            auto &available = context._scheduleNodes[1];
            available._inflightRequests = 16;
            available._queueTotalPredictedLatencyMs = 100.0;
            available._queueDecayHeadRemainingMs = 100.0;
            auto &unknown = context._scheduleNodes[2];
            auto model = makeTrustedLatencyModel();
            model->overloadPredictionTrusted = trusted;
            unknown._latencyModel = std::move(model);
            const std::array<int32_t *, 4> busyCounts = {
                &unknown._inflightRequests, &unknown._runningRequests,
                &unknown._batchWaitingRequests, &unknown._queuedBatchRequests};
            if (busyField < busyCounts.size()) {
                *busyCounts[busyField] = 1;
            } else if (busyField == busyCounts.size()) {
                // Prefill completion releases AgentBatchR's counters, not decode slots.
                NaviSchedWorkloadSnapshot workload;
                workload.revision = 1;
                workload.eventTimeUs = context._scheduleTimeUs;
                workload.requestCount = 512;
                workload.runningRequestCount = 512;
                workload.runningDecodeRequestCount = 512;
                workload.runningDecodeGeneratedTokenCount = 512;
                workload.prefillCapacitySplit = true;
                workload.maxRunningRequestCount = 512;
                workload.runningCapacitySlotCount = 512;
                ASSERT_TRUE(workload.valid());
                unknown._unifiedLatencyPrediction = true;
                unknown._workload = workload;
                unknown._workloadFeatures = NaviSchedLatencyFeatures();
                ASSERT_TRUE(unknown._workloadFeatures.appendPrefillWorkload(workload));
                unknown._reportedWorkloadFeatures = unknown._workloadFeatures;
                unknown._maxRunningRequestCount = 512;
                unknown._workloadRunningCapacitySlotCount = 512;
                ASSERT_EQ(0, unknown.getRunningRequests());
                ASSERT_EQ(512, unknown.getWorkloadFeatures().getPrecedingRequestCount());
                ASSERT_EQ(512, unknown.getWorkloadFeatures().getRunningDecodeRequestCount());
            }
            ASSERT_DOUBLE_EQ(0.0, unknown.getEstimatedBacklogLatencyMs());
            const auto normalRouting = CostSchedulerColdStartStrategy::analyze(context);
            EXPECT_EQ(trusted ? 3 : 2, normalRouting.trustedNodeCount);
            EXPECT_EQ(trusted ? 0 : 1, normalRouting.untrustedNodeCount);
            for (const auto &item : context._requests) {
                auto request = std::make_shared<ClientRequestToMasterData>();
                request->requestId = item.request.requestId;
                request->bizName = replay.bizName;
                request->timeoutMs = 1000;
                ScheduleReplayRunner::addResponseRequest(
                    context, std::make_shared<MasterScheduleRequestData>(
                        request, std::make_shared<CaptureAsyncPipe>()));
            }
            MasterScheduleR scheduleResource;
            MasterScheduleContextKernel kernel;
            kernel._schedulerKernelId = CostSchedulerKernel::KERNEL_ID;
            const_cast<MasterScheduleR *&>(kernel._masterScheduleR) = &scheduleResource;
            kernel._maxWaitScheduleTimeMs = 30;
            kernel._queueOverloadStartCycleMultiplier = 10;
            kernel._queueOverloadFullCycleMultiplier = 30;
            auto contextPtr = std::make_shared<NaviSchedScheduleContext>(std::move(context));
            ASSERT_TRUE(kernel.applyQueueOverloadLimit(
                std::make_shared<MasterScheduleContextData>(contextPtr),
                []() { return std::numeric_limits<uint64_t>::max(); }));
            ASSERT_EQ(4, contextPtr->requestCount());
            EXPECT_DOUBLE_EQ(0.75, contextPtr->_queueOverloadDropProbability);
            multi_call::RandomGenerator randomGenerator(31);
            CostSchedulerColdStartStrategy::Result result;
            ASSERT_TRUE(CostSchedulerColdStartStrategy::apply(
                *contextPtr, randomGenerator, result,
                []() { return std::numeric_limits<uint64_t>::max(); }));
            EXPECT_EQ(trusted ? 0 : 1, result.untrustedNodeCount);
            EXPECT_EQ(trusted ? 3 : 2, result.trustedNodeCount);
            EXPECT_EQ(4, result.trustedRequestCount + result.untrustedRequestCount);
            EXPECT_EQ(trusted ? std::vector<size_t>({0, 1, 2})
                              : std::vector<size_t>({0, 1}),
                      contextPtr->_scheduleViewNodeIndexes);
        }
    }
}

TEST_F(NaviSchedResourceTest, testQueueOverloadRecoveryStaysOpenAsBusyNodeDrains)
{
    for (const double busyBacklogMs : {1800.0, 900.0, 899.0, 600.0, 301.0, 300.0}) {
        SCOPED_TRACE(busyBacklogMs);
        auto replay = makeCostSchedulerReplay(1, 2);
        NaviSchedScheduleContext context;
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
        for (size_t index = 0; index < context.nodeCount(); ++index) {
            auto &node = context._scheduleNodes[index];
            node._latencyModel = makeTrustedLatencyModel();
            node._unifiedLatencyPrediction = false;
            node._inflightRequests = index == 0 ? 2 : 0;
            node._queueTotalPredictedLatencyMs = index == 0 ? busyBacklogMs : 0.0;
            node._queueDecayHeadRemainingMs = node._queueTotalPredictedLatencyMs;
            node._queueReportReceiveTimeUs = context._scheduleTimeUs;
        }
        auto request = std::make_shared<ClientRequestToMasterData>();
        request->requestId = context._requests.front().request.requestId;
        request->bizName = replay.bizName;
        request->timeoutMs = 1000;
        ScheduleReplayRunner::addResponseRequest(
            context, std::make_shared<MasterScheduleRequestData>(
                request, std::make_shared<CaptureAsyncPipe>()));
        MasterScheduleR resource;
        MasterScheduleContextKernel kernel;
        kernel._schedulerKernelId = CostSchedulerKernel::KERNEL_ID;
        const_cast<MasterScheduleR *&>(kernel._masterScheduleR) = &resource;
        kernel._maxWaitScheduleTimeMs = 30;
        kernel._queueOverloadStartCycleMultiplier = 10;
        kernel._queueOverloadFullCycleMultiplier = 30;
        auto contextPtr = std::make_shared<NaviSchedScheduleContext>(std::move(context));
        kernel.applyQueueOverloadLimit(std::make_shared<MasterScheduleContextData>(contextPtr));
        EXPECT_DOUBLE_EQ(0.0, contextPtr->_queueOverloadDropProbability);
        EXPECT_EQ(1, contextPtr->requestCount());
        EXPECT_TRUE(contextPtr->_deferredResponses.empty());
        if (busyBacklogMs > 300.0 && contextPtr->requestCount() == 1) {
            multi_call::RandomGenerator randomGenerator(31);
            CostSchedulerColdStartStrategy::Result result;
            ASSERT_TRUE(CostSchedulerColdStartStrategy::apply(*contextPtr, randomGenerator, result));
            EXPECT_EQ(std::vector<size_t>({0, 1}), contextPtr->_scheduleViewNodeIndexes);
        }
    }
}

