TEST_F(NaviSchedResourceTest, testQueueOverloadRecoveryRequiresCostRoutingGraph)
{
    for (const std::string &scheduler : {CostSchedulerKernel::KERNEL_ID,
                                      std::string("navi_sched.random_scheduler_k"),
                                      MaxCacheHitSchedulerKernel::KERNEL_ID}) {
        SCOPED_TRACE(scheduler);
        auto graph = MasterScheduleGraph::buildGraph("model_biz", "{}", scheduler, "{}", 7);
        ASSERT_TRUE(graph);
        const navi::NodeDef *contextNode = nullptr;
        for (const auto &subGraph : graph->sub_graphs()) {
            for (const auto &node : subGraph.nodes()) {
                if (node.kernel_name() == MasterScheduleContextKernel::KERNEL_ID) {
                    ASSERT_EQ(nullptr, contextNode);
                    contextNode = &node;
                }
            }
        }
        ASSERT_NE(nullptr, contextNode);
        const std::string configPath;
        navi::KernelConfigContext config(configPath, nullptr, contextNode);
        MasterScheduleContextKernel kernel;
        ASSERT_TRUE(kernel.config(config));
        EXPECT_EQ(scheduler, kernel._schedulerKernelId);
        auto replay = makeCostSchedulerReplay(1, 2);
        NaviSchedScheduleContext context;
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
        for (size_t index = 0; index < context.nodeCount(); ++index) {
            auto &node = context._scheduleNodes[index];
            node._latencyModel = makeTrustedLatencyModel();
            node._unifiedLatencyPrediction = false;
            node._inflightRequests = index == 0 ? 2 : 0;
            node._queueTotalPredictedLatencyMs = index == 0 ? 2000.0 : 0.0;
            node._queueDecayHeadRemainingMs = node._queueTotalPredictedLatencyMs;
            node._queueReportReceiveTimeUs = context._scheduleTimeUs;
        }
        auto request = std::make_shared<ClientRequestToMasterData>();
        request->requestId = context._requests.front().request.requestId;
        request->bizName = replay.bizName;
        request->timeoutMs = 1000;
        ScheduleReplayRunner::addResponseRequest(
            context, std::make_shared<MasterScheduleRequestData>(
                request, std::make_shared<CaptureAsyncPipe>()));
        MasterScheduleR resource;
        const_cast<MasterScheduleR *&>(kernel._masterScheduleR) = &resource;
        kernel._maxWaitScheduleTimeMs = 30;
        kernel._queueOverloadStartCycleMultiplier = 10;
        kernel._queueOverloadFullCycleMultiplier = 30;
        auto contextPtr = std::make_shared<NaviSchedScheduleContext>(std::move(context));
        const bool costRouting = scheduler == CostSchedulerKernel::KERNEL_ID;
        EXPECT_EQ(costRouting, kernel.applyQueueOverloadLimit(
            std::make_shared<MasterScheduleContextData>(contextPtr)));
        EXPECT_DOUBLE_EQ(costRouting ? 0.0 : 1.0, contextPtr->_queueOverloadDropProbability);
        EXPECT_EQ(costRouting ? 1 : 0, contextPtr->requestCount());
        EXPECT_EQ(costRouting ? 0 : 1, contextPtr->_deferredResponses.size());
    }
}

TEST_F(NaviSchedResourceTest, testQueueOverloadRecoversDrainedIncidentNodes)
{
    auto replay = makeCostSchedulerReplay(1, 24);
    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
    for (auto &node : context._scheduleNodes) {
        node._latencyModel = makeTrustedLatencyModel();
        node._inflightRequests = 0;
        node._queueTotalPredictedLatencyMs = 0.0;
    }
    auto &busy = context._scheduleNodes[0];
    busy._inflightRequests = 1765;
    busy._queueTotalPredictedLatencyMs = 490255.0;
    busy._queueDecayHeadRemainingMs = 490255.0;
    busy._queueReportReceiveTimeUs = context._scheduleTimeUs;

    auto request = std::make_shared<ClientRequestToMasterData>();
    request->requestId = context._requests.front().request.requestId;
    request->bizName = replay.bizName;
    request->timeoutMs = 1000;
    ScheduleReplayRunner::addResponseRequest(
        context, std::make_shared<MasterScheduleRequestData>(
                     request, std::make_shared<CaptureAsyncPipe>()));

    MasterScheduleR scheduleResource;
    MasterScheduleContextKernel kernel;
    kernel._schedulerKernelId = CostSchedulerKernel::KERNEL_ID;
    const_cast<MasterScheduleR *&>(kernel._masterScheduleR) = &scheduleResource;
    kernel._maxWaitScheduleTimeMs = 100;
    kernel._queueOverloadStartCycleMultiplier = 250;
    kernel._queueOverloadFullCycleMultiplier = 750;
    auto contextPtr = std::make_shared<NaviSchedScheduleContext>(std::move(context));
    ASSERT_GT(contextPtr->_scheduleNodes[0].getEstimatedBacklogLatencyMs(), 75000.0);
    ASSERT_TRUE(kernel.applyQueueOverloadLimit(
        std::make_shared<MasterScheduleContextData>(contextPtr)));
    ASSERT_EQ(1, contextPtr->requestCount());
    EXPECT_TRUE(contextPtr->_deferredResponses.empty());
    EXPECT_LT(scheduleResource.getQueueOverloadStats().latestDropProbability, 1.0);

    multi_call::RandomGenerator randomGenerator(31);
    CostSchedulerColdStartStrategy::Result coldStartResult;
    ASSERT_TRUE(CostSchedulerColdStartStrategy::apply(
        *contextPtr, randomGenerator, coldStartResult));
    ASSERT_EQ(24, contextPtr->_scheduleViewNodeIndexes.size());
    for (size_t i = 0; i < 24; ++i) {
        EXPECT_EQ(i, contextPtr->_scheduleViewNodeIndexes[i]);
    }

    CostSchedulerConfig config;
    config.maxLoopCount = 1;
    config.optimizationTimeBudgetUs = -1;
    config.initialWeightSeed = 31;
    auto state = CostSchedulerGraphState::create(contextPtr, config, 2);
    ASSERT_TRUE(state);
    EXPECT_EQ(24, state->_nodeCount);
    for (size_t worker = 0; worker < 2; ++worker) {
        ASSERT_TRUE(state->runRow(worker, 0));
    }
    ASSERT_TRUE(state->finishRow(0));
    for (size_t worker = 0; worker < 2; ++worker) {
        ASSERT_TRUE(state->runProjection(worker, 0));
    }
    ASSERT_TRUE(state->finishProjection(0));
    for (size_t worker = 0; worker < 2; ++worker) {
        ASSERT_TRUE(state->runFinalRow(worker));
    }
    ASSERT_TRUE(state->finalize());
    EXPECT_FALSE(contextPtr->_scheduleViewActive);
    EXPECT_EQ(24, contextPtr->nodeCount());
    std::vector<NaviSchedDecision> decisions;
    ASSERT_TRUE(ScheduleReplayRunner::collectDecisions(*contextPtr, decisions));
    ASSERT_EQ(1, decisions.size());
    EXPECT_EQ(request->requestId, decisions.front().requestId);
    EXPECT_EQ("cost_selected", decisions.front().reason);
    EXPECT_NE(replay.nodes.front().serverAddress, decisions.front().target.address);
    const auto selected = std::find_if(replay.nodes.begin() + 1, replay.nodes.end(),
        [&](const auto &node) { return node.serverAddress == decisions.front().target.address; });
    EXPECT_NE(replay.nodes.end(), selected);
}

TEST_F(NaviSchedResourceTest, testQueueOverloadRecoversIdleCapacityForLargeRound)
{
    auto replay = makeCostSchedulerReplay(32, 3);
    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
    for (auto &node : context._scheduleNodes) {
        node._latencyModel = makeTrustedLatencyModel();
        node._inflightRequests = 0;
        node._maxRunningRequestCount = 16;
        node._queueTotalPredictedLatencyMs = 0.0;
    }
    auto &busy = context._scheduleNodes[0];
    busy._inflightRequests = 1000;
    busy._queueTotalPredictedLatencyMs = 1000000.0;
    busy._queueDecayHeadRemainingMs = 1000000.0;
    busy._queueReportReceiveTimeUs = context._scheduleTimeUs;
    for (const auto &item : context._requests) {
        auto request = std::make_shared<ClientRequestToMasterData>();
        request->requestId = item.request.requestId;
        request->bizName = replay.bizName;
        request->timeoutMs = 1000;
        ScheduleReplayRunner::addResponseRequest(
            context, std::make_shared<MasterScheduleRequestData>(
                         request, std::make_shared<CaptureAsyncPipe>()));
    }
    MasterScheduleR scheduleResource;
    MasterScheduleContextKernel kernel;
    kernel._schedulerKernelId = CostSchedulerKernel::KERNEL_ID;
    const_cast<MasterScheduleR *&>(kernel._masterScheduleR) = &scheduleResource;
    kernel._maxWaitScheduleTimeMs = 100;
    kernel._queueOverloadStartCycleMultiplier = 250;
    kernel._queueOverloadFullCycleMultiplier = 750;
    auto contextPtr = std::make_shared<NaviSchedScheduleContext>(std::move(context));
    EXPECT_TRUE(kernel.applyQueueOverloadLimit(
        std::make_shared<MasterScheduleContextData>(contextPtr), [] { return uint64_t(0); }));
    EXPECT_DOUBLE_EQ(0.0, contextPtr->_queueOverloadDropProbability);
    EXPECT_EQ(32, contextPtr->requestCount());
    EXPECT_TRUE(contextPtr->_deferredResponses.empty());
}

