    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
    auto &busy = context._scheduleNodes[0];
    busy._latencyModel = makeTrustedLatencyModel();
    busy._inflightRequests = 2;
    busy._queueTotalPredictedLatencyMs = 2400.0;
    busy._queueReportReceiveTimeUs = context._scheduleTimeUs;
    busy._unifiedLatencyPrediction = false;
    auto &unknown = context._scheduleNodes[1];
    unknown._latencyModel = makeTrustedLatencyModel();
    unknown._inflightRequests = 1000;
    unknown._queueTotalPredictedLatencyMs = 0.0;
    unknown._unifiedLatencyPrediction = false;
    ASSERT_DOUBLE_EQ(0.0, unknown.getEstimatedBacklogLatencyMs());

    auto request = std::make_shared<ClientRequestToMasterData>();
    request->requestId = context._requests.front().request.requestId;
    request->bizName = replay.bizName;
    request->timeoutMs = 1000;
