    request->requestId = 500;
    request->bizName = "model_biz";
    request->timeoutMs = 1000;
    std::vector<ClientRequestToMasterDataConstPtr> requests{request};
    auto context = std::make_shared<NaviSchedScheduleContext>(
        SchedulerTestDriver::makeContext(runtime, requests));
    auto &node = context->_scheduleNodes[0];
    node._unifiedLatencyPrediction = true;
    auto model = std::make_shared<NaviSchedLatencyModel>();
    model->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
