    model->sessionSampleCount = 128;
    model->parameters.assign(NonLinearPrefillModelR::PARAMETER_COUNT, 0.0);
    model->parameters[NonLinearPrefillModelR::NONLINEAR_CURVATURE_PARAMETER_INDEX] =
        parameterForFormulaCoefficient(
            NonLinearPrefillModelR::NONLINEAR_CURVATURE_PARAMETER_INDEX,
            NonLinearPrefillModelR::MIN_NONLINEAR_CURVATURE);
    model->parameters[NonLinearPrefillModelR::TOTAL_PROMPT_PARAMETER_INDEX] =
        parameterForFormulaCoefficient(
            NonLinearPrefillModelR::TOTAL_PROMPT_PARAMETER_INDEX, 1.0);
    node._latencyModel = std::move(model);
    ASSERT_TRUE(node._workloadFeatures.appendBatchCount(1));
    node._workloadFeatures.appendRequest(0, 921600);
    node._reportedWorkloadFeatures = node._workloadFeatures;
    node._workloadReportReceiveTimeUs = context->_scheduleTimeUs;
    ASSERT_DOUBLE_EQ(0.0, node.getEstimatedQueueWaitMs());
    EXPECT_NEAR(900.0, node.getEstimatedBacklogLatencyMs(), 0.2);
    node._inflightRequests = 1;
    node._inflightPredictedLatencySumMs = 900.0;

