TEST_F(NaviSchedResourceTest,
       testMasterLatencyModelSlotReplacementInvalidatesOldCollector)
{
    MasterLatencyModelR pool;
    ASSERT_TRUE(pool.activateAgent("agent_0", "old_collector"));

    NonLinearPrefillModelR model;
    AgentLatencyToMasterData latency;
    latency.formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    latency.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    latency.modelRevision = 1024;
    latency.parameters = model.getInitialParameters();
    latency.optimizerState = makeLatencyOptimizerState(latency.parameters.size());
    latency.zeroPoint = NonLinearPrefillModelR::calculateZeroPoint(latency.parameters);

    bool accepted = false;
    MasterLatencyModelR::RecordResult result;
    ASSERT_TRUE(pool.record("agent_0", "rtx", latency, true, 1, "old_collector",
                            &accepted, false, &result));
    ASSERT_TRUE(accepted);
    ASSERT_TRUE(result.model);

    const auto oldSlot = pool.getLiveModelSlot("agent_0", "old_collector");
    ASSERT_TRUE(oldSlot);
    ASSERT_EQ(result.model.get(), oldSlot->getModel().get());

    ASSERT_TRUE(pool.activateAgent("agent_0", "new_collector"));
    EXPECT_FALSE(oldSlot->getModel());

    const auto newSlot = pool.getLiveModelSlot("agent_0", "new_collector");
    ASSERT_TRUE(newSlot);
    EXPECT_FALSE(newSlot->getModel());

    latency.modelRevision = 1025;
    ASSERT_TRUE(pool.record("agent_0", "rtx", latency, true, 2, "new_collector",
                            &accepted, false, &result));
    ASSERT_TRUE(accepted);
    ASSERT_TRUE(newSlot->getModel());
    EXPECT_EQ(result.model.get(), newSlot->getModel().get());

    pool.removeAgent("agent_0", "old_collector");
    ASSERT_TRUE(newSlot->getModel());
    EXPECT_EQ(result.model.get(), newSlot->getModel().get());

    pool.removeAgent("agent_0", "new_collector");
    EXPECT_FALSE(newSlot->getModel());
}

TEST_F(NaviSchedResourceTest,
       testMasterLatencyModelForcesUntrustedAfterTenConsecutiveRejects)
{
    MasterLatencyModelR pool;
    ASSERT_TRUE(pool.activateAgent("agent_0", "collector_0"));
    NonLinearPrefillModelR model;
    AgentLatencyToMasterData latency;
    latency.formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    latency.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    latency.modelRevision = 1024;
    latency.parameters = model.getInitialParameters();
    latency.optimizerState = makeLatencyOptimizerState(latency.parameters.size());
    latency.zeroPoint = NonLinearPrefillModelR::calculateZeroPoint(latency.parameters);

    MasterLatencyModelR::RecordResult result;
    bool liveUpdateAccepted = false;
    ASSERT_TRUE(pool.record("agent_0", "rtx", latency, true, 1, "collector_0",
                            &liveUpdateAccepted, false, &result));
    ASSERT_TRUE(liveUpdateAccepted);
    ASSERT_TRUE(result.model);
    ASSERT_TRUE(result.model->overloadPredictionTrusted);

    auto rejected = latency;
    rejected.modelRevision = 1025;
    for (uint32_t count = 1; count <= 10; ++count) {
        liveUpdateAccepted = true;
        EXPECT_FALSE(pool.record("agent_0", "rtx", rejected, false, count + 1,
                                 "collector_0", &liveUpdateAccepted, false, &result));
        EXPECT_FALSE(liveUpdateAccepted);
        ASSERT_TRUE(result.model);
        EXPECT_EQ(count, result.consecutiveRejectedCount);
        EXPECT_EQ(count, result.model->consecutiveRejectedCount);
        EXPECT_EQ("trusted_regression", result.model->lastRejectReason);
        EXPECT_EQ(count == 10, result.forcedUntrusted);
        EXPECT_EQ(count < 10, result.model->overloadPredictionTrusted);
    }

    auto recovered = latency;
    recovered.modelRevision = 1025;
    liveUpdateAccepted = false;
    ASSERT_TRUE(pool.record("agent_0", "rtx", recovered, true, 20, "collector_0",
                            &liveUpdateAccepted, false, &result));
    EXPECT_TRUE(liveUpdateAccepted);
    ASSERT_TRUE(result.model);
    EXPECT_TRUE(result.model->overloadPredictionTrusted);
    EXPECT_EQ(0, result.model->consecutiveRejectedCount);
    EXPECT_TRUE(result.model->lastRejectReason.empty());

    EXPECT_FALSE(pool.record("agent_0", "rtx", rejected, false, 21, "collector_0",
                             &liveUpdateAccepted, false, &result));
    ASSERT_EQ(1, result.model->consecutiveRejectedCount);
    EXPECT_FALSE(pool.record("agent_0", "rtx", recovered, true, 22, "collector_0",
                             &liveUpdateAccepted, false, &result));
    EXPECT_TRUE(liveUpdateAccepted);
    ASSERT_TRUE(result.model);
    EXPECT_EQ(0, result.model->consecutiveRejectedCount);
    EXPECT_TRUE(result.model->lastRejectReason.empty());

    pool.removeAgent("agent_0", "collector_0");
    ASSERT_TRUE(pool.activateAgent("agent_0", "collector_1"));
    autil::ScopedLock lock(pool._lock);
    EXPECT_EQ(0, pool._liveModels.at("agent_0")->consecutiveRejectedCount);
    EXPECT_FALSE(std::atomic_load_explicit(&pool._liveModels.at("agent_0")->model,
                                           std::memory_order_acquire));
}

TEST_F(NaviSchedResourceTest,
       testMasterLatencyModelCountsInvalidRejectsAndBlocksStalePromotion)
{
    MasterLatencyModelR pool;
    ASSERT_TRUE(pool.activateAgent("agent_0", "collector_0"));
    NonLinearPrefillModelR model;
    AgentLatencyToMasterData latency;
    latency.formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    latency.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    latency.modelRevision = 1024;
    latency.parameters = model.getInitialParameters();
    latency.optimizerState = makeLatencyOptimizerState(latency.parameters.size());
    latency.zeroPoint = NonLinearPrefillModelR::calculateZeroPoint(latency.parameters);

    MasterLatencyModelR::RecordResult result;
    bool accepted = false;
    ASSERT_TRUE(pool.record("agent_0", "rtx", latency, true, 1, "collector_0", &accepted,
                            false, &result));
    ASSERT_TRUE(accepted);

    auto invalid = latency;
    invalid.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION - 1;
    for (uint32_t count = 1; count <= 10; ++count) {
        accepted = true;
        EXPECT_FALSE(pool.record("agent_0", "rtx", invalid, true, count + 1,
                                 "collector_0", &accepted, false, &result));
        EXPECT_FALSE(accepted);
        ASSERT_TRUE(result.model);
        EXPECT_EQ(count, result.consecutiveRejectedCount);
        EXPECT_EQ("invalid_model", result.model->lastRejectReason);
        EXPECT_EQ(count == 10, result.forcedUntrusted);
        EXPECT_EQ(count < 10, result.model->overloadPredictionTrusted);
    }

    accepted = true;
    EXPECT_FALSE(pool.record("agent_0", "rtx", latency, true, 20, "collector_0",
                             &accepted, false, &result));
    EXPECT_FALSE(accepted);
    ASSERT_TRUE(result.model);
    EXPECT_FALSE(result.model->overloadPredictionTrusted);
    EXPECT_EQ(10, result.model->consecutiveRejectedCount);

    latency.modelRevision = 1025;
    latency.zeroPoint = NonLinearPrefillModelR::calculateZeroPoint(latency.parameters);
    accepted = false;
    ASSERT_TRUE(pool.record("agent_0", "rtx", latency, true, 21, "collector_0", &accepted,
                            false, &result));
    EXPECT_TRUE(accepted);
    ASSERT_TRUE(result.model);
    EXPECT_TRUE(result.model->overloadPredictionTrusted);
    EXPECT_EQ(0, result.model->consecutiveRejectedCount);
}

TEST_F(NaviSchedResourceTest, testMasterLatencyModelSourceMismatchPreservesCurrentModel)
{
    MasterLatencyModelR pool;
    ASSERT_TRUE(pool.activateAgent("agent_0", "collector_0"));
    NonLinearPrefillModelR model;
    auto latency = model.getInitialParameters();
    latency[NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX] =
        parameterForFormulaCoefficient(
            NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX, 12.0);
    AgentLatencyToMasterData initial;
    initial.formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    initial.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    initial.modelRevision = 1024;
    initial.parameters = latency;
    initial.optimizerState = makeLatencyOptimizerState(latency.size());
    initial.zeroPoint = NonLinearPrefillModelR::calculateZeroPoint(latency);

    MasterLatencyModelR::RecordResult result;
    bool accepted = false;
    ASSERT_TRUE(pool.record("agent_0", "rtx", initial, true, 1, "collector_0", &accepted,
                            false, &result));
    ASSERT_TRUE(accepted);
    ASSERT_TRUE(result.model);
    const auto current = result.model;

    auto incoming = initial;
    incoming.modelRevision = 2048;
    accepted = true;
    EXPECT_FALSE(pool.record("agent_0", "rtx", incoming, true, 2, "old_collector",
                             &accepted, false, &result));
    EXPECT_FALSE(accepted);
    EXPECT_EQ(MasterLatencyModelR::RejectReason::SOURCE_MISMATCH, result.rejectReason);
    EXPECT_EQ(0, result.consecutiveRejectedCount);
    ASSERT_TRUE(result.model);
    EXPECT_EQ(current.get(), result.model.get());
    EXPECT_EQ(1024, result.model->revision);
    EXPECT_TRUE(result.model->overloadPredictionTrusted);
}

TEST_F(NaviSchedResourceTest, testMasterRestoresMonotonicWorkloadAndPdMode)
{
    const auto makeWorkload = [](uint64_t revision, int32_t requestCount) {
        auto update = std::make_shared<AgentUpdateToMasterData>();
        update->event = NaviSchedAgentEvent::WORKLOAD_UPDATED;
        update->eventTimeUs = 1000 + revision;
        update->workload = std::make_shared<NaviSchedWorkloadSnapshot>();
        update->workload->revision = revision;
        update->workload->eventTimeUs = update->eventTimeUs;
        update->workload->requestCount = requestCount;
        return update;
    };

    TestMasterStateR runtime;
    runtime.registerAgent("agent_0", "agent_biz", "127.0.0.1:1000", 0);
    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    handshake->control->pdSeparated = false;
    handshake->control->unifiedLatencyPrediction = true;
    handshake->workload = makeWorkload(5, 2)->workload;
    enableCapacitySplitWorkload(*handshake->workload);
    ASSERT_TRUE(runtime.reportAgent("agent_0", handshake));

    auto state = runtime.getNodeState(hashString("agent_0"));
    ASSERT_TRUE(state);
    auto info = state->getInfo();
    ASSERT_FALSE(info.pdSeparated);
    ASSERT_EQ(5, info.workload.revision);
    ASSERT_EQ(2, info.workload.requestCount);
    ASSERT_GT(info.workloadReportReceiveTimeUs, 0);

    auto fresh = makeWorkload(6, 3);
    enableCapacitySplitWorkload(*fresh->workload);
    ASSERT_TRUE(runtime.reportAgent("agent_0", fresh));
    auto stale = makeWorkload(5, 9);
    enableCapacitySplitWorkload(*stale->workload);
    ASSERT_TRUE(runtime.reportAgent("agent_0", stale));
    info = state->getInfo();
    ASSERT_EQ(6, info.workload.revision);
    ASSERT_EQ(3, info.workload.requestCount);
    ASSERT_EQ(1, info.workloadStaleUpdateCount);
    ASSERT_EQ(2, runtime.getAgentRequestStats().workloadUpdateCount);

    auto restarted = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    restarted->control->pdSeparated = true;
    restarted->workload = makeWorkload(1, 1)->workload;
    ASSERT_TRUE(runtime.reportAgent("agent_0", restarted));
    info = state->getInfo();
    ASSERT_TRUE(info.pdSeparated);
    ASSERT_EQ(1, info.workload.revision);
    ASSERT_EQ(1, info.workload.requestCount);
    ASSERT_EQ(0, info.workloadStaleUpdateCount);

    auto emptyRestart = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    ASSERT_TRUE(runtime.reportAgent("agent_0", emptyRestart));
    info = state->getInfo();
    ASSERT_EQ(0, info.workload.revision);
    ASSERT_EQ(0, info.workloadReportReceiveTimeUs);
}

TEST_F(NaviSchedResourceTest, testMasterTracksExecutionLoadAndCacheValidity)
{
    TestMasterStateR runtime;
    runtime.registerAgent("agent_0", "model_biz", "127.0.0.1:19000", 100);
    auto agentIdHash = hashString("agent_0");
    auto load = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED);
    load->requestEvent->batchWaitingRequests = 7;
    load->requestEvent->queuedBatchRequests = 5;
    load->requestEvent->runningRequests = 3;
    load->requestEvent->batchTimeoutCount = 9;
    load->requestEvent->queueTotalPredictedLatencyMs = 35.5;
    ASSERT_TRUE(runtime.reportAgent("agent_0", load));
    auto state = runtime.getNodeState(agentIdHash);
    ASSERT_TRUE(state);
    auto queueReportReceiveTimeUs = state->getInfo().queueReportReceiveTimeUs;
    ASSERT_GT(queueReportReceiveTimeUs, 0);

    auto request = makeRequestUpdate(NaviSchedAgentEvent::REQUEST_RECEIVED, 100);
    request->requestEvent->requestId = 101;
    setInflightSnapshot(request, 2, 1);
    ASSERT_TRUE(runtime.reportAgent("agent_0", request));

    auto finished = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED, 150);
    setInflightSnapshot(finished, 3, 0);
    finished->requestEvent->completedRequestCount = 1;
    finished->requestEvent->latencyMs = 8.5;
    finished->requestEvent->batchWaitingRequests = 7;
    finished->requestEvent->queuedBatchRequests = 5;
    finished->requestEvent->runningRequests = 3;
    finished->requestEvent->batchTimeoutCount = 9;
    finished->requestEvent->queueTotalPredictedLatencyMs = 35.5;
    ASSERT_TRUE(runtime.reportAgent("agent_0", finished));

    auto cache = makeCacheSnapshot({11, UINT64_MAX}, 200);
    ASSERT_TRUE(runtime.reportAgent("agent_0", cache));
    ASSERT_EQ(2, state->getMatchedBlockCount({11, UINT64_MAX}));

    auto removed = makeCacheUpdate(200);
    removed->cache->removedBlockHashes = makeBlockHashes({11, UINT64_MAX});
    setVerifiedCacheState(*removed->cache, 2, {});
    ASSERT_TRUE(runtime.reportAgent("agent_0", removed));
    auto info = state->getInfo();
    ASSERT_EQ(7, info.batchWaitingRequests);
    ASSERT_EQ(5, info.queuedBatchRequests);
    ASSERT_EQ(3, info.runningRequests);
    ASSERT_EQ(9, info.batchTimeoutCount);
    ASSERT_DOUBLE_EQ(8.5, info.lastRequestLatencyMs);
    ASSERT_DOUBLE_EQ(35.5, info.queueTotalPredictedLatencyMs);
    ASSERT_GE(info.queueReportReceiveTimeUs, queueReportReceiveTimeUs);
    ASSERT_EQ(0, state->getMatchedBlockCount({11, UINT64_MAX}));
    ASSERT_EQ("batch_finished", info.lastRequestEventType);
    ASSERT_EQ(150, info.lastRequestEventTimeUs);
    ASSERT_EQ("cache_updated", info.lastEventType);
    ASSERT_EQ(200, info.lastEventTimeUs);
}

TEST_F(NaviSchedResourceTest, testMasterInflightRevisionRejectsConflictAndHandshakeResets)
{
    TestMasterStateR runtime;
    runtime.registerAgent("agent_0", "agent_biz", "", 0);
    auto initial = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED, 100);
    setInflightSnapshot(initial, 2, 1, 10.0);
    initial->requestEvent->batchWaitingRequests = 3;
    initial->requestEvent->queueTotalPredictedLatencyMs = 25.0;
    ASSERT_TRUE(runtime.reportAgent("agent_0", initial));

    auto conflicting =
        makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED, 200);
    setInflightSnapshot(conflicting, 2, 2, 20.0);
    conflicting->requestEvent->batchWaitingRequests = 9;
    conflicting->requestEvent->queueTotalPredictedLatencyMs = 90.0;
    EXPECT_FALSE(runtime.reportAgent("agent_0", conflicting));

    auto state = runtime.getNodeState(hashString("agent_0"));
    ASSERT_TRUE(state);
    auto info = state->getInfo();
    EXPECT_EQ(2, info.inflightStatsRevision);
    EXPECT_EQ(1, info.inflightRequests);
    EXPECT_DOUBLE_EQ(10.0, info.inflightPredictedLatencySumMs);
    EXPECT_EQ(3, info.batchWaitingRequests);
    EXPECT_DOUBLE_EQ(25.0, info.queueTotalPredictedLatencyMs);
    EXPECT_EQ(100, info.lastEventTimeUs);
    auto stats = runtime.getAgentRequestStats();
    EXPECT_EQ(1, stats.reportCount);
    EXPECT_EQ(1, stats.executionLoadCount);
    EXPECT_EQ(1, runtime.getAgentReportCount());

    auto stale = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED, 300);
    setInflightSnapshot(stale, 1, 7, 70.0);
    stale->requestEvent->batchWaitingRequests = 4;
    stale->requestEvent->queueTotalPredictedLatencyMs = 35.0;
    ASSERT_TRUE(runtime.reportAgent("agent_0", stale));
    info = state->getInfo();
    EXPECT_EQ(2, info.inflightStatsRevision);
    EXPECT_EQ(1, info.inflightRequests);
    EXPECT_DOUBLE_EQ(10.0, info.inflightPredictedLatencySumMs);
    EXPECT_EQ(4, info.batchWaitingRequests);
    EXPECT_DOUBLE_EQ(35.0, info.queueTotalPredictedLatencyMs);

    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    setInflightSnapshot(handshake, 1, 0);
    ASSERT_TRUE(runtime.reportAgent("agent_0", handshake));
    info = state->getInfo();
    EXPECT_EQ(1, info.inflightStatsRevision);
    EXPECT_EQ(0, info.inflightRequests);
    EXPECT_DOUBLE_EQ(0.0, info.inflightPredictedLatencySumMs);
}

