TEST_F(NaviSchedResourceTest, testInvalidOptimizerDoesNotPartiallyCommitInflightSnapshot)
{
    TestMasterStateR runtime;
    auto state = runtime.registerAgent("agent_0", "agent_biz", "127.0.0.1:19000", 0);
    ASSERT_TRUE(state);

    NonLinearPrefillModelR model;
    const auto makeModelUpdate = [&](int64_t revision, uint64_t inflightRevision,
                                     int32_t inflightRequests) {
        auto update = makeRequestUpdate(NaviSchedAgentEvent::LATENCY_MODEL_UPDATED, 200);
        update->latency = std::make_shared<AgentLatencyToMasterData>();
        update->latency->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
        update->latency->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
        update->latency->modelRevision = revision;
        update->latency->parameters = model.getInitialParameters();
        setInflightSnapshot(update, inflightRevision, inflightRequests, 120.0);
        return update;
    };

    ASSERT_TRUE(runtime.reportAgent("agent_0", makeModelUpdate(7, 10, 2)));
    const auto acceptedModel = state->getLatencyInfo();
    ASSERT_TRUE(acceptedModel);
    const auto acceptedInfo = state->getInfo();

    auto invalid = makeModelUpdate(8, 11, 3);
    invalid->latency->optimizerState = {};
    EXPECT_FALSE(runtime.MasterStateR::reportAgent("agent_0", invalid));

    const auto afterRejectedModel = state->getLatencyInfo();
    ASSERT_TRUE(afterRejectedModel);
    EXPECT_EQ(acceptedModel->revision, afterRejectedModel->revision);
    EXPECT_EQ(acceptedModel->parameters, afterRejectedModel->parameters);
    EXPECT_EQ(1, afterRejectedModel->consecutiveRejectedCount);
    EXPECT_EQ("invalid_model", afterRejectedModel->lastRejectReason);
    const auto afterRejectedInfo = state->getInfo();
    EXPECT_EQ(acceptedInfo.inflightStatsRevision,
              afterRejectedInfo.inflightStatsRevision);
    EXPECT_EQ(acceptedInfo.inflightRequests, afterRejectedInfo.inflightRequests);
    EXPECT_DOUBLE_EQ(acceptedInfo.inflightPredictedLatencySumMs,
                     afterRejectedInfo.inflightPredictedLatencySumMs);

    auto invalidRevision = makeModelUpdate(0, 12, 4);
    invalidRevision->latency->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    invalidRevision->latency->optimizerState = {};
    EXPECT_FALSE(runtime.MasterStateR::reportAgent("agent_0", invalidRevision));
    const auto afterInvalidRevision = state->getInfo();
    EXPECT_EQ(acceptedInfo.inflightStatsRevision,
              afterInvalidRevision.inflightStatsRevision);
    EXPECT_EQ(acceptedInfo.inflightRequests, afterInvalidRevision.inflightRequests);
    EXPECT_DOUBLE_EQ(acceptedInfo.inflightPredictedLatencySumMs,
                     afterInvalidRevision.inflightPredictedLatencySumMs);
    const auto rejectedModel = state->getLatencyInfo();
    ASSERT_TRUE(rejectedModel);
    EXPECT_EQ(2, rejectedModel->consecutiveRejectedCount);
    EXPECT_EQ("invalid_model", rejectedModel->lastRejectReason);
}

TEST_F(NaviSchedResourceTest, testMasterRejectsAssignmentsBeyondInflightLimit)
{
    auto context = makeCapacitySplitCostSchedulerContext(2, 32, 0, 0);
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
    ASSERT_TRUE(context.valid());
    ASSERT_EQ(1, context.nodeCount());
    context._scheduleNodes[0]._inflightRequests =
        NAVI_SCHED_MAX_INFLIGHT_REQUEST_COUNT - 1;
    ASSERT_TRUE(context.selectNode(0, 0, "selected"));
    ASSERT_TRUE(context.selectNode(1, 0, "selected"));
    ASSERT_TRUE(context.prepareResult(context._scheduleTimeUs));

    ASSERT_EQ(2, context._decisions.size());
    EXPECT_FALSE(context._decisions[0].target.address.empty());
    EXPECT_EQ(1, context._decisions[0].expectedBatchSize);
    EXPECT_TRUE(context._decisions[1].target.address.empty());
    EXPECT_EQ("rate_limited", context._decisions[1].reason);
    EXPECT_EQ(NaviSchedScheduleContext::INVALID_NODE_INDEX,
              context._selectedNodeIndexes[1]);
}

