    ASSERT_NE(std::string::npos,
              masterJson.find("\"latency_model_consecutive_rejected_count\":9"));
    ASSERT_NE(std::string::npos,
              masterJson.find("\"latency_model_last_reject_reason\":\"stale_revision\""));
    ASSERT_NE(std::string::npos, masterJson.find("\"master_sent_request_count\":11"));
    ASSERT_NE(std::string::npos, masterJson.find("\"master_sent_batch_count\":4"));
    ASSERT_NE(std::string::npos,
              masterJson.find("\"pending_cache_resync_trigger_count\":3"));
