TEST_F(NaviSchedResourceTest, testMasterReportsReplayPreparationOnlyForCollectedReplay)
{
    kmonitor::KMonitorFactory::Shutdown();
    kmonitor::MetricsConfig config;
    config.set_tenant_name("default");
    config.set_service_name("replay_preparation_metric_test");
    config.set_sink_address("127.0.0.1:4141");
    config.set_manually_mode(true);
    config.set_inited(true);
    ASSERT_TRUE(kmonitor::KMonitorFactory::Init(config));
    kmonitor::KMonitorFactory::Start();
    {
        auto reporter = std::make_shared<kmonitor::MetricsReporter>(
            "", kmonitor::MetricsTags());
        kmonitor::MetricsReporterR reporterR(reporter);
        MasterScheduleResultKernel kernel;
        kernel._metricsReporterR__ = &reporterR;
        NaviSchedScheduleContext context;
        const std::string metricName =
            "replay_preparation_metric_test.master.schedule_replay_prepare_ms";
        auto *manager = reporter->_monitor->manager_;
        auto &metrics = manager->sharded_metrics_[manager->GetShardId(metricName)];

        kernel.reportPredictionMetrics(context);
        EXPECT_EQ(0u, metrics.metric_data_map_.count(metricName));
        context._replayPrepareUs = 1234;
        kernel.reportPredictionMetrics(context);
        EXPECT_EQ(0u, metrics.metric_data_map_.count(metricName));

        context.setReplay(std::make_shared<NaviSchedScheduleReplay>());
        context._replayPrepareUs = -1;
        kernel.reportPredictionMetrics(context);
        EXPECT_EQ(0u, metrics.metric_data_map_.count(metricName));
        context._replayPrepareUs = 0;
        kernel.reportPredictionMetrics(context);
        kmonitor::MetricsTestUtil::checkMetricWithValue(
            reporter.get(), metricName, nullptr, 0.0);
        context._replayPrepareUs = 1234;
        kernel.reportPredictionMetrics(context);

        context.setReplay(nullptr);
        context._replayPrepareUs = 5678;
        kernel.reportPredictionMetrics(context);
        kmonitor::MetricsData *data = nullptr;
        kmonitor::MetricsTestUtil::getMetricsData(reporter.get(), metricName, data);
        ASSERT_NE(nullptr, data);
        const auto metric = data->metric_map_.find(reporter->_tags.Hashcode());
        ASSERT_NE(data->metric_map_.end(), metric);
        const auto *gauge = dynamic_cast<kmonitor::GaugeMetric *>(metric->second.second);
        ASSERT_NE(nullptr, gauge);
        EXPECT_EQ(2, gauge->calculator_.Count());
        EXPECT_DOUBLE_EQ(1.234, gauge->calculator_.Sum());
    }
    kmonitor::KMonitorFactory::Shutdown();
}

