TEST_F(NaviSchedResourceTest, testAgentReportsPrecomputedCacheHashes)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init());
    auto resource = context.get();
    auto pipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("collector", pipe));

    NaviSchedCacheUpdate update;
    update.totalBlocks = 100;
    update.addedBlockHashes = makeBlockHashes({11, 22});
    ASSERT_EQ(1, resource->reportCacheUpdated(update));
    auto added = dynamic_cast<AgentUpdateToMasterData *>(pipe->datas.back().get());
    ASSERT_TRUE(added);
    ASSERT_TRUE(added->cache);
    ASSERT_EQ(NaviSchedBlockHashes({11, 22}), *added->cache->addedBlockHashes);

    update.addedBlockHashes = makeBlockHashes({33});
    update.removedBlockHashes = makeBlockHashes({11, 22});
    ASSERT_EQ(1, resource->reportCacheUpdated(update));
    auto replaced = dynamic_cast<AgentUpdateToMasterData *>(pipe->datas.back().get());
    ASSERT_TRUE(replaced);
    ASSERT_TRUE(replaced->cache);
    ASSERT_EQ(NaviSchedBlockHashes({33}), *replaced->cache->addedBlockHashes);
    ASSERT_EQ(2, replaced->cache->removedBlockHashes->size());

    auto replayPipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("replay", replayPipe));
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT, replayPipe->datas.size());
    auto replay = dynamic_cast<AgentUpdateToMasterData *>(replayPipe->datas[1].get());
    ASSERT_TRUE(replay);
    ASSERT_TRUE(replay->cache);
    ASSERT_EQ(NaviSchedBlockHashes({33}), *replay->cache->addedBlockHashes);
}

TEST_F(NaviSchedResourceTest, testAgentPreservesConcurrentCacheUpdateOrder)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init());
    auto resource = context.get();
    auto pipe = std::make_shared<DelayedCacheAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("collector", pipe));

    NaviSchedCacheUpdate first;
    first.addedBlockHashes = makeBlockHashes({11});
    NaviSchedCacheUpdate second;
    second.addedBlockHashes = makeBlockHashes({22});
    std::thread firstThread([&]() { ASSERT_EQ(1, resource->reportCacheUpdated(first)); });
    while (!pipe->firstIncrementEntered.load(std::memory_order_acquire)) {
        std::this_thread::yield();
    }
    std::thread secondThread(
        [&]() { ASSERT_EQ(1, resource->reportCacheUpdated(second)); });
    firstThread.join();
    secondThread.join();

    std::lock_guard<std::mutex> lock(pipe->mutex);
    ASSERT_EQ((std::vector<uint64_t>{1, 2}), pipe->revisions);
}

