TEST_F(NaviSchedResourceTest, testAgentSnapshotDoesNotRaceQueuedCacheDelta)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init());
    auto resource = context.get();
    auto firstPipe = std::make_shared<DelayedCacheAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("first", firstPipe));

    NaviSchedCacheUpdate first;
    first.blockSize = 1;
    first.linearStep = 1;
    first.hybridTailRequired = 0;
    first.addedBlockHashes = makeBlockHashes({11});
    std::thread updateThread(
        [&]() { ASSERT_EQ(1, resource->reportCacheUpdated(first)); });
    while (!firstPipe->firstIncrementEntered.load(std::memory_order_acquire)) {
        std::this_thread::yield();
    }

    auto secondPipe = std::make_shared<CaptureAsyncPipe>();
    std::thread subscribeThread(
        [&]() { ASSERT_TRUE(resource->subscribe("second", secondPipe)); });
    updateThread.join();
    subscribeThread.join();

    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT, secondPipe->datas.size());
    auto snapshot = dynamic_cast<AgentUpdateToMasterData *>(secondPipe->datas[1].get());
    ASSERT_TRUE(snapshot);
    ASSERT_TRUE(snapshot->cache);
    EXPECT_TRUE(snapshot->cache->fullSnapshot);
    EXPECT_EQ(1, snapshot->cache->revision);
    EXPECT_EQ(NaviSchedBlockHashes({11}), *snapshot->cache->addedBlockHashes);

    NaviSchedCacheUpdate second;
    second.addedBlockHashes = makeBlockHashes({22});
    ASSERT_EQ(2, resource->reportCacheUpdated(second));
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT + 1, secondPipe->datas.size());
    auto delta = dynamic_cast<AgentUpdateToMasterData *>(secondPipe->datas.back().get());
    ASSERT_TRUE(delta);
    ASSERT_TRUE(delta->cache);
    EXPECT_FALSE(delta->cache->fullSnapshot);
    EXPECT_EQ(2, delta->cache->revision);
}

TEST_F(NaviSchedResourceTest, testAgentPendingSnapshotDoesNotRaceQueuedPendingDelta)
{
    AgentReportTestContext context;
    ASSERT_TRUE(context.init());
    auto resource = context.get();
    auto firstPipe = std::make_shared<BlockingPendingCacheAsyncPipe>();
    ASSERT_TRUE(resource->subscribe("first", firstPipe));

    NaviSchedPendingCacheReservation reservation;
    reservation.batchId = 7;
    reservation.scheduleBatchId = 7;
    reservation.fullReadyBlockHashes = {11, 22};
    bool readyResult = false;
    std::thread updateThread(
        [&]() { readyResult = resource->reportPendingCacheReady(reservation); });
    const bool blocked = firstPipe->waitUntilBlocked();
    if (!blocked) {
        firstPipe->release();
        updateThread.join();
    }
    ASSERT_TRUE(blocked);

    auto secondPipe = std::make_shared<CaptureAsyncPipe>();
    bool subscribeResult = false;
    std::thread subscribeThread(
        [&]() { subscribeResult = resource->subscribe("second", secondPipe); });
    size_t subscriberCount = 0;
    for (size_t retry = 0; retry < 1000; ++retry) {
        subscriberCount = resource->getSubscriberCount();
        if (subscriberCount == 2) {
            break;
        }
        usleep(1000);
    }
    firstPipe->release();
    updateThread.join();
    subscribeThread.join();

    ASSERT_TRUE(readyResult);
    ASSERT_TRUE(subscribeResult);
    ASSERT_EQ(2, subscriberCount);
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT, secondPipe->datas.size());
    auto snapshot = dynamic_cast<AgentUpdateToMasterData *>(secondPipe->datas[2].get());
    ASSERT_TRUE(snapshot);
    ASSERT_TRUE(snapshot->pendingCache);
    EXPECT_TRUE(snapshot->pendingCache->fullSnapshot);
    EXPECT_EQ(1, snapshot->pendingCache->revision);
    ASSERT_EQ(1, snapshot->pendingCache->addedReservations.size());
    EXPECT_EQ(7, snapshot->pendingCache->addedReservations.front().batchId);
    EXPECT_EQ(NaviSchedBlockHashes({11, 22}),
              snapshot->pendingCache->addedReservations.front().fullReadyBlockHashes);

    ASSERT_TRUE(resource->reportPendingCacheAborted(7));
    ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT + 1, secondPipe->datas.size());
    auto delta = dynamic_cast<AgentUpdateToMasterData *>(secondPipe->datas.back().get());
    ASSERT_TRUE(delta);
    ASSERT_TRUE(delta->pendingCache);
    EXPECT_FALSE(delta->pendingCache->fullSnapshot);
    EXPECT_EQ(2, delta->pendingCache->revision);
    EXPECT_EQ(std::vector<int64_t>({7}), delta->pendingCache->removedBatchIds);
}

