TEST_F(NaviSchedResourceTest, testAgentLatencyPredictionModeValidation)
{
    auto makeConfig = [](const std::string &name, bool pdSeparated,
                         bool unifiedLatencyPrediction) {
        NaviSchedAgentConfig config;
        config.runtime.bizName = "agent_biz";
        config.runtime.threadNum = 2;
        config.runtime.queueSize = 100;
        config.service.name = name;
        config.service.enableKmon = false;
        config.service.gig.grpcPort = 0;
        config.service.enableSnapshot = false;
        config.service.waitNoQuery = false;
        config.pdSeparated = pdSeparated;
        config.unifiedLatencyPrediction = unifiedLatencyPrediction;
        return config;
    };

    NaviSchedAgent invalid(makeConfig("agent_non_pd_split_invalid", false, false));
    EXPECT_FALSE(invalid.init());

    struct ValidMode {
        const char *name;
        bool pdSeparated;
        bool unifiedLatencyPrediction;
    };
    const std::vector<ValidMode> validModes = {
        {"agent_pd_split", true, false},
        {"agent_pd_unified", true, true},
        {"agent_non_pd_unified", false, true},
    };
    for (const auto &mode : validModes) {
        NaviSchedAgent agent(
            makeConfig(mode.name, mode.pdSeparated, mode.unifiedLatencyPrediction));
        ASSERT_TRUE(agent.init()) << mode.name;
        agent.stop();
    }
}

TEST_F(NaviSchedResourceTest, testAgentLatencyPredictionModeBehaviorMatrix)
{
    struct Mode {
        bool pdSeparated;
        bool unifiedLatencyPrediction;
        bool derivesUnifiedWorkload;
        bool hasInitialWorkload;
        bool prefillCapacitySplit;
    };
    const std::vector<Mode> modes = {
        {true, false, false, false, false},
        {true, true, true, true, false},
        {false, true, false, true, true},
    };
    for (const auto &mode : modes) {
        AgentReportTestContext context;
        ASSERT_TRUE(context.init(0, "", 0, false, mode.pdSeparated, false,
                                 mode.unifiedLatencyPrediction));
        auto reportR = context.get();
        ASSERT_TRUE(reportR);
        EXPECT_EQ(mode.pdSeparated, reportR->pdSeparated());
        EXPECT_EQ(mode.unifiedLatencyPrediction, reportR->usesUnifiedLatencyPrediction());
        EXPECT_EQ(
            mode.derivesUnifiedWorkload,
            AgentLatencyKernelTest::derivesUnifiedWorkloadFromBatches(reportR.get()));
        const auto initialWorkload = reportR->getWorkloadSnapshot();
        ASSERT_EQ(mode.hasInitialWorkload, bool(initialWorkload));
        if (initialWorkload) {
            EXPECT_TRUE(initialWorkload->valid());
            EXPECT_EQ(mode.prefillCapacitySplit, initialWorkload->prefillCapacitySplit);
        }

        auto pipe = std::make_shared<CaptureAsyncPipe>();
        ASSERT_TRUE(reportR->subscribe("collector", pipe));
        ASSERT_EQ(AGENT_INITIAL_REPORT_COUNT, pipe->datas.size());
        auto handshake =
            std::dynamic_pointer_cast<AgentUpdateToMasterData>(pipe->datas.front());
        ASSERT_TRUE(handshake);
        ASSERT_EQ(NaviSchedAgentEvent::AGENT_HANDSHAKE, handshake->event);
        ASSERT_EQ(mode.hasInitialWorkload, bool(handshake->workload));
        if (handshake->workload) {
            EXPECT_TRUE(handshake->workload->valid());
            EXPECT_EQ(mode.prefillCapacitySplit,
                      handshake->workload->prefillCapacitySplit);
        }
    }
}

TEST_F(NaviSchedResourceTest, testMasterRejectsPdModeFeatureMismatches)
{
    const auto makeLatency = [](size_t parameterCount, int64_t revision = 1) {
        auto latency = std::make_shared<AgentLatencyToMasterData>();
        latency->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
        latency->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
        latency->modelRevision = revision;
        latency->parameters = parametersForFormulaCoefficients(
            std::vector<double>(parameterCount, 1.0));
        return latency;
    };
    const auto makeWorkload = [](bool capacitySplit, uint64_t revision = 1) {
        auto workload = makeWorkloadUpdate(revision, 100 + revision)->workload;
        if (capacitySplit) {
            enableCapacitySplitWorkload(*workload);
        }
        return workload;
    };
    const auto makeHandshake = [&](bool pdSeparated, size_t parameterCount,
                                   bool capacitySplit) {
        auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
        handshake->control->pdSeparated = pdSeparated;
        handshake->control->unifiedLatencyPrediction = true;
        handshake->latency = makeLatency(parameterCount);
        handshake->workload = makeWorkload(capacitySplit);
        return handshake;
    };

    TestMasterStateR runtime;
    runtime.registerAgent("pd_bad_model", "agent_biz", "127.0.0.1:1001", 0);
    EXPECT_FALSE(runtime.reportAgent(
        "pd_bad_model",
        makeHandshake(true, NonLinearPrefillModelR::CAPACITY_SPLIT_PARAMETER_COUNT,
                      false)));
    runtime.registerAgent("non_pd_bad_model", "agent_biz", "127.0.0.1:1002", 0);
    EXPECT_FALSE(runtime.reportAgent(
        "non_pd_bad_model",
        makeHandshake(false, NonLinearPrefillModelR::PARAMETER_COUNT, true)));
    runtime.registerAgent("pd_bad_workload", "agent_biz", "127.0.0.1:1003", 0);
    EXPECT_FALSE(runtime.reportAgent(
        "pd_bad_workload",
        makeHandshake(true, NonLinearPrefillModelR::PARAMETER_COUNT, true)));
    runtime.registerAgent("non_pd_bad_workload", "agent_biz", "127.0.0.1:1004", 0);
    EXPECT_FALSE(runtime.reportAgent(
        "non_pd_bad_workload",
        makeHandshake(false, NonLinearPrefillModelR::CAPACITY_SPLIT_PARAMETER_COUNT,
                      false)));

    runtime.registerAgent("pd", "agent_biz", "127.0.0.1:1005", 0);
    ASSERT_TRUE(runtime.reportAgent(
        "pd", makeHandshake(true, NonLinearPrefillModelR::PARAMETER_COUNT, false)));
    auto pdBadLatency =
        makeLatency(NonLinearPrefillModelR::CAPACITY_SPLIT_PARAMETER_COUNT, 2);
    auto pdLatencyUpdate = makeLatencyUpdate(200);
    pdLatencyUpdate->latency = std::move(pdBadLatency);
    EXPECT_FALSE(runtime.reportAgent("pd", pdLatencyUpdate));
    auto pdWorkloadUpdate = makeWorkloadUpdate(2, 200);
    enableCapacitySplitWorkload(*pdWorkloadUpdate->workload);
    EXPECT_FALSE(runtime.reportAgent("pd", pdWorkloadUpdate));

    runtime.registerAgent("non_pd", "agent_biz", "127.0.0.1:1006", 0);
    ASSERT_TRUE(runtime.reportAgent(
        "non_pd",
        makeHandshake(false, NonLinearPrefillModelR::CAPACITY_SPLIT_PARAMETER_COUNT,
                      true)));
    auto nonPdLatencyUpdate = makeLatencyUpdate(200);
    nonPdLatencyUpdate->latency = makeLatency(NonLinearPrefillModelR::PARAMETER_COUNT, 2);
    EXPECT_FALSE(runtime.reportAgent("non_pd", nonPdLatencyUpdate));
    EXPECT_FALSE(runtime.reportAgent("non_pd", makeWorkloadUpdate(2, 200)));
}

