    CostSchedulerColdStartStrategy::Result trustedResult;
    ASSERT_TRUE(CostSchedulerColdStartStrategy::apply(trustedContext, trustedRandom,
                                                      trustedResult));
    EXPECT_TRUE(trustedResult.costScheduleRequired);
    EXPECT_DOUBLE_EQ(5.0, trustedResult.targetInflight);
    EXPECT_EQ(2, trustedResult.trustedNodeCount);
    EXPECT_EQ(0, trustedResult.untrustedNodeCount);
    EXPECT_EQ(3, trustedResult.trustedRequestCount);
    EXPECT_EQ(0, trustedResult.untrustedRequestCount);
    EXPECT_EQ(0, trustedResult.rejectedRequestCount);
    EXPECT_TRUE(trustedContext._scheduleViewActive);
    EXPECT_EQ(3, trustedContext.requestCount());
    EXPECT_EQ(2, trustedContext.nodeCount());

    auto fullReplay = makeCostSchedulerReplay(3, 2);
