TEST_F(NaviSchedResourceTest, testCostSchedulerColdStartRampProgressBoundaries)
{
    constexpr int64_t START_TIME_US = 10'000'000;
    EXPECT_DOUBLE_EQ(
        0.0, CostSchedulerColdStartStrategy::calculateRampProgress(START_TIME_US, 0, 0));
    EXPECT_DOUBLE_EQ(0.0, CostSchedulerColdStartStrategy::calculateRampProgress(
                              START_TIME_US - 1, START_TIME_US, 128));
    EXPECT_DOUBLE_EQ(1.0, CostSchedulerColdStartStrategy::calculateRampProgress(
                              START_TIME_US + 60'000'000, START_TIME_US, 0));
    EXPECT_DOUBLE_EQ(0.5, CostSchedulerColdStartStrategy::calculateRampProgress(
                              START_TIME_US + 30'000'000, START_TIME_US, 64));
    EXPECT_DOUBLE_EQ(1.0, CostSchedulerColdStartStrategy::calculateRampProgress(
                              START_TIME_US + 60'000'000, START_TIME_US, 64));
    EXPECT_DOUBLE_EQ(0.5, CostSchedulerColdStartStrategy::calculateRampProgress(
                              START_TIME_US + 30'000'000, START_TIME_US, 128));
    EXPECT_DOUBLE_EQ(1.0, CostSchedulerColdStartStrategy::calculateRampProgress(
                              START_TIME_US + 60'000'000, START_TIME_US, 128));
    EXPECT_DOUBLE_EQ(1.0, CostSchedulerColdStartStrategy::calculateRampProgress(
                              START_TIME_US + 299'999'999, START_TIME_US, 127));
    EXPECT_DOUBLE_EQ(1.0, CostSchedulerColdStartStrategy::calculateRampProgress(
                              START_TIME_US + 300'000'000, START_TIME_US, 0));

    EXPECT_FALSE(CostSchedulerColdStartStrategy::isRampFinished(START_TIME_US, 0, 0));
    EXPECT_FALSE(CostSchedulerColdStartStrategy::isRampFinished(
        START_TIME_US + 59'999'999, START_TIME_US, 128));
    EXPECT_TRUE(CostSchedulerColdStartStrategy::isRampFinished(START_TIME_US + 60'000'000,
                                                               START_TIME_US, 0));
    EXPECT_TRUE(CostSchedulerColdStartStrategy::isRampFinished(
        START_TIME_US + 299'999'999, START_TIME_US, 0));

    EXPECT_DOUBLE_EQ(
        1.0, CostSchedulerColdStartStrategy::calculateRampedTargetInflight(100.0, 0.0));
    EXPECT_DOUBLE_EQ(
        50.5, CostSchedulerColdStartStrategy::calculateRampedTargetInflight(100.0, 0.5));
    EXPECT_DOUBLE_EQ(
        100.0, CostSchedulerColdStartStrategy::calculateRampedTargetInflight(100.0, 1.0));
    EXPECT_DOUBLE_EQ(
        1.0, CostSchedulerColdStartStrategy::calculateRampedTargetInflight(0.0, 0.0));
    EXPECT_DOUBLE_EQ(
        0.0, CostSchedulerColdStartStrategy::calculateRampedTargetInflight(0.0, 1.0));
}

TEST_F(NaviSchedResourceTest,
       testCostSchedulerRampsTrustedCandidateUntilLocalSamplesAreCollected)
{
    auto replay = makeCostSchedulerReplay(10, 2);
    replay.nodes[0].inflightRequests = 20;
    replay.nodes[1].inflightRequests = 0;
    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    context._scheduleNodes[1]._agentStartTimeUs = replay.scheduleTimeUs;
    auto candidate =
        std::make_shared<NaviSchedLatencyModel>(*context._scheduleNodes[1]._latencyModel);
    candidate->revision = 4096;
    candidate->warmStarted = true;
    candidate->sessionSampleCount = 0;
    context._scheduleNodes[1]._latencyModel = std::move(candidate);
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
    context._coldStartBootstrapRequestCount = 10;

    multi_call::RandomGenerator randomGenerator(71);
    (void)randomGenerator.get();
    CostSchedulerColdStartStrategy::Result result;
    ASSERT_TRUE(CostSchedulerColdStartStrategy::apply(context, randomGenerator, result));
    EXPECT_EQ(1, result.trustedNodeCount);
    EXPECT_EQ(1, result.untrustedNodeCount);
    EXPECT_EQ(1, result.rampingNodeCount);
    EXPECT_DOUBLE_EQ(0.0, result.minimumRampProgress);
    EXPECT_DOUBLE_EQ(1.0, result.minimumRampedTargetInflight);
    EXPECT_EQ(1, result.untrustedCapacity);
    EXPECT_EQ(1, result.untrustedRequestCount);
    EXPECT_EQ(9, result.trustedRequestCount);
    ASSERT_EQ(10, context._selectedNodeIndexes.size());
    EXPECT_EQ(1, context._selectedNodeIndexes[0]);
    EXPECT_EQ(NaviSchedLatencyTrainingPhase::RAMP,
              context._decisions[0].latencyTrainingPhase);
}

TEST_F(NaviSchedResourceTest, testCostSchedulerRampUsesFixedDuration)
{
    EXPECT_DOUBLE_EQ(0.0,
                     CostSchedulerColdStartStrategy::calculateRampProgress(100, 0, 0));
    EXPECT_FALSE(CostSchedulerColdStartStrategy::isRampFinished(100, 0, 4096));
    EXPECT_FALSE(CostSchedulerColdStartStrategy::isRampFinished(100, -1, 4096));

    const auto run = [](int64_t elapsedUs, uint64_t sessionSampleCount,
                        size_t expectedCapacity, bool expectedRamping) {
        auto replay = makeCostSchedulerReplay(20, 2);
        replay.scheduleTimeUs = 1'000'000'000;
        replay.nodes[0].inflightRequests = 20;
        replay.nodes[1].inflightRequests = 0;
        NaviSchedScheduleContext context;
        CostSchedulerColdStartStrategy::Result result;
        const auto contextMade = ScheduleReplayRunner::makeContext(replay, context);
        EXPECT_TRUE(contextMade);
        if (!contextMade) {
            return result;
        }
        context._scheduleNodes[1]._agentStartTimeUs = replay.scheduleTimeUs - elapsedUs;
        auto model = std::make_shared<NaviSchedLatencyModel>(
            *context._scheduleNodes[1]._latencyModel);
        model->sessionSampleCount = sessionSampleCount;
        context._scheduleNodes[1]._latencyModel = std::move(model);
        const auto contextPrepared = ScheduleReplayRunner::prepareContext(context);
        EXPECT_TRUE(contextPrepared);
        if (!contextPrepared) {
            return result;
        }
        context._coldStartBootstrapRequestCount = 20;
        multi_call::RandomGenerator randomGenerator(73);
        (void)randomGenerator.get();
        const auto applied =
            CostSchedulerColdStartStrategy::apply(context, randomGenerator, result);
        EXPECT_TRUE(applied);
        if (!applied) {
            return result;
        }
        EXPECT_EQ(expectedRamping ? 1 : 0, result.rampingNodeCount);
        EXPECT_EQ(expectedCapacity, result.untrustedCapacity);
        return result;
    };

    auto fixedDuration = run(60'000'000, 0, 0, false);
    EXPECT_EQ(2, fixedDuration.trustedNodeCount);
    EXPECT_EQ(0, fixedDuration.untrustedNodeCount);
    EXPECT_DOUBLE_EQ(1.0, fixedDuration.minimumRampProgress);
    EXPECT_DOUBLE_EQ(0.0, fixedDuration.minimumRampedTargetInflight);
    auto extraSamplesDoNotChangeRamp = run(60'000'000, 128, 0, false);
    EXPECT_EQ(2, extraSamplesDoNotChangeRamp.trustedNodeCount);
    EXPECT_EQ(0, extraSamplesDoNotChangeRamp.untrustedNodeCount);
    EXPECT_EQ(20, extraSamplesDoNotChangeRamp.trustedRequestCount);
    auto afterDuration = run(300'000'000, 0, 0, false);
    EXPECT_EQ(2, afterDuration.trustedNodeCount);
    EXPECT_EQ(0, afterDuration.untrustedNodeCount);
    auto timeLimited = run(30'000'000, 128, 10, true);
    EXPECT_DOUBLE_EQ(0.5, timeLimited.minimumRampProgress);
    auto sampleCountDoesNotFinishRamp = run(30'000'000, 4096, 10, true);
    EXPECT_DOUBLE_EQ(0.5, sampleCountDoesNotFinishRamp.minimumRampProgress);
}

