TEST_F(NaviSchedResourceTest, testFirstTrustedModelChangesAdmissionWithoutTrafficGrowth)
{
    // Counterfactual for the historical 0 -> 1 trusted-node transition. The
    // workload is synthetic and identical in every run, not a historical tape.
    const std::array<std::pair<int64_t, bool>, 4> states = {
        {{255, false}, {258, true}, {258, false}, {258, true}}};
    for (const auto &[modelRevision, firstTrusted] : states) {
        auto replay = makeCostSchedulerReplay(30, 7);
        for (auto &node : replay.nodes) {
            node.latencyModelRevision = 255;
            node.latencyModelTrusted = false;
            node.inflightRequests = 100;
            node.inflightPredictedLatencySumMs = 500000.0;
            node.queueTotalPredictedLatencyMs = 5000.0;
            node.queueDecayHeadRemainingMs = 5000.0;
        }
        replay.nodes[0].latencyModelRevision = modelRevision;
        replay.nodes[0].latencyModelTrusted = firstTrusted;
        NaviSchedScheduleContext context;
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
        ASSERT_EQ(30, context.requestCount());
        for (auto &node : context._scheduleNodes) {
            node._agentStartTimeUs = 1;
        }
        const auto analysis = CostSchedulerColdStartStrategy::analyze(context);
        EXPECT_EQ(firstTrusted ? 1 : 0, analysis.trustedNodeCount);
        EXPECT_EQ(firstTrusted ? 6 : 7, analysis.untrustedNodeCount);
        EXPECT_DOUBLE_EQ(100.0, analysis.targetInflight);
        EXPECT_EQ(0, analysis.untrustedCapacity);

        multi_call::RandomGenerator randomGenerator(101);
        (void)randomGenerator.get();
        CostSchedulerColdStartStrategy::Result result;
        ASSERT_TRUE(CostSchedulerColdStartStrategy::apply(
            context, randomGenerator, result));
        EXPECT_EQ(firstTrusted ? 30 : 0, result.trustedRequestCount);
        EXPECT_EQ(0, result.untrustedRequestCount);
        EXPECT_EQ(firstTrusted ? 0 : 30, result.rejectedRequestCount);
        EXPECT_EQ(firstTrusted, result.costScheduleRequired);
        if (firstTrusted) {
            ASSERT_EQ(1, context.nodeCount());
            ASSERT_EQ(30, context.requestCount());
            EXPECT_EQ("agent_0", context.getNode(0).getAgentId());
        } else {
            ASSERT_EQ(30, context._decisions.size());
            for (const auto &decision : context._decisions) {
                EXPECT_EQ("rate_limited", decision.reason);
            }
        }
    }
}

TEST_F(NaviSchedResourceTest, testCostSchedulerColdStartIsIndependentOfFrameworkAndPdMode)
{
    for (const auto &framework : {std::string("vllm"), std::string("rtp")}) {
        for (const auto pdSeparated : {false, true}) {
            for (const auto unifiedPrediction : {false, true}) {
                auto replay = makeCostSchedulerReplay(4, 2);
                for (auto &node : replay.nodes) {
                    node.latencyModelFingerprint = framework;
                    node.pdSeparated = pdSeparated;
                    node.unifiedLatencyPrediction = unifiedPrediction;
                    node.latencyModelTrusted = false;
                    node.inflightRequests = 0;
                }
                NaviSchedScheduleContext context;
                ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
                ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
                multi_call::RandomGenerator randomGenerator(23);
                (void)randomGenerator.get();
                CostSchedulerColdStartStrategy::Result result;
                ASSERT_TRUE(CostSchedulerColdStartStrategy::apply(
                    context, randomGenerator, result));
                EXPECT_EQ(0, result.trustedNodeCount);
                EXPECT_EQ(2, result.untrustedNodeCount);
                EXPECT_EQ(4, result.untrustedRequestCount);
                EXPECT_EQ(0, result.rejectedRequestCount);

                std::vector<NaviSchedDecision> decisions;
                ASSERT_TRUE(ScheduleReplayRunner::collectDecisions(context, decisions));
                std::map<std::string, size_t> selectedCount;
                for (const auto &decision : decisions) {
                    ++selectedCount[decision.target.address];
                }
                EXPECT_EQ(2, selectedCount["127.0.0.1:18000"]);
                EXPECT_EQ(2, selectedCount["127.0.0.1:18001"]);
            }
        }
    }
}

