TEST_F(NaviSchedResourceTest, testCostSchedulerMinimumLoopsIgnoreBudget)
{
    for (const bool replayEnabled : {false, true}) {
        for (size_t minimum : {1u, 2u, 3u}) {
            auto replay = makeCostSchedulerReplay(4, 2);
            auto context = std::make_shared<NaviSchedScheduleContext>();
            ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *context));
            ASSERT_TRUE(ScheduleReplayRunner::prepareContext(*context));
            if (replayEnabled) {
                ScheduleReplayRunner::setReplay(
                    *context, std::make_shared<NaviSchedScheduleReplay>());
            }
            CostSchedulerConfig config;
            config.minLoopCount = minimum;
            config.maxLoopCount = 5;
            config.optimizationTimeBudgetUs = 1;
            auto state = CostSchedulerGraphState::create(context, config, 2);
            ASSERT_TRUE(state);
            for (size_t iteration = 0; iteration < minimum; ++iteration) {
                for (size_t worker = 0; worker < 2; ++worker) {
                    ASSERT_TRUE(state->runRow(worker, iteration));
                }
                ASSERT_TRUE(state->finishRow(iteration));
                for (size_t worker = 0; worker < 2; ++worker) {
                    ASSERT_TRUE(state->runProjection(worker, iteration));
                }
                // Exhaust the budget deterministically without relying on sleeps.
                state->_optimizationBeginUs = autil::TimeUtility::monotonicTimeUs() - 1000000;
                ASSERT_TRUE(state->finishProjection(iteration));
                EXPECT_EQ(iteration + 1 < minimum, state->shouldContinue());
                EXPECT_EQ(iteration + 1, context->_costGradientIterationCount);
            }
            EXPECT_EQ(minimum, state->actualLoopCount());
            EXPECT_EQ("time_budget", state->stopReason());
        }
    }
    EXPECT_TRUE(CostSchedulerKernelInternal::shouldRunNextLoop(1, 10, 1, 100, 100, 2));
    EXPECT_TRUE(CostSchedulerKernelInternal::shouldRunNextLoop(2, 10, 1, 100, 100, 3));
    EXPECT_FALSE(CostSchedulerKernelInternal::shouldRunNextLoop(3, 10, 1, 100, 100, 3));
    EXPECT_FALSE(CostSchedulerKernelInternal::shouldRunNextLoop(2, 2, 1, 100, 100, 3));
}

TEST_F(NaviSchedResourceTest, testMinimumLoopCountDynamicPatch)
{
    SchedulerConfigR resource;
    for (int minimum : {3, 2, 1, 0, -1, 1001}) {
        const auto before = resource.get();
        SchedulerConfigR::Request request;
        request.update = true;
        request.configJson = "{\"min_loop_count\":" + std::to_string(minimum) + "}";
        request.responsePipe = std::make_shared<CaptureAsyncPipe>();
        SchedulerConfigResponseDataPtr response;
        bool waiting = false;
        ASSERT_TRUE(resource.processRequest(request, response, waiting));
        ASSERT_TRUE(response);
        EXPECT_EQ(minimum > 0 && minimum <= 1000, response->accepted);
        const auto after = resource.get();
        EXPECT_EQ(response->accepted ? minimum : before.config.cost.minLoopCount,
                  after.config.cost.minLoopCount);
        EXPECT_EQ(before.config.cost.maxLoopCount, after.config.cost.maxLoopCount);
        EXPECT_EQ(before.generation + (response->accepted ? 1 : 0), after.generation);
    }
}

TEST_F(NaviSchedResourceTest, testCostSchedulerSelectsDynamicLoopCount)
{
    EXPECT_FALSE(CostSchedulerKernelInternal::shouldRunNextLoop(1, 1, 100, 10, 10));
    EXPECT_FALSE(CostSchedulerKernelInternal::shouldRunNextLoop(1, 10, 1, 100, 100, 1));
    EXPECT_FALSE(CostSchedulerKernelInternal::shouldRunNextLoop(2, 10, 100, 90, 30));
    EXPECT_TRUE(CostSchedulerKernelInternal::shouldRunNextLoop(2, 10, 100, 40, 20));
    EXPECT_TRUE(CostSchedulerKernelInternal::shouldRunNextLoop(9, 10, -1, 1000, 100));
    EXPECT_FALSE(CostSchedulerKernelInternal::shouldRunNextLoop(2, 10, 0, 0, 0));
}

TEST_F(NaviSchedResourceTest, testReplayCollectionDoesNotConsumeOptimizationBudget)
{
    for (const bool collectReplay : {false, true}) {
        for (const bool realTimeout : {false, true}) {
            auto replay = makeCostSchedulerReplay(4, 2);
            auto context = std::make_shared<NaviSchedScheduleContext>();
            ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *context));
            ASSERT_TRUE(ScheduleReplayRunner::prepareContext(*context));
            if (collectReplay) {
                ScheduleReplayRunner::setReplay(
                    *context, std::make_shared<NaviSchedScheduleReplay>());
            }
            CostSchedulerConfig config;
            config.maxLoopCount = 10;
            config.optimizationTimeBudgetUs = 5'000'000;
            config.minLoopCount = 1;
            auto state = CostSchedulerGraphState::create(context, config, 1);
            ASSERT_TRUE(state);
            ASSERT_TRUE(state->runRow(0, 0));
            ASSERT_TRUE(state->finishRow(0));
            ASSERT_TRUE(state->runProjection(0, 0));
            // Model wall time without sleeping: collection adds eight seconds,
            // while actual work takes either two or six seconds.
            const int64_t workUs = realTimeout ? 6'000'000 : 2'000'000;
            const int64_t collectionUs = collectReplay ? 8'000'000 : 0;
            state->_optimizationBeginUs =
                autil::TimeUtility::monotonicTimeUs() - workUs - collectionUs;
            state->_lastLoopEndUs = state->_optimizationBeginUs;
            state->_lastLoopReplayCollectionUs = 0;
            context->_replayCollectionTimeUs = collectionUs;
            ASSERT_TRUE(state->finishProjection(0));
            EXPECT_EQ(!realTimeout, state->shouldContinue());
            EXPECT_EQ(realTimeout ? "time_budget" : "max_loop_count",
                      state->_stopReason);
            EXPECT_EQ(realTimeout ? 1u : 10u, state->_allowedLoopCount);
            EXPECT_EQ(1, context->_costOptimizerLoopCount);
            EXPECT_EQ(10, context->_costOptimizerMaxLoopCount);
            EXPECT_EQ(realTimeout, context->_costOptimizerTimeBudgetExhausted);
        }
    }
}

