TEST_F(NaviSchedResourceTest, testCostSchedulerReportsReturnedDiscreteLoss)
{
    constexpr size_t REQUEST_COUNT = 12;
    constexpr size_t NODE_COUNT = 32;
    constexpr double LAMBDA = 0.0;
    constexpr double LATENCY_WEIGHT_CONCAVITY = 0.0;
    auto replay = makeCostSchedulerReplay(REQUEST_COUNT, NODE_COUNT);
    auto context = std::make_shared<NaviSchedScheduleContext>();
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *context));
    std::vector<NaviSchedDecision> decisions;
    ASSERT_TRUE(ScheduleReplayRunner::runCostScheduler(
        replay, context, LAMBDA, 4.8520302639, 1.0, 0.0, 50, LATENCY_WEIGHT_CONCAVITY,
        decisions));
    ASSERT_EQ(REQUEST_COUNT, decisions.size());

    NaviSchedScheduleContext expectedContext;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, expectedContext));
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(expectedContext));
    std::vector<int64_t> tokenCounts(REQUEST_COUNT);
    std::vector<double> inverseTokenCounts(REQUEST_COUNT);
    auto totalTokenCount = CostSchedulerKernelInternal::fillRequestTokenCounts(
        expectedContext, tokenCounts.data(), inverseTokenCounts.data());
    CostSchedulerKernelInternal::ReplayInfo replayInfo;
    auto costs = CostSchedulerKernelInternal::prepare(
        expectedContext, tokenCounts.data(), LAMBDA, 1.0, 1.0, 0.0, 1, 0, replayInfo);
    ASSERT_TRUE(costs);

    std::vector<uint32_t> returnedNodeIndexes(REQUEST_COUNT);
    for (size_t requestIndex = 0; requestIndex < REQUEST_COUNT; ++requestIndex) {
        auto nodeIt =
            std::find_if(replay.nodes.begin(), replay.nodes.end(),
                         [&decision = decisions[requestIndex]](const auto &node) {
                             return node.serverAddress == decision.target.address;
                         });
        ASSERT_NE(replay.nodes.end(), nodeIt);
        returnedNodeIndexes[requestIndex] =
            static_cast<uint32_t>(std::distance(replay.nodes.begin(), nodeIt));
    }
    CostSchedulerKernelInternal::DiscreteForwardWorkspace workspace;
    auto expectedLoss = CostSchedulerKernelInternal::forwardDiscrete(
        expectedContext, costs.get(), returnedNodeIndexes.data(), tokenCounts.data(),
        inverseTokenCounts.data(), totalTokenCount, LAMBDA, LATENCY_WEIGHT_CONCAVITY,
        workspace);
    ASSERT_TRUE(std::isfinite(expectedLoss));
    for (const auto &decision : decisions) {
        EXPECT_NEAR(expectedLoss, decision.scheduleLoss, 1e-12);
    }
    ASSERT_TRUE(context->_discreteSearchLosses);
    EXPECT_GE(context->_discreteSearchLosses->first, expectedLoss);
    EXPECT_NEAR(expectedLoss, context->_discreteSearchLosses->second, 1e-12);
}

TEST_F(NaviSchedResourceTest, testCostSchedulerSpecializedGradientMatchesTape)
{
    constexpr size_t REQUEST_COUNT = 5;
    constexpr size_t NODE_COUNT = 7;
    constexpr size_t WEIGHT_COUNT = REQUEST_COUNT * NODE_COUNT;
    constexpr double LAMBDA = 0.37;
    constexpr double LATENCY_WEIGHT_CONCAVITY = 128.0;
    auto replay = makeCostSchedulerReplay(REQUEST_COUNT, NODE_COUNT);
    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));

    std::vector<int64_t> tokenCounts(REQUEST_COUNT);
    std::vector<double> inverseTokenCounts(REQUEST_COUNT);
    auto totalTokenCount = CostSchedulerKernelInternal::fillRequestTokenCounts(
        context, tokenCounts.data(), inverseTokenCounts.data());
    CostSchedulerKernelInternal::ReplayInfo replayInfo;
    auto costs = CostSchedulerKernelInternal::prepare(context, tokenCounts.data(), LAMBDA,
                                                      1.0, 1.0, 0.0, 1, 0, replayInfo);
    ASSERT_TRUE(costs);
    std::vector<double> weights(WEIGHT_COUNT);
    for (size_t index = 0; index < WEIGHT_COUNT; ++index) {
        weights[index] = 0.01 * (index % 13 + 1);
    }

    std::vector<CostSchedulerKernelInternal::NodeGradient> nodeGradients(NODE_COUNT);
    std::vector<double> actualGradients(WEIGHT_COUNT);
    auto actualValue = CostSchedulerKernelInternal::forwardNodeRange(
        context, costs.get(), weights.data(), tokenCounts.data(),
        inverseTokenCounts.data(), totalTokenCount, LAMBDA, LATENCY_WEIGHT_CONCAVITY, 0,
        NODE_COUNT, nodeGradients.data(), nullptr, nullptr);
    CostSchedulerKernelInternal::backwardNodeRange(
        context, costs.get(), weights.data(), tokenCounts.data(),
        inverseTokenCounts.data(), REQUEST_COUNT, 0, NODE_COUNT, nodeGradients.data(),
        actualGradients.data());

    AutoGradTape tape(WEIGHT_COUNT, NODE_COUNT * 9, 0, WEIGHT_COUNT * 3);
    AutoGradTape::Value firstSum;
    AutoGradTape::Value secondSum;
    for (size_t nodeIndex = 0; nodeIndex < NODE_COUNT; ++nodeIndex) {
        AutoGradTape::StaticParameterLinearSums<4> sums(&tape);
        auto rowOffset = nodeIndex * REQUEST_COUNT;
        for (size_t requestIndex = 0; requestIndex < REQUEST_COUNT; ++requestIndex) {
            sums.add(
                weights[rowOffset + requestIndex],
                {costs[rowOffset + requestIndex], 1.0, 1.0 / tokenCounts[requestIndex],
                 static_cast<double>(tokenCounts[requestIndex])});
        }
        auto values = sums.finish();
        const auto &node = context.getNode(nodeIndex);
        auto latency = NonLinearPrefillModelR::calculateLatencyFromRequestCostSum(
            node.getLatencyParameters(), values[0], values[3]);
        firstSum = firstSum + latency * values[1];
        secondSum = secondSum + (latency + node.getEstimatedQueueWaitMs()) *
                                    log1p(LATENCY_WEIGHT_CONCAVITY * values[2]) /
                                    std::log(LATENCY_WEIGHT_CONCAVITY);
    }
    auto expectedValue =
        firstSum * LAMBDA / totalTokenCount + secondSum * (1.0 - LAMBDA) / REQUEST_COUNT;
    std::vector<double> expectedGradients;
    ASSERT_TRUE(tape.backward(expectedValue, expectedGradients));
    EXPECT_NEAR(expectedValue.value(), actualValue, 1e-12);
    ASSERT_EQ(expectedGradients.size(), actualGradients.size());
    for (size_t index = 0; index < WEIGHT_COUNT; ++index) {
        EXPECT_NEAR(expectedGradients[index], actualGradients[index], 1e-12);
    }
}

TEST_F(NaviSchedResourceTest,
       testCapacitySplitCostSchedulerDiscreteMatchesBatchPrediction)
{
    constexpr size_t REQUEST_COUNT = 4;
    constexpr double LAMBDA = 1.0;
    constexpr double LATENCY_WEIGHT_CONCAVITY = 0.0;
    struct CapacityCase {
        int32_t maxRunningRequestCount;
        int32_t workloadOccupiedSlotCount;
        int32_t reservedOccupiedSlotCount;
        int64_t workloadElapsedUs;
    };
    const std::vector<CapacityCase> capacityCases = {
        {4, 0, 0, 0},
        {2, 2, 2, 0},
        {3, 2, 0, 0},
        {3, 2, 0, 1'000'000'000},
    };
    for (const auto &capacityCase : capacityCases) {
        auto context = makeCapacitySplitCostSchedulerContext(
            REQUEST_COUNT, capacityCase.maxRunningRequestCount,
            capacityCase.workloadOccupiedSlotCount,
            capacityCase.reservedOccupiedSlotCount, capacityCase.workloadElapsedUs);
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
        std::vector<int64_t> tokenCounts(REQUEST_COUNT);
        std::vector<double> inverseTokenCounts(REQUEST_COUNT);
        const auto totalTokenCount = CostSchedulerKernelInternal::fillRequestTokenCounts(
            context, tokenCounts.data(), inverseTokenCounts.data());
        CostSchedulerKernelInternal::ReplayInfo replayInfo;
        auto costs = CostSchedulerKernelInternal::prepare(
            context, tokenCounts.data(), LAMBDA, 1.0, 1.0, 0.0, 1, 0, replayInfo);
        ASSERT_TRUE(costs);

        const std::vector<uint32_t> nodeIndexes(REQUEST_COUNT, 0);
        CostSchedulerKernelInternal::DiscreteForwardWorkspace workspace;
        const auto discreteValue = CostSchedulerKernelInternal::forwardDiscrete(
            context, costs.get(), nodeIndexes.data(), tokenCounts.data(),
            inverseTokenCounts.data(), totalTokenCount, LAMBDA, LATENCY_WEIGHT_CONCAVITY,
            workspace);
        const std::vector<double> oneHotWeights(REQUEST_COUNT, 1.0);
        const auto oneHotValue = CostSchedulerKernelInternal::forwardNodeRange(
            context, costs.get(), oneHotWeights.data(), tokenCounts.data(),
            inverseTokenCounts.data(), totalTokenCount, LAMBDA, LATENCY_WEIGHT_CONCAVITY,
            0, 1, nullptr, nullptr, nullptr);
        std::vector<size_t> requestIndexes(REQUEST_COUNT);
        std::iota(requestIndexes.begin(), requestIndexes.end(), 0);
        const auto batchLatency =
            context.estimateBatchExecutionLatencyMs(0, requestIndexes);
        EXPECT_NEAR(oneHotValue, discreteValue, 1e-12);
        const auto &node = context.getNode(0);
        const auto existingFullLatency = NonLinearPrefillModelR::predict(
            node.getWorkloadFeatures(), node.getLatencyParameters());
        NaviSchedLatencyFeatures existingFloor;
        ASSERT_TRUE(node.getUnifiedDecayFloorFeatures(existingFloor));
        const auto existingFloorLatency =
            NonLinearPrefillModelR::predict(existingFloor, node.getLatencyParameters());
        const auto expectedFirstTerm = batchLatency - node.getExistingUnifiedLatencyMs();
        EXPECT_NEAR(node.decayUnifiedLatency(existingFullLatency, existingFloorLatency),
                    node.getExistingUnifiedLatencyMs(), 1e-9);
        EXPECT_NEAR(expectedFirstTerm / totalTokenCount, discreteValue, 1e-7);
    }
}

