TEST_F(NaviSchedResourceTest,
       testCapacitySplitCostSchedulerGradientMatchesFiniteDifference)
{
    constexpr size_t REQUEST_COUNT = 4;
    constexpr double LAMBDA = 0.37;
    constexpr double LATENCY_WEIGHT_CONCAVITY = 128.0;
    constexpr double DELTA = 1e-6;
    const std::vector<double> weights = {0.4, 0.7, 0.6, 0.5};

    auto runCase = [&](int64_t workloadElapsedUs, double expectedRunningCapacity) {
        auto context = makeCapacitySplitCostSchedulerContext(REQUEST_COUNT, 2, 1, 0,
                                                             workloadElapsedUs);
        auto latencyModel = std::make_shared<NaviSchedLatencyModel>(
            *context._scheduleNodes[0]._latencyModel);
        auto residualParameters = LatencyResidualModel::makeInitialParameters();
        int64_t residualLastUpdateTimeUs = 0;
        for (size_t round = 0; round < 20; ++round) {
            for (int32_t bucket = LatencyResidualModel::MIN_BUCKET;
                 bucket < LatencyResidualModel::MAX_BUCKET; ++bucket) {
                const auto basePrediction = std::exp2(bucket + 0.37);
                const auto actualLatency =
                    (round + bucket) % 2 == 0 ? 0.0 : basePrediction * 10.0;
                ASSERT_TRUE(LatencyResidualModel::update(
                    basePrediction, actualLatency, residualParameters,
                    residualLastUpdateTimeUs,
                    static_cast<int64_t>(round * 100 + bucket)));
            }
        }
        ASSERT_TRUE(LatencyResidualModel::validateParameters(residualParameters));
        ASSERT_TRUE(std::any_of(residualParameters.begin(), residualParameters.end(),
                                [](double value) { return value != 0.0; }));
        latencyModel->residualParameters = std::move(residualParameters);
        latencyModel->residualLastUpdateTimeUs =
            context.getScheduleTimeUs() - 210 * 1000 * 1000;
        context._scheduleNodes[0]._latencyModel = std::move(latencyModel);
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
        std::vector<int64_t> tokenCounts(REQUEST_COUNT);
        std::vector<double> inverseTokenCounts(REQUEST_COUNT);
        const auto totalTokenCount = CostSchedulerKernelInternal::fillRequestTokenCounts(
            context, tokenCounts.data(), inverseTokenCounts.data());
        CostSchedulerKernelInternal::ReplayInfo replayInfo;
        auto costs = CostSchedulerKernelInternal::prepare(
            context, tokenCounts.data(), LAMBDA, 1.0, 1.0, 0.0, 1, 0, replayInfo);
        ASSERT_TRUE(costs);

        CostSchedulerKernelInternal::NodeGradient nodeGradient;
        std::vector<double> gradients(REQUEST_COUNT);
        const auto value = CostSchedulerKernelInternal::forwardNodeRange(
            context, costs.get(), weights.data(), tokenCounts.data(),
            inverseTokenCounts.data(), totalTokenCount, LAMBDA, LATENCY_WEIGHT_CONCAVITY,
            0, 1, &nodeGradient, nullptr, nullptr);
        ASSERT_TRUE(std::isfinite(value));
        EXPECT_DOUBLE_EQ(expectedRunningCapacity, nodeGradient.runningCapacity);
        CostSchedulerKernelInternal::backwardNodeRange(
            context, costs.get(), weights.data(), tokenCounts.data(),
            inverseTokenCounts.data(), REQUEST_COUNT, 0, 1, &nodeGradient,
            gradients.data());

        for (size_t requestIndex = 0; requestIndex < REQUEST_COUNT; ++requestIndex) {
            auto lowerWeights = weights;
            auto upperWeights = weights;
            lowerWeights[requestIndex] -= DELTA;
            upperWeights[requestIndex] += DELTA;
            const auto lower = CostSchedulerKernelInternal::forwardNodeRange(
                context, costs.get(), lowerWeights.data(), tokenCounts.data(),
                inverseTokenCounts.data(), totalTokenCount, LAMBDA,
                LATENCY_WEIGHT_CONCAVITY, 0, 1, nullptr, nullptr, nullptr);
            const auto upper = CostSchedulerKernelInternal::forwardNodeRange(
                context, costs.get(), upperWeights.data(), tokenCounts.data(),
                inverseTokenCounts.data(), totalTokenCount, LAMBDA,
                LATENCY_WEIGHT_CONCAVITY, 0, 1, nullptr, nullptr, nullptr);
            const auto finiteDifference = (upper - lower) / (2.0 * DELTA);
            EXPECT_NEAR(finiteDifference, gradients[requestIndex],
                        std::max(1e-6, std::abs(finiteDifference) * 1e-6));
        }
    };

    runCase(0, 1.0);
    runCase(1'000'000'000, 2.0);
}

