TEST_F(NaviSchedResourceTest, testFlexLBBaselineDoesNotInventShadowLoad)
{
    auto replay = makeCostSchedulerReplay(6, 2);
    for (size_t requestIndex = 0; requestIndex < replay.requests.size(); ++requestIndex) {
        replay.requests[requestIndex].request.promptTokenCount = 1000;
        replay.requests[requestIndex].request.blockSize = 16;
        replay.nodeMatches[requestIndex][0].matchedBlockCount = 1;
        replay.nodeMatches[requestIndex][1].matchedBlockCount = 0;
    }
    for (auto &node : replay.nodes) {
        node.queueTotalPredictedLatencyMs = 0.0;
    }
    FlexLBBaselineSchedulerKernel scheduler;
    FlexLBBaselineSchedulerKernelTestAccess::setScoreTieRandomEnabled(scheduler, false);
    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    auto replayOutput = std::make_shared<NaviSchedScheduleReplay>(replay);
    ScheduleReplayRunner::setReplay(context, replayOutput);
    std::vector<NaviSchedDecision> decisions;
    ASSERT_TRUE(ScheduleReplayRunner::runContext(context, scheduler, decisions));
    ASSERT_EQ(replay.requests.size(), decisions.size());
    for (const auto &decision : decisions) {
        EXPECT_EQ(replay.nodes[0].serverAddress, decision.target.address);
        EXPECT_EQ("flexlb_baseline_selected", decision.reason);
    }
    EXPECT_FALSE(autil::legacy::AnyCast<bool>(
        replayOutput->schedulerInfo.at("use_reported_load")));
    EXPECT_FALSE(autil::legacy::AnyCast<bool>(
        replayOutput->schedulerInfo.at("score_tie_random_enabled")));
    EXPECT_DOUBLE_EQ(0.1, autil::legacy::AnyCast<double>(
                              replayOutput->schedulerInfo.at("score_tie_threshold_pct")));
    EXPECT_EQ("flexlb_formula", autil::legacy::AnyCast<std::string>(
                                    replayOutput->schedulerInfo.at("predictor_type")));
}

