TEST_F(NaviSchedResourceTest, testCostPreparationTimingPreservesCostsAndResetsRanges)
{
    for (const bool capacitySplit : {false, true}) {
        SCOPED_TRACE(capacitySplit);
        auto replay = makeCostSchedulerReplay(5, 3);
        if (capacitySplit) {
            configureCapacitySplitCostSchedulerReplay(replay, 3, 1, 1, 0);
        }
        NaviSchedScheduleContext context;
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));
        std::vector<int64_t> tokens(context.requestCount());
        CostSchedulerKernelInternal::fillRequestTokenCounts(context, tokens.data(), nullptr);
        const auto matrixSize = context.requestCount() * context.nodeCount();
        std::vector<float> expected(matrixSize * 2, -123.0f);
        std::vector<float> timed(matrixSize * 2, -123.0f);
        ASSERT_TRUE(CostSchedulerKernelInternal::fillCostsForNodeRange(
            context, tokens.data(), 0, 3, expected.data()));
        CostSchedulerKernelInternal::PreparationTiming timing;
        timing.matchUs = 123456;
        timing.costEvaluationUs = 654321;
        timing.completedNodes = 7;
        ASSERT_TRUE(CostSchedulerKernelInternal::fillCostsForNodeRange(
            context, tokens.data(), 1, 3, timed.data(), &timing));
        EXPECT_EQ(2u, timing.completedNodes);
        EXPECT_GE(timing.matchUs, 0);
        EXPECT_GE(timing.costEvaluationUs, 0);
        for (size_t index = 0; index < matrixSize * 2; ++index) {
            const auto nodeIndex = (index % matrixSize) / context.requestCount();
            EXPECT_FLOAT_EQ(nodeIndex == 0 ? -123.0f : expected[index], timed[index]);
        }
        ASSERT_TRUE(CostSchedulerKernelInternal::fillCostsForNodeRange(
            context, tokens.data(), 0, 1, timed.data(), &timing));
        EXPECT_EQ(1u, timing.completedNodes);
        EXPECT_EQ(expected, timed);
        timing.matchUs = 123456;
        timing.costEvaluationUs = 654321;
        timing.completedNodes = 7;
        EXPECT_FALSE(CostSchedulerKernelInternal::fillCostsForNodeRange(
            context, nullptr, 0, 3, timed.data(), &timing));
        EXPECT_EQ(0, timing.matchUs);
        EXPECT_EQ(0, timing.costEvaluationUs);
        EXPECT_EQ(0u, timing.completedNodes);
        EXPECT_EQ(expected, timed);
        ASSERT_TRUE(CostSchedulerKernelInternal::fillCostsForNodeRange(
            context, tokens.data(), 3, 3, timed.data(), &timing));
        EXPECT_EQ(0, timing.matchUs);
        EXPECT_EQ(0, timing.costEvaluationUs);
        EXPECT_EQ(0u, timing.completedNodes);
        EXPECT_EQ(expected, timed);
    }
}

TEST_F(NaviSchedResourceTest, testCostSchedulerRetainsInitialAssignmentWithinOneLoop)
{
    constexpr size_t REQUEST_COUNT = 32;
    constexpr size_t NODE_COUNT = 4;
    for (size_t workers : {1u, 4u}) {
        auto replay = makeCostSchedulerReplay(REQUEST_COUNT, NODE_COUNT);
        configureCapacitySplitCostSchedulerReplay(replay, 2, 0, 0, 0);
        auto context = std::make_shared<NaviSchedScheduleContext>();
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *context));
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(*context));
        CostSchedulerConfig config;
        config.maxLoopCount = 1;
        config.optimizationTimeBudgetUs = -1;
        config.alpha = 512;
        auto state = CostSchedulerGraphState::create(context, config, workers);
        ASSERT_TRUE(state);
        std::vector<double> weights(REQUEST_COUNT * NODE_COUNT, 0.0);
        std::vector<uint32_t> initialNodes(REQUEST_COUNT);
        for (size_t request = 0; request < REQUEST_COUNT; ++request) {
            initialNodes[request] = request % NODE_COUNT;
            weights[initialNodes[request] * REQUEST_COUNT + request] = 1.0;
        }
        ASSERT_TRUE(state->resetWeights(weights.data(), weights.size()));
        for (size_t worker = 0; worker < workers; ++worker) {
            ASSERT_TRUE(state->runRow(worker, 0));
        }
        CostSchedulerKernelInternal::DiscreteForwardWorkspace workspace;
        const auto initialLoss = CostSchedulerKernelInternal::forwardDiscrete(
            *context, state->_costs.get(), initialNodes.data(),
            state->_requestTokenCounts.get(), state->_inverseRequestTokenCounts.get(),
            state->_tokenNormalizationDenominator, config.lambda,
            config.latencyWeightConcavity, workspace);
        ASSERT_TRUE(std::isfinite(initialLoss));
        ASSERT_TRUE(state->finishRow(0));
        for (size_t worker = 0; worker < workers; ++worker) {
            ASSERT_TRUE(state->runProjection(worker, 0));
        }
        ASSERT_TRUE(state->finishProjection(0));
        for (size_t worker = 0; worker < workers; ++worker) {
            ASSERT_TRUE(state->runFinalRow(worker));
        }
        ASSERT_TRUE(state->finalize(0));
        EXPECT_LE(state->forwardValue(), initialLoss);
        EXPECT_FALSE(state->_replayInfo);
    }
}

TEST_F(NaviSchedResourceTest, testCostSchedulerParallelStagesMatchSerial)
{
    constexpr size_t REQUEST_COUNT = 5;
    constexpr size_t NODE_COUNT = 7;
    constexpr size_t LOOP_COUNT = 8;
    for (const size_t PARALLELISM : {4u, 64u}) {
        auto replay = makeCostSchedulerReplay(REQUEST_COUNT, NODE_COUNT);
        configureCapacitySplitCostSchedulerReplay(replay, 3, 1, 1, 0);
        auto serialContext = std::make_shared<NaviSchedScheduleContext>();
        auto parallelContext = std::make_shared<NaviSchedScheduleContext>();
        auto regularContext = std::make_shared<NaviSchedScheduleContext>();
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *serialContext));
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *parallelContext));
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *regularContext));
        auto serialReplay = std::make_shared<NaviSchedScheduleReplay>(replay);
        auto parallelReplay = std::make_shared<NaviSchedScheduleReplay>(replay);
        ScheduleReplayRunner::setReplay(*serialContext, serialReplay);
        ScheduleReplayRunner::setReplay(*parallelContext, parallelReplay);
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(*serialContext));
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(*parallelContext));
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(*regularContext));

        CostSchedulerConfig config;
        config.maxLoopCount = LOOP_COUNT;
        config.initialWeightSeed = 20260823;
        auto serial = CostSchedulerGraphState::create(serialContext, config, 1);
        auto parallel = CostSchedulerGraphState::create(parallelContext, config, PARALLELISM);
        auto regular = CostSchedulerGraphState::create(regularContext, config, 1);
        ASSERT_TRUE(serial);
        ASSERT_TRUE(parallel);
        ASSERT_TRUE(regular);
        std::vector<double> initialWeights(serial->weights(),
                                           serial->weights() + serial->weightCount());
        ASSERT_TRUE(parallel->resetWeights(initialWeights.data(), initialWeights.size()));
        ASSERT_TRUE(regular->resetWeights(initialWeights.data(), initialWeights.size()));

        for (size_t iteration = 0; iteration < LOOP_COUNT; ++iteration) {
            ASSERT_TRUE(serial->runRow(0, iteration));
            ASSERT_TRUE(serial->finishRow(iteration));
            ASSERT_TRUE(regular->runRow(0, iteration));
            ASSERT_TRUE(regular->finishRow(iteration));
            for (size_t workerIndex = 0; workerIndex < PARALLELISM; ++workerIndex) {
                ASSERT_TRUE(parallel->runRow(workerIndex, iteration));
            }
            ASSERT_TRUE(parallel->finishRow(iteration));
            EXPECT_NEAR(serial->forwardValue(), parallel->forwardValue(), 1e-12);
            EXPECT_NEAR(serial->forwardValue(), regular->forwardValue(), 1e-12);
            for (size_t index = 0; index < serial->weightCount(); ++index) {
                EXPECT_NEAR(serial->gradients()[index], parallel->gradients()[index], 1e-12);
                EXPECT_NEAR(serial->weights()[index], parallel->weights()[index], 1e-12);
            }

            ASSERT_TRUE(serial->runProjection(0, iteration));
            ASSERT_TRUE(serial->finishProjection(iteration));
            ASSERT_TRUE(regular->runProjection(0, iteration));
            ASSERT_TRUE(regular->finishProjection(iteration));
            for (size_t workerIndex = 0; workerIndex < PARALLELISM; ++workerIndex) {
                ASSERT_TRUE(parallel->runProjection(workerIndex, iteration));
            }
            ASSERT_TRUE(parallel->finishProjection(iteration));
            for (size_t index = 0; index < serial->weightCount(); ++index) {
                EXPECT_NEAR(serial->weights()[index], parallel->weights()[index], 1e-12);
                EXPECT_NEAR(serial->weights()[index], regular->weights()[index], 1e-12);
            }
        }
        ASSERT_TRUE(serial->runFinalRow(0));
        ASSERT_TRUE(regular->runFinalRow(0));
        for (size_t workerIndex = 0; workerIndex < PARALLELISM; ++workerIndex) {
            ASSERT_TRUE(parallel->runFinalRow(workerIndex));
        }
        ASSERT_TRUE(serial->finalize());
        ASSERT_TRUE(parallel->finalize());
        ASSERT_TRUE(regular->finalize());
        EXPECT_NEAR(serial->forwardValue(), parallel->forwardValue(), 1e-12);
        EXPECT_NEAR(serial->forwardValue(), regular->forwardValue(), 1e-12);

        std::vector<NaviSchedDecision> serialDecisions;
        std::vector<NaviSchedDecision> parallelDecisions;
        std::vector<NaviSchedDecision> regularDecisions;
        ASSERT_TRUE(ScheduleReplayRunner::collectDecisions(*serialContext, serialDecisions));
        ASSERT_TRUE(
            ScheduleReplayRunner::collectDecisions(*parallelContext, parallelDecisions));
        ASSERT_TRUE(
            ScheduleReplayRunner::collectDecisions(*regularContext, regularDecisions));
        EXPECT_TRUE(ScheduleReplayRunner::decisionsEqual(serialDecisions, parallelDecisions));
        EXPECT_TRUE(ScheduleReplayRunner::decisionsEqual(serialDecisions, regularDecisions));

        parallelReplay->decisions = parallelDecisions;
        auto replayContext = std::make_shared<NaviSchedScheduleContext>();
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(*parallelReplay, *replayContext));
        auto replayOutput = std::make_shared<NaviSchedScheduleReplay>(*parallelReplay);
        ScheduleReplayRunner::setReplay(*replayContext, replayOutput);
        std::vector<NaviSchedDecision> replayDecisions;
        ASSERT_TRUE(ScheduleReplayRunner::runCostScheduler(
            *parallelReplay, replayContext, 1.0, 0.01, 1.0, 0.0, 1, 128.0, replayDecisions));
        EXPECT_TRUE(ScheduleReplayRunner::decisionsEqual(parallelDecisions, replayDecisions));
        CostSchedulerKernelInternal::ReplayInfo replayedInfo;
        autil::legacy::FromJson(replayedInfo,
                                autil::legacy::Any(replayOutput->schedulerInfo));
        EXPECT_EQ(PARALLELISM, replayedInfo.parallelism);
        ASSERT_EQ(1, replayedInfo.optimizationRuns.size());
        CostSchedulerKernelInternal::ReplayInfo recordedInfo;
        autil::legacy::FromJson(recordedInfo,
                                autil::legacy::Any(parallelReplay->schedulerInfo));
        ASSERT_EQ(1, recordedInfo.optimizationRuns.size());
        ASSERT_EQ(recordedInfo.schedInfos.size(), replayedInfo.schedInfos.size());
        bool foundDistinctWaitingCost = false;
        for (size_t nodeIndex = 0; nodeIndex < recordedInfo.schedInfos.size(); ++nodeIndex) {
            ASSERT_EQ(recordedInfo.schedInfos[nodeIndex].size(),
                      replayedInfo.schedInfos[nodeIndex].size());
            for (size_t requestIndex = 0;
                 requestIndex < recordedInfo.schedInfos[nodeIndex].size(); ++requestIndex) {
                const auto &recorded = recordedInfo.schedInfos[nodeIndex][requestIndex];
                const auto &replayed = replayedInfo.schedInfos[nodeIndex][requestIndex];
                EXPECT_FLOAT_EQ(recorded.schedInfo.waitingCost,
                                replayed.schedInfo.waitingCost);
                foundDistinctWaitingCost =
                    foundDistinctWaitingCost ||
                    recorded.schedInfo.cost != recorded.schedInfo.waitingCost;
            }
        }
        EXPECT_TRUE(foundDistinctWaitingCost);
        EXPECT_EQ(recordedInfo.optimizationRuns[0].initialWeights,
                  replayedInfo.optimizationRuns[0].initialWeights);
        EXPECT_NEAR(recordedInfo.optimizationRuns[0].finalForwardValue,
                    replayedInfo.optimizationRuns[0].finalForwardValue, 1e-12);
        EXPECT_NEAR(recordedInfo.optimizationRuns[0].bestForwardValue,
                    replayedInfo.optimizationRuns[0].bestForwardValue, 1e-12);

        auto overrideContext = std::make_shared<NaviSchedScheduleContext>();
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(*parallelReplay, *overrideContext));
        auto overrideOutput = std::make_shared<NaviSchedScheduleReplay>(*parallelReplay);
        ScheduleReplayRunner::setReplay(*overrideContext, overrideOutput);
        std::vector<NaviSchedDecision> overrideDecisions;
        ASSERT_TRUE(ScheduleReplayRunner::runCostScheduler(*parallelReplay, overrideContext,
                                                           1.0, 0.01, 1.0, 0.0, 1, 128.0,
                                                           overrideDecisions, 0.5, 0.0));
        CostSchedulerKernelInternal::ReplayInfo overrideInfo;
        autil::legacy::FromJson(overrideInfo,
                                autil::legacy::Any(overrideOutput->schedulerInfo));
        EXPECT_DOUBLE_EQ(0.5, overrideInfo.latencyTokenNormalizationPower);
        EXPECT_DOUBLE_EQ(0.0, overrideInfo.latencyWeightConcavity);
        EXPECT_EQ(20260823, overrideInfo.initialWeightSeed);
        EXPECT_DOUBLE_EQ(1.0 / 1000.0, overrideInfo.selectionJitterRatio);
        EXPECT_EQ(recordedInfo.optimizationRuns[0].bestNodeIndexes,
                  replayedInfo.optimizationRuns[0].bestNodeIndexes);
    }
}

TEST_F(NaviSchedResourceTest, testCostSchedulerPreparesNodeMajorState)
{
    NaviSchedScheduleReplay replay;
    replay.scheduleTimeUs = 1'000'000'000;
    replay.bizName = "model_biz";

    NaviSchedScheduleItem firstRequest;
    firstRequest.request.requestId = 1;
    firstRequest.request.bizName = replay.bizName;
    firstRequest.request.promptTokenCount = 600;
    firstRequest.request.blockHashes = makeBlockHashes({11, 12});
    firstRequest.request.timeoutMs = 1000;
    firstRequest.remainingTimeoutMs = 1000;
    replay.requests.emplace_back(std::move(firstRequest));

    NaviSchedScheduleItem secondRequest;
    secondRequest.request.requestId = 2;
    secondRequest.request.bizName = replay.bizName;
    secondRequest.request.promptTokenCount = 700;
    secondRequest.request.blockHashes = makeBlockHashes({21, 22});
    secondRequest.request.timeoutMs = 1000;
    secondRequest.remainingTimeoutMs = 1000;
    replay.requests.emplace_back(std::move(secondRequest));

    const auto parameters = makeStandardLatencyParameters();
    NaviSchedNodeInfo firstNode;
    firstNode.agentId = "agent_0";
    firstNode.bizName = replay.bizName;
    firstNode.serverAddress = "127.0.0.1:18000";
    firstNode.online = true;
    firstNode.queueTotalPredictedLatencyMs = 12.0;
    firstNode.queueReportReceiveTimeUs = replay.scheduleTimeUs;
    firstNode.latencyFormula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    firstNode.latencyBinaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    firstNode.latencyModelRevision = 1;
    firstNode.latencyParameters = parameters;
    firstNode.latencyModelTrusted = true;
    replay.nodes.emplace_back(std::move(firstNode));

    NaviSchedNodeInfo secondNode;
    secondNode.agentId = "agent_1";
    secondNode.bizName = replay.bizName;
    secondNode.serverAddress = "127.0.0.1:18001";
    secondNode.online = true;
    secondNode.queueTotalPredictedLatencyMs = 34.0;
    secondNode.queueReportReceiveTimeUs = replay.scheduleTimeUs;
    secondNode.latencyFormula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    secondNode.latencyBinaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    secondNode.latencyModelRevision = 1;
    secondNode.latencyParameters = parameters;
    secondNode.latencyModelTrusted = true;
    replay.nodes.emplace_back(std::move(secondNode));

    replay.nodeMatches = {
        {{1}, {2}},
        {{0}, {1}},
    };
    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    CostSchedulerPreparedState state;
    ASSERT_TRUE(ScheduleReplayRunner::prepareCostScheduler(context, state));
    ASSERT_EQ(2, state.requestCount);
    ASSERT_EQ(2, state.nodeCount);
    ASSERT_EQ(std::vector<int64_t>({600, 700}), state.requestTokenCounts);
    ASSERT_EQ(1300, state.totalTokenCount);
    ASSERT_EQ(4, state.costs.size());
    ASSERT_EQ(4, state.queueWaits.size());
    ASSERT_EQ(4, state.weights.size());

    const int64_t cacheHitTokens[] = {256, 0, 512, 256};
    const double queueWaits[] = {12.0, 12.0, 34.0, 34.0};
    for (size_t nodeIndex = 0; nodeIndex < state.nodeCount; ++nodeIndex) {
        for (size_t requestIndex = 0; requestIndex < state.requestCount; ++requestIndex) {
            auto index = requestIndex + nodeIndex * state.requestCount;
            const auto &request = replay.requests[requestIndex].request;
            auto expectedCost = NonLinearPrefillModelR::calculateRequestLinearCost(
                parameters, request.promptTokenCount, cacheHitTokens[index]);
            EXPECT_FLOAT_EQ(static_cast<float>(expectedCost),
                            static_cast<float>(state.costs[index]));
            EXPECT_DOUBLE_EQ(queueWaits[index], state.queueWaits[index]);
        }
    }

    auto collectedReplay = std::make_shared<NaviSchedScheduleReplay>(replay);
    ScheduleReplayRunner::setReplay(context, collectedReplay);
    CostSchedulerKernel scheduler;
    std::vector<NaviSchedDecision> decisions;
    ASSERT_TRUE(ScheduleReplayRunner::runContext(context, scheduler, decisions));
    ASSERT_FALSE(collectedReplay->schedulerInfo.empty());
    ASSERT_EQ(2, decisions.size());
    EXPECT_EQ("cost_selected", decisions[0].reason);
    EXPECT_EQ("cost_selected", decisions[1].reason);

    CostSchedulerKernelInternal::ReplayInfo optimizerReplay;
    autil::legacy::FromJson(optimizerReplay,
                            autil::legacy::Any(collectedReplay->schedulerInfo));
    EXPECT_DOUBLE_EQ(0.5, optimizerReplay.lambda);
    EXPECT_DOUBLE_EQ(CostSchedulerConfig().alpha, optimizerReplay.alpha);
    EXPECT_DOUBLE_EQ(CostSchedulerConfig().alphaDecay, optimizerReplay.alphaDecay);
    EXPECT_DOUBLE_EQ(CostSchedulerConfig().minAlpha, optimizerReplay.minAlpha);
    EXPECT_EQ(CostSchedulerConfig().maxLoopCount, optimizerReplay.maxLoopCount);
    ASSERT_EQ(1, optimizerReplay.optimizationRuns.size());
    const auto &optimizationRun = optimizerReplay.optimizationRuns[0];
    ASSERT_EQ(4, optimizationRun.initialWeights.size());
    ASSERT_EQ(static_cast<size_t>(CostSchedulerConfig().minLoopCount), optimizationRun.steps.size());
    EXPECT_EQ(optimizationRun.steps.size(), optimizationRun.actualLoopCount);
    EXPECT_EQ("time_budget", optimizationRun.stopReason);
    ASSERT_EQ(4, optimizationRun.finalWeights.size());
    EXPECT_TRUE(std::isfinite(optimizationRun.finalForwardValue));
    EXPECT_TRUE(std::isfinite(optimizationRun.bestForwardValue));
    ASSERT_EQ(2, optimizationRun.bestNodeIndexes.size());
    EXPECT_GT(optimizationRun.elapsedUs, 0);
    for (size_t iteration = 0; iteration < optimizationRun.steps.size(); ++iteration) {
        const auto &step = optimizationRun.steps[iteration];
        EXPECT_EQ(iteration, step.iteration);
        EXPECT_DOUBLE_EQ(CostSchedulerConfig().alpha, step.alpha);
        EXPECT_TRUE(std::isfinite(step.forwardValue));
        EXPECT_GE(step.elapsedUs, 0);
        EXPECT_GE(step.forwardUs, 0);
        EXPECT_GE(step.backwardUs, 0);
        EXPECT_GE(step.updateUs, 0);
        EXPECT_GE(step.projectionUs, 0);
        EXPECT_GE(step.bindUs, 0);
        if (iteration > 0) {
            EXPECT_LE(step.forwardValue,
                      optimizationRun.steps[iteration - 1].forwardValue + 1e-12);
        }
        ASSERT_EQ(4, step.gradients.size());
        ASSERT_EQ(4, step.weightsBeforeUpdate.size());
        ASSERT_EQ(4, step.weightsBeforeProjection.size());
        ASSERT_EQ(4, step.weightsAfterProjection.size());
        const auto &expectedBeforeUpdate =
            0 == iteration ? optimizationRun.initialWeights
                           : optimizationRun.steps[iteration - 1].weightsAfterProjection;
        EXPECT_EQ(expectedBeforeUpdate, step.weightsBeforeUpdate);
        for (size_t requestIndex = 0; requestIndex < 2; ++requestIndex) {
            double weightSum = 0.0;
            for (size_t nodeIndex = 0; nodeIndex < 2; ++nodeIndex) {
                auto weight = step.weightsAfterProjection[requestIndex + nodeIndex * 2];
                EXPECT_GE(weight, 0.0);
                weightSum += weight;
            }
            EXPECT_NEAR(1.0, weightSum, 1e-12);
        }
    }
    EXPECT_EQ(optimizationRun.steps.back().weightsAfterProjection,
              optimizationRun.finalWeights);
    auto expectedBestValue = optimizationRun.finalForwardValue;
    for (size_t iteration = 1; iteration < optimizationRun.steps.size(); ++iteration) {
        expectedBestValue =
            std::min(expectedBestValue, optimizationRun.steps[iteration].forwardValue);
    }
    EXPECT_NEAR(expectedBestValue, optimizationRun.bestForwardValue, 1e-12);
    for (size_t requestIndex = 0; requestIndex < decisions.size(); ++requestIndex) {
        auto nodeIndex = optimizationRun.bestNodeIndexes[requestIndex];
        ASSERT_LT(nodeIndex, replay.nodes.size());
        EXPECT_EQ(replay.nodes[nodeIndex].serverAddress,
                  decisions[requestIndex].target.address);
        EXPECT_NEAR(optimizationRun.bestForwardValue,
                    decisions[requestIndex].scheduleLoss, 1e-12);
    }

    collectedReplay->decisions = decisions;
    ASSERT_FALSE(collectedReplay->decisions.empty());
    auto recordedPrediction = std::make_shared<NaviSchedLatencyPrediction>();
    ASSERT_TRUE(recordedPrediction->features.appendBatchCount(2));
    recordedPrediction->features.appendRequest(128, 384);
    ASSERT_TRUE(recordedPrediction->floorFeatures.appendBatchCount(1));
    recordedPrediction->floorFeatures.appendRequest(64, 448);
    recordedPrediction->fixedLatencyMs = -7.25;
    recordedPrediction->hasFloor = true;
    recordedPrediction->recomputable = true;
    collectedReplay->decisions.front().latencyPrediction = recordedPrediction;

    autil::DataBuffer buffer;
    collectedReplay->serialize(buffer);
    NaviSchedScheduleReplay wireDecoded;
    wireDecoded.deserialize(buffer);
    autil::legacy::json::JsonMap normalizedSchedulerInfo;
    autil::legacy::FastFromJsonString(
        normalizedSchedulerInfo,
        autil::legacy::FastToJsonString(collectedReplay->schedulerInfo));
    EXPECT_EQ(autil::legacy::FastToJsonString(normalizedSchedulerInfo),
              autil::legacy::FastToJsonString(wireDecoded.schedulerInfo));
    auto replayJson = NaviSchedScheduleReplayJson::toJsonString(wireDecoded);
    EXPECT_NE(std::string::npos, replayJson.find(R"("scheduler_info":{)"));
    EXPECT_EQ(std::string::npos, replayJson.find("scheduler_info_json"));
    EXPECT_EQ(std::string::npos, replayJson.find(R"(\"layout\")"));
    NaviSchedScheduleReplay jsonDecoded;
    ASSERT_NO_THROW(NaviSchedScheduleReplayJson::fromJsonString(replayJson, jsonDecoded));
    ASSERT_TRUE(jsonDecoded.decisions.front().latencyPrediction);
    const auto &decodedPrediction = *jsonDecoded.decisions.front().latencyPrediction;
    EXPECT_EQ(2, decodedPrediction.features.getBatchCount());
    EXPECT_EQ(128, decodedPrediction.features.getCacheHitTokenCount());
    EXPECT_EQ(384, decodedPrediction.features.getCacheMissTokenCount());
    EXPECT_EQ(64, decodedPrediction.floorFeatures.getCacheHitTokenCount());
    EXPECT_EQ(448, decodedPrediction.floorFeatures.getCacheMissTokenCount());
    EXPECT_DOUBLE_EQ(-7.25, decodedPrediction.fixedLatencyMs);
    EXPECT_TRUE(decodedPrediction.hasFloor);
    EXPECT_TRUE(decodedPrediction.recomputable);
    CostSchedulerKernelInternal::ReplayInfo jsonOptimizerReplay;
    autil::legacy::FromJson(jsonOptimizerReplay,
                            autil::legacy::Any(jsonDecoded.schedulerInfo));
    EXPECT_EQ(optimizerReplay.scheduler, jsonOptimizerReplay.scheduler);
    EXPECT_DOUBLE_EQ(optimizerReplay.lambda, jsonOptimizerReplay.lambda);
    EXPECT_DOUBLE_EQ(optimizerReplay.alpha, jsonOptimizerReplay.alpha);
    EXPECT_DOUBLE_EQ(optimizerReplay.alphaDecay, jsonOptimizerReplay.alphaDecay);
    EXPECT_DOUBLE_EQ(optimizerReplay.minAlpha, jsonOptimizerReplay.minAlpha);
    EXPECT_EQ(optimizerReplay.maxLoopCount, jsonOptimizerReplay.maxLoopCount);
    auto replayContext = std::make_shared<NaviSchedScheduleContext>();
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(jsonDecoded, *replayContext));
    std::vector<NaviSchedDecision> replayDecisions;
    ASSERT_TRUE(ScheduleReplayRunner::runCostScheduler(
        jsonDecoded, replayContext, optimizerReplay.lambda, optimizerReplay.alpha,
        optimizerReplay.alphaDecay, optimizerReplay.minAlpha,
        static_cast<int32_t>(optimizerReplay.maxLoopCount), 128.0, replayDecisions));
    EXPECT_TRUE(
        ScheduleReplayRunner::decisionsEqual(decisions, replayDecisions, replay.bizName));
    ASSERT_EQ(optimizerReplay.schedInfos.size(), jsonOptimizerReplay.schedInfos.size());
    for (size_t nodeIndex = 0; nodeIndex < optimizerReplay.schedInfos.size();
         ++nodeIndex) {
        const auto &expectedNode = optimizerReplay.schedInfos[nodeIndex];
        const auto &actualNode = jsonOptimizerReplay.schedInfos[nodeIndex];
        ASSERT_EQ(expectedNode.size(), actualNode.size());
        for (size_t requestIndex = 0; requestIndex < expectedNode.size();
             ++requestIndex) {
            const auto &expected = expectedNode[requestIndex].schedInfo;
            const auto &actual = actualNode[requestIndex].schedInfo;
            EXPECT_FLOAT_EQ(expected.cost, actual.cost);
            EXPECT_FLOAT_EQ(expected.queueWaitMs, actual.queueWaitMs);
            EXPECT_NEAR(expected.weight, actual.weight, 1e-12);
        }
    }
    ASSERT_EQ(optimizerReplay.optimizationRuns.size(),
              jsonOptimizerReplay.optimizationRuns.size());
    for (size_t runIndex = 0; runIndex < optimizerReplay.optimizationRuns.size();
         ++runIndex) {
        const auto &expectedRun = optimizerReplay.optimizationRuns[runIndex];
        const auto &actualRun = jsonOptimizerReplay.optimizationRuns[runIndex];
        expectDoubleVectorsNear(expectedRun.initialWeights, actualRun.initialWeights);
        expectDoubleVectorsNear(expectedRun.finalWeights, actualRun.finalWeights);
        EXPECT_NEAR(expectedRun.finalForwardValue, actualRun.finalForwardValue, 1e-12);
        EXPECT_NEAR(expectedRun.bestForwardValue, actualRun.bestForwardValue, 1e-12);
        EXPECT_EQ(expectedRun.bestNodeIndexes, actualRun.bestNodeIndexes);
        EXPECT_EQ(expectedRun.elapsedUs, actualRun.elapsedUs);
        ASSERT_EQ(expectedRun.steps.size(), actualRun.steps.size());
        for (size_t stepIndex = 0; stepIndex < expectedRun.steps.size(); ++stepIndex) {
            const auto &expected = expectedRun.steps[stepIndex];
            const auto &actual = actualRun.steps[stepIndex];
            EXPECT_EQ(expected.iteration, actual.iteration);
            EXPECT_DOUBLE_EQ(expected.alpha, actual.alpha);
            EXPECT_NEAR(expected.forwardValue, actual.forwardValue, 1e-12);
            EXPECT_EQ(expected.elapsedUs, actual.elapsedUs);
            EXPECT_EQ(expected.forwardUs, actual.forwardUs);
            EXPECT_EQ(expected.backwardUs, actual.backwardUs);
            EXPECT_EQ(expected.updateUs, actual.updateUs);
            EXPECT_EQ(expected.projectionUs, actual.projectionUs);
            EXPECT_EQ(expected.bindUs, actual.bindUs);
            expectDoubleVectorsNear(expected.gradients, actual.gradients);
            expectDoubleVectorsNear(expected.weightsBeforeUpdate,
                                    actual.weightsBeforeUpdate);
            expectDoubleVectorsNear(expected.weightsBeforeProjection,
                                    actual.weightsBeforeProjection);
            expectDoubleVectorsNear(expected.weightsAfterProjection,
                                    actual.weightsAfterProjection);
        }
    }
}

// Adapt the archived capture into a synthetic fixture for today's candidate
// and bounded recovery policies. Keep the original capture files unchanged.
static void includeAllCapturedOverloadCandidates(NaviSchedScheduleReplay &replay)
{
    using JsonMap = autil::legacy::json::JsonMap;
    auto &info = replay.schedulerInfo;
    const size_t nodeCount = replay.nodes.size();
    const size_t acceptedCount = nodeCount == 7 ? 10 : 18;
    ASSERT_TRUE(nodeCount == 7 || nodeCount == 6);
    int64_t recordedNodeCount = 0;
    autil::legacy::FromJson(recordedNodeCount, info.at("cold_start_trusted_node_count"));
    EXPECT_EQ(nodeCount == 7 ? 5 : 4, recordedNodeCount);
    info["cold_start_trusted_node_count"] = int64_t(nodeCount);
    info["cold_start_target_inflight"] = nodeCount == 7 ? 5641.0 / 7.0 : 4340.0 / 6.0;
    std::vector<JsonMap> queueRecords;
    autil::legacy::FromJson(queueRecords, info.at("queue_overload_random_decisions"));
    auto admissionContext = std::make_shared<NaviSchedScheduleContext>();
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *admissionContext));
    admissionContext->setReplay(std::make_shared<NaviSchedScheduleReplay>());
    admissionContext->_responseRequests.resize(admissionContext->requestCount());
    MasterScheduleR scheduleResource;
    MasterScheduleContextKernel admission;
    admission._schedulerKernelId = CostSchedulerKernel::KERNEL_ID;
    const_cast<MasterScheduleR *&>(admission._masterScheduleR) = &scheduleResource;
    autil::legacy::FromJson(admission._maxWaitScheduleTimeMs,
                            info.at("queue_overload_schedule_cycle_ms"));
    autil::legacy::FromJson(admission._queueOverloadStartCycleMultiplier,
                            info.at("queue_overload_start_cycle_multiplier"));
    autil::legacy::FromJson(admission._queueOverloadFullCycleMultiplier,
                            info.at("queue_overload_full_cycle_multiplier"));
    size_t drawIndex = 0;
    // Preserve the captured accepted subset for optimizer comparison, while
    // rebuilding its random audit under the current admission probability.
    ASSERT_TRUE(admission.applyQueueOverloadLimit(
        std::make_shared<MasterScheduleContextData>(admissionContext), [&]() {
            if (drawIndex >= queueRecords.size()) {
                ADD_FAILURE() << "more admission draws than captured requests";
                return uint64_t(0);
            }
            bool accepted = false;
            autil::legacy::FromJson(accepted, queueRecords[drawIndex++].at("accepted"));
            return accepted ? std::numeric_limits<uint64_t>::max() : uint64_t(0);
        }));
    ASSERT_EQ(queueRecords.size(), drawIndex);
    ASSERT_EQ(acceptedCount, admissionContext->requestCount());
    ASSERT_EQ(queueRecords.size(), admissionContext->_queueOverloadRandomDecisions.size());
    for (size_t index = 0; index < queueRecords.size(); ++index) {
        const auto &decision = admissionContext->_queueOverloadRandomDecisions[index];
        queueRecords[index]["sample"] = std::to_string(decision.sample);
        queueRecords[index]["probability"] = decision.probability;
    }
    info["queue_overload_drop_probability"] = admissionContext->_queueOverloadDropProbability;
    // The synthetic audit uses current workload weights; the archived average
    // was computed from prefill inflight alone.
    info["queue_overload_average_predicted_latency_ms"] =
        admissionContext->_queueOverloadAveragePredictedLatencyMs;
    for (auto &decision : replay.decisions) {
        if (decision.reason == "rate_limited") {
            decision.predictedQueueLatencyMs =
                admissionContext->_queueOverloadAveragePredictedLatencyMs;
        }
    }
    info["queue_overload_random_decisions"] = autil::legacy::ToJson(queueRecords);
    std::vector<JsonMap> runs;
    autil::legacy::FromJson(runs, info.at("optimization_runs"));
    ASSERT_EQ(1u, runs.size());
    std::vector<double> weights;
    autil::legacy::FromJson(weights, runs[0].at("initial_weights"));
    ASSERT_EQ((nodeCount - 2) * acceptedCount, weights.size());
    weights.resize(nodeCount * acceptedCount, 0.0);
    runs[0]["initial_weights"] = autil::legacy::ToJson(weights);
    info["optimization_runs"] = autil::legacy::ToJson(runs);
}

TEST_F(NaviSchedResourceTest, testCostSchedulerReplaysCapturedOverloadRounds)
{
    for (const auto &sample : std::vector<std::pair<std::string, size_t>>{
             {"overload-21416.json", 18}, {"overload-21457.json", 30}}) {
        SCOPED_TRACE(sample.first);
        std::ifstream input("rtp_llm/flexlb/navi_sched/testdata/schedule_replay/" + sample.first);
        ASSERT_TRUE(input.is_open());
        std::string json((std::istreambuf_iterator<char>(input)),
                         std::istreambuf_iterator<char>());
        NaviSchedScheduleReplay replay;
        ASSERT_NO_THROW(NaviSchedScheduleReplayJson::fromJsonString(json, replay));
        ASSERT_EQ(sample.second, replay.requests.size());
        ASSERT_EQ(sample.second, replay.decisions.size());
        if (sample.first == "overload-21457.json") {
            std::ifstream expectedInput(
                "rtp_llm/flexlb/navi_sched/testdata/schedule_replay/overload-21457-unfiltered-expected.json");
            ASSERT_TRUE(expectedInput.is_open());
            const std::string expectedJson((std::istreambuf_iterator<char>(expectedInput)),
                                           std::istreambuf_iterator<char>());
            autil::legacy::json::JsonMap expected;
            autil::legacy::FromJsonString(expected, expectedJson);
            auto inputJson = autil::legacy::json::ParseJson(json);
            auto fields = autil::legacy::AnyCast<autil::legacy::json::JsonMap>(inputJson);
            fields["decisions"] = expected.at("decisions");
            NaviSchedScheduleReplayJson::fromJsonString(
                autil::legacy::ToJsonString(fields), replay);
        }
        ASSERT_NO_FATAL_FAILURE(includeAllCapturedOverloadCandidates(replay));
        auto context = std::make_shared<NaviSchedScheduleContext>();
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *context));
        std::vector<NaviSchedDecision> decisions;
        ASSERT_TRUE(ScheduleReplayRunner::runCostScheduler(
            replay, context, 0.5, 512.0, 1.0, 0.0, 10, 0.0, decisions));
        ASSERT_EQ(sample.second, decisions.size());
        auto repeatedContext = std::make_shared<NaviSchedScheduleContext>();
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *repeatedContext));
        std::vector<NaviSchedDecision> repeatedDecisions;
        ASSERT_TRUE(ScheduleReplayRunner::runCostScheduler(
            replay, repeatedContext, 0.5, 512.0, 1.0, 0.0, 10, 0.0, repeatedDecisions));
        EXPECT_TRUE(ScheduleReplayRunner::decisionsEqual(
            decisions, repeatedDecisions, replay.bizName));
        size_t rejected = 0;
        for (size_t index = 0; index < decisions.size(); ++index) {
            const auto &expected = replay.decisions[index];
            const auto &actual = decisions[index];
            SCOPED_TRACE(index);
            EXPECT_EQ(expected.requestId, actual.requestId);
            EXPECT_EQ(expected.reason, actual.reason);
            if (sample.first == "overload-21416.json") {
                EXPECT_EQ(expected.batchId, actual.batchId);
                EXPECT_EQ(expected.expectedBatchSize, actual.expectedBatchSize);
                EXPECT_EQ(expected.target.address, actual.target.address);
                EXPECT_EQ(expected.target.agentAddress, actual.target.agentAddress);
            }
            EXPECT_EQ(expected.scheduleId, actual.scheduleId);
            EXPECT_EQ(expected.scheduleTimeUs, actual.scheduleTimeUs);
            EXPECT_EQ(expected.predictedCacheHitTokenCount, actual.predictedCacheHitTokenCount);
            // Retaining intermediate candidates may improve the archived plan.
            EXPECT_LE(actual.scheduleLoss, expected.scheduleLoss + 1e-6);
            EXPECT_NEAR(expected.predictedQueueLatencyMs, actual.predictedQueueLatencyMs, 1e-6);
            if (sample.first == "overload-21416.json") {
                EXPECT_NEAR(expected.predictedExecutionLatencyMs, actual.predictedExecutionLatencyMs, 1e-6);
            }
            rejected += actual.reason == "rate_limited";
        }
        EXPECT_EQ(sample.second == 18 ? 8 : 12, rejected);
    }
}

TEST_F(NaviSchedResourceTest, testCostSchedulerRejectsCorruptCapturedAudit)
{
    std::ifstream input("rtp_llm/flexlb/navi_sched/testdata/schedule_replay/overload-21416.json");
    ASSERT_TRUE(input.is_open());
    std::string json((std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
    NaviSchedScheduleReplay original;
    ASSERT_NO_THROW(NaviSchedScheduleReplayJson::fromJsonString(json, original));
    const auto rejected = [](const NaviSchedScheduleReplay &replay) {
        auto context = std::make_shared<NaviSchedScheduleContext>();
        std::vector<NaviSchedDecision> decisions;
        return !ScheduleReplayRunner::makeContext(replay, *context) ||
               !ScheduleReplayRunner::runCostScheduler(
                   replay, context, 0.5, 512.0, 1.0, 0.0, 10, 0.0, decisions);
    };
    // A capture of the removed filtering policy must not pass as today's audit.
    EXPECT_TRUE(rejected(original));
    ASSERT_NO_FATAL_FAILURE(includeAllCapturedOverloadCandidates(original));
    EXPECT_FALSE(rejected(original));
    using JsonMap = autil::legacy::json::JsonMap;
    std::vector<JsonMap> records;
    autil::legacy::FromJson(records, original.schedulerInfo.at("queue_overload_random_decisions"));
    ASSERT_EQ(18, records.size());
    auto replay = original;
    records.pop_back();
    replay.schedulerInfo["queue_overload_random_decisions"] = autil::legacy::ToJson(records);
    EXPECT_TRUE(rejected(replay));
    autil::legacy::FromJson(records, original.schedulerInfo.at("queue_overload_random_decisions"));
    records.push_back(records.back());
    replay.schedulerInfo["queue_overload_random_decisions"] = autil::legacy::ToJson(records);
    EXPECT_TRUE(rejected(replay));
    records.resize(18);
    records[0]["accepted"] = true;
    replay.schedulerInfo["queue_overload_random_decisions"] = autil::legacy::ToJson(records);
    EXPECT_TRUE(rejected(replay));
    records[0]["sample"] = std::string("18446744073709551616");
    replay.schedulerInfo["queue_overload_random_decisions"] = autil::legacy::ToJson(records);
    EXPECT_TRUE(rejected(replay));
    replay = original;
    std::vector<JsonMap> runtime;
    autil::legacy::FromJson(runtime, replay.schedulerInfo.at("replay_node_runtime"));
    runtime[0]["workload_report_age_ms"] = 9999.0;
    replay.schedulerInfo["replay_node_runtime"] = autil::legacy::ToJson(runtime);
    EXPECT_TRUE(rejected(replay));
    replay = original;
    replay.schedulerInfo["queue_overload_average_predicted_latency_ms"] = -1.0;
    EXPECT_TRUE(rejected(replay));
    replay = original;
    replay.schedulerInfo["cold_start_trusted_node_count"] = int64_t(8);
    EXPECT_TRUE(rejected(replay));
}

