TEST_F(NaviSchedResourceTest, testCostSchedulerConfiguresLatencyRequestWeights)
{
    NaviSchedScheduleReplay replay;
    replay.scheduleTimeUs = 1'000'000;
    replay.bizName = "model_biz";
    NaviSchedScheduleItem request;
    request.request.requestId = 1;
    request.request.bizName = replay.bizName;
    request.request.promptTokenCount = 16;
    request.request.timeoutMs = 1000;
    request.remainingTimeoutMs = 1000;
    replay.requests.emplace_back(std::move(request));
    replay.nodeMatches.emplace_back();

    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    int64_t tokenCounts[1] = {0};
    double requestWeights[1] = {0.0};
    EXPECT_EQ(16, CostSchedulerKernelInternal::fillRequestTokenCounts(
                      context, tokenCounts, requestWeights, 1.0));
    EXPECT_DOUBLE_EQ(1.0 / 16.0, requestWeights[0]);
    CostSchedulerKernelInternal::fillRequestTokenCounts(context, tokenCounts,
                                                        requestWeights, 0.5);
    EXPECT_DOUBLE_EQ(0.25, requestWeights[0]);
    CostSchedulerKernelInternal::fillRequestTokenCounts(context, tokenCounts,
                                                        requestWeights, 0.0);
    EXPECT_DOUBLE_EQ(1.0, requestWeights[0]);
    EXPECT_DOUBLE_EQ(16.0,
                     CostSchedulerKernelInternal::calculateTokenNormalizationDenominator(
                         tokenCounts, 1, 1.0));
    EXPECT_DOUBLE_EQ(4.0,
                     CostSchedulerKernelInternal::calculateTokenNormalizationDenominator(
                         tokenCounts, 1, 0.5));
    EXPECT_DOUBLE_EQ(1.0,
                     CostSchedulerKernelInternal::calculateTokenNormalizationDenominator(
                         tokenCounts, 1, 0.0));
}

TEST_F(NaviSchedResourceTest, testCostSchedulerNormalizesBothTermsByPower)
{
    constexpr size_t REQUEST_COUNT = 5;
    constexpr size_t NODE_COUNT = 7;
    auto replay = makeCostSchedulerReplay(REQUEST_COUNT, NODE_COUNT);
    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    ASSERT_TRUE(ScheduleReplayRunner::prepareContext(context));

    std::vector<int64_t> tokenCounts(REQUEST_COUNT);
    std::vector<double> requestWeights(REQUEST_COUNT);
    auto totalTokenCount = CostSchedulerKernelInternal::fillRequestTokenCounts(
        context, tokenCounts.data(), requestWeights.data(), 0.0);
    auto requestDenominator =
        CostSchedulerKernelInternal::calculateTokenNormalizationDenominator(
            tokenCounts.data(), REQUEST_COUNT, 0.0);
    ASSERT_DOUBLE_EQ(static_cast<double>(REQUEST_COUNT), requestDenominator);

    CostSchedulerKernelInternal::ReplayInfo replayInfo;
    auto costs = CostSchedulerKernelInternal::prepare(context, tokenCounts.data(), 1.0,
                                                      1.0, 1.0, 0.0, 1, 0, replayInfo);
    ASSERT_TRUE(costs);
    std::vector<double> weights(REQUEST_COUNT * NODE_COUNT, 0.0);
    for (size_t requestIndex = 0; requestIndex < REQUEST_COUNT; ++requestIndex) {
        weights[(requestIndex % NODE_COUNT) * REQUEST_COUNT + requestIndex] = 1.0;
    }
    auto requestLevelValue = CostSchedulerKernelInternal::forwardNodeRange(
        context, costs.get(), weights.data(), tokenCounts.data(), requestWeights.data(),
        requestDenominator, 1.0, 0.0, 0, NODE_COUNT, nullptr, nullptr, nullptr);
    auto tokenLevelValue = CostSchedulerKernelInternal::forwardNodeRange(
        context, costs.get(), weights.data(), tokenCounts.data(), requestWeights.data(),
        static_cast<double>(totalTokenCount), 1.0, 0.0, 0, NODE_COUNT, nullptr, nullptr,
        nullptr);
    EXPECT_NEAR(requestLevelValue / tokenLevelValue,
                static_cast<double>(totalTokenCount) / REQUEST_COUNT, 1e-12);
}

TEST_F(NaviSchedResourceTest, testConcurrentNodeUpdate)
{
    TestMasterStateR runtime;
    std::vector<std::thread> threads;
    for (size_t threadId = 0; threadId < 8; ++threadId) {
        threads.emplace_back([threadId, &runtime]() {
            for (size_t i = 0; i < 100; ++i) {
                auto report = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED, i);
                setInflightSnapshot(report, i + 1, i);
                report->requestEvent->completedRequestCount = 1;
                ASSERT_TRUE(
                    runtime.reportAgent("prefill_" + std::to_string(threadId), report));
            }
        });
    }
    for (auto &thread : threads) {
        thread.join();
    }
    auto nodes = runtime.getNodes();
    ASSERT_EQ(8, nodes.size());
    ASSERT_EQ(99, nodes["prefill_0"].lastEventTimeUs);
    ASSERT_EQ(800, runtime.getAgentReportCount());
}

TEST_F(NaviSchedResourceTest, testConcurrentReadDuringSingleNodeUpdate)
{
    TestMasterStateR runtime;
    runtime.registerAgent("agent_0", "agent_biz", "127.0.0.1:1000", 100);
    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    ASSERT_TRUE(runtime.reportAgent("agent_0", handshake));
    auto state = runtime.getNodeState(hashString("agent_0"));
    ASSERT_TRUE(state);

    std::atomic<bool> updating{true};
    std::atomic<bool> valid{true};
    std::thread writer([&runtime, &updating]() {
        for (int64_t index = 1; index <= 2000; ++index) {
            auto report = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED, index);
            setInflightSnapshot(report, index + 1, index % 32);
            report->requestEvent->latencyMs = static_cast<double>(index);
            report->requestEvent->completedRequestCount = 1;
            if (!runtime.reportAgent("agent_0", report)) {
                break;
            }
        }
        updating.store(false, std::memory_order_release);
    });
    std::vector<std::thread> readers;
    for (size_t index = 0; index < 4; ++index) {
        readers.emplace_back([&state, &updating, &valid]() {
            while (updating.load(std::memory_order_acquire)) {
                auto info = state->getInfo();
                if ("agent_0" != info.agentId || "agent_biz" != info.bizName ||
                    info.inflightRequests < 0 || info.inflightRequests >= 32) {
                    valid.store(false, std::memory_order_relaxed);
                    return;
                }
            }
        });
    }
    writer.join();
    for (auto &reader : readers) {
        reader.join();
    }
    ASSERT_TRUE(valid.load(std::memory_order_relaxed));
    auto info = state->getInfo();
    ASSERT_EQ(2000, info.lastEventTimeUs);
    ASSERT_GT(info.lastReceiveTimeUs, 0);
    ASSERT_EQ("batch_finished", info.lastRequestEventType);
}

TEST_F(NaviSchedResourceTest, testScheduleSnapshotUpdatesAtomically)
{
    TestMasterStateR runtime;
    runtime.registerAgent("agent_0", "agent_biz", "127.0.0.1:1000", 100);
    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    handshake->control->serverInfo.port = 18000;
    handshake->latency = std::make_shared<AgentLatencyToMasterData>();
    handshake->latency->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
    handshake->latency->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
    handshake->latency->modelRevision = 1;
    handshake->latency->parameters.assign(NonLinearPrefillModelR::PARAMETER_COUNT, 1.0);
    ASSERT_TRUE(runtime.reportAgent("agent_0", handshake));
    ASSERT_TRUE(runtime.reportAgent("agent_0", makeCachePolicyUpdate(256)));
    ASSERT_TRUE(runtime.reportAgent("agent_0", makeEmptyPendingCacheSnapshot()));
    auto state = runtime.getNodeState(hashString("agent_0"));
    ASSERT_TRUE(state);

    NaviSchedNodeSnapshot initial;
    ASSERT_TRUE(state->getScheduleSnapshot("agent_biz", initial));
    ASSERT_TRUE(initial.info);
    const auto *initialInfo = initial.info.get();

    std::atomic<bool> updating{true};
    std::atomic<bool> valid{true};
    std::thread writer([&runtime, &updating, &valid]() {
        for (int64_t revision = 2; revision <= 1000; ++revision) {
            auto load = makeRequestUpdate(NaviSchedAgentEvent::BATCH_FINISHED, revision);
            setInflightSnapshot(load, revision, revision);
            load->requestEvent->batchWaitingRequests = revision + 1;
            load->requestEvent->queuedBatchRequests = revision + 2;
            load->requestEvent->runningRequests = revision + 3;
            load->requestEvent->batchTimeoutCount = revision + 4;
            load->requestEvent->abnormalBatchFinishCount = revision + 5;
            load->requestEvent->queueTotalPredictedLatencyMs = revision + 6;
            load->requestEvent->completedRequestCount = 1;
            if (!runtime.reportAgent("agent_0", load)) {
                valid.store(false, std::memory_order_relaxed);
                break;
            }
            auto model = makeLatencyUpdate(revision);
            model->latency->formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
            model->latency->binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
            model->latency->modelRevision = revision;
            model->latency->parameters.assign(NonLinearPrefillModelR::PARAMETER_COUNT,
                                              revision);
            if (!runtime.reportAgent("agent_0", model)) {
                valid.store(false, std::memory_order_relaxed);
                break;
            }
            if (!runtime.reportAgent("agent_0", makeWorkloadUpdate(revision, revision))) {
                valid.store(false, std::memory_order_relaxed);
                break;
            }
        }
        updating.store(false, std::memory_order_release);
    });
    std::vector<std::thread> readers;
    for (size_t index = 0; index < 4; ++index) {
        readers.emplace_back([&state, &updating, &valid]() {
            while (updating.load(std::memory_order_acquire)) {
                NaviSchedNodeSnapshot snapshot;
                if (!state->getScheduleSnapshot("agent_biz", snapshot) ||
                    !snapshot.info) {
                    valid.store(false, std::memory_order_relaxed);
                    return;
                }
                const auto inflight = snapshot.load.inflightRequests;
                if (inflight > 0 &&
                    (snapshot.load.batchWaitingRequests != inflight + 1 ||
                     snapshot.load.queuedBatchRequests != inflight + 2 ||
                     snapshot.load.runningRequests != inflight + 3 ||
                     snapshot.load.batchTimeoutCount !=
                         static_cast<uint64_t>(inflight + 4) ||
                     snapshot.load.abnormalBatchFinishCount !=
                         static_cast<uint64_t>(inflight + 5) ||
                     snapshot.load.queueTotalPredictedLatencyMs != inflight + 6)) {
                    valid.store(false, std::memory_order_relaxed);
                    return;
                }
                if (snapshot.latencyModel) {
                    const auto revision = snapshot.latencyModel->revision;
                    if (snapshot.info->latencyModelRevision != revision ||
                        snapshot.info->latencyParameters !=
                            snapshot.latencyModel->parameters) {
                        valid.store(false, std::memory_order_relaxed);
                        return;
                    }
                    for (auto parameter : snapshot.latencyModel->parameters) {
                        if (parameter != revision) {
                            valid.store(false, std::memory_order_relaxed);
                            return;
                        }
                    }
                }
                const auto workloadRevision = snapshot.workload.revision;
                if (workloadRevision > 0 &&
                    (snapshot.workload.requestCount !=
                         static_cast<int32_t>(workloadRevision) ||
                     snapshot.workload.remainingPrefillRequestCount !=
                         static_cast<int32_t>(workloadRevision) ||
                     snapshot.workload.remainingPrefillContextTokenCount !=
                         static_cast<int64_t>(workloadRevision * 3) ||
                     snapshot.workload.remainingPrefillTokenCount !=
                         static_cast<int64_t>(workloadRevision * 4) ||
                     snapshot.workload.remainingTotalContextTokenCount !=
                         static_cast<int64_t>(workloadRevision * 7) ||
                     snapshot.workload.remainingTotalTokenCount !=
                         static_cast<int64_t>(workloadRevision * 8) ||
                     snapshot.workload.inFlightScheduledTokenCount !=
                         static_cast<int64_t>(workloadRevision * 12) ||
                     snapshot.workloadReportReceiveTimeUs <= 0)) {
                    valid.store(false, std::memory_order_relaxed);
                    return;
                }
            }
        });
    }
    writer.join();
    for (auto &reader : readers) {
        reader.join();
    }
    ASSERT_TRUE(valid.load(std::memory_order_relaxed));

    NaviSchedNodeSnapshot updated;
    ASSERT_TRUE(state->getScheduleSnapshot("agent_biz", updated));
    ASSERT_EQ(1000, updated.latencyModel->revision);
    ASSERT_EQ(1000, updated.workload.revision);
    ASSERT_EQ(12000, updated.workload.inFlightScheduledTokenCount);
    runtime.registerAgent("agent_0", "agent_biz", "127.0.0.1:1001", 100);
    NaviSchedNodeSnapshot addressChanged;
    ASSERT_TRUE(state->getScheduleSnapshot("agent_biz", addressChanged));
    ASSERT_NE(initialInfo, addressChanged.info.get());
    ASSERT_EQ("127.0.0.1:1001", addressChanged.info->collectorAddress);
}

TEST_F(NaviSchedResourceTest, testAgentRestartsWithSameIdentity)
{
    TestMasterStateR runtime;
    const std::string agentId = "127.0.0.1:1000";
    const auto agentIdHash = hashString(agentId);
    auto oldState = runtime.registerAgent(agentId, "agent_biz", "127.0.0.1:1000", 100);
    ASSERT_TRUE(oldState);
    auto handshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    ASSERT_TRUE(runtime.reportAgent(agentId, handshake));

    auto cacheUpdate = makeCacheSnapshot({11, 22}, 200, 3, {11}, {11});
    ASSERT_TRUE(runtime.reportAgent(agentId, cacheUpdate));
    ASSERT_TRUE(runtime.reportAgent(agentId, makeWorkloadUpdate(10, 300)));
    auto load = makeRequestUpdate(NaviSchedAgentEvent::EXECUTION_LOAD_UPDATED, 400);
    load->requestEvent->queueTotalPredictedLatencyMs = 50.0;
    ASSERT_TRUE(runtime.reportAgent(agentId, load));
    ASSERT_TRUE(reservePendingCache(oldState, 7, {33, 44}));
    ASSERT_EQ(1, pendingCacheBatchCount(oldState));
    auto stopping = makeControlUpdate(NaviSchedAgentEvent::AGENT_STOPPING);
    ASSERT_TRUE(runtime.reportAgent(agentId, stopping));
    auto stoppedState = runtime.getNodeState(agentIdHash);
    ASSERT_EQ(oldState, stoppedState);
    auto stoppedInfo = stoppedState->getInfo();
    ASSERT_FALSE(stoppedInfo.online);
    ASSERT_DOUBLE_EQ(0.0, stoppedInfo.queueTotalPredictedLatencyMs);
    ASSERT_EQ(0, stoppedInfo.workload.revision);
    ASSERT_EQ(0, stoppedInfo.workloadReportReceiveTimeUs);
    ASSERT_EQ(0, pendingCacheBatchCount(oldState));
    ASSERT_EQ(0, stoppedState->getMatchedBlockCount({11, 22}));
    auto stoppedCache = stoppedState->getCacheSyncStats();
    ASSERT_FALSE(stoppedCache.cacheStateReady);
    ASSERT_FALSE(stoppedCache.cachePolicyReady);
    ASSERT_EQ(-1, stoppedCache.agentCachedBlockCount);
    ASSERT_EQ(-1, stoppedCache.agentFullReadyBlockCount);
    ASSERT_EQ(-1, stoppedCache.agentTailReadyBlockCount);
    ASSERT_EQ(0, stoppedCache.masterHashChecksum);
    ASSERT_EQ(0, stoppedCache.masterFullReadyHashChecksum);
    ASSERT_EQ(0, stoppedCache.masterTailReadyHashChecksum);

    runtime.registerAgent(agentId, "agent_biz", "127.0.0.1:1000", 200);
    auto restartedHandshake = makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE);
    restartedHandshake->control->pdSeparated = false;
    restartedHandshake->control->unifiedLatencyPrediction = true;
    restartedHandshake->workload = makeWorkloadUpdate(1, 500)->workload;
    enableCapacitySplitWorkload(*restartedHandshake->workload);
    ASSERT_TRUE(runtime.reportAgent(agentId, restartedHandshake));
    ASSERT_TRUE(runtime.reportAgent(agentId, makeCacheSnapshot({55}, 600, 1)));
    auto newState = runtime.getNodeState(agentIdHash);
    ASSERT_TRUE(newState);
    ASSERT_EQ(oldState, newState);
    auto info = newState->getInfo();
    ASSERT_TRUE(info.online);
    ASSERT_EQ(200, info.totalBlocks);
    ASSERT_FALSE(info.pdSeparated);
    ASSERT_EQ(1, info.workload.revision);
    ASSERT_EQ(1, newState->getMatchedBlockCount({55}));
}

