TEST_F(NaviSchedResourceTest, testStaleCollectorPendingUpdatesDoNotPolluteReplacement)
{
    TestMasterStateR runtime;
    const std::string agentId = "127.0.0.1:1000";
    auto oldState = runtime.createAgent(agentId, "agent_biz", agentId, 0);
    ASSERT_TRUE(oldState);
    ASSERT_TRUE(runtime.reportAgent(
        oldState, makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE)));

    auto replacement = runtime.createAgent(agentId, "agent_biz", agentId, 0);
    ASSERT_TRUE(replacement);
    ASSERT_NE(oldState, replacement);
    ASSERT_TRUE(runtime.reportAgent(
        replacement, makeControlUpdate(NaviSchedAgentEvent::AGENT_HANDSHAKE)));
    ASSERT_TRUE(reservePendingCache(replacement, 8, {33}));

    NaviSchedPendingCacheReservation staleReservation;
    staleReservation.batchId = 101;
    staleReservation.scheduleBatchId = 101;
    staleReservation.fullReadyBlockHashes = {11};
    auto staleSnapshot = std::make_shared<AgentUpdateToMasterData>();
    staleSnapshot->event = NaviSchedAgentEvent::PENDING_CACHE_UPDATED;
    staleSnapshot->pendingCache = std::make_shared<AgentPendingCacheToMasterData>();
    staleSnapshot->pendingCache->fullSnapshot = true;
    staleSnapshot->pendingCache->revision = 1;
    staleSnapshot->pendingCache->addedReservations = {staleReservation};
    staleSnapshot->pendingCache->batchCount = 1;
    staleSnapshot->pendingCache->uniqueBlockCount = 1;
    staleSnapshot->pendingCache->checksum =
        PendingCacheUtil::reservationChecksum(staleReservation);
    ASSERT_TRUE(runtime.reportAgent(oldState, staleSnapshot));

    auto stats = pendingCacheStats(replacement);
    ASSERT_EQ(1, stats.batchCount);
    ASSERT_EQ(1, stats.scheduledBatchCount);
    ASSERT_EQ(0, stats.agentBatchCount);
    ASSERT_FALSE(stats.agentSnapshotReady);
    ASSERT_EQ(1, replacement->getMatchedBlockCount({33}));
    ASSERT_EQ(0, replacement->getMatchedBlockCount({11}));

    NaviSchedPendingCacheReservation staleDeltaReservation;
    staleDeltaReservation.batchId = 102;
    staleDeltaReservation.scheduleBatchId = 102;
    staleDeltaReservation.fullReadyBlockHashes = {22};
    auto staleDelta = std::make_shared<AgentUpdateToMasterData>();
    staleDelta->event = NaviSchedAgentEvent::PENDING_CACHE_UPDATED;
    staleDelta->pendingCache = std::make_shared<AgentPendingCacheToMasterData>();
    staleDelta->pendingCache->revision = 2;
    staleDelta->pendingCache->addedReservations = {staleDeltaReservation};
    staleDelta->pendingCache->batchCount = 2;
    staleDelta->pendingCache->uniqueBlockCount = 2;
    staleDelta->pendingCache->checksum =
        PendingCacheUtil::reservationChecksum(staleReservation) ^
        PendingCacheUtil::reservationChecksum(staleDeltaReservation);
    ASSERT_TRUE(runtime.reportAgent(oldState, staleDelta));

    stats = pendingCacheStats(replacement);
    EXPECT_EQ(1, stats.batchCount);
    EXPECT_EQ(1, stats.scheduledBatchCount);
    EXPECT_EQ(0, stats.agentBatchCount);
    EXPECT_FALSE(stats.agentSnapshotReady);
    EXPECT_EQ(1, replacement->getMatchedBlockCount({33}));
    EXPECT_EQ(0, replacement->getMatchedBlockCount({22}));
}

