TEST_F(NaviSchedResourceTest, testAgentHistoryPersistsCapacitySplitModel)
{
    const auto stateFile = GET_TEMP_DATA_PATH() + "latency/capacity-split-model.state";
    navi::NaviResourceHelper modelHelper;
    ASSERT_TRUE(modelHelper.config(
        NonLinearPrefillModelR::RESOURCE_ID,
        R"({"use_batch_count_feature":false,"use_capacity_split_feature":true})"));
    auto model = modelHelper.getOrCreateResPtr<NonLinearPrefillModelR>();
    ASSERT_TRUE(model);

    navi::NaviResourceHelper historyHelper;
    ASSERT_TRUE(historyHelper.config(
        AgentHistoryR::RESOURCE_ID,
        std::string(R"({"state_file":")") + stateFile +
            R"(","formula_fingerprint":"formula-a","history_fingerprint":"history-a","binary_fingerprint":"binary-a"})"));
    auto history = historyHelper.getOrCreateResPtr<AgentHistoryR>();
    ASSERT_TRUE(history);
    NaviSchedLatencySample sample;
    ASSERT_TRUE(sample.features.appendCapacitySplitAggregate(
        2, 3, 100, 200, 14000.0, 7000.0, 4, 300, 400, 44000.0, 23000.0));
    ASSERT_TRUE(sample.features.appendPrecedingRequestCount(11));
    sample.latencyMs = 123.5;
    sample.eventTimeUs = 456;
    bool fitReady = false;
    bool persistReady = false;
    history->append(sample, fitReady, persistReady);

    auto savedSnapshot = std::make_shared<NaviSchedLatencyModelSnapshot>();
    savedSnapshot->formula = model->getFormula();
    savedSnapshot->binaryVersion = model->getBinaryVersion();
    savedSnapshot->revision = 7;
    savedSnapshot->parameters = model->getInitialParameters();
    savedSnapshot->overloadPredictionTrusted = true;
    ASSERT_EQ(NonLinearPrefillModelR::CAPACITY_SPLIT_PARAMETER_COUNT,
              savedSnapshot->parameters.size());
    NonLinearPrefillModelR::OptimizerState savedOptimizer;
    for (size_t index = 0; index < savedSnapshot->parameters.size(); ++index) {
        savedOptimizer.adamMoment1[index] = 0.25 + index;
        savedOptimizer.adamMoment2[index] = 1.5 + index;
    }
    savedOptimizer.step = 123;
    ASSERT_TRUE(model->restoreOptimizerState(savedOptimizer));
    ASSERT_TRUE(history->save(savedSnapshot, model->getOptimizerState()));

    navi::NaviResourceHelper loadedHistoryHelper;
    ASSERT_TRUE(loadedHistoryHelper.config(
        AgentHistoryR::RESOURCE_ID,
        std::string(R"({"state_file":")") + stateFile +
            R"(","formula_fingerprint":"formula-a","history_fingerprint":"history-a","binary_fingerprint":"binary-a"})"));
    auto loadedHistory = loadedHistoryHelper.getOrCreateResPtr<AgentHistoryR>();
    ASSERT_TRUE(loadedHistory);
    navi::NaviResourceHelper loadedModelHelper;
    ASSERT_TRUE(loadedModelHelper.config(
        NonLinearPrefillModelR::RESOURCE_ID,
        R"({"use_batch_count_feature":false,"use_capacity_split_feature":true})"));
    auto loadedModel = loadedModelHelper.getOrCreateResPtr<NonLinearPrefillModelR>();
    ASSERT_TRUE(loadedModel);
    std::shared_ptr<const NaviSchedLatencyModelSnapshot> loadedSnapshot;
    bool fitOnStart = false;
    ASSERT_TRUE(loadedHistory->load(*loadedModel, loadedSnapshot, fitOnStart));
    ASSERT_TRUE(loadedSnapshot);
    EXPECT_EQ(savedSnapshot->binaryVersion, loadedSnapshot->binaryVersion);
    EXPECT_EQ(savedSnapshot->revision, loadedSnapshot->revision);
    EXPECT_EQ(savedSnapshot->parameters, loadedSnapshot->parameters);
    EXPECT_EQ(savedOptimizer.adamMoment1, loadedModel->getOptimizerState().adamMoment1);
    EXPECT_EQ(savedOptimizer.adamMoment2, loadedModel->getOptimizerState().adamMoment2);
    EXPECT_EQ(savedOptimizer.step, loadedModel->getOptimizerState().step);
    ASSERT_EQ(1, loadedHistory->getHistory()->size());
    const auto &loadedSample = loadedHistory->getHistory()->front();
    EXPECT_TRUE(loadedSample.features.usesCapacitySplit());
    EXPECT_EQ(sample.features.getRunningBatchSize(),
              loadedSample.features.getRunningBatchSize());
    EXPECT_EQ(sample.features.getWaitingBatchSize(),
              loadedSample.features.getWaitingBatchSize());
    EXPECT_EQ(sample.features.getWaitingCacheMissTokenCount(),
              loadedSample.features.getWaitingCacheMissTokenCount());
    EXPECT_EQ(sample.features.getPrecedingRequestCount(),
              loadedSample.features.getPrecedingRequestCount());
    EXPECT_DOUBLE_EQ(sample.features.getWaitingCacheMissTokenSquareSum(),
                     loadedSample.features.getWaitingCacheMissTokenSquareSum());
    EXPECT_DOUBLE_EQ(sample.latencyMs, loadedSample.latencyMs);
    EXPECT_EQ(sample.eventTimeUs, loadedSample.eventTimeUs);
}

TEST_F(NaviSchedResourceTest, testAgentHistorySnapshotUsesCopyOnWrite)
{
    AgentHistoryR history;
    NaviSchedLatencySample sample;
    sample.latencyMs = 1.0;
    bool fitReady = false;
    bool persistReady = false;
    history.append(sample, fitReady, persistReady);
    auto firstSnapshot = history.getHistory();
    ASSERT_EQ(1, firstSnapshot->size());

    sample.latencyMs = 2.0;
    history.append(sample, fitReady, persistReady);
    auto secondSnapshot = history.getHistory();
    ASSERT_EQ(1, firstSnapshot->size());
    ASSERT_EQ(2, secondSnapshot->size());
    ASSERT_NE(firstSnapshot.get(), secondSnapshot.get());
    ASSERT_EQ(1.0, firstSnapshot->front().latencyMs);
    ASSERT_EQ(2.0, secondSnapshot->back().latencyMs);
}

TEST_F(NaviSchedResourceTest, testAgentHistorySkipsWarmupSamplesBeforeOnlineFit)
{
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(AgentHistoryR::RESOURCE_ID,
                              R"({"warmup_sample_count":2,"fit_batch_size":2})"));
    auto history = helper.getOrCreateResPtr<AgentHistoryR>();
    ASSERT_TRUE(history);
    NaviSchedLatencySample sample;
    sample.latencyMs = 1.0;
    bool fitReady = true;
    bool persistReady = true;

    history->append(sample, fitReady, persistReady);
    ASSERT_FALSE(fitReady);
    ASSERT_FALSE(persistReady);
    history->append(sample, fitReady, persistReady);
    ASSERT_TRUE(history->getHistory()->empty());

    history->append(sample, fitReady, persistReady);
    ASSERT_FALSE(fitReady);
    history->append(sample, fitReady, persistReady);
    ASSERT_TRUE(fitReady);
    ASSERT_EQ(2, history->getHistory()->size());
}

TEST_F(NaviSchedResourceTest, testAgentHistorySkipsWarmupBeforeRampCollection)
{
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(AgentHistoryR::RESOURCE_ID,
                              R"({"warmup_sample_count":2,"fit_batch_size":2})"));
    auto history = helper.getOrCreateResPtr<AgentHistoryR>();
    ASSERT_TRUE(history);
    NaviSchedLatencySample sample;
    sample.latencyMs = 1.0;
    AgentHistoryR::AppendResult result;

    ASSERT_FALSE(history->append(sample, NaviSchedLatencyTrainingPhase::RAMP, result));
    EXPECT_FALSE(result.appended);
    ASSERT_FALSE(history->append(sample, NaviSchedLatencyTrainingPhase::RAMP, result));
    EXPECT_FALSE(result.appended);
    EXPECT_FALSE(history->_rampCollectionObserved);
    EXPECT_TRUE(history->getHistory()->empty());

    ASSERT_TRUE(history->append(sample, NaviSchedLatencyTrainingPhase::RAMP, result));
    EXPECT_TRUE(result.appended);
    EXPECT_TRUE(result.trainingDeferred);
    EXPECT_FALSE(result.fitReady);
    EXPECT_TRUE(history->_rampCollectionObserved);
    EXPECT_FALSE(history->_rampCollectionCompleted);

    ASSERT_TRUE(history->append(sample, NaviSchedLatencyTrainingPhase::NORMAL, result));
    EXPECT_TRUE(result.fitReady);
    EXPECT_TRUE(result.rampReplay);
    EXPECT_EQ(2, history->_pendingFitSampleCount);
    EXPECT_TRUE(history->_rampCollectionCompleted);

    EXPECT_FALSE(
        history->append(sample, static_cast<NaviSchedLatencyTrainingPhase>(127), result));
    EXPECT_FALSE(result.appended);
    EXPECT_EQ(2, history->getHistory()->size());
}

TEST_F(NaviSchedResourceTest, testLatencyBatchSampleAndFitInterval)
{
    AgentLatencyInput input;
    input.latencyMs = 123.5;
    NaviSchedRequestStats first;
    first.totalTokenCount = 1024;
    first.cacheHitTokenCount = 512;
    NaviSchedRequestStats second;
    second.totalTokenCount = 2048;
    NaviSchedRequestStats third;
    third.totalTokenCount = 512;
    third.cacheHitTokenCount = 512;
    input.queries = {first, second, third};
    auto sample = input.makeLatencySample();
    ASSERT_EQ(3, sample.features.getBatchSize());
    ASSERT_EQ(1024, sample.features.getCacheHitTokenCount());
    ASSERT_EQ(2560, sample.features.getCacheMissTokenCount());
    ASSERT_DOUBLE_EQ(123.5, sample.latencyMs);

    first.latencyTrainingPhase = NaviSchedLatencyTrainingPhase::RAMP;
    second.latencyTrainingPhase = NaviSchedLatencyTrainingPhase::RAMP;
    input.queries = {first, second};
    EXPECT_EQ(NaviSchedLatencyTrainingPhase::RAMP, input.getLatencyTrainingPhase());
    input.queries.emplace_back(third);
    EXPECT_EQ(NaviSchedLatencyTrainingPhase::NORMAL, input.getLatencyTrainingPhase());

    AgentHistoryR history;
    bool fitReady = false;
    bool persistReady = false;
    for (size_t index = 0; index < 3; ++index) {
        history.append(sample, fitReady, persistReady);
        ASSERT_FALSE(fitReady);
    }
    history.append(sample, fitReady, persistReady);
    ASSERT_TRUE(fitReady);
    ASSERT_EQ(4, history.getFitBatch().size());
}

