    unified.modelLatencyMs = 80.0;
    unified.eventTimeUs = 123;
    unified.precedingFeatures.appendRequest(100, 200);
    NaviSchedRequestStats request;
    request.requestId = 1;
    request.totalTokenCount = 50;
    request.cacheHitTokenCount = 20;
    unified.queries.emplace_back(request);

