TEST_F(NaviSchedResourceTest, testAgentLatencyValidationUsesPreUpdatePrediction)
{
    AgentLatencyKernel kernel;
    AgentLatencyInput input;
    input.latencyMs = 70.0;
    input.backendQueueLatencyMs = 5.0;
    input.predictedQueueLatencyMs = 10.0;
    input.predictedExecutionLatencyMs = 80.0;
    const auto stats = recordLatencyValidation(kernel, input, 75.0);
    ASSERT_EQ(1, stats.sampleCount);
    ASSERT_DOUBLE_EQ(10.0, stats.masterPredictedQueueMeanMs);
    ASSERT_DOUBLE_EQ(5.0, stats.actualQueueMeanMs);
    ASSERT_DOUBLE_EQ(-5.0, stats.queueBiasMeanMs);
    ASSERT_DOUBLE_EQ(5.0, stats.queueMaeMs);
    ASSERT_EQ(0, stats.zeroPredictedQueueSampleCount);
    ASSERT_EQ(1, stats.positivePredictedQueueSampleCount);
    ASSERT_DOUBLE_EQ(10.0, stats.positivePredictedQueueMeanMs);
    ASSERT_DOUBLE_EQ(5.0, stats.positivePredictedQueueActualMeanMs);
    ASSERT_DOUBLE_EQ(-5.0, stats.positivePredictedQueueBiasMeanMs);
    ASSERT_DOUBLE_EQ(5.0, stats.positivePredictedQueueMaeMs);
    ASSERT_DOUBLE_EQ(80.0, stats.masterPredictedExecutionMeanMs);
    ASSERT_DOUBLE_EQ(75.0, stats.agentPredictedExecutionMeanMs);
    ASSERT_DOUBLE_EQ(70.0, stats.actualExecutionMeanMs);
    ASSERT_DOUBLE_EQ(-10.0, stats.masterExecutionBiasMeanMs);
    ASSERT_NEAR(100.0 / 7.0, stats.masterExecutionMapePct, 1e-12);
    ASSERT_DOUBLE_EQ(-5.0, stats.agentExecutionBiasMeanMs);
    ASSERT_NEAR(50.0 / 7.0, stats.agentExecutionMapePct, 1e-12);
    ASSERT_EQ(7, stats.executionLatencyBuckets.size());
    for (size_t bucketId = 0; bucketId < 6; ++bucketId) {
        EXPECT_EQ(0, stats.executionLatencyBuckets[bucketId].sampleCount);
    }
    const auto &bucket = stats.executionLatencyBuckets[6];
    ASSERT_EQ(1, bucket.sampleCount);
    ASSERT_DOUBLE_EQ(10.0, bucket.masterExecutionMaeMs);
    ASSERT_NEAR(100.0 / 7.0, bucket.masterExecutionMapePct, 1e-12);
    ASSERT_DOUBLE_EQ(5.0, bucket.agentExecutionMaeMs);
    ASSERT_NEAR(50.0 / 7.0, bucket.agentExecutionMapePct, 1e-12);
    ASSERT_DOUBLE_EQ(90.0, stats.masterPredictedTotalMeanMs);
    ASSERT_DOUBLE_EQ(75.0, stats.actualTotalMeanMs);
    ASSERT_DOUBLE_EQ(-15.0, stats.totalBiasMeanMs);
    ASSERT_DOUBLE_EQ(20.0, stats.totalMapePct);
}

TEST_F(NaviSchedResourceTest, testAgentReportsEachLatencyErrorSampleDirectly)
{
    kmonitor::KMonitorFactory::Shutdown();
    kmonitor::MetricsConfig config;
    config.set_tenant_name("default");
    config.set_service_name("latency_sample_test_service");
    config.set_sink_address("127.0.0.1:4141");
    config.set_manually_mode(true);
    config.set_inited(true);
    ASSERT_TRUE(kmonitor::KMonitorFactory::Init(config));
    kmonitor::KMonitorFactory::Start();

    {
        auto reporter =
            std::make_shared<kmonitor::MetricsReporter>("", kmonitor::MetricsTags());
        kmonitor::MetricsReporterR reporterR(reporter);
        AgentLatencyKernel kernel;
        kernel._metricsReporterR__ = &reporterR;

        AgentLatencyInput input;
        input.latencyMs = 70.0;
        input.backendQueueLatencyMs = 5.0;
        input.predictedQueueLatencyMs = 10.0;
        input.predictedExecutionLatencyMs = 80.0;
        input.predictedCacheHitTokenCount = 20;
        input.actualCacheHitTokenCount = 16;
        AgentLatencyKernel::QueueFeatures queueFeatures;
        queueFeatures.rawLatencyMs = 9.0;
        queueFeatures.precedingBatchCount = 2.0;
        recordLatencyValidation(kernel, input, 75.0, &queueFeatures, 7.0);

        const auto metric = [](const char *suffix) {
            return std::string("latency_sample_test_service.agent.") + suffix;
        };
        const auto check = [&](const char *suffix, double expected) {
            kmonitor::MetricsTestUtil::checkMetricWithValue(
                reporter.get(), metric(suffix), nullptr, expected);
        };
        check("validation_cache_hit_tokens_error", -4.0);
        check("validation_cache_hit_tokens_absolute_error", 4.0);
        check("validation_queue_error_ms", -5.0);
        check("validation_queue_absolute_error_ms", 5.0);
        check("queue_model_raw_error_ms", -4.0);
        check("queue_model_raw_absolute_error_ms", 4.0);
        check("queue_model_error_ms", -2.0);
        check("queue_model_absolute_error_ms", 2.0);
        check("validation_queue_positive_error_ms", -5.0);
        check("validation_queue_positive_absolute_error_ms", 5.0);
        check("validation_execution_master_error_ms", -10.0);
        check("validation_execution_master_absolute_error_ms", 10.0);
        check("validation_execution_master_absolute_percentage_error_pct", 100.0 / 7.0);
        check("validation_execution_agent_error_ms", -5.0);
        check("validation_execution_agent_absolute_error_ms", 5.0);
        check("validation_execution_agent_absolute_percentage_error_pct", 50.0 / 7.0);
        check("validation_total_error_ms", -15.0);
        check("validation_total_absolute_error_ms", 15.0);
        check("validation_total_absolute_percentage_error_pct", 20.0);

        const kmonitor::MetricsTags bucketTags("bucket_id", "6");
        kmonitor::MetricsTestUtil::checkMetricWithValue(
            reporter.get(),
            metric("validation_execution_bucket_master_absolute_error_ms"), &bucketTags,
            10.0);
        kmonitor::MetricsTestUtil::checkMetricWithValue(
            reporter.get(),
            metric("validation_execution_bucket_master_absolute_percentage_error_pct"),
            &bucketTags, 100.0 / 7.0);
        kmonitor::MetricsTestUtil::checkMetricWithValue(
            reporter.get(), metric("validation_execution_bucket_agent_absolute_error_ms"),
            &bucketTags, 5.0);
        kmonitor::MetricsTestUtil::checkMetricWithValue(
            reporter.get(),
            metric("validation_execution_bucket_agent_absolute_percentage_error_pct"),
            &bucketTags, 50.0 / 7.0);
    }

    kmonitor::KMonitorFactory::Shutdown();
}

