TEST_F(NaviSchedResourceTest, testUnifiedBatchWorkloadLifecycleIsAtomic)
{
    AgentBatchR batchR(20, 1000);
    NaviSchedBatchPtr firstBatch;
    NaviSchedBatchPtr secondBatch;
    auto first = makeRequestStats(1);
    first.totalTokenCount = 100;
    first.cacheHitTokenCount = 40;
    auto fullyCached = makeRequestStats(2);
    fullyCached.totalTokenCount = 200;
    fullyCached.cacheHitTokenCount = 200;
    auto second = makeRequestStats(3);
    second.totalTokenCount = 50;
    second.cacheHitTokenCount = 10;
    ASSERT_TRUE(batchR.addRequest(
        first, 101, 2, [&](const NaviSchedBatchPtr &batch) { firstBatch = batch; }));
    ASSERT_TRUE(
        batchR.addRequest(fullyCached, 101, 2,
                          [&](const NaviSchedBatchPtr &batch) { firstBatch = batch; }));
    ASSERT_TRUE(batchR.addRequest(
        second, 102, 1, [&](const NaviSchedBatchPtr &batch) { secondBatch = batch; }));
    ASSERT_TRUE(firstBatch);
    ASSERT_TRUE(secondBatch);

    const auto values =
        AgentLatencyKernelTest::unifiedBatchLifecycle(firstBatch, secondBatch);
    EXPECT_EQ(std::vector<double>(
                  {1, 1, 101, 102, 2, 3, 2, 1, 2, 1, 1, 1, 100, 1, 1, 1, 1, 1, 0, 0, 0}),
              values);
}

TEST_F(NaviSchedResourceTest, testUnifiedPartialAbortReplacementIsAtomic)
{
    auto first = makeRequestStats(1);
    first.totalTokenCount = 100;
    first.cacheHitTokenCount = 40;
    auto fullyCached = makeRequestStats(2);
    fullyCached.totalTokenCount = 200;
    fullyCached.cacheHitTokenCount = 200;

    AgentBatchR originalBatchR(20, 1000);
    NaviSchedBatchPtr originalBatch;
    ASSERT_TRUE(originalBatchR.addRequest(
        first, 101, 2, [&](const NaviSchedBatchPtr &batch) { originalBatch = batch; }));
    ASSERT_TRUE(originalBatchR.addRequest(
        fullyCached, 101, 2,
        [&](const NaviSchedBatchPtr &batch) { originalBatch = batch; }));
    ASSERT_TRUE(originalBatch);

    AgentBatchR remainingBatchR(20, 1000);
    NaviSchedBatchPtr remainingBatch;
    ASSERT_TRUE(remainingBatchR.addRequest(
        first, 101, 1, [&](const NaviSchedBatchPtr &batch) { remainingBatch = batch; }));
    ASSERT_TRUE(remainingBatch);

    AgentBatchR lateRemainingBatchR(20, 1000);
    NaviSchedBatchPtr lateRemainingBatch;
    ASSERT_TRUE(lateRemainingBatchR.addRequest(
        fullyCached, 101, 1,
        [&](const NaviSchedBatchPtr &batch) { lateRemainingBatch = batch; }));
    ASSERT_TRUE(lateRemainingBatch);

    constexpr int64_t LOCAL_BATCH_ID = 700;
    originalBatch->batchId = LOCAL_BATCH_ID;
    remainingBatch->batchId = LOCAL_BATCH_ID;
    remainingBatch->expectedBatchSize = 2;
    lateRemainingBatch->batchId = LOCAL_BATCH_ID;
    lateRemainingBatch->expectedBatchSize = 2;

    const auto values = AgentLatencyKernelTest::unifiedBatchReplacementLifecycle(
        originalBatch, remainingBatch, lateRemainingBatch);
    EXPECT_EQ(
        std::vector<double>(
            {1,    1,    1, 1, 40,        60,  3600,           2400, 1, 1, 1, 40, 60,
             3600, 2400, 0, 0, 1'000'000, 101, LOCAL_BATCH_ID, 1,    1, 1, 1, 1}),
        values);
}

