TEST_F(NaviSchedResourceTest, testPartialAbortLatencyInputRequiresExactRequestIdentity)
{
    AgentBatchR batchR(20, 1000);
    NaviSchedBatchPtr readyBatch;
    const auto first = makeRequestStats(1);
    const auto second = makeRequestStats(2);
    ASSERT_TRUE(batchR.addRequest(
        first, 101, 2, [&](const NaviSchedBatchPtr &batch) { readyBatch = batch; }));
    ASSERT_TRUE(batchR.addRequest(
        second, 101, 2, [&](const NaviSchedBatchPtr &batch) { readyBatch = batch; }));
    ASSERT_TRUE(readyBatch);

    AgentBatchR::ExecutionState state;
    std::vector<NaviSchedRequestStats> abortedRequests;
    NaviSchedBatchPtr remainingBatch;
    NaviSchedPendingCacheReservation remainingPendingCache;
    ASSERT_TRUE(batchR.abortBatchRequests(readyBatch->batchId, {first.requestId}, state,
                                          abortedRequests, remainingBatch,
                                          remainingPendingCache));
    ASSERT_EQ(1, abortedRequests.size());
    ASSERT_TRUE(remainingBatch);

    AgentLatencyInputR input;
    auto mismatchedLocalBatch = state.localBatch;
    mismatchedLocalBatch.requestIds = {999};
    EXPECT_FALSE(input.submitBatchRequestsAborted(
        abortedRequests, remainingBatch, state.batchId, 1, state.batchWaitingRequests,
        state.queuedBatchRequests, state.runningRequests, state.eventTimeUs,
        mismatchedLocalBatch));

    auto mismatchedAbortedRequests = abortedRequests;
    mismatchedAbortedRequests.front().requestId = 999;
    EXPECT_FALSE(input.submitBatchRequestsAborted(
        mismatchedAbortedRequests, remainingBatch, state.batchId, 1,
        state.batchWaitingRequests, state.queuedBatchRequests, state.runningRequests,
        state.eventTimeUs, state.localBatch));

    auto mismatchedRemainingBatch = std::make_shared<NaviSchedBatch>(*remainingBatch);
    mismatchedRemainingBatch->requestIds = {first.requestId};
    EXPECT_FALSE(input.submitBatchRequestsAborted(
        abortedRequests, mismatchedRemainingBatch, state.batchId, 1,
        state.batchWaitingRequests, state.queuedBatchRequests, state.runningRequests,
        state.eventTimeUs, state.localBatch));

    ASSERT_TRUE(input.submitBatchRequestsAborted(
        abortedRequests, remainingBatch, state.batchId, 1, state.batchWaitingRequests,
        state.queuedBatchRequests, state.runningRequests, state.eventTimeUs,
        state.localBatch));
    std::vector<AgentLatencyInput> inputs;
    input.take(inputs);
    ASSERT_EQ(1, inputs.size());
    EXPECT_EQ(AgentLatencyInputType::BATCH_REQUESTS_ABORTED, inputs.front().type);
    EXPECT_EQ((std::vector<uint64_t>{first.requestId}),
              inputs.front().localBatch.requestIds);
    EXPECT_EQ((std::vector<uint64_t>{second.requestId}),
              inputs.front().batch->requestIds);
}

TEST_F(NaviSchedResourceTest,
       testMasterLatencyModelPoolFiltersSortsDeduplicatesAndIsolatesKeys)
{
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(MasterLatencyModelR::RESOURCE_ID,
                              R"({"source_min_revision":128,"max_candidates":3})"));
    auto pool = helper.getOrCreateResPtr<MasterLatencyModelR>();
    ASSERT_TRUE(pool);
    pool->_trustMinRevision = 128;

    NonLinearPrefillModelR model;
    const auto makeParameters = [&model](double baseLatency) {
        auto parameters = model.getInitialParameters();
        parameters[NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX] =
            parameterForFormulaCoefficient(
                NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX,
                baseLatency);
        return parameters;
    };
    const auto first = makeParameters(10.0);
    const auto duplicate = makeParameters(20.0);
    const auto last = makeParameters(40.0);
    const auto makeLatency = [](int64_t revision, const std::vector<double> &parameters) {
        AgentLatencyToMasterData latency;
        latency.formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
        latency.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
        latency.modelRevision = revision;
        latency.parameters = parameters;
        latency.optimizerState = makeLatencyOptimizerState(parameters.size());
        latency.zeroPoint = NonLinearPrefillModelR::calculateZeroPoint(parameters);
        return latency;
    };

    EXPECT_TRUE(pool->record("agent_a", "rtx", makeLatency(128, first), false, 10));
    EXPECT_FALSE(pool->record("agent_a", "rtx", makeLatency(127, first), true, 10));
    auto mismatchedVersion = makeLatency(128, first);
    --mismatchedVersion.binaryVersion;
    EXPECT_FALSE(pool->record("agent_a", "rtx", mismatchedVersion, true, 10));
    auto missingVersion = makeLatency(128, first);
    missingVersion.binaryVersion = 0;
    EXPECT_FALSE(pool->record("agent_a", "rtx", missingVersion, true, 10));
    auto invalid = makeLatency(128, first);
    invalid.parameters.pop_back();
    EXPECT_FALSE(pool->record("agent_a", "rtx", invalid, true, 10));
    auto nonMonotonicResidual = makeLatency(128, first);
    nonMonotonicResidual.residualParameters[3] = 100000.0;
    nonMonotonicResidual.residualParameters[4] = -100000.0;
    EXPECT_FALSE(pool->record("agent_a", "rtx", nonMonotonicResidual, true, 10));

    EXPECT_TRUE(pool->record("agent_a", "rtx", makeLatency(130, first), true, 10));
    EXPECT_TRUE(pool->record("agent_b", "rtx", makeLatency(160, duplicate), true, 20));
    EXPECT_TRUE(pool->record("agent_c", "rtx", makeLatency(150, duplicate), true, 30));
    EXPECT_TRUE(pool->record("agent_d", "rtx", makeLatency(140, last), true, 40));
    EXPECT_FALSE(pool->record("agent_b", "rtx", makeLatency(159, first), true, 50));

    auto warmup = pool->makeWarmup("rtx", NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL,
                                   NonLinearPrefillModelR::BINARY_VERSION,
                                   NonLinearPrefillModelR::PARAMETER_COUNT);
    ASSERT_TRUE(warmup);
    ASSERT_EQ(2, warmup->candidates.size());
    EXPECT_EQ(160, warmup->candidates[0].sourceRevision);
    EXPECT_EQ(duplicate, warmup->candidates[0].parameters);
    EXPECT_EQ(140, warmup->candidates[1].sourceRevision);
    EXPECT_EQ(last, warmup->candidates[1].parameters);
    EXPECT_FALSE(pool->makeWarmup("mi308", NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL,
                                  NonLinearPrefillModelR::BINARY_VERSION,
                                  NonLinearPrefillModelR::PARAMETER_COUNT));
    auto crossVersionWarmup =
        pool->makeWarmup("rtx", NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL,
                         NonLinearPrefillModelR::BINARY_VERSION - 1,
                         NonLinearPrefillModelR::PARAMETER_COUNT);
    EXPECT_FALSE(crossVersionWarmup);

    auto capacitySplitParameters = parametersForFormulaCoefficients(
        std::vector<double>(NonLinearPrefillModelR::CAPACITY_SPLIT_PARAMETER_COUNT,
                            1.0));
    EXPECT_TRUE(pool->record("agent_e", "rtx", makeLatency(170, capacitySplitParameters),
                             true, 60));
    auto capacitySplitWarmup =
        pool->makeWarmup("rtx", NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL,
                         NonLinearPrefillModelR::BINARY_VERSION,
                         NonLinearPrefillModelR::CAPACITY_SPLIT_PARAMETER_COUNT);
    ASSERT_TRUE(capacitySplitWarmup);
    ASSERT_EQ(1, capacitySplitWarmup->candidates.size());
    EXPECT_EQ(capacitySplitParameters,
              capacitySplitWarmup->candidates.front().parameters);

    auto mismatchedTooSmallCapacity = makeLatency(171, capacitySplitParameters);
    --mismatchedTooSmallCapacity.binaryVersion;
    mismatchedTooSmallCapacity
        .parameters[NonLinearPrefillModelR::PRECEDING_REQUEST_COUNT_PARAMETER_INDEX] =
        0.5;
    EXPECT_FALSE(pool->record("agent_f", "rtx", mismatchedTooSmallCapacity, true, 70));

    const auto stats = pool->getStats();
    EXPECT_EQ(1, stats.fingerprintCount);
    EXPECT_EQ(4, stats.candidateCount);
    EXPECT_EQ(6, stats.acceptedUpdateCount);
    EXPECT_EQ(7, stats.rejectedUpdateCount);
    EXPECT_EQ(2, stats.warmupResponseCount);
}

TEST_F(NaviSchedResourceTest,
       testMasterLatencyModelLiveCandidateIndexTracksMovesAndPrunes)
{
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(MasterLatencyModelR::RESOURCE_ID,
                              R"({"source_min_revision":128,"max_candidates":2})"));
    auto pool = helper.getOrCreateResPtr<MasterLatencyModelR>();
    ASSERT_TRUE(pool);
    pool->_trustMinRevision = 128;

    NonLinearPrefillModelR model;
    const auto makeLatency = [&model](int64_t revision, double baseLatency) {
        AgentLatencyToMasterData latency;
        latency.formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
        latency.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
        latency.modelRevision = revision;
        latency.parameters = model.getInitialParameters();
        latency.parameters[NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX] =
            parameterForFormulaCoefficient(
                NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX,
                baseLatency);
        latency.optimizerState = makeLatencyOptimizerState(latency.parameters.size());
        latency.zeroPoint =
            NonLinearPrefillModelR::calculateZeroPoint(latency.parameters);
        return latency;
    };
    for (const auto &agentId :
         {std::string("agent_a"), std::string("agent_b"), std::string("agent_c")}) {
        ASSERT_TRUE(pool->activateAgent(agentId, agentId + "_collector"));
    }
    ASSERT_TRUE(pool->record("agent_a", "fingerprint_a", makeLatency(128, 1.0), true, 1,
                             "agent_a_collector"));
    ASSERT_TRUE(pool->record("agent_b", "fingerprint_a", makeLatency(129, 2.0), true, 2,
                             "agent_b_collector"));
    ASSERT_TRUE(pool->record("agent_c", "fingerprint_a", makeLatency(130, 3.0), true, 3,
                             "agent_c_collector"));
    {
        autil::ScopedLock lock(pool->_lock);
        EXPECT_EQ(2, pool->_liveCandidateKeys.size());
        EXPECT_EQ(0, pool->_liveCandidateKeys.count("agent_a"));
        ASSERT_EQ(1, pool->_liveCandidateKeys.count("agent_b"));
        ASSERT_EQ(1, pool->_liveCandidateKeys.count("agent_c"));
        EXPECT_EQ("fingerprint_a", pool->_liveCandidateKeys.at("agent_b").fingerprint);
        EXPECT_EQ("fingerprint_a", pool->_liveCandidateKeys.at("agent_c").fingerprint);
    }

    ASSERT_TRUE(pool->record("agent_b", "fingerprint_b", makeLatency(131, 4.0), true, 4,
                             "agent_b_collector"));
    {
        autil::ScopedLock lock(pool->_lock);
        ASSERT_EQ(1, pool->_liveCandidateKeys.count("agent_b"));
        EXPECT_EQ("fingerprint_b", pool->_liveCandidateKeys.at("agent_b").fingerprint);
        for (const auto &[key, candidates] : pool->_liveCandidates) {
            if (key.fingerprint == "fingerprint_a") {
                EXPECT_EQ(0, candidates.count("agent_b"));
                EXPECT_EQ(1, candidates.count("agent_c"));
            }
        }
    }

    pool->removeAgent("agent_c", "agent_c_collector");
    {
        autil::ScopedLock lock(pool->_lock);
        EXPECT_EQ(0, pool->_liveCandidateKeys.count("agent_c"));
        EXPECT_EQ(1, pool->_liveCandidateKeys.size());
    }
}

TEST_F(NaviSchedResourceTest,
       testMasterLatencyModelAcceptsRampTrustDowngradeWithoutRejectingModel)
{
    MasterLatencyModelR pool;
    pool._sourceMinRevision = 1024;

    NonLinearPrefillModelR model;
    auto latency = [&model](int64_t revision) {
        AgentLatencyToMasterData result;
        result.formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
        result.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
        result.modelRevision = revision;
        result.parameters = model.getInitialParameters();
        result.optimizerState = makeLatencyOptimizerState(result.parameters.size());
        result.zeroPoint = NonLinearPrefillModelR::calculateZeroPoint(result.parameters);
        return result;
    };

    const auto trustedLatency = latency(1024);
    MasterLatencyModelR directPool;
    bool directAccepted = false;
    MasterLatencyModelR::RecordResult directResult;
    EXPECT_TRUE(directPool.record("direct", "rtx", trustedLatency, true, 1, "collector",
                                  &directAccepted, false, &directResult, false));
    EXPECT_TRUE(directAccepted);
    ASSERT_TRUE(directResult.model);
    EXPECT_FALSE(directResult.model->overloadPredictionTrusted);

    ASSERT_TRUE(pool.record("agent", "rtx", trustedLatency, true, 1, "collector", nullptr,
                            false, nullptr, true));

    auto untrustedLatency = trustedLatency;
    untrustedLatency.modelRevision = 1023;
    untrustedLatency.parameters[NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX] =
        parameterForFormulaCoefficient(
            NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX, 99.0);
    untrustedLatency.zeroPoint =
        NonLinearPrefillModelR::calculateZeroPoint(untrustedLatency.parameters);
    untrustedLatency.sessionSampleCount = 1;
    MasterLatencyModelR::RecordResult result;
    bool accepted = false;
    EXPECT_FALSE(pool.record("agent", "rtx", untrustedLatency, false, 2, "collector",
                             &accepted, false, &result, false));
    EXPECT_TRUE(accepted);
    EXPECT_TRUE(result.accepted);
    EXPECT_EQ(0u, result.consecutiveRejectedCount);
    ASSERT_TRUE(result.model);
    EXPECT_FALSE(result.model->overloadPredictionTrusted);
    EXPECT_EQ(trustedLatency.modelRevision, result.model->revision);
    EXPECT_EQ(trustedLatency.parameters, result.model->parameters);
    EXPECT_EQ(1, result.model->sessionSampleCount);
    EXPECT_EQ(0u, pool.getStats().rejectedUpdateCount);

    accepted = false;
    result = {};
    ASSERT_TRUE(pool.record("agent", "rtx", trustedLatency, true, 3, "collector",
                            &accepted, false, &result, true));
    EXPECT_TRUE(accepted);

    accepted = false;
    result = {};
    EXPECT_FALSE(pool.record("agent", "rtx", untrustedLatency, false, 4, "collector",
                             &accepted, false, &result, true));
    EXPECT_FALSE(accepted);
    EXPECT_EQ(MasterLatencyModelR::RejectReason::TRUSTED_REGRESSION, result.rejectReason);
    EXPECT_EQ(1u, result.consecutiveRejectedCount);
}

TEST_F(NaviSchedResourceTest,
       testMasterLatencyModelPoolNotifiesUntrustedCandidateUntilTrusted)
{
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(MasterLatencyModelR::RESOURCE_ID,
                              R"({"source_min_revision":128,"max_candidates":4})"));
    auto pool = helper.getOrCreateResPtr<MasterLatencyModelR>();
    ASSERT_TRUE(pool);
    pool->_trustMinRevision = 128;

    NonLinearPrefillModelR model;
    const auto makeLatency = [&model](int64_t revision, double baseLatency) {
        AgentLatencyToMasterData latency;
        latency.formula = NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL;
        latency.binaryVersion = NonLinearPrefillModelR::BINARY_VERSION;
        latency.modelRevision = revision;
        latency.parameters = model.getInitialParameters();
        latency.parameters[NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX] =
            parameterForFormulaCoefficient(
                NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX,
                baseLatency);
        latency.optimizerState = makeLatencyOptimizerState(latency.parameters.size());
        latency.zeroPoint =
            NonLinearPrefillModelR::calculateZeroPoint(latency.parameters);
        return latency;
    };

    auto targetLatency = makeLatency(10, 1.0);
    auto notificationPipe = std::make_shared<CaptureAsyncPipe>();
    ASSERT_TRUE(pool->activateAgent("target", "target_collector"));
    EXPECT_TRUE(
        pool->record("target", "rtx", targetLatency, false, 1, "target_collector"));
    ASSERT_TRUE(pool->updateWarmupSubscriber("target", "target_collector", "rtx",
                                             targetLatency, false, notificationPipe));
    EXPECT_EQ(1, pool->getStats().warmupSubscriberCount);

    auto first = makeLatency(128, 10.0);
    ASSERT_TRUE(pool->record("source_a", "rtx", first, true, 2, "source_a_collector"));
    ASSERT_EQ(1, notificationPipe->overrideCount);
    const auto firstVersion = pool->getWarmupCandidateVersion(
        "rtx", NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL, first.parameters.size());
    ASSERT_GT(firstVersion, 0);
    uint64_t emittedVersion = 0;
    auto firstWarmup =
        pool->makeWarmupIfNew("rtx", NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL,
                              NonLinearPrefillModelR::BINARY_VERSION,
                              first.parameters.size(), 0, emittedVersion);
    ASSERT_TRUE(firstWarmup);
    EXPECT_EQ(firstVersion, emittedVersion);
    EXPECT_FALSE(
        pool->makeWarmupIfNew("rtx", NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL,
                              NonLinearPrefillModelR::BINARY_VERSION,
                              first.parameters.size(), emittedVersion, emittedVersion));

    auto continuouslyFitted = makeLatency(129, 20.0);
    ASSERT_TRUE(pool->record("source_a", "rtx", continuouslyFitted, true, 3,
                             "source_a_collector"));
    EXPECT_EQ(1, notificationPipe->overrideCount);
    EXPECT_EQ(firstVersion, pool->getWarmupCandidateVersion(
                                "rtx", NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL,
                                first.parameters.size()));

    auto second = makeLatency(128, 30.0);
    ASSERT_TRUE(pool->record("source_b", "rtx", second, true, 4, "source_b_collector"));
    EXPECT_EQ(2, notificationPipe->overrideCount);
    EXPECT_GT(
        pool->getWarmupCandidateVersion(
            "rtx", NAVI_SCHED_LATENCY_FORMULA_NONLINEAR_PREFILL, first.parameters.size()),
        firstVersion);

    targetLatency.modelRevision = 128;
    targetLatency.zeroPoint =
        NonLinearPrefillModelR::calculateZeroPoint(targetLatency.parameters);
    ASSERT_TRUE(
        pool->record("target", "rtx", targetLatency, true, 5, "target_collector"));
    EXPECT_EQ(0, pool->getStats().warmupSubscriberCount);

    auto third = makeLatency(128, 40.0);
    ASSERT_TRUE(pool->record("source_c", "rtx", third, true, 6, "source_c_collector"));
    EXPECT_EQ(2, notificationPipe->overrideCount);
    const auto stats = pool->getStats();
    EXPECT_EQ(2, stats.warmupNotificationCount);
    EXPECT_EQ(0, stats.warmupNotificationFailureCount);
}

