TEST_F(NaviSchedResourceTest, testColdStartCandidateIsNotRefittedOrRolledBack)
{
    const std::string fingerprint = "refit-regression-fingerprint";
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(
        AgentHistoryR::RESOURCE_ID,
        R"({"fit_batch_size":2,"fit_interval":100,"warmup_sample_count":0})"));
    ASSERT_TRUE(
        helper.config(NonLinearPrefillModelR::RESOURCE_ID,
                      R"({"learning_rate":10.0,"use_batch_count_feature":false})"));
    ASSERT_TRUE(helper.config(
        LatencyModelR::RESOURCE_ID,
        std::string(R"({"latency_model_fingerprint":")") + fingerprint +
            R"(","cold_start_fit_epochs":1,"cold_start_evaluation_sample_count":2,"trust_min_revision":1024})"));
    auto latencyModel = helper.getOrCreateResPtr<LatencyModelR>();
    ASSERT_TRUE(latencyModel);
    latencyModel->_rampFinished = true;
    const auto initial = latencyModel->getSnapshot();
    ASSERT_TRUE(initial);

    auto candidateParameters = initial->parameters;
    candidateParameters[NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX] +=
        parameterForFormulaCoefficient(
            NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX, 0.01);
    MasterLatencyModelWarmupToAgentData warmup;
    warmup.fingerprint = fingerprint;
    warmup.formula = initial->formula;
    warmup.binaryVersion = initial->binaryVersion;
    warmup.candidates = {makeLatencyModelCandidate(1024, candidateParameters)};
    std::shared_ptr<const NaviSchedLatencyModelSnapshot> updated;
    ASSERT_TRUE(latencyModel->applyColdStartCandidates(warmup, updated));
    ASSERT_TRUE(updated);
    const auto expectedParameters = candidateParameters;
    EXPECT_EQ(expectedParameters, updated->parameters);
    EXPECT_FALSE(updated->overloadPredictionTrusted);

    NaviSchedLatencySample sample;
    sample.features.appendRequest(0, 1024);
    sample.latencyMs = latencyModel->predict(sample.features, candidateParameters) + 0.5;
    bool saveNeeded = false;
    for (size_t index = 0; index < 32; ++index) {
        sample.eventTimeUs = index + 1;
        ASSERT_TRUE(latencyModel->recordSample(sample, updated, saveNeeded));
        EXPECT_FALSE(updated);
    }

    const auto selected = latencyModel->getSnapshot();
    ASSERT_TRUE(selected);
    EXPECT_EQ(expectedParameters, selected->parameters);
    EXPECT_EQ(1, selected->revision);
    EXPECT_FALSE(selected->overloadPredictionTrusted);
    EXPECT_TRUE(selected->warmStarted);
    EXPECT_EQ(0, latencyModel->_coldStartRefitRejectedCount.load());
    EXPECT_EQ(1, latencyModel->getOptimizerState().step);
}

