TEST_F(NaviSchedResourceTest,
       testLatencyModelAdvancesUnchangedLocalFitAndTrustsAtConfiguredRevision)
{
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(AgentHistoryR::RESOURCE_ID,
                              R"({"fit_batch_size":1,"warmup_sample_count":0})"));
    ASSERT_TRUE(
        helper.config(LatencyModelR::RESOURCE_ID, R"({"trust_min_revision":1024})"));
    auto latencyModel = helper.getOrCreateResPtr<LatencyModelR>();
    ASSERT_TRUE(latencyModel);
    latencyModel->_rampFinished = true;

    auto snapshot =
        std::make_shared<NaviSchedLatencyModelSnapshot>(*latencyModel->getSnapshot());
    snapshot->revision = 1022;
    snapshot->overloadPredictionTrusted = false;
    latencyModel->publishSnapshot(snapshot);

    NaviSchedLatencySample sample;
    sample.features.appendRequest(0, 1024);
    sample.latencyMs = latencyModel->predict(sample.features, snapshot->parameters);
    std::shared_ptr<const NaviSchedLatencyModelSnapshot> updated;
    ASSERT_TRUE(latencyModel->fit({sample}, updated));
    ASSERT_TRUE(updated);
    EXPECT_EQ(1023, updated->revision);
    EXPECT_EQ(snapshot->parameters, updated->parameters);
    EXPECT_FALSE(updated->overloadPredictionTrusted);

    sample.latencyMs = latencyModel->predict(sample.features, updated->parameters);
    ASSERT_TRUE(latencyModel->fit({sample}, updated));
    ASSERT_TRUE(updated);
    EXPECT_EQ(1024, updated->revision);
    EXPECT_TRUE(updated->overloadPredictionTrusted);
}

