TEST_F(NaviSchedResourceTest,
       testLatencyModelUpdatesZeroPointWithoutRetainedLowLatencySamples)
{
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(AgentHistoryR::RESOURCE_ID,
                              R"({"fit_batch_size":1,"warmup_sample_count":0})"));
    ASSERT_TRUE(helper.config(
        AgentSchedulerConfigR::RESOURCE_ID,
        R"({"config_json":"{\"latency_fit_batch_size\":1,\"latency_zero_anchor_min_samples\":2,\"latency_zero_anchor_max_ms\":256}"})"));
    ASSERT_TRUE(
        helper.config(LatencyModelR::RESOURCE_ID,
                      R"({"zero_anchor_min_samples":2,"zero_anchor_max_ms":256})"));
    auto model = helper.getOrCreateResPtr<LatencyModelR>();
    ASSERT_TRUE(model);

    auto initial = model->getSnapshot();
    ASSERT_TRUE(initial);
    const auto initialZeroPoint =
        initial->parameters[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX];

    NaviSchedLatencySample sample;
    sample.features.appendRequest(0, 1);
    sample.latencyMs = 200.0;
    std::shared_ptr<const NaviSchedLatencyModelSnapshot> updated;
    bool saveNeeded = false;
    ASSERT_TRUE(model->recordSample(sample, updated, saveNeeded));
    ASSERT_TRUE(updated);
    EXPECT_NE(initialZeroPoint,
              updated->parameters[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX]);
    EXPECT_EQ(1, model->_agentHistoryR->getRetainedSampleCountAtMost(256.0));
    EXPECT_NE(0.0, model->getOptimizerState()
                       .adamMoment1[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX]);

    sample.latencyMs = 210.0;
    updated.reset();
    ASSERT_TRUE(model->recordSample(sample, updated, saveNeeded));
    ASSERT_TRUE(updated);
    EXPECT_NE(initialZeroPoint,
              updated->parameters[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX]);
    EXPECT_NE(0.0, model->getOptimizerState()
                       .adamMoment1[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX]);
}

