    for (auto index : {
             NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX,
             NonLinearPrefillModelR::TOTAL_PROMPT_PARAMETER_INDEX,
         }) {
        auto parameters = initialParameters;
        parameters[index] = -0.001;
        EXPECT_FALSE(NonLinearPrefillModelR::validateParameters(parameters));
    }

    auto parameters = initialParameters;
