TEST_F(NaviSchedResourceTest, testLatencyModelRepairsZeroPointWhenRestoringSnapshot)
{
    const auto stateFile = GET_TEMP_DATA_PATH() + "latency/zero-point-restore.state";
    std::filesystem::remove(stateFile);
    const std::string fingerprint = "zero-point-restore-fingerprint";
    const auto historyConfig =
        std::string(R"({"state_file":")") + stateFile +
        R"(","formula_fingerprint":"formula-a","history_fingerprint":"history-a","binary_fingerprint":"binary-a"})";

    {
        navi::NaviResourceHelper helper;
        ASSERT_TRUE(helper.config(AgentHistoryR::RESOURCE_ID, historyConfig));
        ASSERT_TRUE(helper.config(NonLinearPrefillModelR::RESOURCE_ID, "{}"));
        auto history = helper.getOrCreateResPtr<AgentHistoryR>();
        auto parameterModel = helper.getOrCreateResPtr<NonLinearPrefillModelR>();
        ASSERT_TRUE(history);
        ASSERT_TRUE(parameterModel);

        auto snapshot = std::make_shared<NaviSchedLatencyModelSnapshot>();
        snapshot->formula = parameterModel->getFormula();
        snapshot->binaryVersion = parameterModel->getBinaryVersion();
        snapshot->revision = 1;
        snapshot->parameters = parameterModel->getInitialParameters();
        snapshot->parameters[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX] = 0.0;
        snapshot->optimizerState = parameterModel->getOptimizerState();
        snapshot->overloadPredictionTrusted = true;
        ASSERT_TRUE(snapshot->valid());
        ASSERT_TRUE(history->save(snapshot, parameterModel->getOptimizerState()));
    }

    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(AgentHistoryR::RESOURCE_ID, historyConfig));
    ASSERT_TRUE(helper.config(
        LatencyModelR::RESOURCE_ID,
        std::string(R"({"latency_model_fingerprint":")") + fingerprint + R"("})"));
    auto model = helper.getOrCreateResPtr<LatencyModelR>();
    auto parameterModel = helper.getOrCreateResPtr<NonLinearPrefillModelR>();
    ASSERT_TRUE(model);
    ASSERT_TRUE(parameterModel);
    const auto restored = model->getSnapshot();
    ASSERT_TRUE(restored);
    EXPECT_DOUBLE_EQ(
        parameterModel
            ->getInitialParameters()[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX],
        restored->parameters[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX]);
    EXPECT_DOUBLE_EQ(
        0.0, model->getOptimizerState()
                 .adamMoment1[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX]);
    EXPECT_DOUBLE_EQ(
        0.0, model->getOptimizerState()
                 .adamMoment2[NonLinearPrefillModelR::ZERO_POINT_PARAMETER_INDEX]);
    std::filesystem::remove(stateFile);
}

TEST_F(NaviSchedResourceTest, testDirectColdStartRejectsIncompatibleResidualModel)
{
    const std::string fingerprint = "invalid-residual-warmup";
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(
        helper.config(AgentHistoryR::RESOURCE_ID, R"({"warmup_sample_count":0})"));
    ASSERT_TRUE(helper.config(
        LatencyModelR::RESOURCE_ID,
        std::string(R"({"latency_model_fingerprint":")") + fingerprint + R"("})"));
    auto model = helper.getOrCreateResPtr<LatencyModelR>();
    ASSERT_TRUE(model);
    const auto initial = model->getSnapshot();
    const auto initialOptimizer = model->getOptimizerState();
    ASSERT_TRUE(initial);

    auto candidate = makeLatencyModelCandidate(2048, initial->parameters);
    candidate.residualVersion = LatencyResidualModel::VERSION - 1;
    MasterLatencyModelWarmupToAgentData warmup;
    warmup.fingerprint = fingerprint;
    warmup.formula = initial->formula;
    warmup.binaryVersion = initial->binaryVersion;
    warmup.candidates = {candidate};
    ASSERT_FALSE(warmup.valid());

    std::shared_ptr<const NaviSchedLatencyModelSnapshot> updated;
    EXPECT_FALSE(model->applyColdStartCandidates(warmup, updated));
    EXPECT_FALSE(updated);
    EXPECT_EQ(initial, model->getSnapshot());
    EXPECT_EQ(initialOptimizer.step, model->getOptimizerState().step);

    candidate.residualVersion = LatencyResidualModel::VERSION + 1;
    warmup.candidates = {candidate};
    ASSERT_FALSE(warmup.valid());

    EXPECT_FALSE(model->applyColdStartCandidates(warmup, updated));
    EXPECT_FALSE(updated);
    EXPECT_EQ(initial, model->getSnapshot());
    EXPECT_EQ(initialOptimizer.step, model->getOptimizerState().step);

    candidate.residualVersion = LatencyResidualModel::VERSION;
    candidate.residualParameters.pop_back();
    warmup.candidates = {candidate};
    ASSERT_FALSE(warmup.valid());
    EXPECT_FALSE(model->applyColdStartCandidates(warmup, updated));
    EXPECT_FALSE(updated);
    EXPECT_EQ(initial, model->getSnapshot());
    EXPECT_EQ(initialOptimizer.step, model->getOptimizerState().step);

    candidate = makeLatencyModelCandidate(2048, initial->parameters);
    candidate.residualParameters[3] = 100000.0;
    candidate.residualParameters[4] = -100000.0;
    warmup.candidates = {candidate};
    ASSERT_TRUE(warmup.valid());
    ASSERT_FALSE(LatencyResidualModel::validateParameters(candidate.residualParameters));
    EXPECT_FALSE(model->applyColdStartCandidates(warmup, updated));
    EXPECT_FALSE(updated);
    EXPECT_EQ(initial, model->getSnapshot());
    EXPECT_EQ(initialOptimizer.step, model->getOptimizerState().step);
}

TEST_F(NaviSchedResourceTest, testDisabledResidualPreservesStateAndRejectsDivergentBase)
{
    navi::NaviResourceHelper helper;
    auto model = helper.getOrCreateResPtr<LatencyModelR>();
    ASSERT_TRUE(model);
    const auto initial = model->getSnapshot();
    ASSERT_TRUE(initial);
    auto parameters = initial->parameters;
    parameters[NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX] = 2'000'000.0;
    ASSERT_TRUE(NonLinearPrefillModelR::validateParameters(parameters));
    auto residualParameters = initial->residualParameters;
    residualParameters[3] = 30.0;
    ASSERT_TRUE(LatencyResidualModel::validateParameters(residualParameters));
    constexpr int64_t RESIDUAL_TIME_US = 90;

    NaviSchedLatencySample sample;
    sample.features.appendRequest(1024, 2048);
    sample.latencyMs = 300.0;
    sample.eventTimeUs = 100;
    AgentSchedulerConfig config;
    config.residualLearningRate = 0.0;
    config.latencyOnlineLearningRateScale = 1.0;
    std::vector<double> updatedParameters;
    std::vector<double> updatedResidualParameters;
    int64_t updatedResidualTimeUs = -1;
    ASSERT_TRUE(model->fitOnlineBatch(
        {sample}, parameters, residualParameters, RESIDUAL_TIME_US,
        config,
        updatedParameters, updatedResidualParameters, updatedResidualTimeUs));
    const auto basePrediction = model->_nonLinearPrefillModelR->predictConfigured(
        sample.features, updatedParameters);
    EXPECT_GT(basePrediction, 1'000'000.0);
    EXPECT_LT(basePrediction, NonLinearPrefillModelR::MAX_FIT_PREDICTION_MS);
    EXPECT_EQ(residualParameters, updatedResidualParameters);
    EXPECT_EQ(RESIDUAL_TIME_US, updatedResidualTimeUs);
    config.residualLearningRate = 0.2;
    EXPECT_TRUE(model->applyRuntimeConfig(config));
    EXPECT_GT(model->getResidualRuntimeConfig().learningRate, 0.0);
    config.residualLearningRate = 0.0;
    EXPECT_TRUE(model->applyRuntimeConfig(config));
    EXPECT_DOUBLE_EQ(0.0, model->getResidualRuntimeConfig().learningRate);
    EXPECT_DOUBLE_EQ(0.0,
                     model->getResidualRuntimeConfig().learningRate);
    parameters[NonLinearPrefillModelR::BASE_LATENCY_PARAMETER_INDEX] = 10'000'000.0;
    EXPECT_FALSE(model->fitOnlineBatch(
        {sample}, parameters, residualParameters, RESIDUAL_TIME_US,
        config,
        updatedParameters, updatedResidualParameters, updatedResidualTimeUs));
}
