TEST_F(NaviSchedResourceTest, testLatencyHistoryColdStartReplayUsesOnlineFitCadence)
{
    navi::NaviResourceHelper helper;
    ASSERT_TRUE(helper.config(
        AgentHistoryR::RESOURCE_ID,
        R"({"fit_batch_size":4,"fit_interval":2,"warmup_sample_count":0,"history_limit":8})"));
    auto history = helper.getOrCreateResPtr<AgentHistoryR>();
    ASSERT_TRUE(history);

    std::vector<size_t> liveFitIndexes;
    for (size_t index = 0; index < 7; ++index) {
        NaviSchedLatencySample sample;
        sample.latencyMs = index + 1;
        bool fitReady = false;
        bool persistReady = false;
        ASSERT_TRUE(history->append(sample, fitReady, persistReady));
        if (fitReady) {
            liveFitIndexes.emplace_back(index);
        }
    }
    EXPECT_EQ((std::vector<size_t>{3, 5}), liveFitIndexes);
    ASSERT_EQ(7, history->getHistory()->size());

    const auto replayBatches = history->getOnlineFitReplayBatches();
    ASSERT_EQ(6, replayBatches.size());
    for (size_t index = 0; index < replayBatches.size(); ++index) {
        const auto &batch = replayBatches[index];
        EXPECT_FALSE(batch.empty());
        EXPECT_LE(batch.size(), history->getHistory()->size());
        EXPECT_DOUBLE_EQ(index + 1.0, batch.back().latencyMs);
    }
}

