TEST_F(NaviSchedResourceTest, testAutoGradAlgebra)
{
    auto x = AutoGrad<3>::parameter(3.0, 0);
    auto y = AutoGrad<3>::parameter(4.0, 1);
    auto z = AutoGrad<3>::parameter(2.0, 2);
    auto value = (x * x + 2.0 * y) / z - y;
    ASSERT_DOUBLE_EQ(4.5, value.value());
    ASSERT_EQ(3, value.gradientCount());
    ASSERT_DOUBLE_EQ(3.0, value.gradient(0));
    ASSERT_DOUBLE_EQ(0.0, value.gradient(1));
    ASSERT_DOUBLE_EQ(-4.25, value.gradient(2));

    auto root = sqrt(x * x + 7.0);
    ASSERT_DOUBLE_EQ(4.0, root.value());
    ASSERT_DOUBLE_EQ(0.75, root.gradient(0));
    ASSERT_DOUBLE_EQ(0.0, root.gradient(1));
    ASSERT_DOUBLE_EQ(0.0, root.gradient(2));
}

TEST_F(NaviSchedResourceTest, testAutoGradTape)
{
    AutoGradTape tape(3, 16);
    auto x = tape.parameter(3.0, 0);
    auto y = tape.parameter(4.0, 1);
    auto z = tape.parameter(2.0, 2);
    auto value = (x * x + 2.0 * y) / z - y;
    std::vector<double> gradient;
    ASSERT_TRUE(tape.backward(value, gradient));
    ASSERT_DOUBLE_EQ(4.5, value.value());
    ASSERT_EQ(3, gradient.size());
    ASSERT_DOUBLE_EQ(3.0, gradient[0]);
    ASSERT_DOUBLE_EQ(0.0, gradient[1]);
    ASSERT_DOUBLE_EQ(-4.25, gradient[2]);

    auto shared = x * y;
    auto root = sqrt(shared * shared + z * z);
    ASSERT_TRUE(tape.backward(root, gradient));
    auto rootValue = std::sqrt(148.0);
    ASSERT_DOUBLE_EQ(rootValue, root.value());
    ASSERT_NEAR(48.0 / rootValue, gradient[0], 1e-12);
    ASSERT_NEAR(36.0 / rootValue, gradient[1], 1e-12);
    ASSERT_NEAR(2.0 / rootValue, gradient[2], 1e-12);

    tape.reset();
    constexpr size_t PARAMETER_COUNT = 4096;
    AutoGradTape largeTape(PARAMETER_COUNT, PARAMETER_COUNT * 3);
    AutoGradTape::Value loss;
    for (size_t index = 0; index < PARAMETER_COUNT; ++index) {
        auto parameter = largeTape.parameter(static_cast<double>(index), index);
        loss = loss + static_cast<double>(index + 1) * parameter;
    }
    ASSERT_TRUE(largeTape.backward(loss, gradient));
    ASSERT_EQ(PARAMETER_COUNT, gradient.size());
    for (size_t index = 0; index < PARAMETER_COUNT; ++index) {
        ASSERT_DOUBLE_EQ(static_cast<double>(index + 1), gradient[index]);
    }
}

TEST_F(NaviSchedResourceTest, testAutoGradTapeRewind)
{
    AutoGradTape tape(3, 16);
    auto evaluate = [&tape](double xValue, double yValue, double zValue) {
        auto x = tape.parameter(xValue, 0);
        auto y = tape.parameter(yValue, 1);
        auto z = tape.parameter(zValue, 2);
        return (x * x + 2.0 * y) / z - y;
    };
    std::vector<double> gradients;
    auto value = evaluate(3.0, 4.0, 2.0);
    ASSERT_TRUE(tape.backward(value, gradients));
    ASSERT_DOUBLE_EQ(4.5, value.value());

    ASSERT_TRUE(tape.rewind());
    value = evaluate(5.0, 2.0, 4.0);
    ASSERT_TRUE(tape.backward(value, gradients));
    ASSERT_DOUBLE_EQ(5.25, value.value());
    ASSERT_DOUBLE_EQ(2.5, gradients[0]);
    ASSERT_DOUBLE_EQ(-0.5, gradients[1]);
    ASSERT_DOUBLE_EQ(-29.0 / 16.0, gradients[2]);

    ASSERT_TRUE(tape.rewind());
    value = evaluate(2.0, 3.0, 5.0);
    ASSERT_TRUE(tape.backward(value, gradients));
    ASSERT_DOUBLE_EQ(-1.0, value.value());
    ASSERT_DOUBLE_EQ(0.8, gradients[0]);
    ASSERT_DOUBLE_EQ(-0.6, gradients[1]);
    ASSERT_DOUBLE_EQ(-0.4, gradients[2]);

    tape.reset();
    auto parameter = tape.parameter(7.0, 0);
    value = parameter * parameter;
    ASSERT_TRUE(tape.backward(value, gradients));
    ASSERT_DOUBLE_EQ(49.0, value.value());
    ASSERT_DOUBLE_EQ(14.0, gradients[0]);
}

TEST_F(NaviSchedResourceTest, testAutoGradStaticParameterLinearSums)
{
    constexpr size_t PARAMETER_COUNT = 4;
    const std::array<std::array<double, 3>, PARAMETER_COUNT> coefficients = {{
        {{1.0, 2.0, -1.0}},
        {{3.0, -2.0, 4.0}},
        {{-1.0, 0.5, 2.0}},
        {{2.0, 1.0, 3.0}},
    }};
    const std::array<double, PARAMETER_COUNT> firstWeights = {
        0.5,
        1.5,
        -2.0,
        3.0,
    };
    AutoGradTape tape(PARAMETER_COUNT, 8, 0, PARAMETER_COUNT * 3);
    AutoGradTape::StaticParameterLinearSums<3> firstSums(&tape);
    for (size_t index = 0; index < PARAMETER_COUNT; ++index) {
        firstSums.add(firstWeights[index], coefficients[index]);
    }
    auto firstValues = firstSums.finish();
    auto firstLoss = firstValues[0] * firstValues[1] + firstValues[2];
    std::vector<double> gradients;
    ASSERT_TRUE(tape.backward(firstLoss, gradients));
    ASSERT_EQ(PARAMETER_COUNT, gradients.size());
    for (size_t index = 0; index < PARAMETER_COUNT; ++index) {
        auto expected = coefficients[index][0] * firstValues[1].value() +
                        coefficients[index][1] * firstValues[0].value() +
                        coefficients[index][2];
        EXPECT_NEAR(expected, gradients[index], 1e-12);
    }

    const std::array<double, PARAMETER_COUNT> secondWeights = {
        2.0,
        -1.0,
        4.0,
        0.25,
    };
    ASSERT_TRUE(tape.rewind());
    AutoGradTape::StaticParameterLinearSums<3> secondSums(&tape);
    for (size_t index = 0; index < PARAMETER_COUNT; ++index) {
        secondSums.add(secondWeights[index], coefficients[index]);
    }
    auto secondValues = secondSums.finish();
    auto secondLoss = secondValues[0] * secondValues[1] + secondValues[2];
    ASSERT_TRUE(tape.backward(secondLoss, gradients));
    for (size_t index = 0; index < PARAMETER_COUNT; ++index) {
        auto expected = coefficients[index][0] * secondValues[1].value() +
                        coefficients[index][1] * secondValues[0].value() +
                        coefficients[index][2];
        EXPECT_NEAR(expected, gradients[index], 1e-12);
    }

    AutoGradTape::StaticParameterLinearSums<3> valueOnlySums(nullptr);
    for (size_t index = 0; index < PARAMETER_COUNT; ++index) {
        valueOnlySums.add(secondWeights[index], coefficients[index]);
    }
    auto valueOnly = valueOnlySums.finish();
    for (size_t index = 0; index < valueOnly.size(); ++index) {
        EXPECT_DOUBLE_EQ(secondValues[index].value(), valueOnly[index].value());
    }
}

