TEST_F(NaviSchedResourceTest, testCostSchedulerUsesExpiredMasterActivationDeadline)
{
    for (const bool parallel : {false, true}) {
        auto replay = makeCostSchedulerReplay(4, 2);
        auto context = std::make_shared<NaviSchedScheduleContext>();
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, *context));
        auto collected = std::make_shared<NaviSchedScheduleReplay>(replay);
        context->setReplay(collected);
        context->_scheduleBeginTimeUs =
            autil::TimeUtility::monotonicTimeUs() - 100'000;
        context->_scheduleDeadlineUs = context->_scheduleBeginTimeUs + 80'000;
        ASSERT_TRUE(ScheduleReplayRunner::prepareContext(*context));
        if (parallel) {
            CostSchedulerConfig config;
            config.optimizationTimeBudgetUs = 1'000'000;
            config.minLoopCount = 1;
            auto state = CostSchedulerGraphState::create(context, config, 2);
            ASSERT_TRUE(state);
            EXPECT_EQ(context->_scheduleBeginTimeUs, state->_optimizationBeginUs);
            EXPECT_EQ(80'000, state->_config.optimizationTimeBudgetUs);
            for (size_t worker = 0; worker < 2; ++worker) {
                ASSERT_TRUE(state->prepareWorker(worker));
            }
            ASSERT_TRUE(state->finishPreparation());
            for (size_t worker = 0; worker < 2; ++worker) {
                ASSERT_TRUE(state->runRow(worker, 0));
            }
            ASSERT_TRUE(state->finishRow(0));
            for (size_t worker = 0; worker < 2; ++worker) {
                ASSERT_TRUE(state->runProjection(worker, 0));
            }
            ASSERT_TRUE(state->finishProjection(0));
            EXPECT_FALSE(state->shouldContinue());
            for (size_t worker = 0; worker < 2; ++worker) {
                ASSERT_TRUE(state->runFinalRow(worker));
            }
            ASSERT_TRUE(state->finalize());
        } else {
            CostSchedulerKernel scheduler;
            scheduler._config.optimizationTimeBudgetUs = 1'000'000;
            scheduler._config.minLoopCount = 1;
            std::vector<NaviSchedDecision> decisions;
            ASSERT_TRUE(ScheduleReplayRunner::runContext(*context, scheduler, decisions));
            EXPECT_EQ(4u, decisions.size());
        }
        CostSchedulerKernelInternal::ReplayInfo info;
        autil::legacy::FromJson(info, autil::legacy::Any(collected->schedulerInfo));
        ASSERT_EQ(1u, info.optimizationRuns.size());
        const auto &run = info.optimizationRuns.front();
        EXPECT_EQ(1u, run.actualLoopCount);
        EXPECT_EQ("time_budget", run.stopReason);
        EXPECT_GE(run.elapsedUs, 100'000);
        EXPECT_EQ(0u, run.refinementEvaluations);
    }
}

TEST_F(NaviSchedResourceTest, testPrepareResultDecaysRunningHeadDuringScheduling)
{
    auto replay = makeCostSchedulerReplay(1, 1);
    replay.nodes[0].queueTotalPredictedLatencyMs = 150.0;
    replay.nodes[0].queueDecayHeadRemainingMs = 80.0;
    replay.nodes[0].queueReportReceiveTimeUs = replay.scheduleTimeUs - 10'000;
    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    ASSERT_TRUE(context.prepare());
    ASSERT_TRUE(context.selectNode(0, 0, "selected"));
    const auto execution = context.estimateBatchExecutionLatencyMs(0, {0});
    EXPECT_DOUBLE_EQ(140.0, context.getNode(0).getEstimatedQueueWaitMs());

    ASSERT_TRUE(context.prepareResult(replay.scheduleTimeUs + 65'000));
    ASSERT_EQ(1, context._decisions.size());
    EXPECT_DOUBLE_EQ(75.0, context._decisions[0].predictedQueueLatencyMs);
    EXPECT_DOUBLE_EQ(execution, context._decisions[0].predictedExecutionLatencyMs);
    EXPECT_EQ(replay.scheduleTimeUs, context._decisions[0].scheduleTimeUs);
    EXPECT_EQ(replay.scheduleTimeUs + 65'000, context._queuePredictionTimeUs);
    // Preparing a second time must not age the already delivered decision.
    const auto batchId = context._decisions[0].batchId;
    ASSERT_TRUE(context.prepareResult(replay.scheduleTimeUs + 500'000));
    EXPECT_DOUBLE_EQ(75.0, context._decisions[0].predictedQueueLatencyMs);
    EXPECT_EQ(batchId, context._decisions[0].batchId);
    EXPECT_EQ(replay.scheduleTimeUs + 65'000, context._queuePredictionTimeUs);
    // Optimization/replay snapshot time is distinct from response prediction time.
    EXPECT_DOUBLE_EQ(140.0, context.getNode(0).getEstimatedQueueWaitMs());
}

TEST_F(NaviSchedResourceTest, testPrepareResultPreservesWaitingAndReservedQueue)
{
    for (double headRemainingMs : {0.0, 30.0, 80.0}) {
        auto replay = makeCostSchedulerReplay(1, 1);
        replay.nodes[0].queueTotalPredictedLatencyMs = 150.0;
        replay.nodes[0].queueDecayHeadRemainingMs = headRemainingMs;
        replay.nodes[0].queueReportReceiveTimeUs = replay.scheduleTimeUs;
        NaviSchedScheduleContext context;
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
        ASSERT_TRUE(context.prepare());
        ASSERT_TRUE(context.selectNode(0, 0, "selected"));
        ASSERT_TRUE(context.prepareResult(replay.scheduleTimeUs + 500'000));
        // No decay of work that was waiting or reserved at snapshot time.
        EXPECT_DOUBLE_EQ(150.0 - headRemainingMs,
                         context._decisions[0].predictedQueueLatencyMs);
    }
}

TEST_F(NaviSchedResourceTest, testPrepareResultQueueUsesCompressionAndClampsClock)
{
    auto replay = makeCostSchedulerReplay(1, 1);
    replay.nodes[0].queueTotalPredictedLatencyMs = 150.0;
    replay.nodes[0].queueDecayHeadRemainingMs = 80.0;
    replay.nodes[0].queueReportReceiveTimeUs = replay.scheduleTimeUs - 10'000;
    for (int64_t finishDeltaUs : {-20'000, 20'000}) {
        NaviSchedScheduleContext context;
        ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
        context._timeCompression = 2.0;
        context._scheduleNodes[0]._timeCompression = 2.0;
        ASSERT_TRUE(context.prepare());
        ASSERT_TRUE(context.selectNode(0, 0, "selected"));
        ASSERT_TRUE(context.prepareResult(replay.scheduleTimeUs + finishDeltaUs));
        EXPECT_DOUBLE_EQ(finishDeltaUs < 0 ? 130.0 : 90.0,
                         context._decisions[0].predictedQueueLatencyMs);
    }
}

TEST_F(NaviSchedResourceTest, testReplayRestoresQueuePredictionResultTime)
{
    auto replay = makeCostSchedulerReplay(1, 1);
    replay.nodes[0].queueTotalPredictedLatencyMs = 150.0;
    replay.nodes[0].queueDecayHeadRemainingMs = 80.0;
    replay.nodes[0].queueReportReceiveTimeUs = replay.scheduleTimeUs - 10'000;
    replay.schedulerInfo["queue_prediction_time_us"] = replay.scheduleTimeUs + 65'000;
    NaviSchedScheduleContext context;
    ASSERT_TRUE(ScheduleReplayRunner::makeContext(replay, context));
    ASSERT_TRUE(context.prepare());
    ASSERT_TRUE(context.selectNode(0, 0, "selected"));
    std::vector<NaviSchedDecision> decisions;
    ASSERT_TRUE(ScheduleReplayRunner::collectDecisions(context, decisions));
    ASSERT_EQ(1u, decisions.size());
    EXPECT_DOUBLE_EQ(75.0, decisions[0].predictedQueueLatencyMs);
    EXPECT_DOUBLE_EQ(140.0, context.getNode(0).getEstimatedQueueWaitMs());
    replay.schedulerInfo["queue_prediction_time_us"] = replay.scheduleTimeUs - 1;
    EXPECT_FALSE(ScheduleReplayRunner::makeContext(replay, context));
}
